fn notification_source_exclusion_patterns() -> Result<&'static RegexSet, String> {
    static PATTERNS: OnceLock<Result<RegexSet, String>> = OnceLock::new();
    PATTERNS
        .get_or_init(|| {
            RegexSet::new(NOTIFICATION_SOURCE_EXCLUSION_PATTERNS)
                .map_err(|error| format!("invalid published notification exclusion regex: {error}"))
        })
        .as_ref()
        .map_err(Clone::clone)
}

