fn keyguard_session_evidence_csv(sessions: &[KeyguardSessionEvidence]) -> Result<Vec<u8>, String> {
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "pickup_id",
            "source_data_rows",
            "keyguard_state_paths",
            "dismissal_outcome",
            "session_outcome_class",
            "retry_count",
            "lock_types",
            "code_lengths",
            "pattern_stealth_modes",
            "screen_off_reasons",
            "prior_attempt_counts",
            "lock_screen_interaction_observed",
            "session_duration_ns",
            "preparation_duration_ns",
            "attempts",
            "code_attempt_sequence",
        ])
        .map_err(|error| format!("write keyguard session-evidence header: {error}"))?;
    for session in sessions {
        let fields = vec![
            session.participant_id.clone(),
            session.pickup_id.clone(),
            serde_json::to_string(&session.source_data_rows)
                .map_err(|error| format!("serialize keyguard source rows: {error}"))?,
            serde_json::to_string(&session.keyguard_state_paths)
                .map_err(|error| format!("serialize keyguard state paths: {error}"))?,
            session.dismissal_outcome.clone().unwrap_or_default(),
            session.session_outcome_class.to_owned(),
            session.retry_count.to_string(),
            serde_json::to_string(&session.lock_types)
                .map_err(|error| format!("serialize keyguard lock types: {error}"))?,
            serde_json::to_string(&session.code_lengths)
                .map_err(|error| format!("serialize keyguard code lengths: {error}"))?,
            serde_json::to_string(&session.pattern_stealth_modes)
                .map_err(|error| format!("serialize keyguard stealth modes: {error}"))?,
            serde_json::to_string(&session.screen_off_reasons)
                .map_err(|error| format!("serialize keyguard screen-off reasons: {error}"))?,
            serde_json::to_string(&session.prior_attempt_counts)
                .map_err(|error| format!("serialize keyguard prior-attempt counts: {error}"))?,
            session
                .lock_screen_interaction_observed
                .map(|value| value.to_string())
                .unwrap_or_default(),
            session.session_duration_ns.to_string(),
            session
                .preparation_duration_ns
                .map(|value| value.to_string())
                .unwrap_or_default(),
            serde_json::to_string(&session.attempts)
                .map_err(|error| format!("serialize keyguard attempts: {error}"))?,
            session.code_attempt_sequence.clone().unwrap_or_default(),
        ];
        writer
            .write_record(fields)
            .map_err(|error| format!("write keyguard session-evidence row: {error}"))?;
    }
    writer
        .into_inner()
        .map_err(|error| format!("finish keyguard session-evidence CSV: {error}"))
}

