fn contract_by_setting() -> Result<&'static BTreeMap<String, AdapterGroup>, String> {
    static CONTRACT: OnceLock<Result<BTreeMap<String, AdapterGroup>, String>> = OnceLock::new();
    CONTRACT
        .get_or_init(|| {
            let document: ContractDocument =
                serde_json::from_str(crate::packed_json::ADAPTER_CONTRACT.text()?).map_err(|error| {
                    format!("invalid embedded literature input adapter contract: {error}")
                })?;
            if document.schema_version != "chronicle-literature-input-adapter-contract/v1" {
                return Err("unknown literature input adapter contract version".into());
            }
            let mut by_setting = BTreeMap::new();
            let mut source_schema_ids = BTreeSet::new();
            let mut component_ids = BTreeSet::new();
            for group in document.groups {
                let required_support_roles =
                    group.required_support_roles.iter().collect::<BTreeSet<_>>();
                if group.semantic_type.trim().is_empty()
                    || group.adapter_id.trim().is_empty()
                    || group.adapter_version != "v1"
                    || group.input_role.trim().is_empty()
                    || group.schema_id.trim().is_empty()
                    || group.required_fields.is_empty()
                    || group.gui_surface.trim().is_empty()
                    || required_support_roles.len() != group.required_support_roles.len()
                    || required_support_roles.iter().any(|role| {
                        role.trim().is_empty() || !crate::is_registered_support_role(role)
                    })
                {
                    return Err("incomplete literature input adapter registration".into());
                }
                if !matches!(
                    group.route_kind.as_str(),
                    "protocol_input" | "native_operator_parameter"
                ) {
                    return Err(format!(
                        "unsupported literature input route: {}",
                        group.route_kind
                    ));
                }
                if let Some(component) = &group.component_execution {
                    validate_component_registration_status(&group, component)?;
                    let required_support_roles = component
                        .required_support_roles
                        .iter()
                        .collect::<BTreeSet<_>>();
                    let limitations = component.limitations.iter().collect::<BTreeSet<_>>();
                    if component.component_id
                        != format!("{}/{}", group.adapter_id, group.adapter_version)
                        || component.parent_method_profile_id.trim().is_empty()
                        || component.source_work_id.trim().is_empty()
                        || component.source_method_variant_id.trim().is_empty()
                        || component.method_profile_version.trim().is_empty()
                        || component.derived_result_kind.trim().is_empty()
                        || component.adapted_result_kind.as_deref().is_some_and(|kind| {
                            kind != if component.table_format.as_deref() == Some("arrow-ipc-file") {
                                "literature-input-adapted-arrow"
                            } else { "literature-input-adapted-csv" }
                        })
                        || component.table_format.as_deref().is_some_and(|format| format != "arrow-ipc-file")
                        || component.source_oracle_id.trim().is_empty()
                        || required_support_roles.len()
                            != component.required_support_roles.len()
                        || required_support_roles.iter().any(|role| {
                            role.trim().is_empty() || !crate::is_registered_support_role(role)
                        })
                        || limitations.len() != component.limitations.len()
                        || limitations.iter().any(|limitation| limitation.trim().is_empty())
                        || component.full_profile_execution_status != "blocked"
                        || !component_ids.insert(component.component_id.clone())
                    {
                        return Err(format!(
                            "malformed literature component execution registration: {}",
                            component.component_id
                        ));
                    }
                }
                for slot in group.option_bindings.keys() {
                    if slot.trim().is_empty() {
                        return Err("empty literature adapter option binding".into());
                    }
                }
                for slot in group.runtime_option_overrides.keys() {
                    if slot.trim().is_empty() {
                        return Err("empty literature adapter runtime option override".into());
                    }
                }
                let group_ids = group.method_setting_ids.iter().collect::<BTreeSet<_>>();
                for source_schema in &group.source_schemas {
                    let event_matches_valid = if source_schema.event_matches.is_empty() {
                        source_schema.canonical_value.as_deref().is_some_and(|value| !value.is_empty())
                            && source_schema
                                .source_match_value
                                .as_deref()
                                .or_else(|| source_schema.source_value.as_str())
                                .is_some_and(|value| !value.is_empty())
                            && source_schema.framing_policy.is_none()
                    } else {
                        let source_values = source_schema
                            .event_matches
                            .iter()
                            .map(|entry| entry.source_match_value.as_str())
                            .collect::<BTreeSet<_>>();
                        let frame_roles = source_schema
                            .event_matches
                            .iter()
                            .filter_map(|entry| entry.frame_role.as_deref())
                            .collect::<BTreeSet<_>>();
                        source_schema.source_match_value.is_none()
                            && source_schema.canonical_value.is_none()
                            && source_schema.event_matches.len() == source_values.len()
                            && source_schema.event_matches.iter().all(|entry| {
                                !entry.source_match_value.is_empty()
                                    && !entry.canonical_value.is_empty()
                                    && entry.frame_role.as_deref().is_some_and(|role| {
                                        matches!(role, "start" | "stop")
                                    })
                            })
                            && source_schema.framing_policy.as_deref()
                                == Some("strict_two_token_complete_frames")
                            && frame_roles == BTreeSet::from(["start", "stop"])
                    };
                    if !group_ids.contains(&source_schema.method_setting_id)
                        || !source_schema_ids.insert(source_schema.method_setting_id.clone())
                        || source_schema.source_work_id.trim().is_empty()
                        || source_schema.source_value.is_null()
                        || !valid_bare_digest(&source_schema.source_value_sha256)
                        || !matches!(source_schema.kind.as_str(), "event_type" | "field_alias" | "field_passthrough" | "scope_guard")
                        || source_schema.source_field.trim().is_empty()
                        || source_schema.canonical_field.as_deref().is_some_and(|field| !matches!(field, "interaction_type" | "event_timestamp" | "app_package_name"))
                        || (source_schema.kind == "event_type"
                            && (source_schema.canonical_field.as_deref() != Some("interaction_type")
                                || !event_matches_valid))
                        || (source_schema.kind == "field_alias"
                            && (source_schema.canonical_field.is_none()
                                || source_schema.canonical_value.is_some()
                                || source_schema.source_match_value.is_some()
                                || !source_schema.event_matches.is_empty()
                                || source_schema.framing_policy.is_some()))
                        || (source_schema.kind == "field_passthrough"
                            && (source_schema.canonical_field.is_some()
                                || source_schema.canonical_value.is_some()
                                || source_schema.source_match_value.is_some()
                                || !source_schema.event_matches.is_empty()
                                || source_schema.framing_policy.is_some()))
                        || (source_schema.kind == "scope_guard"
                            && (source_schema.canonical_field.is_some()
                                || source_schema.canonical_value.as_deref() != Some("foreground")
                                || source_schema.source_match_value.is_some()
                                || !source_schema.event_matches.is_empty()
                                || source_schema.framing_policy.is_some()))
                    {
                        return Err(format!(
                            "malformed literature source-schema registration: {}",
                            source_schema.method_setting_id
                        ));
                    }
                }
                for setting_id in &group.method_setting_ids {
                    if by_setting
                        .insert(setting_id.clone(), group.clone())
                        .is_some()
                    {
                        return Err(format!(
                            "duplicate literature input adapter setting: {setting_id}"
                        ));
                    }
                }
            }
            if by_setting.len() != 825 || source_schema_ids.len() != 18 {
                return Err(format!(
                    "literature adapter contract must contain 825 settings/18 source schemas, got {}/{}",
                    by_setting.len(), source_schema_ids.len()
                ));
            }
            Ok(by_setting)
        })
        .as_ref()
        .map_err(Clone::clone)
}

fn valid_bare_digest(value: &str) -> bool {
    value.len() == 64
        && value.bytes().all(|byte| byte.is_ascii_hexdigit())
        && value == value.to_ascii_lowercase()
}

fn validate_component_registration_status(
    group: &AdapterGroup,
    component: &LiteratureComponentExecutionRegistration,
) -> Result<(), String> {
    let extension = match component.component_id.as_str() {
        "chronicle.sdu-supplied-period-reductions/v1" => Some(("outside143:sdu-device-tracker:v1",
            "doi:10.1016/j.chbr.2021.100164", "sdu-device-tracker:source-qualified-outside143:v1",
            "literature-sdu-supplied-period-reductions-csv", "outside143:sdu-device-tracker:v1:period_reductions",
            "sdu-primary-supplied-period-reductions-v1/primary-pdf-sha256:31c48a45306cbc1f9bb9675185bd8aa05e35940999a9b8744e4aa378fe5ae04a")),
        "chronicle.sdu-supplied-validation-arithmetic/v1" => Some(("outside143:sdu-device-tracker:v1",
            "doi:10.1016/j.chbr.2021.100164", "sdu-device-tracker:source-qualified-outside143:v1",
            "literature-sdu-supplied-validation-arithmetic-csv", "outside143:sdu-device-tracker:v1:validation_arithmetic",
            "sdu-primary-supplied-validation-arithmetic-v1/primary-pdf-sha256:31c48a45306cbc1f9bb9675185bd8aa05e35940999a9b8744e4aa378fe5ae04a")),
        "chronicle.usage-logger-released-numeric/v1" => Some(("outside143:usage-logger:v1",
            "doi:10.3758/s13428-021-01585-7", "usage-logger:source-qualified-outside143:v1",
            "literature-usage-logger-released-numeric-csv", "outside143:usage-logger:v1:released_numeric",
            "usage-logger-released-numeric-v1/source-commit:6d1f4d44560ccd9a158c04adb37c6fc988bbbd35")),
        _ => None,
    };
    match component.canonical_registration_status.as_deref() {
        None | Some("blocked_version_mismatch" | "linked_artifact_only") => Ok(()),
        Some("outside_frozen143_extension")
            if extension.is_some_and(|(parent,work,variant,kind,setting,oracle)|
                component.parent_method_profile_id == parent && component.source_work_id == work
                && component.source_method_variant_id == variant && component.derived_result_kind == kind
                && group.method_setting_ids == [setting] && component.source_oracle_id == oracle)
                && component.method_profile_version == "1"
                && group.route_kind == "protocol_input"
                && group.input_role == "raw_chronicle_csv"
                && group.required_support_roles.is_empty()
                && group.source_schemas.is_empty()
                && group.runtime_option_overrides.is_empty()
                && group.option_bindings.is_empty()
                && group.component_config.is_none()
                && component.additional_method_setting_ids.is_empty()
                && component.required_support_roles.is_empty()
                && component.table_format.is_none()
                && component.adapted_result_kind.is_none()
                && !component.limitations.is_empty() => Ok(()),
        _ => Err(format!("unrecognized or malformed component registration status: {}", component.component_id)),
    }
}

fn source_schema_for<'a>(
    group: &'a AdapterGroup,
    setting_id: &str,
) -> Option<&'a SourceSchemaRegistration> {
    group
        .source_schemas
        .iter()
        .find(|registration| registration.method_setting_id == setting_id)
}

fn fixture_csv(lines: &[String]) -> Vec<u8> {
    let mut csv = lines.join("\n");
    csv.push('\n');
    csv.into_bytes()
}

fn fixture_input(case: &ConformanceCase) -> Result<Vec<u8>, String> {
    match (
        case.raw_csv_lines.is_empty(),
        case.raw_binary_bytes.is_empty(),
    ) {
        (false, true) => Ok(fixture_csv(&case.raw_csv_lines)),
        (true, false) => Ok(case.raw_binary_bytes.clone()),
        _ => Err("conformance requires exactly one CSV or binary input".to_owned()),
    }
}

fn conformance_output_text<'a>(
    bytes: &'a [u8],
    expected_digest: Option<&str>,
) -> Result<&'a str, String> {
    if let Some(digest) = expected_digest {
        if sha256(bytes) != digest {
            return Err("binary conformance output digest mismatch".to_owned());
        }
        crate::binary_exports::read_single_table_arrow(bytes)?;
        Ok("")
    } else {
        std::str::from_utf8(bytes)
            .map_err(|error| format!("conformance output is not UTF-8: {error}"))
    }
}

fn conformance_case_binding(
    case: &ConformanceCase,
    registered: &AdapterGroup,
) -> MethodProfileInputBindingReceipt {
    let source_schema = source_schema_for(registered, &case.method_setting_id).cloned();
    MethodProfileInputBindingReceipt {
        setting_id: case.method_setting_id.clone(),
        route_kind: registered.route_kind.clone(),
        input_role: registered.input_role.clone(),
        schema_id: registered.schema_id.clone(),
        adapter_id: registered.adapter_id.clone(),
        adapter_version: registered.adapter_version.clone(),
        required_fields: registered.required_fields.clone(),
        source_value: case.source_value.clone(),
        source_work_id: source_schema
            .as_ref()
            .map(|registration| registration.source_work_id.clone()),
        source_value_sha256: source_schema
            .as_ref()
            .map(|registration| registration.source_value_sha256.clone()),
        source_schema,
        conformance_fixture_id: case.fixture_id.clone(),
        conformance_result_digest: format!("sha256:{}", "0".repeat(64)),
    }
}

fn execute_conformance_case(
    manifest_group: &ConformanceGroup,
    case: &ConformanceCase,
    registered: &AdapterGroup,
    source_method_variant_id: &str,
) -> Result<ConformanceIdentity, String> {
    let registered_adapter_id = format!("{}/{}", registered.adapter_id, registered.adapter_version);
    if manifest_group.adapter_id != registered_adapter_id {
        return Err(format!(
            "literature conformance adapter mismatch for {}",
            case.method_setting_id
        ));
    }
    if case.fixture_id.trim().is_empty()
        || case.source_work_id.trim().is_empty()
        || source_method_variant_id.trim().is_empty()
        || case.source_value.is_null()
        || case.raw_csv_lines.is_empty() && case.raw_binary_bytes.is_empty()
    {
        return Err(format!(
            "incomplete literature conformance case for {}",
            case.method_setting_id
        ));
    }
    if let Some(source_schema) = source_schema_for(registered, &case.method_setting_id) {
        if case.source_work_id != source_schema.source_work_id
            || case.source_value != source_schema.source_value
        {
            return Err(format!(
                "literature conformance source identity mismatch for {}",
                case.method_setting_id
            ));
        }
    }

    let raw_csv = fixture_input(case)?;
    let arrow = registered
        .component_execution
        .as_ref()
        .is_some_and(|component| component.table_format.as_deref() == Some("arrow-ipc-file"));
    if arrow != !case.raw_binary_bytes.is_empty()
        || arrow != case.expected.output_sha256.is_some()
        || arrow != case.expected.derived_output_sha256.is_some()
        || arrow
            && (!case.expected.output_contains.is_empty()
                || !case.expected.output_excludes.is_empty()
                || !case.expected.derived_output_contains.is_empty()
                || !case.expected.derived_output_excludes.is_empty())
    {
        return Err(
            "conformance fixture format does not match its registered component".to_owned(),
        );
    }
    let raw_digest = sha256(&raw_csv);
    let support = case
        .support_csv_lines
        .iter()
        .map(|(role, lines)| {
            let replaced = lines
                .iter()
                .map(|line| line.replace("{{RAW_INPUT_SHA256}}", &raw_digest))
                .collect::<Vec<_>>();
            (role.clone(), fixture_csv(&replaced))
        })
        .collect::<BTreeMap<_, _>>();
    let binding = conformance_case_binding(case, registered);
    let adapted = adapt_literature_inputs_registered(&raw_csv, &raw_digest, &[binding], &|role| {
        support.get(role).map(Vec::as_slice).unwrap_or_default()
    })?
    .ok_or_else(|| {
        format!(
            "literature conformance case emitted no adaptation for {}",
            case.method_setting_id
        )
    })?;
    let output =
        conformance_output_text(&adapted.csv_bytes, case.expected.output_sha256.as_deref())
            .map_err(|error| {
                format!(
                    "literature conformance output is not UTF-8 for {}: {error}",
                    case.method_setting_id
                )
            })?;
    let derived_output = adapted
        .derived_result_bytes
        .as_deref()
        .map(|bytes| conformance_output_text(bytes, case.expected.derived_output_sha256.as_deref()))
        .transpose()
        .map_err(|error| {
            format!(
                "literature conformance derived output is not UTF-8 for {}: {error}",
                case.method_setting_id
            )
        })?;
    let expected = &case.expected;
    if adapted.receipt.source_row_count != expected.source_row_count
        || adapted.receipt.emitted_row_count != expected.emitted_row_count
        || adapted.receipt.mapped_event_row_count != expected.mapped_event_row_count
        || adapted.receipt.materialized_interval_count != expected.materialized_interval_count
        || adapted.receipt.duplicate_source_ids_removed != expected.duplicate_source_ids_removed
        || adapted.receipt.corrected_timestamp_provenance_rows
            != expected.corrected_timestamp_provenance_rows
        || adapted.receipt.participants_removed != expected.participants_removed
        || expected
            .output_contains
            .iter()
            .any(|text| !output.contains(text))
        || expected
            .output_excludes
            .iter()
            .any(|text| output.contains(text))
        || expected
            .derived_output_contains
            .iter()
            .any(|text| derived_output.is_none_or(|output| !output.contains(text)))
        || expected
            .derived_output_excludes
            .iter()
            .any(|text| derived_output.is_some_and(|output| output.contains(text)))
    {
        return Err(format!(
            "literature conformance expectation failed for {}; output={output:?}; derived_output={derived_output:?}",
            case.method_setting_id,
        ));
    }
    let executed_result = serde_json::json!({
        "schemaVersion": "chronicle-literature-input-adapter-executed-result/v1",
        "fixtureId": case.fixture_id,
        "methodSettingId": case.method_setting_id,
        "sourceWorkId": case.source_work_id,
        "sourceValue": case.source_value,
        "adapterId": manifest_group.adapter_id,
        "rawInputSha256": raw_digest,
        "adaptedOutputSha256": adapted.receipt.adapted_input_digest,
        "receipt": adapted.receipt,
        "expected": expected,
        "assertionsPassed": true
    });
    Ok(ConformanceIdentity {
        fixture_id: case.fixture_id.clone(),
        result_digest: sha256(
            &serde_jcs::to_vec(&executed_result)
                .map_err(|error| format!("serialize literature conformance result: {error}"))?,
        ),
        source_work_id: case.source_work_id.clone(),
        source_method_variant_id: source_method_variant_id.to_owned(),
        source_value: case.source_value.clone(),
    })
}

fn conformance_by_setting() -> Result<&'static BTreeMap<String, ConformanceIdentity>, String> {
    static CONFORMANCE: OnceLock<Result<BTreeMap<String, ConformanceIdentity>, String>> =
        OnceLock::new();
    CONFORMANCE
        .get_or_init(|| {
            let manifest: ConformanceManifest = serde_json::from_str(crate::packed_json::ADAPTER_CONFORMANCE.text()?)
                .map_err(|error| {
                    format!("invalid embedded literature conformance manifest: {error}")
                })?;
            if manifest.schema_version != "chronicle-literature-input-adapter-conformance/v2" {
                return Err("unknown literature conformance manifest version".into());
            }
            let contract = contract_by_setting()?;
            let mut by_setting = BTreeMap::new();
            let mut fixture_ids = BTreeSet::new();
            let mut result_digests = BTreeSet::new();
            if manifest.source_method_variants.len() != 825 {
                return Err("literature conformance variant registry must cover 825 settings".into());
            }
            for manifest_group in &manifest.groups {
                for case in &manifest_group.cases {
                    let registered = contract.get(&case.method_setting_id).ok_or_else(|| {
                        format!(
                            "literature conformance case has unregistered setting: {}",
                            case.method_setting_id
                        )
                    })?;
                    let source_method_variant_id = manifest
                        .source_method_variants
                        .get(&case.method_setting_id)
                        .ok_or_else(|| {
                            format!(
                                "literature conformance case lacks source variant: {}",
                                case.method_setting_id
                            )
                        })?;
                    let identity = execute_conformance_case(
                        manifest_group,
                        case,
                        registered,
                        source_method_variant_id,
                    )?;
                    if !fixture_ids.insert(identity.fixture_id.clone()) {
                        return Err(format!(
                            "duplicate literature conformance fixture: {}",
                            identity.fixture_id
                        ));
                    }
                    if !result_digests.insert(identity.result_digest.clone()) {
                        return Err(format!(
                            "duplicate literature conformance result digest: {}",
                            identity.result_digest
                        ));
                    }
                    if by_setting
                        .insert(case.method_setting_id.clone(), identity)
                        .is_some()
                    {
                        return Err(format!(
                            "duplicate literature conformance setting: {}",
                            case.method_setting_id
                        ));
                    }
                }
            }
            if by_setting.len() != 825
                || by_setting.keys().collect::<BTreeSet<_>>()
                    != contract.keys().collect::<BTreeSet<_>>()
            {
                return Err(format!(
                    "literature conformance manifest must exactly cover 825 registered settings, got {}",
                    by_setting.len()
                ));
            }
            Ok(by_setting)
        })
        .as_ref()
        .map_err(Clone::clone)
}

/// Resolve one closed, source-method component authority from the embedded
/// contract and its executed conformance tuples. This is deliberately not a
/// second paper profile: the returned registration names its still-blocked
/// parent profile and only the component's exact executable settings.
pub(crate) fn literature_component_setting_partition(
    component_id: &str,
) -> Result<(&'static [String], &'static [String]), String> {
    let contract = contract_by_setting()?;
    let group = contract
        .values()
        .find(|group| {
            group
                .component_execution
                .as_ref()
                .is_some_and(|component| component.component_id == component_id)
        })
        .ok_or_else(|| format!("unknown literature component: {component_id}"))?;
    let dependencies = &group
        .component_execution
        .as_ref()
        .unwrap()
        .additional_method_setting_ids;
    for setting_id in dependencies {
        if !contract.contains_key(setting_id) {
            return Err(format!(
                "literature component setting is not registered: {setting_id}"
            ));
        }
    }
    Ok((&group.method_setting_ids, dependencies))
}

pub fn literature_component_execution_unit(
    component_id: &str,
) -> Result<
    (
        LiteratureComponentExecutionRegistration,
        Vec<MethodProfileInputBindingReceipt>,
    ),
    String,
> {
    let contract = contract_by_setting()?;
    let group = contract
        .values()
        .find(|group| {
            group
                .component_execution
                .as_ref()
                .is_some_and(|component| component.component_id == component_id)
        })
        .ok_or_else(|| format!("unknown literature component execution unit: {component_id}"))?;
    let registration = group
        .component_execution
        .clone()
        .expect("selected group has component execution metadata");
    let conformance = conformance_by_setting()?;
    let setting_ids = group
        .method_setting_ids
        .iter()
        .chain(&registration.additional_method_setting_ids)
        .collect::<Vec<_>>();
    if setting_ids.iter().copied().collect::<BTreeSet<_>>().len() != setting_ids.len() {
        return Err("literature component has duplicate setting ownership".into());
    }
    let mut bindings = Vec::with_capacity(setting_ids.len());
    for setting_id in setting_ids {
        let group = contract.get(setting_id).ok_or_else(|| {
            format!("literature component setting is not registered: {setting_id}")
        })?;
        let identity = conformance.get(setting_id).ok_or_else(|| {
            format!("literature component setting lacks conformance: {setting_id}")
        })?;
        if identity.source_work_id != registration.source_work_id
            || !source_method_variant_matches(
                &identity.source_method_variant_id,
                &registration.source_method_variant_id,
            )
        {
            return Err(format!(
                "literature component source identity drift: {setting_id}"
            ));
        }
        let source_schema = source_schema_for(group, setting_id).cloned();
        bindings.push(MethodProfileInputBindingReceipt {
            setting_id: setting_id.clone(),
            route_kind: group.route_kind.clone(),
            input_role: group.input_role.clone(),
            schema_id: group.schema_id.clone(),
            adapter_id: group.adapter_id.clone(),
            adapter_version: group.adapter_version.clone(),
            required_fields: group.required_fields.clone(),
            source_value: source_schema
                .as_ref()
                .map(|schema| schema.source_value.clone())
                .unwrap_or_else(|| identity.source_value.clone()),
            source_work_id: source_schema
                .as_ref()
                .map(|schema| schema.source_work_id.clone()),
            source_value_sha256: source_schema
                .as_ref()
                .map(|schema| schema.source_value_sha256.clone()),
            source_schema,
            conformance_fixture_id: identity.fixture_id.clone(),
            conformance_result_digest: identity.result_digest.clone(),
        });
    }
    Ok((registration, bindings))
}

pub fn validate_input_bindings(
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<(), String> {
    validate_input_bindings_for_source(bindings, None, None)
}

fn source_method_variant_matches(registered: &str, receipt: &str) -> bool {
    registered == receipt
        || registered
            .strip_prefix("source-configuration-space-")
            .zip(receipt.strip_prefix("source-audit-configuration-space-"))
            .is_some_and(|(registered, receipt)| registered == receipt)
}

pub fn validate_input_bindings_for_source(
    bindings: &[MethodProfileInputBindingReceipt],
    receipt_source_work_id: Option<&str>,
    receipt_source_method_variant_id: Option<&str>,
) -> Result<(), String> {
    let contract = contract_by_setting()?;
    let conformance = conformance_by_setting()?;
    let mut setting_ids = BTreeSet::new();
    let mut registered_source_work_ids = BTreeSet::new();
    for binding in bindings {
        if !setting_ids.insert(binding.setting_id.as_str()) {
            return Err(format!(
                "duplicate methodProfileReceipt input binding: {}",
                binding.setting_id
            ));
        }
        let registered = contract.get(&binding.setting_id).ok_or_else(|| {
            format!(
                "unregistered methodProfileReceipt input setting: {}",
                binding.setting_id
            )
        })?;
        if binding.route_kind != registered.route_kind
            || binding.input_role != registered.input_role
            || binding.schema_id != registered.schema_id
            || binding.adapter_id != registered.adapter_id
            || binding.adapter_version != registered.adapter_version
            || binding.required_fields != registered.required_fields
        {
            return Err(format!(
                "methodProfileReceipt input binding disagrees with registered contract: {}",
                binding.setting_id
            ));
        }
        if let Some(source_schema) = source_schema_for(registered, &binding.setting_id) {
            registered_source_work_ids.insert(source_schema.source_work_id.as_str());
            if binding.source_work_id.as_deref() != Some(source_schema.source_work_id.as_str())
                || receipt_source_work_id
                    .is_some_and(|source_work_id| source_work_id != source_schema.source_work_id)
                || binding.source_value != source_schema.source_value
                || binding.source_value_sha256.as_deref()
                    != Some(source_schema.source_value_sha256.as_str())
                || binding.source_schema.as_ref() != Some(source_schema)
            {
                return Err(format!(
                    "methodProfileReceipt source-schema identity disagrees with registered contract: {}",
                    binding.setting_id
                ));
            }
        } else if binding.source_work_id.is_some()
            || binding.source_value_sha256.is_some()
            || binding.source_schema.is_some()
        {
            return Err(format!(
                "methodProfileReceipt injects source-schema metadata into an ordinary input binding: {}",
                binding.setting_id
            ));
        }
        let registered_conformance = conformance.get(&binding.setting_id).ok_or_else(|| {
            format!(
                "methodProfileReceipt input setting lacks registered conformance: {}",
                binding.setting_id
            )
        })?;
        if matches!(
            (receipt_source_work_id, receipt_source_method_variant_id),
            (Some(work), Some(variant))
                if work != registered_conformance.source_work_id
                    || !source_method_variant_matches(
                        &registered_conformance.source_method_variant_id,
                        variant,
                    )
        ) || receipt_source_work_id.is_some() != receipt_source_method_variant_id.is_some()
            || binding.source_value != registered_conformance.source_value
            || binding.conformance_fixture_id != registered_conformance.fixture_id
            || binding.conformance_result_digest != registered_conformance.result_digest
        {
            return Err(format!(
                "methodProfileReceipt input binding disagrees with registered conformance tuple: {}",
                binding.setting_id
            ));
        }
    }
    if registered_source_work_ids.len() > 1 {
        return Err(
            "methodProfileReceipt mixes source-schema bindings from different works".into(),
        );
    }
    let analysis_adapter_ids = [
        "chronicle.analysis-feature-missingness",
        "chronicle.analysis-positive-feature-missingness",
    ];
    let analysis_binding_ids = bindings
        .iter()
        .filter(|binding| analysis_adapter_ids.contains(&binding.adapter_id.as_str()))
        .map(|binding| binding.setting_id.as_str())
        .collect::<BTreeSet<_>>();
    if !analysis_binding_ids.is_empty() {
        let source_work_ids = analysis_binding_ids
            .iter()
            .filter_map(|setting_id| conformance.get(*setting_id))
            .map(|identity| identity.source_work_id.as_str())
            .collect::<BTreeSet<_>>();
        if source_work_ids.len() != 1 {
            return Err(
                "chronicle.analysis-feature-missingness refuses a cross-work setting group".into(),
            );
        }
        let source_work_id = *source_work_ids.iter().next().expect("one source work");
        let analysis_adapter_id = bindings
            .iter()
            .find(|binding| analysis_binding_ids.contains(binding.setting_id.as_str()))
            .map(|binding| binding.adapter_id.as_str())
            .expect("one analysis adapter");
        if bindings
            .iter()
            .filter(|binding| analysis_binding_ids.contains(binding.setting_id.as_str()))
            .any(|binding| binding.adapter_id != analysis_adapter_id)
        {
            return Err(
                "chronicle analysis-feature missingness refuses mixed adapter contracts".into(),
            );
        }
        let expected = contract
            .iter()
            .filter(|(setting_id, group)| {
                group.adapter_id == analysis_adapter_id
                    && conformance
                        .get(*setting_id)
                        .is_some_and(|identity| identity.source_work_id == source_work_id)
            })
            .map(|(setting_id, _)| setting_id.as_str())
            .collect::<BTreeSet<_>>();
        if analysis_binding_ids != expected {
            return Err(
                "chronicle analysis-feature missingness requires the complete source operation setting group"
                    .into(),
            );
        }
    }
    Ok(())
}

pub fn receipt_uses_capability_evidence(bindings: &[MethodProfileInputBindingReceipt]) -> bool {
    bindings
        .iter()
        .any(|binding| binding.input_role == "input_capability_evidence_file")
}

pub fn receipt_is_kernel_input_eligible(receipt: &LiteratureInputAdaptationReceipt) -> bool {
    receipt.source_oracle_id().is_none()
}

pub fn refuse_reserved_adapter_columns(raw_csv: &[u8]) -> Result<(), String> {
    if raw_csv.is_empty() {
        return Ok(());
    }
    let mut reader = csv::ReaderBuilder::new()
        .flexible(true)
        .from_reader(raw_csv);
    if reader
        .headers()
        .map_err(|error| format!("raw CSV header: {error}"))?
        .iter()
        .any(|header| header == "literature_source_data_row")
    {
        return Err("raw input uses reserved adapter column literature_source_data_row".into());
    }
    Ok(())
}

fn header_index(headers: &csv::StringRecord, name: &str) -> Option<usize> {
    headers.iter().position(|header| header == name)
}

fn required_header(
    headers: &csv::StringRecord,
    name: &str,
    adapter: &str,
) -> Result<usize, String> {
    header_index(headers, name).ok_or_else(|| format!("{adapter} requires raw column {name}"))
}

fn record_value(record: &csv::StringRecord, index: Option<usize>) -> &str {
    index
        .and_then(|index| record.get(index))
        .unwrap_or("")
        .trim()
}

fn source_value_plain_text(value: &Value) -> Result<String, String> {
    match value {
        Value::String(value) if !value.is_empty() => Ok(value.clone()),
        Value::Number(value) => Ok(value.to_string()),
        _ => Err(
            "chronicle.study-date-interior-exclusion requires string or number sourceValue".into(),
        ),
    }
}

fn validate_study_date_interior_exclusion_support(
    bindings: &[MethodProfileInputBindingReceipt],
    study_dates_csv: &[u8],
    raw_participants: &BTreeSet<String>,
) -> Result<(), String> {
    let active = bindings
        .iter()
        .filter(|binding| binding.adapter_id == "chronicle.study-date-interior-exclusion")
        .collect::<Vec<_>>();
    if active.is_empty() {
        return Ok(());
    }
    if study_dates_csv.is_empty() {
        return Err("chronicle.study-date-interior-exclusion requires study_dates_file".into());
    }

    let mut reader = csv::ReaderBuilder::new()
        .flexible(true)
        .from_reader(study_dates_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("study_dates_file header: {error}"))?
        .clone();
    let mut seen_headers = BTreeSet::new();
    if headers.iter().any(|header| !seen_headers.insert(header)) {
        return Err("study_dates_file has duplicate column names".into());
    }
    for field in &active[0].required_fields {
        if header_index(&headers, field).is_none() {
            return Err(format!(
                "chronicle.study-date-interior-exclusion requires study_dates_file column {field}"
            ));
        }
    }
    let participant =
        header_index(&headers, "participant_id").expect("validated participant_id support field");
    let label =
        header_index(&headers, "exclusion_label").expect("validated exclusion_label support field");
    let mut labels_by_participant: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for record in reader.records() {
        let record = record.map_err(|error| format!("study_dates_file row: {error}"))?;
        let label = record_value(&record, Some(label));
        let participant = record_value(&record, Some(participant));
        if !participant.is_empty() && !label.is_empty() {
            labels_by_participant
                .entry(participant.to_owned())
                .or_default()
                .insert(label.to_owned());
        }
    }
    for raw_participant in raw_participants {
        let available_labels = matching_study_participant_id(
            raw_participant,
            labels_by_participant.keys().map(String::as_str),
        )
        .and_then(|matched_id| labels_by_participant.get(matched_id));
        for binding in &active {
            let expected = source_value_plain_text(&binding.source_value)?;
            if available_labels.is_none_or(|labels| !labels.contains(&expected)) {
                return Err(format!(
                    "chronicle.study-date-interior-exclusion requires every raw participant to have exclusion_label matching sourceValue for {}",
                    binding.setting_id
                ));
            }
        }
    }
    Ok(())
}

fn set_record_value(record: &mut csv::StringRecord, index: usize, value: &str) {
    let mut fields = record.iter().map(str::to_owned).collect::<Vec<_>>();
    fields[index] = value.to_owned();
    *record = csv::StringRecord::from(fields);
}

fn civil_day(value: &str) -> Option<i64> {
    let date = value.get(..10)?;
    let mut parts = date.split('-');
    let year = parts.next()?.parse::<i64>().ok()?;
    let month = parts.next()?.parse::<i64>().ok()?;
    let day = parts.next()?.parse::<i64>().ok()?;
    if parts.next().is_some() || !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let adjusted_year = year - i64::from(month <= 2);
    let era = adjusted_year.div_euclid(400);
    let year_of_era = adjusted_year - era * 400;
    let shifted_month = month + if month > 2 { -3 } else { 9 };
    let day_of_year = (153 * shifted_month + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    Some(era * 146_097 + day_of_era)
}

fn participants_with_continuous_days(
    rows: &[csv::StringRecord],
    participant: usize,
    event_timestamp: usize,
    minimum_days: usize,
) -> BTreeSet<String> {
    let mut dates = BTreeMap::<String, BTreeSet<i64>>::new();
    for row in rows {
        if let Some(day) = civil_day(record_value(row, Some(event_timestamp))) {
            dates
                .entry(record_value(row, Some(participant)).to_owned())
                .or_default()
                .insert(day);
        }
    }
    dates
        .into_iter()
        .filter_map(|(participant, days)| {
            let mut longest = 0usize;
            let mut run = 0usize;
            let mut previous = None;
            for day in days {
                run = if previous.is_some_and(|previous| day == previous + 1) {
                    run + 1
                } else {
                    1
                };
                longest = longest.max(run);
                previous = Some(day);
            }
            (longest >= minimum_days).then_some(participant)
        })
        .collect()
}

const QUALITY_MIN_5_DAYS: &str = "method-setting-9fbd11c7c21eb3cd9b0372fd";
const QUALITY_MIN_14_DAYS: &str = "method-setting-8d4a3c24973e368db5edb017";
const QUALITY_MORE_THAN_10_DAYS: &str = "method-setting-b273d45441cffb58ccf6d05a";
const QUALITY_EXCLUDE_NO_USAGE: &str = "method-setting-086e0ecbe90e5820171d2e67";
const QUALITY_DROP_NO_DATA_DAY: &str = "method-setting-8da40d0ded8e63cfa8debe3b";
const QUALITY_DISCARD_FIRST_WEEK: &str = "method-setting-c53ed90e89f8cfaf6eee373e";
const QUALITY_MIN_4_WEEK_SPAN: &str = "method-setting-df7636eeeb84adfbcdcfae0e";
const QUALITY_MIN_30_DAYS: &str = "method-setting-2a7b02b71cfe6131e3ab5528";
const QUALITY_MIN_MISSING_30_DAY_WINDOW: &str = "method-setting-3665ea1fff24fed263602b2d";
const QUALITY_EARLIEST_WINDOW_TIE: &str = "method-setting-d2c934bbc9b30b804c2170ec";
const QUALITY_PARTICIPATION_14_DAYS: &str = "method-setting-9da3ee68fd7b55a6c9ef5472";
const QUALITY_BATTERY_PERIOD_NO_DATA_10_PERCENT: &str = "method-setting-d0f08f5649ba4e55b1423d67";

fn observed_days_by_participant(
    rows: &[csv::StringRecord],
    participant: usize,
    event_timestamp: usize,
) -> BTreeMap<String, BTreeSet<i64>> {
    let mut days = BTreeMap::<String, BTreeSet<i64>>::new();
    for row in rows {
        if let Some(day) = civil_day(record_value(row, Some(event_timestamp))) {
            days.entry(record_value(row, Some(participant)).to_owned())
                .or_default()
                .insert(day);
        }
    }
    days
}

fn quality_control_participants(
    rows: &[csv::StringRecord],
    participant: usize,
    event_timestamp: usize,
    interaction_type: usize,
    package: Option<usize>,
    setting_ids: &BTreeSet<&str>,
) -> BTreeSet<String> {
    let days = observed_days_by_participant(rows, participant, event_timestamp);
    let mut included = rows
        .iter()
        .map(|row| record_value(row, Some(participant)).to_owned())
        .collect::<BTreeSet<_>>();
    included.retain(|participant_id| {
        let observed = days.get(participant_id).cloned().unwrap_or_default();
        let count = observed.len();
        let span = observed
            .first()
            .zip(observed.last())
            .map_or(0, |(first, last)| last - first + 1);
        (!setting_ids.contains(QUALITY_MIN_5_DAYS) || count >= 5)
            && (!setting_ids.contains(QUALITY_MIN_14_DAYS) || count >= 14)
            && (!setting_ids.contains(QUALITY_MORE_THAN_10_DAYS) || count > 10)
            && (!setting_ids.contains(QUALITY_MIN_4_WEEK_SPAN) || span >= 28)
            && (!setting_ids.contains(QUALITY_MIN_30_DAYS) || count >= 30)
            && (!setting_ids.contains(QUALITY_PARTICIPATION_14_DAYS) || count >= 14)
            && (!setting_ids.contains(QUALITY_EXCLUDE_NO_USAGE)
                || rows.iter().any(|row| {
                    record_value(row, Some(participant)) == participant_id
                        && (!record_value(row, package).is_empty()
                            || matches!(
                                record_value(row, Some(interaction_type)),
                                "Activity Resumed" | "App Usage"
                            ))
                }))
    });
    included
}

fn apply_quality_control_rows(
    rows: &mut Vec<csv::StringRecord>,
    participant: usize,
    event_timestamp: usize,
    interaction_type: usize,
    battery_charging_no_data_percent: Option<usize>,
    battery_discharging_no_data_percent: Option<usize>,
    setting_ids: &BTreeSet<&str>,
) -> Result<(), String> {
    if setting_ids.contains(QUALITY_DROP_NO_DATA_DAY) {
        rows.retain(|row| {
            record_value(row, Some(interaction_type)) != "No Data"
                && civil_day(record_value(row, Some(event_timestamp))).is_some()
        });
    }
    if setting_ids.contains(QUALITY_DISCARD_FIRST_WEEK) {
        let first_days = observed_days_by_participant(rows, participant, event_timestamp)
            .into_iter()
            .filter_map(|(id, days)| days.first().copied().map(|day| (id, day)))
            .collect::<BTreeMap<_, _>>();
        rows.retain(|row| {
            civil_day(record_value(row, Some(event_timestamp)))
                .zip(
                    first_days
                        .get(record_value(row, Some(participant)))
                        .copied(),
                )
                .is_some_and(|(day, first)| day >= first + 7)
        });
    }
    if setting_ids.contains(QUALITY_MIN_MISSING_30_DAY_WINDOW)
        || setting_ids.contains(QUALITY_EARLIEST_WINDOW_TIE)
    {
        let windows = observed_days_by_participant(rows, participant, event_timestamp)
            .into_iter()
            .filter_map(|(id, days)| {
                let (&first, &last) = days.first().zip(days.last())?;
                (last - first + 1 >= 30).then(|| {
                    let best = (first..=last - 29)
                        .max_by_key(|start| (days.range(*start..=*start + 29).count(), -start))
                        .expect("non-empty 30-day window range");
                    (id, (best, best + 29))
                })
            })
            .collect::<BTreeMap<_, _>>();
        rows.retain(|row| {
            civil_day(record_value(row, Some(event_timestamp)))
                .zip(windows.get(record_value(row, Some(participant))).copied())
                .is_some_and(|(day, (start, end))| (start..=end).contains(&day))
        });
    }
    if setting_ids.contains(QUALITY_BATTERY_PERIOD_NO_DATA_10_PERCENT) {
        let charging = battery_charging_no_data_percent.ok_or_else(|| {
            "chronicle.battery-period-day-exclusion requires battery_charging_no_data_percent"
                .to_string()
        })?;
        let discharging = battery_discharging_no_data_percent.ok_or_else(|| {
            "chronicle.battery-period-day-exclusion requires battery_discharging_no_data_percent"
                .to_string()
        })?;
        let mut percentages = BTreeMap::<(String, i64), (f64, f64)>::new();
        let mut observed_days = BTreeSet::new();
        for row in rows.iter() {
            let participant_id = record_value(row, Some(participant)).to_owned();
            let day = civil_day(record_value(row, Some(event_timestamp))).ok_or_else(|| {
                "chronicle.battery-period-day-exclusion requires a valid local event_timestamp on every row"
                    .to_string()
            })?;
            let key = (participant_id, day);
            observed_days.insert(key.clone());
            let charging_text = record_value(row, Some(charging));
            let discharging_text = record_value(row, Some(discharging));
            if charging_text.is_empty() && discharging_text.is_empty() {
                continue;
            }
            if charging_text.is_empty() || discharging_text.is_empty() {
                return Err("chronicle.battery-period-day-exclusion requires both battery no-data percentages on the same participant-day row".into());
            }
            let parse_percent = |value: &str| {
                value
                    .parse::<f64>()
                    .ok()
                    .filter(|value| value.is_finite() && (0.0..=100.0).contains(value))
            };
            let pair = (
                parse_percent(charging_text).ok_or_else(|| {
                    "chronicle.battery-period-day-exclusion requires charging percentages from 0 through 100".to_string()
                })?,
                parse_percent(discharging_text).ok_or_else(|| {
                    "chronicle.battery-period-day-exclusion requires discharging percentages from 0 through 100".to_string()
                })?,
            );
            if percentages
                .insert(key, pair)
                .is_some_and(|prior| prior != pair)
            {
                return Err("chronicle.battery-period-day-exclusion refuses conflicting percentages for one participant-day".into());
            }
        }
        if observed_days
            .iter()
            .any(|key| !percentages.contains_key(key))
        {
            return Err("chronicle.battery-period-day-exclusion requires one complete charging/discharging percentage pair per observed participant-day".into());
        }
        rows.retain(|row| {
            let key = (
                record_value(row, Some(participant)).to_owned(),
                civil_day(record_value(row, Some(event_timestamp)))
                    .expect("validated local event_timestamp"),
            );
            percentages
                .get(&key)
                .is_some_and(|(charging, discharging)| *charging < 10.0 && *discharging < 10.0)
        });
    }
    Ok(())
}

fn capability_state_for(
    parsed: &chronicle_chrono_kernel_wasm::b05_foundational_semantics::ParsedCapabilityEvidence,
    raw_digest: &str,
    participant: &str,
    capability: CapabilityId,
) -> Option<CapabilityState> {
    parsed
        .claims
        .iter()
        .find(|claim| {
            claim.raw_input_sha256 == raw_digest
                && claim.participant_id == participant
                && claim.capability_id == capability
        })
        .or_else(|| {
            parsed.claims.iter().find(|claim| {
                claim.raw_input_sha256 == raw_digest
                    && claim.participant_id == "*"
                    && claim.capability_id == capability
            })
        })
        .map(|claim| claim.state)
}

// Each index names a separately validated source column; the registered config owns the reduction.
#[allow(clippy::too_many_arguments)]
fn notification_study_daily_result(
    rows: &[csv::StringRecord],
    participant: usize,
    study_local_date: usize,
    study_week: usize,
    intervention_group: usize,
    tracking_date_observed: usize,
    notification_observed: usize,
    config: &DailyContactCountComponentConfig,
) -> Result<(Vec<u8>, u32), String> {
    #[derive(Clone)]
    struct Day {
        period: u8,
        cohort: String,
    }
    struct VariantResult<'a> {
        config: &'a DailyContactCountVariantConfig,
        daily_counts: BTreeMap<(String, String), u64>,
        period_stats: BTreeMap<(String, u8), (u64, u32)>,
    }

    let parse_bool = |value: &str| match value {
        "true" => Ok(true),
        "false" => Ok(false),
        _ => Err("daily contact count booleans must be true or false".to_string()),
    };

    if config.variants.is_empty() {
        return Err(
            "daily contact count component requires at least one configured variant".into(),
        );
    }
    if config.period_reduction_gate.baseline_period
        == config.period_reduction_gate.comparison_period
        || !config
            .period_reduction_gate
            .inclusive_minimum_reduction_percent
            .is_finite()
        || config
            .period_reduction_gate
            .inclusive_minimum_reduction_percent
            < 0.0
        || config
            .period_reduction_gate
            .inclusive_minimum_reduction_percent
            > 100.0
        || config
            .period_reduction_gate
            .conditional_cohort
            .trim()
            .is_empty()
        || config
            .period_reduction_gate
            .unconditional_cohort
            .trim()
            .is_empty()
        || config.period_reduction_gate.conditional_cohort
            == config.period_reduction_gate.unconditional_cohort
    {
        return Err("daily contact count component has an invalid period reduction gate".into());
    }

    let mut variant_ids = BTreeSet::new();
    let mut absent_day_policies = BTreeSet::new();
    for variant in &config.variants {
        if variant.variant_id.trim().is_empty()
            || variant.evidence_relation.trim().is_empty()
            || !variant_ids.insert(variant.variant_id.as_str())
            || !absent_day_policies.insert(variant.absent_day_policy.as_str())
            || !matches!(
                variant.absent_day_policy.as_str(),
                "count_joined_rows" | "count_matches_and_zero_fill"
            )
        {
            return Err(
                "daily contact count component has an invalid variant configuration".into(),
            );
        }
    }
    if absent_day_policies != BTreeSet::from(["count_joined_rows", "count_matches_and_zero_fill"]) {
        return Err(
            "daily contact count component requires both joined-row and zero-fill variants".into(),
        );
    }

    let mut days = BTreeMap::<(String, String), Day>::new();
    for row in rows {
        if !parse_bool(record_value(row, Some(tracking_date_observed)))? {
            continue;
        }
        let participant_id = record_value(row, Some(participant));
        let date = record_value(row, Some(study_local_date));
        if participant_id.is_empty() || date.len() != 10 {
            return Err("daily contact count spine rows require participant_id and YYYY-MM-DD study_local_date".into());
        }
        let period = record_value(row, Some(study_week))
            .parse::<u8>()
            .map_err(|_| {
                "daily contact count requires an unsigned integer study_week".to_string()
            })?;
        let cohort = record_value(row, Some(intervention_group));
        if cohort != config.period_reduction_gate.conditional_cohort
            && cohort != config.period_reduction_gate.unconditional_cohort
        {
            return Err(
                "daily contact count spine row has an unconfigured intervention_group".into(),
            );
        }
        let key = (participant_id.to_owned(), date.to_owned());
        if days
            .insert(
                key,
                Day {
                    period,
                    cohort: cohort.to_owned(),
                },
            )
            .is_some()
        {
            return Err("daily contact count requires one spine row per participant-day".into());
        }
    }
    if days.is_empty() {
        return Err("daily contact count requires at least one participant-day spine row".into());
    }

    let mut participant_cohorts = BTreeMap::<String, String>::new();
    for ((participant_id, _), day) in &days {
        if participant_cohorts
            .insert(participant_id.clone(), day.cohort.clone())
            .is_some_and(|existing| existing != day.cohort)
        {
            return Err("daily contact count requires one cohort per participant".into());
        }
    }

    let spine = days
        .keys()
        .map(|(participant_id, date)| ParticipantDay {
            participant_id: participant_id.clone(),
            date: date.clone(),
        })
        .collect::<Vec<_>>();
    let mut contacts = Vec::new();
    for row in rows {
        if !parse_bool(record_value(row, Some(notification_observed)))? {
            continue;
        }
        let participant_id = record_value(row, Some(participant));
        let date = record_value(row, Some(study_local_date));
        if participant_id.is_empty() || date.len() != 10 {
            return Err(
                "daily contact rows require participant_id and YYYY-MM-DD study_local_date".into(),
            );
        }
        let key = (participant_id.to_owned(), date.to_owned());
        if let Some(day) = days.get(&key) {
            let period = record_value(row, Some(study_week))
                .parse::<u8>()
                .map_err(|_| {
                    "daily contact rows require an unsigned integer study_week".to_string()
                })?;
            if period == day.period {
                contacts.push(DatedContact {
                    participant_id: participant_id.to_owned(),
                    date: date.to_owned(),
                });
            }
        }
    }

    let mut variant_results = Vec::with_capacity(config.variants.len());
    for variant in &config.variants {
        let policy = match variant.absent_day_policy.as_str() {
            "count_joined_rows" => AbsentDailyCountPolicy::CountJoinedRows,
            "count_matches_and_zero_fill" => AbsentDailyCountPolicy::CountMatchesAndZeroFill,
            _ => unreachable!("variant policy was validated"),
        };
        let counts = count_contacts_on_day_spine(&spine, &contacts, policy)
            .map_err(|error| format!("daily contact count component: {error}"))?;
        let mut daily_counts = BTreeMap::new();
        let mut period_stats = BTreeMap::<(String, u8), (u64, u32)>::new();
        for count in counts {
            let day = days
                .get(&(count.participant_id.clone(), count.date.clone()))
                .expect("count key came from the validated spine");
            daily_counts.insert(
                (count.participant_id.clone(), count.date.clone()),
                count.contact_count,
            );
            let entry = period_stats
                .entry((count.participant_id, day.period))
                .or_default();
            entry.0 = entry
                .0
                .checked_add(count.contact_count)
                .ok_or_else(|| "daily contact count period total overflow".to_string())?;
            entry.1 = entry
                .1
                .checked_add(1)
                .ok_or_else(|| "daily contact count period day-count overflow".to_string())?;
        }
        variant_results.push(VariantResult {
            config: variant,
            daily_counts,
            period_stats,
        });
    }

    let format_decimal = |value: f64| {
        let mut text = format!("{value:.6}");
        while text.ends_with('0') {
            text.pop();
        }
        if text.ends_with('.') {
            text.pop();
        }
        if text == "-0" {
            "0".to_string()
        } else {
            text
        }
    };
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "study_local_date",
            "study_week",
            "intervention_group",
            "variant_id",
            "evidence_relation",
            "absent_day_policy",
            "daily_contact_count",
            "period_total",
            "period_mean",
            "reduction_percent",
            "compliance_included",
        ])
        .map_err(|error| format!("write notification study result header: {error}"))?;
    for variant in &variant_results {
        for ((participant_id, date), day) in &days {
            let daily_count = variant
                .daily_counts
                .get(&(participant_id.clone(), date.clone()))
                .expect("variant count contains every spine day");
            let (period_total, period_days) = variant
                .period_stats
                .get(&(participant_id.clone(), day.period))
                .expect("period statistics contain every spine day");
            let reduction = variant
                .period_stats
                .get(&(
                    participant_id.clone(),
                    config.period_reduction_gate.baseline_period,
                ))
                .zip(variant.period_stats.get(&(
                    participant_id.clone(),
                    config.period_reduction_gate.comparison_period,
                )))
                .and_then(
                    |((baseline_total, baseline_days), (comparison_total, comparison_days))| {
                        let baseline = *baseline_total as f64 / *baseline_days as f64;
                        let comparison = *comparison_total as f64 / *comparison_days as f64;
                        (baseline > 0.0).then_some((1.0 - comparison / baseline) * 100.0)
                    },
                );
            let included = day.cohort == config.period_reduction_gate.unconditional_cohort
                || (day.cohort == config.period_reduction_gate.conditional_cohort
                    && reduction.is_some_and(|value| {
                        value
                            >= config
                                .period_reduction_gate
                                .inclusive_minimum_reduction_percent
                    }));
            writer
                .write_record([
                    participant_id.as_str(),
                    date.as_str(),
                    &day.period.to_string(),
                    day.cohort.as_str(),
                    variant.config.variant_id.as_str(),
                    variant.config.evidence_relation.as_str(),
                    variant.config.absent_day_policy.as_str(),
                    &daily_count.to_string(),
                    &period_total.to_string(),
                    &format_decimal(*period_total as f64 / *period_days as f64),
                    &reduction.map(format_decimal).unwrap_or_default(),
                    if included { "true" } else { "false" },
                ])
                .map_err(|error| format!("write daily contact count result row: {error}"))?;
        }
    }
    let row_count = u32::try_from(days.len().saturating_mul(variant_results.len()))
        .map_err(|_| "daily contact count result row count overflow".to_string())?;
    let bytes = writer
        .into_inner()
        .map_err(|error| format!("finish daily contact count result CSV: {error}"))?;
    Ok((bytes, row_count))
}

fn analysis_feature_matrix_result(bytes: &[u8]) -> Result<(Vec<u8>, u32), String> {
    #[derive(Clone)]
    struct Cell {
        source_row: usize,
        participant_id: String,
        feature_set_id: String,
        feature_id: String,
        input_value: String,
        missing: bool,
    }

    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(bytes);
    let headers = reader
        .headers()
        .map_err(|error| format!("analysis feature matrix header: {error}"))?
        .clone();
    let participant = required_header(
        &headers,
        "participant_id",
        "chronicle.analysis-feature-missingness",
    )?;
    let feature_set = required_header(
        &headers,
        "feature_set_id",
        "chronicle.analysis-feature-missingness",
    )?;
    let feature = required_header(
        &headers,
        "feature_id",
        "chronicle.analysis-feature-missingness",
    )?;
    let value = required_header(&headers, "value", "chronicle.analysis-feature-missingness")?;
    let missing_state = required_header(
        &headers,
        "missing_state",
        "chronicle.analysis-feature-missingness",
    )?;

    let mut identities = BTreeSet::new();
    let mut cells = Vec::new();
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| format!("analysis feature matrix row: {error}"))?;
        let participant_id = record_value(&record, Some(participant));
        let feature_set_id = record_value(&record, Some(feature_set));
        let feature_id = record_value(&record, Some(feature));
        let input_value = record_value(&record, Some(value));
        if participant_id.is_empty() || feature_set_id.is_empty() || feature_id.is_empty() {
            return Err("analysis feature matrix identities must be non-empty".into());
        }
        let missing = match record_value(&record, Some(missing_state)) {
            "missing" => {
                if !input_value.is_empty() {
                    return Err(
                        "analysis feature matrix missing cells must have an empty value".into(),
                    );
                }
                true
            }
            "observed" => {
                if input_value
                    .parse::<f64>()
                    .ok()
                    .is_none_or(|value| !value.is_finite())
                {
                    return Err(
                        "analysis feature matrix observed cells require a finite numeric value"
                            .into(),
                    );
                }
                false
            }
            _ => {
                return Err(
                    "analysis feature matrix missing_state must be observed or missing".into(),
                )
            }
        };
        let identity = (
            feature_set_id.to_owned(),
            participant_id.to_owned(),
            feature_id.to_owned(),
        );
        if !identities.insert(identity) {
            return Err("analysis feature matrix contains a duplicate feature cell".into());
        }
        cells.push(Cell {
            source_row: index + 1,
            participant_id: participant_id.to_owned(),
            feature_set_id: feature_set_id.to_owned(),
            feature_id: feature_id.to_owned(),
            input_value: input_value.to_owned(),
            missing,
        });
    }
    if cells.is_empty() {
        return Err("analysis feature matrix requires at least one feature cell".into());
    }

    let mut participants_by_set = BTreeMap::<String, BTreeSet<String>>::new();
    let mut features_by_set = BTreeMap::<String, BTreeSet<String>>::new();
    let mut missing_by_feature = BTreeMap::<(String, String), usize>::new();
    for cell in &cells {
        participants_by_set
            .entry(cell.feature_set_id.clone())
            .or_default()
            .insert(cell.participant_id.clone());
        features_by_set
            .entry(cell.feature_set_id.clone())
            .or_default()
            .insert(cell.feature_id.clone());
        if cell.missing {
            *missing_by_feature
                .entry((cell.feature_set_id.clone(), cell.feature_id.clone()))
                .or_default() += 1;
        }
    }
    for (set_id, participants) in &participants_by_set {
        let feature_count = features_by_set
            .get(set_id)
            .map(BTreeSet::len)
            .unwrap_or_default();
        if participants.len().checked_mul(feature_count)
            != Some(
                cells
                    .iter()
                    .filter(|cell| cell.feature_set_id == *set_id)
                    .count(),
            )
        {
            return Err(format!(
                "analysis feature matrix feature set {set_id} is not rectangular"
            ));
        }
    }

    let retained_features = features_by_set
        .iter()
        .map(|(set_id, features)| {
            let retained = features
                .iter()
                .filter(|feature_id| {
                    missing_by_feature
                        .get(&(set_id.clone(), (*feature_id).clone()))
                        .copied()
                        .unwrap_or_default()
                        <= 30
                })
                .cloned()
                .collect::<BTreeSet<_>>();
            if retained.is_empty() {
                Err(format!(
                    "analysis feature matrix feature set {set_id} has no features after the >30-participant exclusion"
                ))
            } else {
                Ok((set_id.clone(), retained))
            }
        })
        .collect::<Result<BTreeMap<_, _>, String>>()?;
    let mut participant_missing = BTreeMap::<(String, String), usize>::new();
    for cell in &cells {
        if cell.missing
            && retained_features
                .get(&cell.feature_set_id)
                .is_some_and(|features| features.contains(&cell.feature_id))
        {
            *participant_missing
                .entry((cell.feature_set_id.clone(), cell.participant_id.clone()))
                .or_default() += 1;
        }
    }

    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_row",
            "participant_id",
            "feature_set_id",
            "feature_id",
            "input_value",
            "missing_state",
            "feature_missing_participant_count",
            "feature_retained",
            "participant_missing_feature_count",
            "participant_retained_feature_count",
            "participant_missing_fraction_percent",
            "participant_retained",
            "output_value",
            "disposition",
        ])
        .map_err(|error| format!("write analysis feature matrix header: {error}"))?;
    for cell in &cells {
        let feature_missing_count = missing_by_feature
            .get(&(cell.feature_set_id.clone(), cell.feature_id.clone()))
            .copied()
            .unwrap_or_default();
        let retained = retained_features
            .get(&cell.feature_set_id)
            .expect("feature set was registered");
        let feature_retained = retained.contains(&cell.feature_id);
        let participant_missing_count = participant_missing
            .get(&(cell.feature_set_id.clone(), cell.participant_id.clone()))
            .copied()
            .unwrap_or_default();
        let participant_retained = participant_missing_count * 5 < retained.len();
        let missing_percent = participant_missing_count as f64 * 100.0 / retained.len() as f64;
        let (output_value, disposition) = if !feature_retained {
            ("", "drop_feature")
        } else if !participant_retained {
            ("", "drop_participant")
        } else if cell.missing {
            ("-1", "impute_minus_one")
        } else {
            (cell.input_value.as_str(), "retain_observed")
        };
        writer
            .write_record([
                cell.source_row.to_string(),
                cell.participant_id.clone(),
                cell.feature_set_id.clone(),
                cell.feature_id.clone(),
                cell.input_value.clone(),
                if cell.missing { "missing" } else { "observed" }.to_string(),
                feature_missing_count.to_string(),
                feature_retained.to_string(),
                participant_missing_count.to_string(),
                retained.len().to_string(),
                format!("{missing_percent:.6}"),
                participant_retained.to_string(),
                output_value.to_string(),
                disposition.to_string(),
            ])
            .map_err(|error| format!("write analysis feature matrix row: {error}"))?;
    }
    let row_count = cells.len() as u32;
    let bytes = writer
        .into_inner()
        .map_err(|error| format!("finish analysis feature matrix CSV: {error}"))?;
    Ok((bytes, row_count))
}

/// Applies the existing analysis-feature missingness transform after enforcing
/// the stricter positive-observation boundary required by source bindings that
/// log-transform every observed feature value.
pub fn analysis_positive_feature_matrix_result(bytes: &[u8]) -> Result<(Vec<u8>, u32), String> {
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(bytes);
    let headers = reader
        .headers()
        .map_err(|error| format!("analysis positive feature matrix header: {error}"))?
        .clone();
    let value = required_header(
        &headers,
        "value",
        "chronicle.analysis-positive-feature-missingness",
    )?;
    let missing_state = required_header(
        &headers,
        "missing_state",
        "chronicle.analysis-positive-feature-missingness",
    )?;
    for (index, record) in reader.records().enumerate() {
        let record =
            record.map_err(|error| format!("analysis positive feature matrix row: {error}"))?;
        if record_value(&record, Some(missing_state)) == "observed"
            && record_value(&record, Some(value))
                .parse::<f64>()
                .ok()
                .is_none_or(|value| !value.is_finite() || value <= 0.0)
        {
            return Err(format!(
                "analysis positive feature matrix row {} requires a finite strictly positive observed value",
                index + 1
            ));
        }
    }
    analysis_feature_matrix_result(bytes)
}

type CallSmsEligibilityResult = (Vec<u8>, u32, Option<BTreeSet<String>>);

fn call_sms_eligibility_result(
    rows: &[csv::StringRecord],
    participant: usize,
    communication_modality: Option<usize>,
    support_bytes: &[u8],
    adapter_id: &str,
) -> Result<CallSmsEligibilityResult, String> {
    #[derive(Clone)]
    struct Claim {
        state: String,
        numerator: Option<u128>,
        denominator: Option<u128>,
    }

    let modality = communication_modality
        .ok_or_else(|| format!("{adapter_id} requires raw communication_modality"))?;
    let mut participants = BTreeSet::new();
    let mut event_counts = BTreeMap::<String, u128>::new();
    let mut call_counts = BTreeMap::<String, u128>::new();
    for row in rows {
        let participant_id = record_value(row, Some(participant));
        if participant_id.is_empty() {
            return Err(format!("{adapter_id} refuses an empty raw participant_id"));
        }
        participants.insert(participant_id.to_owned());
        match record_value(row, Some(modality)) {
            "" => {}
            "call" => {
                *event_counts.entry(participant_id.to_owned()).or_default() += 1;
                *call_counts.entry(participant_id.to_owned()).or_default() += 1;
            }
            "sms" => {
                *event_counts.entry(participant_id.to_owned()).or_default() += 1;
            }
            value => {
                return Err(format!(
                    "{adapter_id} refuses unknown communication_modality {value:?}"
                ));
            }
        }
    }
    if participants.is_empty() {
        return Err(format!(
            "{adapter_id} requires at least one raw participant"
        ));
    }

    let mut reader = csv::ReaderBuilder::new()
        .flexible(false)
        .from_reader(support_bytes);
    let headers = reader
        .headers()
        .map_err(|error| format!("call/SMS eligibility header: {error}"))?
        .clone();
    let support_participant = required_header(&headers, "participant_id", adapter_id)?;
    let scope = required_header(&headers, "modality_scope", adapter_id)?;
    let state = required_header(&headers, "availability_state", adapter_id)?;
    let numerator = required_header(&headers, "year_equivalent_exposure_numerator", adapter_id)?;
    let denominator =
        required_header(&headers, "year_equivalent_exposure_denominator", adapter_id)?;
    let mut claims = BTreeMap::<(String, String), Claim>::new();
    for record in reader.records() {
        let record = record.map_err(|error| format!("call/SMS eligibility row: {error}"))?;
        let participant_id = record_value(&record, Some(support_participant));
        let modality_scope = record_value(&record, Some(scope));
        let availability_state = record_value(&record, Some(state));
        let numerator_text = record_value(&record, Some(numerator));
        let denominator_text = record_value(&record, Some(denominator));
        if participant_id.is_empty() || !participants.contains(participant_id) {
            return Err(format!(
                "{adapter_id} support participant must occur in the raw participant roster"
            ));
        }
        if !matches!(modality_scope, "call" | "call_text_combined") {
            return Err(format!(
                "{adapter_id} modality_scope must be call or call_text_combined"
            ));
        }
        if !matches!(availability_state, "available" | "unavailable") {
            return Err(format!(
                "{adapter_id} availability_state must be available or unavailable"
            ));
        }
        let (parsed_numerator, parsed_denominator) = if modality_scope == "call_text_combined" {
            if availability_state != "available" {
                return Err(format!(
                    "{adapter_id} call_text_combined rows must be available"
                ));
            }
            let numerator = numerator_text
                .parse::<u128>()
                .ok()
                .filter(|value| *value > 0)
                .ok_or_else(|| format!("{adapter_id} requires a positive exposure numerator"))?;
            let denominator = denominator_text
                .parse::<u128>()
                .ok()
                .filter(|value| *value > 0)
                .ok_or_else(|| format!("{adapter_id} requires a positive exposure denominator"))?;
            (Some(numerator), Some(denominator))
        } else {
            if !numerator_text.is_empty() || !denominator_text.is_empty() {
                return Err(format!(
                    "{adapter_id} call availability rows must not carry an exposure rational"
                ));
            }
            (None, None)
        };
        let key = (participant_id.to_owned(), modality_scope.to_owned());
        if claims
            .insert(
                key,
                Claim {
                    state: availability_state.to_owned(),
                    numerator: parsed_numerator,
                    denominator: parsed_denominator,
                },
            )
            .is_some()
        {
            return Err(format!(
                "{adapter_id} refuses duplicate participant/modality claims"
            ));
        }
    }

    let expected_scope = if adapter_id == "chronicle.call-sms-volume-gate" {
        "call_text_combined"
    } else {
        "call"
    };
    let claimed_participants = claims
        .keys()
        .filter(|(_, scope)| scope == expected_scope)
        .map(|(participant, _)| participant.clone())
        .collect::<BTreeSet<_>>();
    if claimed_participants != participants {
        return Err(format!(
            "{adapter_id} requires exactly one {expected_scope} claim for every raw participant"
        ));
    }

    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "modality_scope",
            "availability_state",
            "year_equivalent_exposure_numerator",
            "year_equivalent_exposure_denominator",
            "qualifying_event_count",
            "threshold_per_source_year",
            "comparison",
            "retained_for_modality_analysis",
            "disposition",
        ])
        .map_err(|error| format!("write call/SMS eligibility header: {error}"))?;
    let mut retained = BTreeSet::new();
    for participant_id in &participants {
        let claim = claims
            .get(&(participant_id.clone(), expected_scope.to_owned()))
            .expect("complete participant claims checked above");
        let count = if expected_scope == "call" {
            call_counts.get(participant_id).copied().unwrap_or_default()
        } else {
            event_counts
                .get(participant_id)
                .copied()
                .unwrap_or_default()
        };
        let (threshold, comparison, keep, disposition) = if expected_scope == "call" {
            if claim.state == "unavailable" && count > 0 {
                return Err(format!(
                    "{adapter_id} refuses unavailable call data with observed call rows"
                ));
            }
            let keep = claim.state == "available";
            (
                String::new(),
                String::new(),
                keep,
                if keep {
                    "retain_available"
                } else {
                    "exclude_unavailable"
                },
            )
        } else {
            let numerator = claim.numerator.expect("volume numerator validated");
            let denominator = claim.denominator.expect("volume denominator validated");
            let observed = count.checked_mul(denominator).ok_or_else(|| {
                format!("{adapter_id} annualized event-count multiplication overflow")
            })?;
            let threshold = 300u128.checked_mul(numerator).ok_or_else(|| {
                format!("{adapter_id} annualized threshold multiplication overflow")
            })?;
            let keep = observed >= threshold;
            (
                "300".to_owned(),
                "strict_less_than".to_owned(),
                keep,
                if keep {
                    "retain_at_or_above_threshold"
                } else {
                    "exclude_below_threshold"
                },
            )
        };
        if keep {
            retained.insert(participant_id.clone());
        }
        writer
            .write_record([
                participant_id.as_str(),
                expected_scope,
                claim.state.as_str(),
                &claim
                    .numerator
                    .map(|value| value.to_string())
                    .unwrap_or_default(),
                &claim
                    .denominator
                    .map(|value| value.to_string())
                    .unwrap_or_default(),
                &count.to_string(),
                threshold.as_str(),
                comparison.as_str(),
                if keep { "true" } else { "false" },
                disposition,
            ])
            .map_err(|error| format!("write call/SMS eligibility row: {error}"))?;
    }
    let row_count = participants.len() as u32;
    let bytes = writer
        .into_inner()
        .map_err(|error| format!("finish call/SMS eligibility CSV: {error}"))?;
    Ok((
        bytes,
        row_count,
        (expected_scope == "call_text_combined").then_some(retained),
    ))
}

fn communication_schema_rule(
    setting_id: &str,
) -> Option<(
    &'static [&'static str],
    &'static [&'static str],
    &'static [&'static str],
)> {
    match setting_id {
        "method-setting-61c55253c3179344aa3a8fd4" => Some((&["sms"], &[], &[])),
        "method-setting-87c117dce02b18b1c43337ca" => Some((&["call"], &[], &[])),
        "method-setting-da2ee60471ce180dbf10dc33" => Some((
            &["call"],
            &[],
            &["outgoing", "incoming", "missed", "rejected"],
        )),
        "method-setting-7bf69fe3a08a25cf9b505b09" => {
            Some((&["sms"], &["incoming", "outgoing"], &[]))
        }
        "method-setting-9fe0c10a40a41753c58e7972" => {
            Some((&["call"], &["incoming", "outgoing"], &[]))
        }
        "method-setting-5a2759096c25874b86341554" => {
            Some((&["sms"], &[], &["incoming", "outgoing"]))
        }
        "method-setting-c2a2ca2509d736d4293e99f2" => {
            Some((&["call"], &[], &["incoming", "outgoing", "missed"]))
        }
        _ => None,
    }
}

fn strict_two_token_frame_result(
    rows: &[csv::StringRecord],
    headers: &csv::StringRecord,
    registration: &SourceSchemaRegistration,
) -> Result<(Vec<u8>, u32), String> {
    let participant = required_header(headers, "participant_id", "chronicle.source-event-schema")?;
    let source_order = required_header(headers, "source_order", "chronicle.source-event-schema")?;
    let timestamp = required_header(
        headers,
        "timestamp_coordinate",
        "chronicle.source-event-schema",
    )?;
    let source_event = required_header(
        headers,
        "source_event_type",
        "chronicle.source-event-schema",
    )?;
    let interaction =
        required_header(headers, "interaction_type", "chronicle.source-event-schema")?;
    let roles = registration
        .event_matches
        .iter()
        .map(|entry| {
            (
                entry.source_match_value.as_str(),
                entry.frame_role.as_deref().unwrap(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let mut previous_order = None;
    let mut open = BTreeMap::<String, (u32, i64, String, String)>::new();
    let mut frames = Vec::<(String, u32, u32, i64, i64, String, String, String, String)>::new();
    for (row_index, row) in rows.iter().enumerate() {
        let participant_id = record_value(row, Some(participant));
        if participant_id.is_empty() {
            return Err(format!(
                "chronicle.source-event-schema frame row {} requires participant_id",
                row_index + 1
            ));
        }
        let order = record_value(row, Some(source_order))
            .parse::<u32>()
            .map_err(|_| {
                format!(
                "chronicle.source-event-schema frame row {} requires unsigned integer source_order",
                row_index + 1
            )
            })?;
        if previous_order.is_some_and(|previous| order <= previous) {
            return Err("chronicle.source-event-schema requires source_order strictly increasing in source row order".into());
        }
        previous_order = Some(order);
        let coordinate = record_value(row, Some(timestamp))
            .parse::<i64>()
            .map_err(|_| {
                format!(
                "chronicle.source-event-schema frame row {} requires integer timestamp_coordinate",
                row_index + 1
            )
            })?;
        let source_token = row.get(source_event).unwrap_or_default();
        let canonical = record_value(row, Some(interaction));
        match roles.get(source_token).copied() {
            Some("start") => {
                if open
                    .insert(
                        participant_id.to_owned(),
                        (
                            order,
                            coordinate,
                            source_token.to_owned(),
                            canonical.to_owned(),
                        ),
                    )
                    .is_some()
                {
                    return Err(
                        "chronicle.source-event-schema refuses a repeated frame start".into(),
                    );
                }
            }
            Some("stop") => {
                let (start_order, start_coordinate, start_source, start_canonical) =
                    open.remove(participant_id).ok_or_else(|| {
                        "chronicle.source-event-schema refuses an orphan frame stop".to_string()
                    })?;
                if coordinate <= start_coordinate {
                    return Err(
                        "chronicle.source-event-schema requires a frame stop after its start"
                            .into(),
                    );
                }
                frames.push((
                    participant_id.to_owned(),
                    start_order,
                    order,
                    start_coordinate,
                    coordinate,
                    start_source,
                    source_token.to_owned(),
                    start_canonical,
                    canonical.to_owned(),
                ));
            }
            _ => {
                return Err("chronicle.source-event-schema frame row is outside the registered two-token set".into());
            }
        }
    }
    if !open.is_empty() {
        return Err("chronicle.source-event-schema refuses an unclosed frame".into());
    }
    if frames.is_empty() {
        return Err("chronicle.source-event-schema found no complete frame".into());
    }
    frames.sort_by_key(|frame| frame.1);
    let row_count = u32::try_from(frames.len())
        .map_err(|_| "chronicle.source-event-schema frame count overflow")?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "start_source_order",
            "stop_source_order",
            "start_timestamp_coordinate",
            "stop_timestamp_coordinate",
            "start_source_event_type",
            "stop_source_event_type",
            "start_interaction_type",
            "stop_interaction_type",
        ])
        .map_err(|error| format!("chronicle.source-event-schema write frame header: {error}"))?;
    for frame in frames {
        writer
            .serialize(frame)
            .map_err(|error| format!("chronicle.source-event-schema write frame: {error}"))?;
    }
    let bytes = writer
        .into_inner()
        .map_err(|error| format!("chronicle.source-event-schema finish frame CSV: {error}"))?;
    Ok((bytes, row_count))
}

