fn parse_python_float(value: &str, field: &str, row_index: usize) -> Result<f64, String> {
    match value {
        "NaN" | "nan" => Ok(f64::NAN),
        "Inf" | "inf" | "Infinity" => Ok(f64::INFINITY),
        "-Inf" | "-inf" | "-Infinity" => Ok(f64::NEG_INFINITY),
        value => value
            .parse::<f64>()
            .map_err(|_| format!("row {row_index} requires a Python numeric {field}")),
    }
}

fn format_python_float(value: f64) -> String {
    if value.is_nan() {
        "NaN".to_owned()
    } else if value == f64::INFINITY {
        "inf".to_owned()
    } else if value == f64::NEG_INFINITY {
        "-inf".to_owned()
    } else {
        value.to_string()
    }
}

// prediction.py:131–152, c9e3238c1d15d7e9837287e3c98a4b8b012c4ece,
// SHA256 adb01866c722f2de0936c64fa7a444eb0060672bfb00af1968d53260f21665d6.
// This CSV is Chronicle's carrier for prepared numeric values, not an author
// output CSV or a raw-event constructor. Duration units remain undisclosed.
fn rabbit_hole_prepared_features_csv(raw_csv: &[u8]) -> Result<(Vec<u8>, usize), String> {
    let adapter = RABBIT_HOLE_PREPARED_FEATURES_ADAPTER;
    let mut reader = csv::Reader::from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} requires unique prepared column names"));
    }
    let source_row = required_header(&headers, "source_row_id", adapter)?;
    let clicks = required_header(&headers, "f_clicks", adapter)?;
    let scrolls = required_header(&headers, "f_scrolls", adapter)?;
    let duration = required_header(&headers, "f_session_length", adapter)?;
    let weighted_columns = |pattern: &str| -> Result<Vec<(usize, f64)>, String> {
        headers
            .iter()
            .enumerate()
            .filter(|(_, name)| name.contains(pattern))
            .map(|(column, name)| {
                parse_python_float(name.rsplit('_').next().unwrap().trim(), name, 0)
                    .map(|weight| (column, weight))
                    .map_err(|error| format!("{adapter} header suffix: {error}"))
            })
            .collect()
    };
    let hour_columns = weighted_columns("f_hour_of_day_")?;
    let weekday_columns = weighted_columns("f_weekday_")?;
    let mut writer = csv::Writer::from_writer(Vec::new());
    writer
        .write_record([
            "source_row_id",
            "f_hour_of_day",
            "f_weekday",
            "f_click_frequency",
            "f_scroll_frequency",
        ])
        .map_err(|error| format!("{adapter} output header: {error}"))?;
    let mut rows = 0;
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| format!("{adapter} row {}: {error}", index + 1))?;
        let id = record_value(&record, Some(source_row));
        if id.is_empty() {
            return Err(format!("{adapter} row {} requires source_row_id", index + 1));
        }
        let numeric = |column| -> Result<f64, String> {
            let raw = record_value(&record, Some(column));
            let value = if raw.is_empty() {
                0.0
            } else {
                parse_python_float(raw.trim(), &headers[column], index + 1)?
            };
            Ok(if value.is_nan() { 0.0 } else { value })
        };
        let weighted_sum = |columns: &[(usize, f64)]| -> Result<f64, String> {
            columns.iter().try_fold(0.0, |sum, (column, weight)| {
                Ok(sum + numeric(*column)? * weight)
            })
        };
        let denominator = numeric(duration)?;
        writer
            .write_record([
                id.to_owned(),
                format_python_float(weighted_sum(&hour_columns)?),
                format_python_float(weighted_sum(&weekday_columns)?),
                format_python_float(numeric(clicks)? / denominator),
                format_python_float(numeric(scrolls)? / denominator),
            ])
            .map_err(|error| format!("{adapter} row {} output: {error}", index + 1))?;
        rows += 1;
    }
    let output = writer
        .into_inner()
        .map_err(|error| format!("{adapter} output: {error}"))?;
    Ok((output, rows))
}

