// One owner for the already-supported equal-bound/even-half arithmetic. The
// legacy event carrier and the qualified second inventory retain their distinct
// validation and scope; neither caller invents an odd-half allocation.
fn screen_missing_gap_replacement_states<T: Copy + Eq>(
    left: T,
    right: T,
    gap_len: usize,
    fill_equal: bool,
    split_unequal: bool,
) -> Result<Option<Vec<T>>, String> {
    if left == right {
        return Ok(fill_equal.then(|| vec![left; gap_len]));
    }
    if !split_unequal {
        return Ok(None);
    }
    if !gap_len.is_multiple_of(2) {
        return Err("chronicle.screen-missing-gap-fill refuses an odd gap because the source requires two equal parts but gives no tie rule".into());
    }
    Ok(Some((0..gap_len).map(|offset| if offset < gap_len / 2 { left } else { right }).collect()))
}

