fn adapt_supplied_context_sequence(
    adapter: &str,
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let mut allowed_features = BTreeSet::new();
    for binding in bindings {
        let registration = contract_by_setting()?.get(&binding.setting_id)
            .ok_or("supplied context component requires exact registered ownership")?;
        if let Some(keys) = registration.component_config.as_ref()
            .and_then(|config| config.get("featureKeysBySetting"))
            .and_then(|map| map.get(&binding.setting_id))
        {
            for key in keys.as_array().ok_or("invalid fixed feature owner list")? {
                allowed_features.insert(key.as_str().ok_or("invalid fixed feature key")?.to_owned());
            }
        }
    }
    let (output, source, emitted) = supplied_context_sequence::execute(adapter, raw_csv, &allowed_features)?;
    complete_standalone_component_adaptation(adapter, "literature-supplied-context-sequence-csv", original_input_digest, bindings, source, emitted, output)
}

