fn adapt_call_state_summary(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{CALL_STATE_SUMMARY_ADAPTER} has no registered component"))?;
    let config: CallStateSummaryComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{CALL_STATE_SUMMARY_ADAPTER} requires componentConfig"))?,
    )
    .map_err(|error| format!("invalid {CALL_STATE_SUMMARY_ADAPTER} componentConfig: {error}"))?;
    if config.exact_state_tokens != ["incoming", "outgoing", "missed"]
        || config.total_row_policy != "all_supplied_rows_including_missing_and_unrecognized"
        || config.response_rate_denominator != "incoming_plus_missed"
        || config.zero_denominator != "NaN"
    {
        return Err(format!(
            "{CALL_STATE_SUMMARY_ADAPTER} componentConfig drifts from the released source"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{CALL_STATE_SUMMARY_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", CALL_STATE_SUMMARY_ADAPTER)?;
    let state = required_header(&headers, "state", CALL_STATE_SUMMARY_ADAPTER)?;
    let mut states = Vec::<Option<String>>::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{CALL_STATE_SUMMARY_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        if record_value(&record, Some(source_row)).is_empty() {
            return Err(format!(
                "{CALL_STATE_SUMMARY_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let state = record_value(&record, Some(state));
        states.push((!state.is_empty()).then(|| state.to_owned()));
    }
    let state_refs = states
        .iter()
        .map(|state| state.as_deref())
        .collect::<Vec<_>>();
    let summary = summarize_call_states(&state_refs);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "incoming_count",
            "outgoing_count",
            "total_count",
            "missed_count",
            "incoming_response_rate",
        ])
        .map_err(|error| format!("{CALL_STATE_SUMMARY_ADAPTER} write header: {error}"))?;
    writer
        .write_record([
            summary.incoming_count.to_string(),
            summary.outgoing_count.to_string(),
            summary.total_count.to_string(),
            summary.missed_count.to_string(),
            format_python_float(summary.incoming_response_rate),
        ])
        .map_err(|error| format!("{CALL_STATE_SUMMARY_ADAPTER} write row: {error}"))?;
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{CALL_STATE_SUMMARY_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        CALL_STATE_SUMMARY_ADAPTER,
        "literature-call-state-summary-csv",
        original_input_digest,
        bindings,
        states.len(),
        1,
        csv_bytes,
    )
}

fn adapt_call_duration_summary(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{CALL_DURATION_SUMMARY_ADAPTER} has no registered component"))?;
    let config: CallDurationSummaryComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{CALL_DURATION_SUMMARY_ADAPTER} requires componentConfig"))?,
    )
    .map_err(|error| format!("invalid {CALL_DURATION_SUMMARY_ADAPTER} componentConfig: {error}"))?;
    if config.exact_state_tokens != ["incoming", "outgoing"]
        || config.units_per_minute != 60_000.0
        || config.summation_order != "source_row_order_python_builtin_sum"
    {
        return Err(format!(
            "{CALL_DURATION_SUMMARY_ADAPTER} componentConfig drifts from the released source"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{CALL_DURATION_SUMMARY_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", CALL_DURATION_SUMMARY_ADAPTER)?;
    let state = required_header(&headers, "state", CALL_DURATION_SUMMARY_ADAPTER)?;
    let overlap = required_header(&headers, "overlap", CALL_DURATION_SUMMARY_ADAPTER)?;
    let mut rows = Vec::<(Option<String>, f64)>::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{CALL_DURATION_SUMMARY_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        if record_value(&record, Some(source_row)).is_empty() {
            return Err(format!(
                "{CALL_DURATION_SUMMARY_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let state = record_value(&record, Some(state));
        rows.push((
            (!state.is_empty()).then(|| state.to_owned()),
            parse_python_float(
                record_value(&record, Some(overlap)),
                "overlap",
                row_index + 1,
            )?,
        ));
    }
    let overlaps = rows
        .iter()
        .map(|(state, overlap)| CallOverlap {
            state: state.as_deref(),
            overlap: *overlap,
        })
        .collect::<Vec<_>>();
    let summary =
        summarize_call_overlap_durations(&overlaps, config.units_per_minute).map_err(|_| {
            format!("{CALL_DURATION_SUMMARY_ADAPTER} requires finite positive units_per_minute")
        })?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["incoming_minutes", "total_minutes", "outgoing_minutes"])
        .map_err(|error| format!("{CALL_DURATION_SUMMARY_ADAPTER} write header: {error}"))?;
    writer
        .write_record([
            format_python_float(summary.incoming_minutes),
            format_python_float(summary.total_minutes),
            format_python_float(summary.outgoing_minutes),
        ])
        .map_err(|error| format!("{CALL_DURATION_SUMMARY_ADAPTER} write row: {error}"))?;
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{CALL_DURATION_SUMMARY_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        CALL_DURATION_SUMMARY_ADAPTER,
        "literature-call-duration-summary-csv",
        original_input_digest,
        bindings,
        rows.len(),
        1,
        csv_bytes,
    )
}

fn adapt_grouped_category_count(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{GROUPED_CATEGORY_COUNT_ADAPTER} has no registered component"))?;
    let config: GroupedCategoryCountComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{GROUPED_CATEGORY_COUNT_ADAPTER} requires componentConfig"))?,
    )
    .map_err(|error| {
        format!("invalid {GROUPED_CATEGORY_COUNT_ADAPTER} componentConfig: {error}")
    })?;
    let expected = BTreeMap::from([
        (
            "foreground_app_use".to_owned(),
            vec!["foreground_app_use".to_owned()],
        ),
        (
            "internet".to_owned(),
            vec!["connected".to_owned(), "disconnected".to_owned()],
        ),
        (
            "screen".to_owned(),
            vec!["screen_on".to_owned(), "screen_off".to_owned()],
        ),
    ]);
    if config.allowed_categories_by_stream != expected
        || config.group_scope != "stream_participant_source_day"
        || config.absent_group_policy != "do_not_synthesize_or_zero_fill"
    {
        return Err(format!(
            "{GROUPED_CATEGORY_COUNT_ADAPTER} componentConfig drifts from the bounded source"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{GROUPED_CATEGORY_COUNT_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", GROUPED_CATEGORY_COUNT_ADAPTER)?;
    let stream = required_header(&headers, "stream_id", GROUPED_CATEGORY_COUNT_ADAPTER)?;
    let participant = required_header(&headers, "participant_id", GROUPED_CATEGORY_COUNT_ADAPTER)?;
    let day = required_header(&headers, "source_day_id", GROUPED_CATEGORY_COUNT_ADAPTER)?;
    let category = required_header(&headers, "category", GROUPED_CATEGORY_COUNT_ADAPTER)?;
    let mut observations = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{GROUPED_CATEGORY_COUNT_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let row_values = [source_row, stream, participant, day, category]
            .map(|column| record_value(&record, Some(column)));
        if row_values.iter().any(|value| value.is_empty()) {
            return Err(format!(
                "{GROUPED_CATEGORY_COUNT_ADAPTER} row {} requires every declared field",
                row_index + 1
            ));
        }
        let allowed = config
            .allowed_categories_by_stream
            .get(row_values[1])
            .is_some_and(|allowed| allowed.iter().any(|value| value == row_values[4]));
        if !allowed {
            return Err(format!(
                "{GROUPED_CATEGORY_COUNT_ADAPTER} row {} has an unregistered stream/category pair",
                row_index + 1
            ));
        }
        observations.push((
            (
                row_values[1].to_owned(),
                row_values[2].to_owned(),
                row_values[3].to_owned(),
            ),
            row_values[4].to_owned(),
        ));
    }
    let counts = count_categories_by_group(observations.iter().cloned());
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "stream_id",
            "participant_id",
            "source_day_id",
            "category",
            "observation_count",
        ])
        .map_err(|error| format!("{GROUPED_CATEGORY_COUNT_ADAPTER} write header: {error}"))?;
    for count in &counts {
        writer
            .serialize((
                count.group.0.as_str(),
                count.group.1.as_str(),
                count.group.2.as_str(),
                count.category.as_str(),
                count.observation_count,
            ))
            .map_err(|error| format!("{GROUPED_CATEGORY_COUNT_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{GROUPED_CATEGORY_COUNT_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        GROUPED_CATEGORY_COUNT_ADAPTER,
        "literature-grouped-category-count-csv",
        original_input_digest,
        bindings,
        observations.len(),
        counts.len(),
        csv_bytes,
    )
}

fn adapt_grouped_scalar_extrema(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} has no registered component"))?;
    let config: GroupedScalarExtremaComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} requires componentConfig"))?,
    )
    .map_err(|error| {
        format!("invalid {GROUPED_SCALAR_EXTREMA_ADAPTER} componentConfig: {error}")
    })?;
    if config.group_scope != "participant_source_day"
        || config.coordinate != "integer_minutes_from_source_local_hour_zero"
        || config.integral_domain != [0, 1439]
        || config.absent_group_policy != "do_not_synthesize_or_zero_fill"
    {
        return Err(format!(
            "{GROUPED_SCALAR_EXTREMA_ADAPTER} componentConfig drifts from the bounded source"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", GROUPED_SCALAR_EXTREMA_ADAPTER)?;
    let participant = required_header(&headers, "participant_id", GROUPED_SCALAR_EXTREMA_ADAPTER)?;
    let day = required_header(&headers, "source_day_id", GROUPED_SCALAR_EXTREMA_ADAPTER)?;
    let minutes = required_header(
        &headers,
        "minutes_from_hour_zero",
        GROUPED_SCALAR_EXTREMA_ADAPTER,
    )?;
    let mut observations = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{GROUPED_SCALAR_EXTREMA_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let source_row_id = record_value(&record, Some(source_row));
        let participant_id = record_value(&record, Some(participant));
        let source_day_id = record_value(&record, Some(day));
        if source_row_id.is_empty() || participant_id.is_empty() || source_day_id.is_empty() {
            return Err(format!(
                "{GROUPED_SCALAR_EXTREMA_ADAPTER} row {} requires every identity field",
                row_index + 1
            ));
        }
        let minute = record_value(&record, Some(minutes))
            .parse::<u16>()
            .map_err(|_| {
                format!(
                    "{GROUPED_SCALAR_EXTREMA_ADAPTER} row {} requires an integer minute in [0,1440)",
                    row_index + 1
                )
            })?;
        if minute >= 1440 {
            return Err(format!(
                "{GROUPED_SCALAR_EXTREMA_ADAPTER} row {} requires an integer minute in [0,1440)",
                row_index + 1
            ));
        }
        observations.push((
            (participant_id.to_owned(), source_day_id.to_owned()),
            f64::from(minute),
        ));
    }
    let extrema = finite_scalar_extrema_by_group(observations.iter().cloned())
        .map_err(|_| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} refuses non-finite input"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "source_day_id",
            "first_use_minutes",
            "last_use_minutes",
        ])
        .map_err(|error| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} write header: {error}"))?;
    for row in &extrema {
        writer
            .serialize((
                row.group.0.as_str(),
                row.group.1.as_str(),
                row.minimum as u16,
                row.maximum as u16,
            ))
            .map_err(|error| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{GROUPED_SCALAR_EXTREMA_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        GROUPED_SCALAR_EXTREMA_ADAPTER,
        "literature-grouped-scalar-extrema-csv",
        original_input_digest,
        bindings,
        observations.len(),
        extrema.len(),
        csv_bytes,
    )
}

fn adapt_scan_signal_proximity_summary(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} has no registered component")
        })?;
    let config: ScanSignalProximitySummaryComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} componentConfig: {error}")
        })?;
    if config.above_exclusive_lower != -70.0
        || config.inclusive_lower != -90.0
        || config.inclusive_upper != -70.0
        || config.above_weight != 1.0
        || config.within_weight != 3.0
        || config.empty_scan_encoding != "one_row_with_empty_signal"
    {
        return Err(format!(
            "{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} componentConfig drifts from the released source"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} header: {error}"))?
        .clone();
    let scan_id = required_header(&headers, "scan_id", SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER)?;
    let signal = required_header(&headers, "signal", SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER)?;
    let mut scans = BTreeMap::<String, Vec<f64>>::new();
    let mut empty_sentinels = BTreeSet::<String>::new();
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let scan = record_value(&record, Some(scan_id));
        if scan.is_empty() {
            return Err(format!(
                "{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} row {} has empty scan_id",
                row_index + 1
            ));
        }
        let signal_text = record_value(&record, Some(signal));
        if signal_text.is_empty() {
            if scans.get(scan).is_some_and(|values| !values.is_empty())
                || !empty_sentinels.insert(scan.to_owned())
            {
                return Err(format!(
                    "{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} scan {scan} mixes or duplicates the empty-scan sentinel"
                ));
            }
            scans.entry(scan.to_owned()).or_default();
        } else {
            if empty_sentinels.contains(scan) {
                return Err(format!(
                    "{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} scan {scan} mixes signals with the empty-scan sentinel"
                ));
            }
            scans
                .entry(scan.to_owned())
                .or_default()
                .push(parse_python_float(signal_text, "signal", row_index + 1)?);
        }
    }
    let scans = scans.into_values().collect::<Vec<_>>();
    let summary = summarize_scan_signal_proximity(
        &scans,
        ScanSignalProximityConfig {
            above_exclusive_lower: config.above_exclusive_lower,
            inclusive_lower: config.inclusive_lower,
            inclusive_upper: config.inclusive_upper,
            above_weight: config.above_weight,
            within_weight: config.within_weight,
        },
    )
    .map_err(|error| format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER}: {error:?}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "observations_per_scan",
            "above_per_scan",
            "within_per_scan",
            "weighted_proximity_mean",
        ])
        .map_err(|error| {
            format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} write header: {error}")
        })?;
    writer
        .write_record([
            format_python_float(summary.observations_per_scan),
            format_python_float(summary.above_per_scan),
            format_python_float(summary.within_per_scan),
            format_python_float(summary.weighted_proximity_mean),
        ])
        .map_err(|error| format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} write row: {error}"))?;
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        SCAN_SIGNAL_PROXIMITY_SUMMARY_ADAPTER,
        "literature-scan-signal-proximity-summary-csv",
        original_input_digest,
        bindings,
        source_row_count,
        1,
        csv_bytes,
    )
}

fn adapt_finite_scalar_pivot_classifier(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} has no registered component")
        })?;
    let config: FiniteScalarPivotClassifierComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} componentConfig: {error}")
        })?;
    if config.pivot != 4.0
        || config.below_label != -1
        || config.equal_label != 0
        || config.above_label != 1
        || config.comparison_tolerance != 0.0
    {
        return Err(format!(
            "{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} componentConfig drifts from the disclosed exact pivot"
        ));
    }
    let classifier = FiniteScalarPivotClassifier::new(
        config.pivot,
        config.below_label,
        config.equal_label,
        config.above_label,
    )
    .map_err(|error| format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER}: {error}"))?;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER,
    )?;
    let score = required_header(&headers, "score", FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER)?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", "score", "label"])
        .map_err(|error| {
            format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} write header: {error}")
        })?;
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let source_row_id = record_value(&record, Some(source_row));
        if source_row_id.is_empty() {
            return Err(format!(
                "{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let value = record_value(&record, Some(score))
            .parse::<f64>()
            .map_err(|_| {
                format!(
                    "{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} row {} requires a finite score",
                    row_index + 1
                )
            })?;
        let label = classifier.category_for(value).map_err(|error| {
            format!(
                "{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        writer
            .serialize((source_row_id, value, label))
            .map_err(|error| {
                format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        FINITE_SCALAR_PIVOT_CLASSIFIER_ADAPTER,
        "literature-finite-scalar-pivot-classifier-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )
}

fn adapt_distance_matrix_medoid(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER} has no registered component"))?;
    let config: DistanceMatrixMedoidComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER} requires componentConfig"))?,
    )
    .map_err(|error| {
        format!("invalid {DISTANCE_MATRIX_MEDOID_ADAPTER} componentConfig: {error}")
    })?;
    if config.reduction_axis != "columns"
        || config.tie_policy != "first_minimum"
        || config.two_point_policy != "first_point"
        || config.matrix_column_prefix != "distance_"
        || config.malformed_matrix_policy != "fail_closed"
    {
        return Err(format!(
            "{DISTANCE_MATRIX_MEDOID_ADAPTER} componentConfig is outside the implemented bounded semantics"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER} header: {error}"))?
        .clone();
    let point_id = required_header(&headers, "point_id", DISTANCE_MATRIX_MEDOID_ADAPTER)?;
    if point_id != 0 || headers.len() < 2 {
        return Err(format!(
            "{DISTANCE_MATRIX_MEDOID_ADAPTER} requires point_id followed by distance_0..distance_n_minus_1"
        ));
    }
    let point_count = headers.len() - 1;
    for column_index in 0..point_count {
        let expected = format!("{}{}", config.matrix_column_prefix, column_index);
        if headers.get(column_index + 1) != Some(expected.as_str()) {
            return Err(format!(
                "{DISTANCE_MATRIX_MEDOID_ADAPTER} requires contiguous distance columns; expected {expected}"
            ));
        }
    }
    let mut point_ids = Vec::new();
    let mut seen_point_ids = BTreeSet::new();
    let mut matrix = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{DISTANCE_MATRIX_MEDOID_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let id = record_value(&record, Some(point_id));
        if id.is_empty() || !seen_point_ids.insert(id.to_owned()) {
            return Err(format!(
                "{DISTANCE_MATRIX_MEDOID_ADAPTER} row {} requires a unique nonempty point_id",
                row_index + 1
            ));
        }
        let mut row = Vec::with_capacity(point_count);
        for column_index in 0..point_count {
            let value = record_value(&record, Some(column_index + 1))
                .parse::<f64>()
                .map_err(|_| {
                    format!(
                        "{DISTANCE_MATRIX_MEDOID_ADAPTER} row {} distance_{column_index} must be finite",
                        row_index + 1
                    )
                })?;
            if !value.is_finite() {
                return Err(format!(
                    "{DISTANCE_MATRIX_MEDOID_ADAPTER} row {} distance_{column_index} must be finite",
                    row_index + 1
                ));
            }
            row.push(value);
        }
        point_ids.push(id.to_owned());
        matrix.push(row);
    }
    if matrix.len() != point_count {
        return Err(format!(
            "{DISTANCE_MATRIX_MEDOID_ADAPTER} requires a square matrix: {} rows for {point_count} distance columns",
            matrix.len()
        ));
    }
    let medoid_index = distance_matrix_medoid_index(&matrix)
        .map_err(|error| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER}: {error:?}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["medoid_index", "point_id"])
        .map_err(|error| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER} write header: {error}"))?;
    writer
        .serialize((medoid_index, &point_ids[medoid_index]))
        .map_err(|error| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER} write row: {error}"))?;
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{DISTANCE_MATRIX_MEDOID_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        DISTANCE_MATRIX_MEDOID_ADAPTER,
        "literature-distance-matrix-medoid-csv",
        original_input_digest,
        bindings,
        point_count,
        1,
        csv_bytes,
    )
}

fn adapt_named_count_ratios(
    adapter_id: &str,
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter_id} has no registered component"))?;
    let config: NamedCountRatiosComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{adapter_id} requires componentConfig"))?,
    )
    .map_err(|error| format!("invalid {adapter_id} componentConfig: {error}"))?;
    if config.ratios.is_empty()
        || config.zero_denominator_policy != "fail_closed"
        || config.denominator_overflow_policy != "fail_closed"
    {
        return Err(format!(
            "{adapter_id} componentConfig is incomplete"
        ));
    }
    let mut ratio_ids = BTreeSet::new();
    if config.ratios.iter().any(|ratio| {
        ratio.ratio_id.is_empty()
            || ratio.numerator_field.is_empty()
            || ratio.denominator_fields.is_empty()
            || !ratio_ids.insert(ratio.ratio_id.clone())
    }) {
        return Err(format!(
            "{adapter_id} requires unique named ratios with denominator terms"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter_id} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", adapter_id)?;
    if adapter_id != NAMED_COUNT_RATIOS_ADAPTER
        && headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
    {
        return Err(format!("{adapter_id} refuses duplicate column names"));
    }
    let mut records = reader.records();
    let record = records
        .next()
        .ok_or_else(|| format!("{adapter_id} requires exactly one count row"))?
        .map_err(|error| format!("{adapter_id} row 1: {error}"))?;
    if records.next().is_some() {
        return Err(format!(
            "{adapter_id} requires exactly one count row"
        ));
    }
    if record_value(&record, Some(source_row)).is_empty() {
        return Err(format!(
            "{adapter_id} requires a nonempty source_row_id"
        ));
    }
    let parse_count = |field: &str| -> Result<u64, String> {
        let index = required_header(&headers, field, adapter_id)?;
        record_value(&record, Some(index))
            .parse::<u64>()
            .map_err(|_| {
                format!("{adapter_id} field {field} requires a nonnegative integer")
            })
    };
    let requests = config
        .ratios
        .iter()
        .map(|ratio| {
            Ok(CountRatioRequest {
                name: ratio.ratio_id.clone(),
                numerator: parse_count(&ratio.numerator_field)?,
                denominator_terms: ratio
                    .denominator_fields
                    .iter()
                    .map(|field| parse_count(field))
                    .collect::<Result<Vec<_>, _>>()?,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    let ratios = construct_named_count_ratios(requests)
        .map_err(|error| format!("{adapter_id}: {error}"))?;
    let scope_fields: &[&str] = match adapter_id {
        CLASS_RINGER_FRACTIONS_ADAPTER => &["participant_id", "class_scope_id"],
        APP_POSTPONE_FRACTION_ADAPTER => &["app_id", "call_scope_id"],
        HEALTHYMIND_NOTIFICATION_RATES_ADAPTER => &["participant_id", "notification_count_scope_id", "count_stage"],
        _ => &[],
    };
    let scope_values = scope_fields.iter().map(|field| {
        let column = required_header(&headers, field, adapter_id)?;
        let value = record.get(column).unwrap_or_default();
        if value.is_empty() {
            return Err(format!("{adapter_id} requires a nonempty {field}"));
        }
        Ok(value.to_owned())
    }).collect::<Result<Vec<_>, String>>()?;
    if adapter_id == HEALTHYMIND_NOTIFICATION_RATES_ADAPTER
        && (scope_values.iter().any(|value| value.trim().is_empty())
            || scope_values[2] != "caller-resolved-notification-counts")
    {
        return Err(format!("{adapter_id} requires an explicit participant/count scope and caller-resolved-notification-counts count_stage"));
    }
    if !scope_fields.is_empty()
        && ratios.iter().any(|ratio| ratio.ratio.numerator > ratio.ratio.denominator)
    {
        return Err(format!("{adapter_id} requires each numerator <= its own denominator"));
    }
    let mut output_headers = scope_fields.iter().copied()
        .chain(["ratio_id", "numerator", "denominator", "ratio"]).collect::<Vec<_>>();
    if adapter_id == HEALTHYMIND_NOTIFICATION_RATES_ADAPTER {
        output_headers.push("percent");
    }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(output_headers)
        .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    for ratio in &ratios {
        let mut fields = scope_values.clone();
        fields.extend([
            ratio.name.clone(),
            ratio.ratio.numerator.to_string(),
            ratio.ratio.denominator.to_string(),
            format_python_float(ratio.ratio.value()),
        ]);
        if adapter_id == HEALTHYMIND_NOTIFICATION_RATES_ADAPTER {
            fields.push(format_python_float(ratio.ratio.value() * 100.0));
        }
        writer
            .write_record(fields)
            .map_err(|error| format!("{adapter_id} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{adapter_id} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        adapter_id,
        "literature-named-count-ratios-csv",
        original_input_digest,
        bindings,
        1,
        ratios.len(),
        csv_bytes,
    )
}

fn parse_source_bound_scalar(
    encoded: &str,
    input_domain: &str,
    adapter_id: &str,
    row_index: usize,
    input_field: &str,
) -> Result<f64, String> {
    let value = match input_domain {
        "unsigned_integer" => encoded
            .parse::<u64>()
            .map(|value| value as f64)
            .map_err(|_| ()),
        "integer" => encoded
            .parse::<i64>()
            .map(|value| value as f64)
            .map_err(|_| ()),
        "finite_nonnegative" | "finite" => encoded.parse::<f64>().map_err(|_| ()),
        "boolean" => match encoded {
            "false" => Ok(0.0),
            "true" => Ok(1.0),
            _ => Err(()),
        },
        _ => unreachable!("validated input domain"),
    }
    .map_err(|_| {
        format!(
            "{adapter_id} row {row_index} field {input_field} violates input domain {input_domain}"
        )
    })?;
    if !value.is_finite() || (input_domain == "finite_nonnegative" && value < 0.0) {
        return Err(format!(
            "{adapter_id} row {row_index} field {input_field} violates input domain {input_domain}"
        ));
    }
    Ok(value)
}

fn adapt_source_bound_scalar_predicate(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
    adapter_id: &'static str,
) -> Result<AdaptedLiteratureInput, String> {
    let prepared_stage = ANDROID_PREPARED_PREDICATE_STAGES.iter()
        .find_map(|(id, stage)| (*id == adapter_id).then_some(*stage));
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter_id} has no registered component"))?;
    let config: SourceBoundScalarPredicateComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{adapter_id} requires componentConfig"))?,
    )
    .map_err(|error| format!("invalid {adapter_id} componentConfig: {error}"))?;
    let pivot_field_is_complete =
        config.pivot_field.is_some() && config.pivot_field_domain.is_some();
    let fixed_pivot_is_selected = config.pivot.is_some() && config.pivot_field.is_none();
    if config.input_field.is_empty()
        || config.comparison_tolerance != 0.0
        || !(fixed_pivot_is_selected || (config.pivot.is_none() && pivot_field_is_complete))
        || config.pivot.is_some_and(|pivot| !pivot.is_finite())
        || config
            .pivot_field
            .as_ref()
            .is_some_and(|field| field.is_empty())
        || config.pivot_field.is_none() != config.pivot_field_domain.is_none()
        || config.pivot_field_domain.as_deref().is_some_and(|domain| {
            !matches!(
                domain,
                "unsigned_integer" | "integer" | "finite_nonnegative" | "finite"
            )
        })
        || config.below_disposition.is_empty()
        || config.equal_disposition.is_empty()
        || config.above_disposition.is_empty()
        || !matches!(
            config.input_domain.as_str(),
            "unsigned_integer" | "integer" | "finite_nonnegative" | "finite" | "boolean"
        )
        || !matches!(
            config.operator.as_str(),
            "ordered_threshold_bucketizer" | "finite_scalar_pivot_classifier"
        )
        || config.inclusive_minimum.is_some() != config.inclusive_maximum.is_some()
        || config
            .inclusive_minimum
            .zip(config.inclusive_maximum)
            .is_some_and(|(minimum, maximum)| {
                !minimum.is_finite() || !maximum.is_finite() || minimum > maximum
            })
        || config.required_exact_context.iter().any(|context| {
            context.input_field.is_empty()
                || !context.exact_value.is_finite()
                || !matches!(
                    context.input_domain.as_str(),
                    "unsigned_integer" | "integer" | "finite_nonnegative" | "finite"
                )
                || (context.input_domain == "unsigned_integer"
                    && (context.exact_value < 0.0 || context.exact_value.fract() != 0.0))
                || (context.input_domain == "integer" && context.exact_value.fract() != 0.0)
                || (context.input_domain == "finite_nonnegative" && context.exact_value < 0.0)
        })
        || (config.operator == "ordered_threshold_bucketizer"
            && config.equal_disposition != config.above_disposition)
    {
        return Err(format!(
            "{adapter_id} componentConfig is outside the generic exact-comparison contract"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter_id} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter_id} refuses duplicate headers"));
    }
    let stage_column = prepared_stage.map(|_| required_header(&headers, "input_stage", adapter_id)).transpose()?;
    let source_row = required_header(&headers, "source_row_id", adapter_id)?;
    let scalar = required_header(&headers, &config.input_field, adapter_id)?;
    let pivot_column = config
        .pivot_field
        .as_ref()
        .map(|field| required_header(&headers, field, adapter_id))
        .transpose()?;
    let context_columns = config
        .required_exact_context
        .iter()
        .map(|context| {
            required_header(&headers, &context.input_field, adapter_id)
                .map(|column| (context, column))
        })
        .collect::<Result<Vec<_>, String>>()?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", config.input_field.as_str(), "disposition"])
        .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record =
            record.map_err(|error| format!("{adapter_id} row {}: {error}", row_index + 1))?;
        source_row_count += 1;
        // Opaque row identities are preserved; numeric token parsing remains unchanged.
        let source_row_id = record.get(source_row).unwrap_or_default();
        if prepared_stage.is_some_and(|stage| record.get(stage_column.expect("prepared stage column")) != Some(stage)) {
            return Err(format!("{adapter_id} requires exact caller-qualified input_stage"));
        }
        if source_row_id.trim().is_empty() {
            return Err(format!(
                "{adapter_id} row {} requires a nonempty source_row_id",
                row_index + 1
            ));
        }
        let value = parse_source_bound_scalar(
            record_value(&record, Some(scalar)),
            &config.input_domain,
            adapter_id,
            row_index + 1,
            &config.input_field,
        )?;
        let pivot = if let Some(pivot) = config.pivot {
            pivot
        } else {
            let pivot_field = config
                .pivot_field
                .as_deref()
                .expect("validated pivot field");
            parse_source_bound_scalar(
                record_value(&record, pivot_column),
                config
                    .pivot_field_domain
                    .as_deref()
                    .expect("validated pivot field domain"),
                adapter_id,
                row_index + 1,
                pivot_field,
            )?
        };
        for (context, column) in &context_columns {
            let actual = parse_source_bound_scalar(
                record_value(&record, Some(*column)),
                &context.input_domain,
                adapter_id,
                row_index + 1,
                &context.input_field,
            )?;
            if actual != context.exact_value {
                return Err(format!(
                    "{adapter_id} row {} field {} must equal configured source context {}",
                    row_index + 1,
                    context.input_field,
                    context.exact_value
                ));
            }
        }
        if config
            .inclusive_minimum
            .zip(config.inclusive_maximum)
            .is_some_and(|(minimum, maximum)| value < minimum || value > maximum)
        {
            return Err(format!(
                "{adapter_id} row {} field {} violates inclusive source domain",
                row_index + 1,
                config.input_field
            ));
        }
        let disposition = if config.operator == "ordered_threshold_bucketizer" {
            OrderedThresholdBucketizer::new(
                vec![pivot],
                vec![
                    config.below_disposition.clone(),
                    config.equal_disposition.clone(),
                ],
            )
            .map_err(|error| format!("{adapter_id}: {error}"))?
            .category_for(value)
            .map_err(|error| format!("{adapter_id} row {}: {error}", row_index + 1))?
            .clone()
        } else {
            FiniteScalarPivotClassifier::new(
                pivot,
                config.below_disposition.clone(),
                config.equal_disposition.clone(),
                config.above_disposition.clone(),
            )
            .map_err(|error| format!("{adapter_id}: {error}"))?
            .category_for(value)
            .map_err(|error| format!("{adapter_id} row {}: {error}", row_index + 1))?
            .clone()
        };
        writer
            .serialize((source_row_id, value, disposition))
            .map_err(|error| format!("{adapter_id} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{adapter_id} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        adapter_id,
        "literature-source-bound-scalar-predicate-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )
}

fn adapt_raw_text_utf16_minimum_gate(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} has no registered component")
        })?;
    let config: RawTextUtf16MinimumGateComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} componentConfig: {error}")
        })?;
    if config.input_field.is_empty()
        || config.minimum_utf16_code_units == 0
        || config.below_disposition.is_empty()
        || config.meets_disposition.is_empty()
        || config.below_disposition == config.meets_disposition
    {
        return Err(format!(
            "{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} componentConfig is outside the generic raw-text UTF-16 minimum contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER,
    )?;
    let raw_text = required_header(
        &headers,
        &config.input_field,
        RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER,
    )?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", "utf16_code_unit_count", "disposition"])
        .map_err(|error| format!("{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} write header: {error}"))?;
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let source_row_id = record_value(&record, Some(source_row));
        if source_row_id.is_empty() {
            return Err(format!(
                "{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} row {} requires a nonempty source_row_id",
                row_index + 1
            ));
        }
        let text = record.get(raw_text).ok_or_else(|| {
            format!(
                "{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} row {} requires field {}",
                row_index + 1,
                config.input_field
            )
        })?;
        let utf16_code_unit_count = text.encode_utf16().count();
        let disposition = if utf16_code_unit_count >= config.minimum_utf16_code_units {
            &config.meets_disposition
        } else {
            &config.below_disposition
        };
        writer
            .serialize((source_row_id, utf16_code_unit_count, disposition))
            .map_err(|error| {
                format!(
                    "{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} write row {}: {error}",
                    row_index + 1
                )
            })?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        RAW_TEXT_UTF16_MINIMUM_GATE_ADAPTER,
        "literature-source-bound-raw-text-utf16-minimum-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )
}

fn adapt_closed_integer_category_map(
    adapter_id: &str,
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter_id} has no registered component"))?;
    let config: ClosedIntegerCategoryMapComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{adapter_id} requires componentConfig"))?,
    )
    .map_err(|error| format!("invalid {adapter_id} componentConfig: {error}"))?;
    let values = config
        .categories
        .iter()
        .map(|entry| entry.value)
        .collect::<BTreeSet<_>>();
    if config.input_field.is_empty()
        || config.source_row_id_field.is_empty()
        || config.source_meaning_field.is_empty()
        || config.output_field.is_empty()
        || values.len() != config.categories.len()
        || config.categories.is_empty()
        || config
            .categories
            .iter()
            .any(|entry| entry.source_meaning.is_empty() || entry.output_value.is_empty())
    {
        return Err(format!(
            "{adapter_id} componentConfig is outside the generic closed integer-category contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new()
        .flexible(false)
        .from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter_id} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, &config.source_row_id_field, adapter_id)?;
    let input = required_header(&headers, &config.input_field, adapter_id)?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            config.source_row_id_field.as_str(),
            config.input_field.as_str(),
            config.source_meaning_field.as_str(),
            config.output_field.as_str(),
        ])
        .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    let mut source_row_count = 0usize;
    for (row_index, row) in reader.records().enumerate() {
        let row = row.map_err(|error| format!("{adapter_id} row {}: {error}", row_index + 1))?;
        source_row_count += 1;
        let source_row_id = record_value(&row, Some(source_row));
        if source_row_id.is_empty() {
            return Err(format!(
                "{adapter_id} row {} requires nonempty {}",
                row_index + 1,
                config.source_row_id_field
            ));
        }
        let raw = row.get(input).ok_or_else(|| {
            format!(
                "{adapter_id} row {} requires {}",
                row_index + 1,
                config.input_field
            )
        })?;
        let value = raw.parse::<i64>().map_err(|_| {
            format!(
                "{adapter_id} row {} requires a signed integer {}",
                row_index + 1,
                config.input_field
            )
        })?;
        if value.to_string() != raw {
            return Err(format!(
                "{adapter_id} row {} refuses a non-canonical integer token",
                row_index + 1
            ));
        }
        let category = config
            .categories
            .iter()
            .find(|entry| entry.value == value)
            .ok_or_else(|| {
                format!(
                    "{adapter_id} row {} value is outside the closed set",
                    row_index + 1
                )
            })?;
        writer
            .write_record([
                source_row_id,
                raw,
                category.source_meaning.as_str(),
                category.output_value.as_str(),
            ])
            .map_err(|error| format!("{adapter_id} write row {}: {error}", row_index + 1))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{adapter_id} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        adapter_id,
        "literature-closed-integer-category-map-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )
}

fn adapt_nonnegative_integer_high_side_cap(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} has no registered component")
        })?;
    let config: NonnegativeIntegerHighSideCapComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} componentConfig: {error}")
        })?;
    if config.input_field.is_empty() || config.comparison != "strictly_greater_than" {
        return Err(format!(
            "{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} componentConfig is outside the generic strict-cap contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER,
    )?;
    let input = required_header(
        &headers,
        &config.input_field,
        NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER,
    )?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_row_id",
            "original_word_count",
            "capped_word_count",
            "was_recoded",
        ])
        .map_err(|error| {
            format!("{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} write header: {error}")
        })?;
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let source_row_id = record_value(&record, Some(source_row));
        if source_row_id.is_empty() {
            return Err(format!(
                "{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} row {} requires a nonempty source_row_id",
                row_index + 1
            ));
        }
        let encoded = record.get(input).ok_or_else(|| {
            format!(
                "{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} row {} requires field {}",
                row_index + 1,
                config.input_field
            )
        })?;
        let original_word_count = encoded.parse::<u64>().map_err(|_| {
            format!(
                "{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} row {} field {} requires a nonnegative integer",
                row_index + 1,
                config.input_field
            )
        })?;
        let was_recoded = original_word_count > config.cap_value;
        writer
            .serialize((
                source_row_id,
                original_word_count,
                if was_recoded {
                    config.cap_value
                } else {
                    original_word_count
                },
                was_recoded,
            ))
            .map_err(|error| {
                format!(
                    "{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} write row {}: {error}",
                    row_index + 1
                )
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        NONNEGATIVE_INTEGER_HIGH_SIDE_CAP_ADAPTER,
        "literature-source-bound-nonnegative-integer-cap-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )
}

fn adapt_exact_category_membership_filter(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} has no registered component")
        })?;
    let config: ExactCategoryMembershipFilterComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} componentConfig: {error}")
        })?;
    let allowed = config.allowed_values.iter().collect::<BTreeSet<_>>();
    if config.input_field.is_empty()
        || allowed.is_empty()
        || allowed.len() != config.allowed_values.len()
        || allowed.iter().any(|value| value.is_empty())
        || config.comparison != "exact_case_and_whitespace_sensitive"
        || config.missing_value_policy != "drop_row"
    {
        return Err(format!(
            "{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} componentConfig is outside the generic exact-membership contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER,
    )?;
    let category = required_header(
        &headers,
        &config.input_field,
        EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER,
    )?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", config.input_field.as_str()])
        .map_err(|error| {
            format!("{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} write header: {error}")
        })?;
    let mut source_row_count = 0usize;
    let mut emitted_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let source_row_id = record.get(source_row).ok_or_else(|| {
            format!(
                "{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} row {} requires field source_row_id",
                row_index + 1
            )
        })?;
        if source_row_id.is_empty() {
            return Err(format!(
                "{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} row {} requires a nonempty source_row_id",
                row_index + 1
            ));
        }
        let value = record.get(category).unwrap_or("");
        if allowed.iter().any(|allowed| allowed.as_str() == value) {
            writer.serialize((source_row_id, value)).map_err(|error| {
                format!(
                    "{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} write row {}: {error}",
                    row_index + 1
                )
            })?;
            emitted_row_count += 1;
        }
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        EXACT_CATEGORY_MEMBERSHIP_FILTER_ADAPTER,
        "literature-source-bound-exact-category-membership-filter-csv",
        original_input_digest,
        bindings,
        source_row_count,
        emitted_row_count,
        csv_bytes,
    )
}

fn adapt_exact_cardinality_group_mean(
    adapter_id: &str,
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{adapter_id} has no registered component")
        })?;
    let config: ExactCardinalityGroupMeanComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{adapter_id} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {adapter_id} componentConfig: {error}")
        })?;
    let configured_fields = [
        config.group_field.as_str(),
        config.member_field.as_str(),
        config.value_field.as_str(),
        config.output_group_field.as_str(),
        config.output_mean_field.as_str(),
    ];
    let source_member_count = match adapter_id {
        TWENTY_TRIAL_TIME_MEAN_ADAPTER | NON_COUNTRY_UNICITY_MEAN_ADAPTER => Some(20),
        COUNTRY_UNICITY_MEAN_ADAPTER => Some(60),
        _ => None,
    };
    if source_member_count.is_some_and(|count| count != config.exact_member_count) {
        return Err(format!("{adapter_id} source cardinality mismatch"));
    }
    if configured_fields.iter().any(|field| field.is_empty())
        || config.exact_member_count == 0
        || config.value_domain != "finite_nonnegative"
        || config.aggregation != "arithmetic_mean"
    {
        return Err(format!(
            "{adapter_id} componentConfig is outside the generic exact-cardinality mean contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter_id} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{adapter_id} refuses duplicate column names"
        ));
    }
    let group_column = required_header(
        &headers,
        &config.group_field,
        adapter_id,
    )?;
    let member_column = required_header(
        &headers,
        &config.member_field,
        adapter_id,
    )?;
    let value_column = required_header(
        &headers,
        &config.value_field,
        adapter_id,
    )?;

    let mut rows = Vec::new();
    let mut members_by_group = BTreeMap::<String, BTreeSet<String>>::new();
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{adapter_id} row {row_number}: {error}")
        })?;
        let group_id = if adapter_id == EXACT_CARDINALITY_GROUP_MEAN_ADAPTER {
            record_value(&record, Some(group_column))
        } else {
            record.get(group_column).unwrap_or_default()
        };
        if group_id.is_empty() {
            return Err(format!(
                "{adapter_id} row {row_number} requires a nonempty {}",
                config.group_field
            ));
        }
        let member_id = if adapter_id == EXACT_CARDINALITY_GROUP_MEAN_ADAPTER {
            record_value(&record, Some(member_column))
        } else {
            record.get(member_column).unwrap_or_default()
        };
        if member_id.is_empty() {
            return Err(format!(
                "{adapter_id} row {row_number} requires a nonempty {}",
                config.member_field
            ));
        }
        if !members_by_group
            .entry(group_id.to_owned())
            .or_default()
            .insert(member_id.to_owned())
        {
            return Err(format!(
                "{adapter_id} row {row_number} duplicates {} within {}",
                config.member_field, config.group_field
            ));
        }
        let encoded = record_value(&record, Some(value_column));
        if encoded.is_empty() {
            return Err(format!(
                "{adapter_id} row {row_number} requires {}",
                config.value_field
            ));
        }
        let value = encoded.parse::<f64>().map_err(|_| {
            format!(
                "{adapter_id} row {row_number} requires finite nonnegative {}",
                config.value_field
            )
        })?;
        if !value.is_finite() || value < 0.0 {
            return Err(format!(
                "{adapter_id} row {row_number} requires finite nonnegative {}",
                config.value_field
            ));
        }
        if matches!(adapter_id, NON_COUNTRY_UNICITY_MEAN_ADAPTER | COUNTRY_UNICITY_MEAN_ADAPTER)
            && value > 1.0
        {
            return Err(format!("{adapter_id} row {row_number} requires a fraction in [0,1]"));
        }
        rows.push(GroupedNumericRow {
            group: Some(group_id.to_owned()),
            values: vec![Some(value)],
        });
    }
    if members_by_group.is_empty()
        || members_by_group
            .values()
            .any(|members| members.len() != config.exact_member_count)
    {
        return Err(format!(
            "{adapter_id} requires exactly {} unique {} values per {}",
            config.exact_member_count, config.member_field, config.group_field
        ));
    }
    let source_row_count = rows.len();
    let summaries = summarize_columns_by_first_seen_group(&rows).map_err(|error| {
        format!("{adapter_id} mean boundary error: {error:?}")
    })?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            config.output_group_field.as_str(),
            config.output_mean_field.as_str(),
        ])
        .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    for summary in &summaries {
        let group_id = summary
            .group
            .as_deref()
            .ok_or_else(|| format!("{adapter_id} lost group identity"))?;
        let mean = summary.means.first().copied().ok_or_else(|| {
            format!("{adapter_id} arithmetic mean is unavailable")
        })?;
        if !mean.is_finite() {
            return Err(format!(
                "{adapter_id} arithmetic mean is non-finite"
            ));
        }
        writer
            .write_record([group_id, format_r_numeric(Some(mean)).as_str()])
            .map_err(|error| {
                format!("{adapter_id} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{adapter_id} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        adapter_id,
        "literature-exact-cardinality-group-mean-csv",
        original_input_digest,
        bindings,
        source_row_count,
        summaries.len(),
        csv_bytes,
    )
}

fn adapt_categorized_distinct_member_counts(
    adapter_id: &str,
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{adapter_id} has no registered component")
        })?;
    let config: CategorizedDistinctMemberCountsComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{adapter_id} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {adapter_id} componentConfig: {error}")
        })?;
    let allowed_partitions = config.allowed_partitions.iter().collect::<BTreeSet<_>>();
    let output_fields = config
        .outputs
        .iter()
        .map(|output| output.output_field.as_str())
        .collect::<BTreeSet<_>>();
    if config.member_json_field.is_empty()
        || config.category_field.is_empty()
        || config.partition_field.is_empty()
        || allowed_partitions.is_empty()
        || allowed_partitions.len() != config.allowed_partitions.len()
        || allowed_partitions
            .iter()
            .any(|partition| partition.is_empty())
        || config.outputs.is_empty()
        || output_fields.len() != config.outputs.len()
        || output_fields.iter().any(|field| field.is_empty())
        || config.outputs.iter().any(|output| {
            output.category_equals.as_deref().is_some_and(str::is_empty)
                || output.partition_equals.as_deref().is_some_and(|partition| {
                    !config
                        .allowed_partitions
                        .iter()
                        .any(|allowed| allowed == partition)
                })
        })
    {
        return Err(format!(
            "{adapter_id} componentConfig is outside the generic categorized distinct-count contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter_id} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{adapter_id} refuses duplicate column names"
        ));
    }
    let source_row = required_header(
        &headers,
        "source_row_id",
        adapter_id,
    )?;
    let member = required_header(
        &headers,
        &config.member_json_field,
        adapter_id,
    )?;
    let category = required_header(
        &headers,
        &config.category_field,
        adapter_id,
    )?;
    let partition = required_header(
        &headers,
        &config.partition_field,
        adapter_id,
    )?;
    let scope_field = match adapter_id {
        FRAME_UNIQUE_APP_COUNT_ADAPTER => Some("frame_id"),
        SESSION_UNIQUE_APP_COUNT_ADAPTER => Some("session_id"),
        _ => None,
    };
    let scope_column = scope_field.map(|field| required_header(&headers, field, adapter_id)).transpose()?;
    let mut supplied_scope: Option<String> = None;
    let mut explicit_empty_scope = false;
    let mut actual_app_observed = false;
    let mut source_row_count = 0usize;
    let mut observations = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{adapter_id} row {row_number}: {error}")
        })?;
        source_row_count += 1;
        if record_value(&record, Some(source_row)).is_empty() {
            return Err(format!(
                "{adapter_id} row {row_number} requires a nonempty source_row_id"
            ));
        }
        let encoded_identity = record_value(&record, Some(member));
        if encoded_identity.is_empty() {
            return Err(format!(
                "{adapter_id} row {row_number} requires JSON field {}",
                config.member_json_field
            ));
        }
        let parsed_identity: Value = serde_json::from_str(encoded_identity).map_err(|_| {
            format!(
                "{adapter_id} row {row_number} has unsupported {}",
                config.member_json_field
            )
        })?;
        let identity = match parsed_identity {
            Value::Null => TypedDistinctMemberIdentity::Null,
            Value::String(value) => TypedDistinctMemberIdentity::Text(value),
            Value::Number(value) => value
                .as_i64()
                .map(TypedDistinctMemberIdentity::Integer)
                .ok_or_else(|| {
                    format!(
                        "{adapter_id} row {row_number} has unsupported {}",
                        config.member_json_field
                    )
                })?,
            _ => {
                return Err(format!(
                    "{adapter_id} row {row_number} has unsupported {}",
                    config.member_json_field
                ))
            }
        };
        let category_value = if scope_field.is_some() {
            record.get(category).unwrap_or_default()
        } else {
            record_value(&record, Some(category))
        };
        if category_value.is_empty() {
            return Err(format!(
                "{adapter_id} row {row_number} requires {}",
                config.category_field
            ));
        }
        let partition_value = if scope_field.is_some() {
            record.get(partition).unwrap_or_default()
        } else {
            record_value(&record, Some(partition))
        };
        if !config
            .allowed_partitions
            .iter()
            .any(|allowed| allowed == partition_value)
        {
            return Err(format!(
                "{adapter_id} row {row_number} has unsupported {}",
                config.partition_field
            ));
        }
        if let Some(scope_column) = scope_column {
            let scope = record.get(scope_column).unwrap_or_default();
            if scope.is_empty() || supplied_scope.as_deref().is_some_and(|previous| previous != scope) {
                return Err(format!("{adapter_id} requires exactly one nonempty supplied scope"));
            }
            supplied_scope = Some(scope.to_owned());
            match (category_value, &identity) {
                ("scope", TypedDistinctMemberIdentity::Null) => {
                    if actual_app_observed {
                        return Err(format!("{adapter_id} empty-scope marker contradicts app observations"));
                    }
                    explicit_empty_scope = true;
                    continue;
                },
                ("app", TypedDistinctMemberIdentity::Integer(_)) => {},
                ("app", TypedDistinctMemberIdentity::Text(value)) if !value.is_empty() => {},
                _ => return Err(format!("{adapter_id} requires a real nonmissing app identity or an explicit empty-scope marker")),
            }
            if explicit_empty_scope {
                return Err(format!("{adapter_id} empty-scope marker contradicts app observations"));
            }
            actual_app_observed = true;
        }
        for (output_index, output) in config.outputs.iter().enumerate() {
            if output
                .category_equals
                .as_deref()
                .is_none_or(|expected| expected == category_value)
                && output
                    .partition_equals
                    .as_deref()
                    .is_none_or(|expected| expected == partition_value)
            {
                observations.push((output_index, identity.clone()));
            }
        }
    }
    let mut counts = vec![0usize; config.outputs.len()];
    for count in count_distinct_members_by_group(observations) {
        counts[count.group] = count.distinct_member_count;
    }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    if scope_field.is_some() && supplied_scope.is_none() {
        return Err(format!("{adapter_id} requires an explicitly supplied scope, not an absent input"));
    }
    writer
        .write_record(
            scope_field.into_iter().chain(config
                .outputs
                .iter()
                .map(|output| output.output_field.as_str())),
        )
        .map_err(|error| {
            format!("{adapter_id} write header: {error}")
        })?;
    writer
        .write_record(supplied_scope.into_iter().chain(counts.iter().map(usize::to_string)))
        .map_err(|error| {
            format!("{adapter_id} write row: {error}")
        })?;
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{adapter_id} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        adapter_id,
        "literature-categorized-distinct-member-counts-csv",
        original_input_digest,
        bindings,
        source_row_count,
        1,
        csv_bytes,
    )
}

// Source: doi:10.1038/s41598-021-82294-1, primary.txt:508-517,
// PDF SHA256 b89d21529f81c067b3cb468644165c3d3bae99ae1161f5b19fa33c32f4e6e24f.
// The caller supplies fingerprints and owned attack selections. This is not a
// sampler, app-ranking implementation, month constructor or Sony collector.
fn supplied_unicity_app_set(
    encoded: &str,
    without_replacement: bool,
) -> Result<BTreeSet<TypedDistinctMemberIdentity>, String> {
    let values: Vec<Value> = serde_json::from_str(encoded).map_err(|_| {
        format!("{SUPPLIED_APP_FINGERPRINT_UNICITY_ADAPTER} requires an explicit app-identity JSON array")
    })?;
    let mut apps = BTreeSet::new();
    for value in values {
        let app = match value {
            Value::String(value) if !value.is_empty() => TypedDistinctMemberIdentity::Text(value),
            Value::Number(value) => value.as_i64().map(TypedDistinctMemberIdentity::Integer)
                .ok_or_else(|| format!("{SUPPLIED_APP_FINGERPRINT_UNICITY_ADAPTER} requires integer or nonempty string app identities"))?,
            _ => return Err(format!("{SUPPLIED_APP_FINGERPRINT_UNICITY_ADAPTER} refuses missing or unsupported app identities")),
        };
        if !apps.insert(app) && without_replacement {
            return Err(format!("{SUPPLIED_APP_FINGERPRINT_UNICITY_ADAPTER} attack subsets must be supplied without replacement"));
        }
    }
    Ok(apps)
}

fn supplied_unicity_apps_json(apps: &BTreeSet<TypedDistinctMemberIdentity>) -> String {
    Value::Array(apps.iter().map(|app| match app {
        TypedDistinctMemberIdentity::Integer(value) => Value::Number((*value).into()),
        TypedDistinctMemberIdentity::Text(value) => Value::String(value.clone()),
        TypedDistinctMemberIdentity::Null => Value::Null,
    }).collect()).to_string()
}

/// Count sampled individuals containing every selected app, not equal fingerprints.
/// The index is merely an exact set-membership representation of the supplied sample.
fn supplied_unicity_containing_individual_count(
    users_by_app: &BTreeMap<TypedDistinctMemberIdentity, BTreeSet<String>>,
    sample_users: usize,
    selected: &BTreeSet<TypedDistinctMemberIdentity>,
) -> usize {
    let mut selected_apps = selected.iter();
    let Some(first) = selected_apps.next() else { return sample_users; };
    let Some(first_users) = users_by_app.get(first) else { return 0; };
    let mut containing = first_users.clone();
    for app in selected_apps {
        let Some(users) = users_by_app.get(app) else { return 0; };
        containing.retain(|individual| users.contains(individual));
    }
    containing.len()
}

fn adapt_supplied_app_fingerprint_unicity(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter_id = SUPPLIED_APP_FINGERPRINT_UNICITY_ADAPTER;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{adapter_id} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter_id} refuses duplicate column names"));
    }
    let fields = ["source_row_id", "population_id", "sample_id", "attack_scope_id",
        "individual_id", "attack_subset_id", "subset_owner_id", "fingerprint_apps_json",
        "selected_apps_json", "requested_app_count", "declared_sample_users"];
    let columns = fields.iter().map(|field| required_header(&headers, field, adapter_id))
        .collect::<Result<Vec<_>, _>>()?;
    let mut scopes = BTreeMap::<(String, String, String), SuppliedUnicityScope>::new();
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| format!("{adapter_id} row {}: {error}", row_index + 1))?;
        source_row_count += 1;
        let value = |index: usize| record.get(columns[index]).unwrap_or_default();
        if (0..=6).any(|index| value(index).is_empty()) {
            return Err(format!("{adapter_id} row {} requires explicit nonempty source/sample/individual/selection identities", row_index + 1));
        }
        if value(6) != value(4) {
            return Err(format!("{adapter_id} row {} attack subset has incorrect individual ownership", row_index + 1));
        }
        let parse_count = |index: usize| value(index).trim().parse::<u64>()
            .map_err(|_| format!("{adapter_id} row {} requires nonnegative integer {}", row_index + 1, fields[index]));
        let requested_app_count = parse_count(9)?;
        let declared_sample_users = parse_count(10)?;
        if requested_app_count == 0 || declared_sample_users == 0 {
            return Err(format!("{adapter_id} requires positive requested app count and nonempty sample inventory"));
        }
        // Fingerprints are binary app sets, so repeated supplied app observations
        // collapse. An attack is explicitly without replacement and cannot repeat.
        let fingerprint = supplied_unicity_app_set(value(7), false)?;
        let selected = supplied_unicity_app_set(value(8), true)?;
        if !selected.is_subset(&fingerprint) {
            return Err(format!("{adapter_id} row {} attack subset is not contained in its owning individual's fingerprint", row_index + 1));
        }
        if selected.len() as u64 != requested_app_count.min(fingerprint.len() as u64) {
            return Err(format!("{adapter_id} row {} selected app count must equal min(requested_app_count, fingerprint size)", row_index + 1));
        }
        let scope = scopes.entry((value(1).to_owned(), value(2).to_owned(), value(3).to_owned()))
            .or_insert_with(|| SuppliedUnicityScope {
                requested_app_count, declared_sample_users, individuals: BTreeMap::new(),
            });
        if scope.requested_app_count != requested_app_count
            || scope.declared_sample_users != declared_sample_users
        {
            return Err(format!("{adapter_id} refuses conflicting attack count or declared sample inventory within a scope"));
        }
        if scope.individuals.insert(value(4).to_owned(), SuppliedUnicityIndividual {
            source_row_id: value(0).to_owned(), subset_id: value(5).to_owned(),
            fingerprint, selected,
        }).is_some() {
            return Err(format!("{adapter_id} requires exactly one owned selection per sampled individual in each attack scope"));
        }
    }
    if scopes.is_empty() {
        return Err(format!("{adapter_id} requires an explicitly supplied nonempty sampled population"));
    }
    // A sample identity cannot silently denote different sampled populations in
    // two attack scopes. Country/month qualification itself remains caller-owned.
    let mut sample_inventories = BTreeMap::<(String, String), BTreeMap<String, BTreeSet<TypedDistinctMemberIdentity>>>::new();
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["result_kind", "source_row_id", "population_id", "sample_id",
        "attack_scope_id", "individual_id", "attack_subset_id", "fingerprint_apps_json",
        "selected_apps_json", "requested_app_count", "selected_app_count",
        "containing_individuals", "is_unique", "unique_users", "sample_users", "unicity_fraction"])
        .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    let mut output_row_count = 0usize;
    for ((population_id, sample_id, attack_scope_id), scope) in scopes {
        if scope.individuals.len() as u64 != scope.declared_sample_users {
            return Err(format!("{adapter_id} supplied individuals do not match the explicit sample inventory"));
        }
        let inventory = scope.individuals.iter().map(|(individual, supplied)| {
            (individual.clone(), supplied.fingerprint.clone())
        }).collect::<BTreeMap<_, _>>();
        let sample_inventory = sample_inventories.entry((population_id.clone(), sample_id.clone()))
            .or_insert_with(|| inventory.clone());
        if sample_inventory != &inventory {
            return Err(format!("{adapter_id} sample membership or fingerprints drift across attack scopes"));
        }
        let mut users_by_app = BTreeMap::<TypedDistinctMemberIdentity, BTreeSet<String>>::new();
        for (individual, supplied) in &scope.individuals {
            for app in &supplied.fingerprint {
                users_by_app.entry(app.clone()).or_default().insert(individual.clone());
            }
        }
        let mut containment_counts = BTreeMap::<BTreeSet<TypedDistinctMemberIdentity>, usize>::new();
        let mut unique_users = 0u64;
        for (individual, supplied) in &scope.individuals {
            let containing = *containment_counts.entry(supplied.selected.clone())
                .or_insert_with(|| supplied_unicity_containing_individual_count(
                    &users_by_app, scope.individuals.len(), &supplied.selected));
            let is_unique = containing == 1;
            if is_unique { unique_users += 1; }
            writer.write_record([
                "individual".to_owned(), supplied.source_row_id.clone(), population_id.clone(),
                sample_id.clone(), attack_scope_id.clone(), individual.clone(), supplied.subset_id.clone(),
                supplied_unicity_apps_json(&supplied.fingerprint), supplied_unicity_apps_json(&supplied.selected),
                scope.requested_app_count.to_string(), supplied.selected.len().to_string(),
                containing.to_string(), is_unique.to_string(), String::new(), String::new(), String::new(),
            ]).map_err(|error| format!("{adapter_id} write individual: {error}"))?;
            output_row_count += 1;
        }
        let ratio = construct_named_count_ratios([CountRatioRequest {
            name: "sample_unicity", numerator: unique_users,
            denominator_terms: vec![scope.declared_sample_users],
        }]).map_err(|error| format!("{adapter_id}: {error}"))?;
        writer.write_record([
            "sample".to_owned(), String::new(), population_id, sample_id, attack_scope_id,
            String::new(), String::new(), String::new(), String::new(),
            scope.requested_app_count.to_string(), String::new(), String::new(), String::new(),
            unique_users.to_string(), scope.declared_sample_users.to_string(),
            format_python_float(ratio[0].ratio.value()),
        ]).map_err(|error| format!("{adapter_id} write sample: {error}"))?;
        output_row_count += 1;
    }
    let csv_bytes = writer.into_inner().map_err(|error| format!("{adapter_id} finish output: {error}"))?;
    complete_standalone_component_adaptation(adapter_id, "literature-supplied-app-fingerprint-unicity-csv",
        original_input_digest, bindings, source_row_count, output_row_count, csv_bytes)
}

// Fukazawa2019, doi:10.1016/j.jbi.2019.103151, publisher-rendered
// primary.txt:158-167 Eq.3; SHA256
// 9c7f55af7cb6109b3bc0c48b299d5dd95152ef4b7b5392e2451fa84080876f8f.
// Only the magnitude of supplied gravity-removed axes is computed here. Eq.5
// already uses OrderedThresholdBucketizer in fixed-grid-categorical-dwell.
// Neither gravity removal nor clock/grid construction is performed.
fn adapt_fukazawa_supplied_acceleration_magnitude(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = FUKAZAWA_SUPPLIED_ACCELERATION_MAGNITUDE_ADAPTER;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{adapter} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || headers.iter().any(|header| header == "magnitude_m_s2")
    {
        return Err(format!("{adapter} requires unique input columns without computed output columns"));
    }
    let fields = ["source_row_id", "participant_id", "device_id", "sensor_stream_id",
        "sample_id", "sample_time", "time_unit", "sensor_modality", "acceleration_unit",
        "acceleration_input_stage", "ax", "ay", "az"];
    let columns = fields.iter().map(|field| required_header(&headers, field, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut output_headers = headers.clone();
    output_headers.push_field("magnitude_m_s2");
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&output_headers).map_err(|error| format!("{adapter} write header: {error}"))?;
    let mut owners = BTreeSet::new();
    let mut rows = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let mut record = record.map_err(|error| format!("{adapter} row {}: {error}", row_index + 1))?;
        let value = |index: usize| record.get(columns[index]).unwrap_or_default();
        if (0..=9).any(|index| value(index).is_empty()) {
            return Err(format!("{adapter} row {} requires explicit nonempty identity/time/unit/stage values", row_index + 1));
        }
        if value(7) != "accelerometer" || value(8) != "m/s^2"
            || value(9) != "gravity_removed"
        {
            return Err(format!("{adapter} row {} requires supplied gravity_removed accelerometer axes in m/s^2", row_index + 1));
        }
        // Sample ownership includes the actual device and sensor stream. The
        // lexical time/unit fields are retained, not parsed, shifted or sampled.
        let owner = [1, 2, 3, 4].map(|index| value(index).to_owned());
        if !owners.insert(owner) {
            return Err(format!("{adapter} row {} duplicates a participant/device/stream/sample owner", row_index + 1));
        }
        let mut axes = [0.0; 3];
        for (axis, index) in axes.iter_mut().zip(10..=12) {
            *axis = parse_source_bound_scalar(value(index), "finite", adapter,
                row_index + 1, fields[index])?;
        }
        let magnitude = finite_three_axis_magnitude(axes).ok_or_else(||
            format!("{adapter} row {} magnitude exceeds the finite output range", row_index + 1))?;
        record.push_field(&magnitude.to_string());
        writer.write_record(&record).map_err(|error| format!("{adapter} write row: {error}"))?;
        rows += 1;
    }
    if rows == 0 {
        return Err(format!("{adapter} requires explicitly supplied acceleration samples"));
    }
    let csv_bytes = writer.into_inner().map_err(|error| format!("{adapter} finish output: {error}"))?;
    complete_standalone_component_adaptation(adapter, "literature-fukazawa-supplied-acceleration-magnitude-csv",
        original_input_digest, bindings, rows, rows, csv_bytes)
}

// Retained RAPIDS1.9.4 commit7cc543b14c7843fee5b4b42a29ec5e10770a2f54:
// src/features/phone_applications_foreground/rapids/main.py::compute_features.
// These supplied typed reductions do not claim the study's deployed revision,
// foreground/episode construction, category resolution or segment construction.
fn adapt_rapids_supplied_foreground_reductions(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = RAPIDS_SUPPLIED_FOREGROUND_REDUCTIONS_ADAPTER;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let fields = ["source_row_id", "participant_id", "device_id", "source_table_id",
        "local_segment", "category_scope_id", "source_has_timestamp_column",
        "timestamp_json", "start_timestamp_json", "duration_minutes_json"];
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut groups = BTreeSet::new();
    let mut timestamp_presence = BTreeMap::new();
    let mut count_rows = Vec::new();
    let mut durations = Vec::new();
    let mut source_rows = 0usize;
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let value = |i: usize| record.get(columns[i]).unwrap_or_default();
        if (0..6).any(|i| value(i).is_empty()) {
            return Err(format!("{adapter} row {} requires declared identities and membership", index + 1));
        }
        let has_timestamp = match value(6) {
            "true" => true, "false" => false,
            _ => return Err(format!("{adapter} row {} requires explicit timestamp-column presence", index + 1)),
        };
        let table = [1, 2, 3].map(|i| value(i).to_owned());
        if timestamp_presence.insert(table, has_timestamp).is_some_and(|old| old != has_timestamp) {
            return Err(format!("{adapter} timestamp-column presence changes within one supplied source table"));
        }
        let group = [1, 2, 3, 4, 5].map(|i| value(i).to_owned());
        groups.insert(group.clone());
        let cells = [7, 8, 9].map(|i| serde_json::from_str::<Value>(value(i))
            .map_err(|e| format!("{adapter} row {} {} typed JSON: {e}", index + 1, fields[i])));
        let [timestamp, start_timestamp, duration] = cells;
        let timestamp = timestamp?;
        let start_timestamp = start_timestamp?;
        let duration = duration?;
        if [&timestamp, &start_timestamp].iter().any(|v| v.is_array() || v.is_object()) {
            return Err(format!("{adapter} requires scalar timestamp cells or explicit JSON null"));
        }
        if !has_timestamp && !timestamp.is_null() {
            return Err(format!("{adapter} an absent source timestamp column requires null in its supplied placeholder"));
        }
        // pandas count excludes null, not typed empty text/false/zero. The
        // caller explicitly supplies scalar types; CSV inference is excluded.
        let selected = if has_timestamp { &timestamp } else { &start_timestamp };
        if !selected.is_null() { count_rows.push((group.clone(), ())); }
        let duration = if duration.is_null() { 0.0 } else {
            duration.as_f64().filter(|v| v.is_finite() && *v >= 0.0)
                .ok_or_else(|| format!("{adapter} row {} requires finite nonnegative duration minutes or null", index + 1))?
        };
        // Convert each supplied null to the source sum's additive zero; unlike
        // the existing R helper's Missing, pandas sum skips typed nulls.
        durations.push(GroupedScalarInput {
            entity: group, raw_partition: (), passthrough: (),
            value: RCompatibleScalar::Finite(duration),
        });
        source_rows += 1;
    }
    let counts = count_categories_by_group(count_rows).into_iter()
        .map(|r| (r.group, r.observation_count)).collect::<BTreeMap<_, _>>();
    let sums = grouped_scalar_sum_then_project_unique(&durations,
        SequentialDivisionConfiguration { first_divisor: 1.0, second_divisor: 1.0 },
        |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?
        .into_iter().map(|r| (r.entity, r.sum)).collect::<BTreeMap<_, _>>();
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["participant_id", "device_id", "source_table_id", "local_segment",
        "category_scope_id", "countevent", "sumduration_minutes"])
        .map_err(|e| format!("{adapter} write header: {e}"))?;
    for group in &groups {
        let RCompatibleScalar::Finite(sum) = sums[group] else {
            return Err(format!("{adapter} summed duration exceeds the finite prepared-output domain"));
        };
        let mut row = group.to_vec();
        row.push(counts.get(group).copied().unwrap_or(0).to_string());
        row.push(sum.to_string());
        writer.write_record(row).map_err(|e| format!("{adapter} write row: {e}"))?;
    }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    complete_standalone_component_adaptation(adapter,
        "literature-rapids-supplied-foreground-reductions-csv",
        original_input_digest, bindings, source_rows, groups.len(), csv)
}

// Retained RAPIDS1.9.4 main.R::compute_data_yield_features. Occupied minute
// and hour membership, segment duration and threshold are explicitly supplied;
// there is no timestamp-to-bin, timezone, sensor-yield or missing-grid constructor.
fn adapt_rapids_supplied_data_yield(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = RAPIDS_SUPPLIED_DATA_YIELD_ADAPTER;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let fields = ["source_row_id", "participant_id", "device_id", "source_table_id",
        "local_segment", "hour_bin_id", "minute_bin_id", "duration_minutes",
        "minute_ratio_threshold"];
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut metadata = BTreeMap::<[String; 4], (f64, f64)>::new();
    let mut minute_owners = BTreeMap::new();
    let mut observations = Vec::new();
    let mut source_rows = 0usize;
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let value = |i: usize| record.get(columns[i]).unwrap_or_default();
        if (0..7).any(|i| value(i).is_empty()) {
            return Err(format!("{adapter} row {} requires explicit source/segment/hour/minute identities", index + 1));
        }
        let group = [1, 2, 3, 4].map(|i| value(i).to_owned());
        let duration = parse_source_bound_scalar(value(7), "finite", adapter, index + 1, fields[7])?;
        let threshold = parse_source_bound_scalar(value(8), "finite", adapter, index + 1, fields[8])?;
        if duration <= 0.0 || !(0.0..=1.0).contains(&threshold) {
            return Err(format!("{adapter} requires positive finite segment minutes and threshold fraction in [0,1]"));
        }
        if metadata.insert(group.clone(), (duration, threshold)).is_some_and(|old| old != (duration, threshold)) {
            return Err(format!("{adapter} segment duration or threshold changes within one owner"));
        }
        // IDs are lexical supplied memberships, not computed clock/grid bins.
        let minute = (group.clone(), value(6).to_owned());
        let hour = value(5).to_owned();
        if minute_owners.insert(minute, hour.clone()).is_some_and(|old| old != hour) {
            return Err(format!("{adapter} a supplied minute belongs to more than one hour within its segment"));
        }
        observations.push(((group, hour), value(6).to_owned()));
        source_rows += 1;
    }
    let counts = count_distinct_members_by_group(observations);
    let mut by_segment = BTreeMap::<[String; 4], Vec<(String, usize)>>::new();
    for count in counts {
        by_segment.entry(count.group.0).or_default()
            .push((count.group.1, count.distinct_member_count));
    }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["participant_id", "device_id", "source_table_id", "local_segment",
        "duration_minutes", "minute_ratio_threshold", "valid_yielded_minutes",
        "valid_yielded_hours", "ratiovalidyieldedminutes", "ratiovalidyieldedhours"])
        .map_err(|e| format!("{adapter} write header: {e}"))?;
    for (group, hours) in &by_segment {
        let (duration, threshold) = metadata[group];
        let classifier = FiniteScalarPivotClassifier::new(threshold, false, false, true)
            .map_err(|e| format!("{adapter}: {e}"))?;
        let mut minute_terms = Vec::new();
        let mut valid_hour_terms = Vec::new();
        for (_, count) in hours {
            let fraction = grouped_scalar_sum_then_project_unique(&[GroupedScalarInput {
                entity: (), raw_partition: (), passthrough: (),
                value: RCompatibleScalar::Finite(*count as f64),
            }], SequentialDivisionConfiguration {
                first_divisor: duration.min(60.0), second_divisor: 1.0,
            }, |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?;
            // Equality is false in the retained source, not the paper >=30/60.
            let valid = match fraction[0].first_scaled_value {
                RCompatibleScalar::Finite(fraction) => *classifier.category_for(fraction)
                    .map_err(|e| format!("{adapter}: {e}"))?,
                // Positive finite inputs may overflow division. R's strict
                // comparison still makes +Inf greater than its finite pivot.
                RCompatibleScalar::PositiveInfinity => true,
                _ => return Err(format!("{adapter} invalid valid-hour comparison")),
            };
            minute_terms.push(GroupedScalarInput {
                entity: (), raw_partition: (), passthrough: (),
                value: RCompatibleScalar::Finite(*count as f64),
            });
            valid_hour_terms.push(GroupedScalarInput {
                entity: (), raw_partition: (), passthrough: (),
                value: RCompatibleScalar::Finite(if valid { 1.0 } else { 0.0 }),
            });
        }
        let minutes = grouped_scalar_sum_then_project_unique(&minute_terms,
            SequentialDivisionConfiguration { first_divisor: duration, second_divisor: 1.0 },
            |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?;
        let duration_hours = duration / 60.0;
        let hours = grouped_scalar_sum_then_project_unique(&valid_hour_terms,
            SequentialDivisionConfiguration {
                first_divisor: if duration_hours > 1.0 { duration_hours } else { 1.0 },
                second_divisor: 1.0,
            }, |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?;
        let finite = |v: RCompatibleScalar| match v {
            RCompatibleScalar::Finite(v) => Ok(v),
            _ => Err(format!("{adapter} reduction exceeds finite prepared-output domain")),
        };
        let yielded_minutes = finite(minutes[0].sum)?;
        let yielded_hours = finite(hours[0].sum)?;
        let minute_ratio = match minutes[0].first_scaled_value {
            RCompatibleScalar::Finite(value) => value.min(1.0),
            RCompatibleScalar::PositiveInfinity => 1.0,
            _ => return Err(format!("{adapter} invalid yielded-minute ratio")),
        };
        let hour_ratio = if duration_hours > 1.0 {
            finite(hours[0].first_scaled_value)?.min(1.0)
        } else { yielded_hours };
        let mut row = group.to_vec();
        row.extend([duration, threshold, yielded_minutes, yielded_hours, minute_ratio, hour_ratio]
            .map(|v| v.to_string()));
        writer.write_record(row).map_err(|e| format!("{adapter} write row: {e}"))?;
    }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    complete_standalone_component_adaptation(adapter,
        "literature-rapids-supplied-data-yield-csv",
        original_input_digest, bindings, source_rows, by_segment.len(), csv)
}

// Next App primary p3 section4.1: "Global" frequency remains per particular
// user. Counts do not select argmax, break ties, construct timeslots or train
// Algorithm1's distributed representation.
fn adapt_nextapp_supplied_opening_counts(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = NEXTAPP_SUPPLIED_OPENING_COUNTS_ADAPTER;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let fields = ["source_row_id", "user_id", "observation_scope_id", "app_id"];
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut observations = Vec::new();
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let values = columns.iter().map(|i| record.get(*i).unwrap_or_default()).collect::<Vec<_>>();
        if values.iter().any(|v| v.is_empty()) {
            return Err(format!("{adapter} row {} requires explicitly supplied occurrence/user/scope/app identities", index + 1));
        }
        observations.push(((values[1].to_owned(), values[2].to_owned()), values[3].to_owned()));
    }
    let source_rows = observations.len();
    let counts = count_categories_by_group(observations);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["user_id", "observation_scope_id", "app_id", "opening_count"])
        .map_err(|e| format!("{adapter} write header: {e}"))?;
    for count in &counts {
        writer.serialize((&count.group.0, &count.group.1, &count.category, count.observation_count))
            .map_err(|e| format!("{adapter} write row: {e}"))?;
    }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    complete_standalone_component_adaptation(adapter,
        "literature-nextapp-supplied-opening-counts-csv",
        original_input_digest, bindings, source_rows, counts.len(), csv)
}

// Prepared scalar operands only. Falaki primary pp3,5-8; corresponding
// activity normalization rank149:376-381; Beyond primary p11 section5.2.
// No raw counters, calls, foreground/activity admission, peak selection,
// missing-hour policy, screen intervals or last-hour window are constructed.
fn adapt_prepared_source_scalar_ratio(
    adapter: &str, raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let (extra, numerator, denominator, fraction): (&[&str], &str, &str, bool) = match adapter {
        FALAKI_APP_TIME_RATIO_ADAPTER => (&["app_id"], "app_time", "phone_interaction_time", true),
        FALAKI_VOICE_TIME_RATIO_ADAPTER => (&[], "voice_time", "interaction_time", true),
        FALAKI_DIURNAL_RATIO_ADAPTER => (&["measure_id", "peak_hour_scope_id", "all_hours_scope_id"], "peak_hour_mean", "all_hours_mean", false),
        ACTIVITY_APP_TIME_RATIO_ADAPTER => (&["app_id", "activity_id"], "app_usage_time", "corresponding_activity_time", true),
        BEYOND_SCREEN_ON_FRACTION_ADAPTER => (&["last_hour_window_id"], "screen_on_time", "last_hour_duration", true),
        _ => return Err(format!("{adapter} is not a prepared source scalar ratio")),
    };
    let mut fields = vec!["source_row_id", "participant_id", "device_id", "observation_scope_id",
        "numerator_clock_id", "denominator_clock_id", "numerator_unit", "denominator_unit"];
    fields.extend_from_slice(extra);
    fields.extend([numerator, denominator]);
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    let mut output_fields = fields.clone();
    output_fields.push("ratio");
    writer.write_record(&output_fields).map_err(|e| format!("{adapter} header: {e}"))?;
    let mut identities = BTreeSet::new();
    let mut count = 0usize;
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let values = columns.iter().map(|i| record.get(*i).unwrap_or_default()).collect::<Vec<_>>();
        if values.iter().any(|v| v.is_empty()) {
            return Err(format!("{adapter} row {} requires supplied operands, units, clocks and lexical identities", index + 1));
        }
        if values[4] != values[5] || values[6] != values[7] {
            return Err(format!("{adapter} requires matching operand clocks and units"));
        }
        if !identities.insert([values[1], values[2], values[3], values[0]].map(str::to_owned)) {
            return Err(format!("{adapter} duplicate prepared operand row within its participant/device/scope"));
        }
        let expected_unit = if adapter == FALAKI_DIURNAL_RATIO_ADAPTER {
            match values[8] {
                "interaction_time" | "session_length" => "seconds",
                "session_count" => "count",
                "traffic_sent" | "traffic_received" => "MB",
                "energy_drain" => "mAh",
                _ => return Err(format!("{adapter} requires a source-qualified interaction, traffic or energy measure")),
            }
        } else { "seconds" };
        if values[6] != expected_unit {
            return Err(format!("{adapter} supplied quantity unit does not match its source measure"));
        }
        let numerator = parse_source_bound_scalar(values[values.len() - 2], "finite_nonnegative",
            adapter, index + 1, numerator)?;
        let denominator = parse_source_bound_scalar(values[values.len() - 1], "finite_nonnegative",
            adapter, index + 1, denominator)?;
        if denominator <= 0.0 || (fraction && numerator > denominator) {
            return Err(format!("{adapter} requires positive denominator and a source-valid numerator"));
        }
        if adapter == BEYOND_SCREEN_ON_FRACTION_ADAPTER && denominator != 3600.0 {
            return Err(format!("{adapter} supplied last-hour duration must be 3600 seconds"));
        }
        // One supplied scalar and the existing division body; no count casting,
        // synthetic group aggregation, or new arithmetic implementation.
        let scalar_projection = grouped_scalar_sum_then_project_unique(&[GroupedScalarInput {
            entity: (), raw_partition: (), passthrough: (),
            value: RCompatibleScalar::Finite(numerator),
        }], SequentialDivisionConfiguration { first_divisor: denominator, second_divisor: 1.0 },
            |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?;
        let RCompatibleScalar::Finite(ratio) = scalar_projection[0].first_scaled_value else {
            return Err(format!("{adapter} ratio exceeds the finite prepared-output domain"));
        };
        if ratio == 0.0 && numerator != 0.0 {
            return Err(format!("{adapter} nonzero ratio underflow exceeds the representable output domain"));
        }
        let mut output = values.into_iter().map(str::to_owned).collect::<Vec<_>>();
        output.push(ratio.to_string());
        writer.write_record(output).map_err(|e| format!("{adapter} row: {e}"))?;
        count += 1;
    }
    if count == 0 { return Err(format!("{adapter} requires observed prepared operands")); }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    let kind = match adapter {
        FALAKI_APP_TIME_RATIO_ADAPTER => "literature-falaki-prepared-app-time-ratio-csv",
        FALAKI_VOICE_TIME_RATIO_ADAPTER => "literature-falaki-prepared-voice-time-ratio-csv",
        FALAKI_DIURNAL_RATIO_ADAPTER => "literature-falaki-prepared-diurnal-ratio-csv",
        ACTIVITY_APP_TIME_RATIO_ADAPTER => "literature-activity-prepared-app-time-ratio-csv",
        BEYOND_SCREEN_ON_FRACTION_ADAPTER => "literature-beyond-prepared-screen-on-fraction-csv",
        _ => unreachable!("validated prepared scalar alias"),
    };
    complete_standalone_component_adaptation(adapter, kind, original_input_digest,
        bindings, count, count, csv)
}

// Falaki primary p8 Figure13 and pp8-10 Figures14/15/20: arithmetic mean
// across individual relative category popularities, never a pooled duration
// ratio or a confidence interval. The complete user inventory is supplied.
fn adapt_falaki_prepared_category_user_mean(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = FALAKI_CATEGORY_USER_MEAN_ADAPTER;
    let fields = ["source_row_id", "dataset_id", "observation_scope_id", "stratum_id",
        "category_id", "user_id", "device_scope_id", "duration_clock_id",
        "complete_user_inventory_json", "relative_category_popularity"];
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut inventory = BTreeMap::<[String; 4], BTreeSet<String>>::new();
    let mut observed = BTreeMap::<[String; 4], BTreeSet<String>>::new();
    let mut groups = Vec::new();
    let mut rows = Vec::new();
    let mut positive_groups = BTreeSet::new();
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let v = columns.iter().map(|i| record.get(*i).unwrap_or_default()).collect::<Vec<_>>();
        if v.iter().any(|v| v.is_empty()) {
            return Err(format!("{adapter} requires explicit group/user/device/clock identities and values"));
        }
        let group = [1, 2, 3, 4].map(|i| v[i].to_owned());
        let members: Vec<String> = serde_json::from_str(v[8])
            .map_err(|e| format!("{adapter} typed user inventory: {e}"))?;
        let unique = members.iter().cloned().collect::<BTreeSet<_>>();
        if unique.is_empty() || unique.len() != members.len() || members.iter().any(|m| m.is_empty()) {
            return Err(format!("{adapter} requires nonempty unique lexical user inventory"));
        }
        if inventory.insert(group.clone(), unique.clone()).is_some_and(|old| old != unique) {
            return Err(format!("{adapter} complete user inventory changes within one category/group"));
        }
        if !unique.contains(v[5]) || !observed.entry(group.clone()).or_default().insert(v[5].to_owned()) {
            return Err(format!("{adapter} requires exactly one owned value per inventoried user"));
        }
        let value = parse_source_bound_scalar(v[9], "finite_nonnegative", adapter, index + 1, fields[9])?;
        if value > 1.0 { return Err(format!("{adapter} relative category popularity must be a fraction in [0,1]")); }
        if value > 0.0 { positive_groups.insert(group.clone()); }
        if !groups.contains(&group) { groups.push(group.clone()); }
        // Serialized tuples are collision-free keys, not inferred source bins.
        rows.push(GroupedNumericRow { group: Some(serde_json::to_string(&group).unwrap()),
            values: vec![Some(value)] });
    }
    if rows.is_empty() || inventory.iter().any(|(g, expected)| observed.get(g) != Some(expected)) {
        return Err(format!("{adapter} every supplied complete user inventory must be observed exactly once"));
    }
    let count = rows.len();
    let summaries = summarize_columns_by_first_seen_group(&rows)
        .map_err(|e| format!("{adapter} mean: {e:?}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["dataset_id", "observation_scope_id", "stratum_id", "category_id",
        "user_count", "mean_relative_category_popularity"])
        .map_err(|e| format!("{adapter} header: {e}"))?;
    for (group, summary) in groups.iter().zip(&summaries) {
        let mean = summary.means[0];
        if !mean.is_finite() { return Err(format!("{adapter} mean exceeds finite output domain")); }
        if mean == 0.0 && positive_groups.contains(group) {
            return Err(format!("{adapter} nonzero fraction mean underflow exceeds the representable output domain"));
        }
        let mut output = group.to_vec();
        output.extend([inventory[group].len().to_string(), mean.to_string()]);
        writer.write_record(output).map_err(|e| format!("{adapter} row: {e}"))?;
    }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    complete_standalone_component_adaptation(adapter, "literature-falaki-prepared-category-user-mean-csv",
        original_input_digest, bindings, count, summaries.len(), csv)
}

// Borapp primary p4 window selection, p5 Table4. A complete supplied 5-minute
// window and typed change indicators are required. No orientation state codes,
// event/capture transition detection, blacklist or probe/window construction.
fn adapt_borapp_prepared_orientation_any_change(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = BORAPP_ORIENTATION_ANY_CHANGE_ADAPTER;
    let fields = ["source_row_id", "participant_id", "device_id", "window_id", "clock_id",
        "window_duration_seconds", "record_kind", "orientation_change_json"];
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut windows = BTreeSet::new();
    let mut changes = BTreeMap::<[String; 4], Vec<bool>>::new();
    let mut ids = BTreeSet::new();
    let mut count = 0usize;
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let v = columns.iter().map(|i| record.get(*i).unwrap_or_default()).collect::<Vec<_>>();
        if v.iter().any(|v| v.is_empty()) {
            return Err(format!("{adapter} requires explicit window/observation identities and typed change value"));
        }
        let group = [1, 2, 3, 4].map(|i| v[i].to_owned());
        if !ids.insert((group.clone(), v[0].to_owned())) {
            return Err(format!("{adapter} duplicate observation identity within one window"));
        }
        if parse_source_bound_scalar(v[5], "finite_nonnegative", adapter, index + 1, fields[5])? != 300.0 {
            return Err(format!("{adapter} requires supplied 5-minute window duration"));
        }
        let typed: Value = serde_json::from_str(v[7])
            .map_err(|e| format!("{adapter} typed orientation change: {e}"))?;
        match v[6] {
            "window_inventory" if typed.is_null() => {
                if !windows.insert(group.clone()) { return Err(format!("{adapter} duplicate window inventory")); }
            }
            "change_observation" => changes.entry(group).or_default().push(typed.as_bool()
                .ok_or_else(|| format!("{adapter} change observation requires JSON Boolean true or false, not missing"))?),
            _ => return Err(format!("{adapter} requires inventory null or typed Boolean change observation")),
        }
        count += 1;
    }
    if windows.is_empty() || changes.keys().any(|g| !windows.contains(g)) {
        return Err(format!("{adapter} observations require their complete supplied window inventory"));
    }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["participant_id", "device_id", "window_id", "clock_id",
        "window_duration_seconds", "screen_orient_changes"])
        .map_err(|e| format!("{adapter} header: {e}"))?;
    for group in &windows {
        let any_change = changes.get(group).is_some_and(|values| values.iter().any(|v| *v));
        let mut output = group.to_vec();
        output.extend(["300".to_owned(), any_change.to_string()]);
        writer.write_record(output).map_err(|e| format!("{adapter} row: {e}"))?;
    }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    complete_standalone_component_adaptation(adapter, "literature-borapp-prepared-orientation-any-change-csv",
        original_input_digest, bindings, count, windows.len(), csv)
}

// Beyond primary p18: one caller-selected unused interval only. Coordinates
// are already unwrapped in a declared common seconds clock and origin. The
// -3600..25200 example has midpoint10800=3 hours relative to that origin;
// this is not a detected night, inferred rollover, date or timezone conversion.
fn adapt_beyond_prepared_unused_interval_coordinates(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let adapter = BEYOND_UNUSED_INTERVAL_COORDINATES_ADAPTER;
    let fields = ["source_row_id", "participant_id", "device_id", "unused_interval_id",
        "query_id", "interval_clock_id", "query_clock_id", "coordinate_clock_type",
        "coordinate_origin_id", "coordinate_unit", "unused_start_seconds",
        "unused_end_seconds", "query_time_seconds"];
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|e| format!("{adapter} header: {e}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{adapter} refuses duplicate input columns"));
    }
    let columns = fields.iter().map(|f| required_header(&headers, f, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    let mut output_fields = fields.to_vec();
    output_fields.extend(["unused_interval_midpoint_seconds", "midpoint_hours_relative_origin", "hours_since_midpoint"]);
    writer.write_record(output_fields).map_err(|e| format!("{adapter} header: {e}"))?;
    let mut interval_endpoints = BTreeMap::new();
    let mut query_owners = BTreeMap::new();
    let mut rows = BTreeSet::new();
    let mut count = 0usize;
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|e| format!("{adapter} row {}: {e}", index + 1))?;
        let v = columns.iter().map(|i| record.get(*i).unwrap_or_default()).collect::<Vec<_>>();
        if v.iter().any(|v| v.is_empty()) {
            return Err(format!("{adapter} requires explicit interval/query/clock/origin identities and finite coordinates"));
        }
        if v[5] != v[6] || v[7] != "caller_qualified_unwrapped_linear" || v[9] != "seconds" {
            return Err(format!("{adapter} requires one known caller-qualified unwrapped common seconds clock"));
        }
        if !rows.insert([v[1], v[2], v[0]].map(str::to_owned)) {
            return Err(format!("{adapter} duplicate supplied coordinate source row"));
        }
        let start = parse_source_bound_scalar(v[10], "finite", adapter, index + 1, fields[10])?;
        let end = parse_source_bound_scalar(v[11], "finite", adapter, index + 1, fields[11])?;
        let query = parse_source_bound_scalar(v[12], "finite", adapter, index + 1, fields[12])?;
        if end <= start { return Err(format!("{adapter} requires a positive already-unwrapped unused interval")); }
        // The same interval identity cannot silently acquire different clocks,
        // origins or endpoints between independent supplied query rows.
        let interval = [1, 2, 3].map(|i| v[i].to_owned());
        let endpoint = (v[5].to_owned(), v[8].to_owned(), start, end);
        if interval_endpoints.insert(interval.clone(), endpoint.clone()).is_some_and(|old| old != endpoint) {
            return Err(format!("{adapter} contradictory supplied interval ownership or endpoints"));
        }
        let query_owner = [1, 2, 4].map(|i| v[i].to_owned());
        let query_value = (v[6].to_owned(), v[8].to_owned(), query);
        if query_owners.insert(query_owner, query_value.clone()).is_some_and(|old| old != query_value) {
            return Err(format!("{adapter} contradictory supplied query ownership or coordinate"));
        }
        let mean = summarize_columns_by_first_seen_group(&[start, end].map(|value| GroupedNumericRow {
            group: Some("one-supplied-interval".to_owned()), values: vec![Some(value)],
        })).map_err(|e| format!("{adapter} midpoint: {e:?}"))?[0].means[0];
        if !mean.is_finite() { return Err(format!("{adapter} midpoint exceeds finite output domain")); }
        if mean == 0.0 && start != -end {
            return Err(format!("{adapter} nonzero midpoint underflow exceeds the representable output domain"));
        }
        // Existing sum/division implements both relative midpoint hours and
        // signed query-minus-midpoint hours. No recency clamp is introduced.
        let midpoint_hours = grouped_scalar_sum_then_project_unique(&[GroupedScalarInput {
            entity: (), raw_partition: (), passthrough: (), value: RCompatibleScalar::Finite(mean),
        }], SequentialDivisionConfiguration { first_divisor: 3600.0, second_divisor: 1.0 },
            |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?;
        let elapsed = grouped_scalar_sum_then_project_unique(&[query, -mean].map(|value| GroupedScalarInput {
            entity: (), raw_partition: (), passthrough: (), value: RCompatibleScalar::Finite(value),
        }), SequentialDivisionConfiguration { first_divisor: 3600.0, second_divisor: 1.0 },
            |_| Some(())).map_err(|e| format!("{adapter}: {e}"))?;
        let RCompatibleScalar::Finite(midpoint_hours) = midpoint_hours[0].first_scaled_value else {
            return Err(format!("{adapter} midpoint hours exceeds finite output domain"));
        };
        let RCompatibleScalar::Finite(elapsed) = elapsed[0].first_scaled_value else {
            return Err(format!("{adapter} signed elapsed hours exceeds finite output domain"));
        };
        if (midpoint_hours == 0.0 && mean != 0.0) || (elapsed == 0.0 && query != mean) {
            return Err(format!("{adapter} nonzero hours underflow exceeds the representable output domain"));
        }
        let mut output = v.into_iter().map(str::to_owned).collect::<Vec<_>>();
        output.extend([mean.to_string(), midpoint_hours.to_string(), elapsed.to_string()]);
        writer.write_record(output).map_err(|e| format!("{adapter} row: {e}"))?;
        count += 1;
    }
    if count == 0 { return Err(format!("{adapter} requires an observed supplied interval/query")); }
    let csv = writer.into_inner().map_err(|e| format!("{adapter} output: {e}"))?;
    complete_standalone_component_adaptation(adapter, "literature-beyond-prepared-unused-interval-coordinates-csv",
        original_input_digest, bindings, count, count, csv)
}

fn adapt_ranked_snapshot_reversal(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} has no registered component"))?;
    let config: RankedSnapshotReversalComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {RANKED_SNAPSHOT_REVERSAL_ADAPTER} componentConfig: {error}")
        })?;
    if config.snapshot_field.is_empty()
        || config.rank_key_field.is_empty()
        || config.payload_field.is_empty()
        || config.rank_key_prefix.is_empty()
        || config.maximum_rows_per_snapshot == 0
        || config.rank_domain != "canonical_zero_based_decimal_no_leading_zero"
        || config.output_order != "descending_source_rank"
        || config.snapshot_order != "first_seen"
    {
        return Err(format!(
            "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} componentConfig is outside the generic ranked-snapshot reversal contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} refuses duplicate column names"
        ));
    }
    let source_row = required_header(&headers, "source_row_id", RANKED_SNAPSHOT_REVERSAL_ADAPTER)?;
    let entity = required_header(&headers, "entity_id", RANKED_SNAPSHOT_REVERSAL_ADAPTER)?;
    let snapshot = required_header(
        &headers,
        &config.snapshot_field,
        RANKED_SNAPSHOT_REVERSAL_ADAPTER,
    )?;
    let rank_key = required_header(
        &headers,
        &config.rank_key_field,
        RANKED_SNAPSHOT_REVERSAL_ADAPTER,
    )?;
    let payload = required_header(
        &headers,
        &config.payload_field,
        RANKED_SNAPSHOT_REVERSAL_ADAPTER,
    )?;
    let mut first_seen_snapshots = Vec::<(String, String)>::new();
    let mut rows_by_snapshot = BTreeMap::<(String, String), Vec<(usize, [String; 5])>>::new();
    let mut seen_ranks = BTreeMap::<(String, String), BTreeSet<usize>>::new();
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number}: {error}")
        })?;
        source_row_count += 1;
        let source_row_id = record_value(&record, Some(source_row));
        let entity_id = record_value(&record, Some(entity));
        let snapshot_id = record_value(&record, Some(snapshot));
        let raw_key = record_value(&record, Some(rank_key));
        let component_value = record_value(&record, Some(payload));
        if source_row_id.is_empty()
            || entity_id.is_empty()
            || snapshot_id.is_empty()
            || raw_key.is_empty()
            || component_value.is_empty()
        {
            return Err(format!(
                "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number} is missing a required ranked-snapshot field"
            ));
        }
        let encoded_rank = raw_key
            .strip_prefix(&config.rank_key_prefix)
            .ok_or_else(|| {
                format!(
                    "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number} requires rank-key prefix {}",
                    config.rank_key_prefix
                )
            })?;
        if encoded_rank.is_empty()
            || !encoded_rank.bytes().all(|byte| byte.is_ascii_digit())
            || (encoded_rank.len() > 1 && encoded_rank.starts_with('0'))
        {
            return Err(format!(
                "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number} requires a canonical zero-based decimal rank"
            ));
        }
        let rank = encoded_rank.parse::<usize>().map_err(|_| {
            format!(
                "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number} rank exceeds the supported integer domain"
            )
        })?;
        if rank >= config.maximum_rows_per_snapshot {
            return Err(format!(
                "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number} rank exceeds snapshot capacity"
            ));
        }
        let snapshot_key = (entity_id.to_owned(), snapshot_id.to_owned());
        if !rows_by_snapshot.contains_key(&snapshot_key) {
            first_seen_snapshots.push(snapshot_key.clone());
        }
        if !seen_ranks
            .entry(snapshot_key.clone())
            .or_default()
            .insert(rank)
        {
            return Err(format!(
                "{RANKED_SNAPSHOT_REVERSAL_ADAPTER} row {row_number} duplicates a rank within its snapshot"
            ));
        }
        rows_by_snapshot.entry(snapshot_key).or_default().push((
            rank,
            [
                source_row_id.to_owned(),
                entity_id.to_owned(),
                snapshot_id.to_owned(),
                raw_key.to_owned(),
                component_value.to_owned(),
            ],
        ));
    }

    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_row_id",
            "entity_id",
            config.snapshot_field.as_str(),
            config.rank_key_field.as_str(),
            config.payload_field.as_str(),
        ])
        .map_err(|error| format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} write header: {error}"))?;
    let mut previous_snapshot_by_entity = BTreeMap::new();
    let mut emitted_row_count = 0usize;
    for (entity_id, snapshot_id) in first_seen_snapshots {
        let rows = rows_by_snapshot
            .get_mut(&(entity_id.clone(), snapshot_id))
            .expect("first-seen snapshot has grouped rows");
        rows.sort_by_key(|(rank, _)| std::cmp::Reverse(*rank));
        let signature: Vec<_> = rows
            .iter()
            .map(|(rank, row)| (*rank, row[4].clone()))
            .collect();
        if previous_snapshot_by_entity.get(&entity_id) == Some(&signature) {
            continue;
        }
        previous_snapshot_by_entity.insert(entity_id, signature);
        for (_, row) in rows {
            writer.write_record(row.iter()).map_err(|error| {
                format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} write row: {error}")
            })?;
            emitted_row_count += 1;
        }
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{RANKED_SNAPSHOT_REVERSAL_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        RANKED_SNAPSHOT_REVERSAL_ADAPTER,
        "literature-ranked-snapshot-reversal-csv",
        original_input_digest,
        bindings,
        source_row_count,
        emitted_row_count,
        csv_bytes,
    )
}

fn adapt_app_relationship_matrices(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{APP_RELATIONSHIP_MATRICES_ADAPTER} refuses duplicate column names"
        ));
    }
    let source_row = required_header(&headers, "source_row_id", APP_RELATIONSHIP_MATRICES_ADAPTER)?;
    let entity = required_header(&headers, "entity_id", APP_RELATIONSHIP_MATRICES_ADAPTER)?;
    let app = required_header(&headers, "app_id", APP_RELATIONSHIP_MATRICES_ADAPTER)?;
    let hour = required_header(&headers, "hour_scope_id", APP_RELATIONSHIP_MATRICES_ADAPTER)?;
    let day = required_header(&headers, "day_scope_id", APP_RELATIONSHIP_MATRICES_ADAPTER)?;
    let policy = required_header(
        &headers,
        "matrix_policy_json",
        APP_RELATIONSHIP_MATRICES_ADAPTER,
    )?;
    let mut configuration = None;
    let mut launches = Vec::new();
    for (index, record) in reader.records().enumerate() {
        let row = record.map_err(|error| {
            format!(
                "{APP_RELATIONSHIP_MATRICES_ADAPTER} row {}: {error}",
                index + 1
            )
        })?;
        let required =
            [source_row, entity, app, hour, day].map(|field| record_value(&row, Some(field)));
        if required.iter().any(|value| value.is_empty()) {
            return Err(format!(
                "{APP_RELATIONSHIP_MATRICES_ADAPTER} row {} is missing a required field",
                index + 1
            ));
        }
        let policy_json = record_value(&row, Some(policy));
        if !policy_json.is_empty() {
            let row_configuration: AppRelationshipConfiguration = serde_json::from_str(policy_json)
                .map_err(|error| {
                format!(
                    "{APP_RELATIONSHIP_MATRICES_ADAPTER} row {} has invalid matrix_policy_json: {error}",
                    index + 1
                )
            })?;
            if configuration.is_some_and(|value| value != row_configuration) {
                return Err(format!(
                    "{APP_RELATIONSHIP_MATRICES_ADAPTER} requires one consistent matrix policy"
                ));
            }
            configuration = Some(row_configuration);
        }
        launches.push(OrderedAppLaunch {
            entity_id: required[1].to_owned(),
            app_id: required[2].to_owned(),
            hour_scope_id: required[3].to_owned(),
            day_scope_id: required[4].to_owned(),
        });
    }
    let configuration = configuration.ok_or_else(|| {
        format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} requires at least one launch row")
    })?;
    let (records, maxima) = materialize_app_relationship_matrices(&launches, configuration)
        .map_err(|_| {
            format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} refuses an undisclosed matrix policy")
        })?;
    let output_row_count = records.len() + maxima.len();
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "record_kind",
            "entity_id",
            "relationship",
            "source_app_id",
            "target_app_id",
            "occurrence_count",
            "probability",
            "maximum_target_app_ids_json",
        ])
        .map_err(|error| format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} write header: {error}"))?;
    for record in records {
        let relationship = match record.relationship {
            Relationship::ConsecutiveTransition => "consecutive_transition",
            Relationship::SameHour => "same_hour",
            Relationship::SameDay => "same_day",
        };
        writer
            .write_record([
                "matrix_cell".to_owned(),
                record.entity_id,
                relationship.to_owned(),
                record.source_app_id,
                record.target_app_id,
                record.occurrence_count.to_string(),
                record.probability.to_string(),
                String::new(),
            ])
            .map_err(|error| format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} write row: {error}"))?;
    }
    for maximum in maxima {
        writer
            .write_record([
                "maximum_transition".to_owned(),
                maximum.entity_id,
                "consecutive_transition".to_owned(),
                maximum.source_app_id,
                String::new(),
                String::new(),
                maximum.probability.to_string(),
                serde_json::to_string(&maximum.target_app_ids).expect("string arrays serialize"),
            ])
            .map_err(|error| format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{APP_RELATIONSHIP_MATRICES_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        APP_RELATIONSHIP_MATRICES_ADAPTER,
        "literature-app-relationship-matrices-csv",
        original_input_digest,
        bindings,
        launches.len(),
        output_row_count,
        csv_bytes,
    )
}

fn adapt_exact_categorical_row_filter(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} has no registered component")
        })?;
    let config: ExactCategoricalRowFilterComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} componentConfig: {error}")
        })?;
    let excluded_values = config.excluded_values.iter().collect::<BTreeSet<_>>();
    if config.required_field.is_empty()
        || config.required_value.is_empty()
        || config.excluded_field.is_empty()
        || config.required_field == config.excluded_field
        || excluded_values.is_empty()
        || excluded_values.len() != config.excluded_values.len()
        || excluded_values.iter().any(|value| value.is_empty())
        || config.comparison != "exact_case_and_whitespace_sensitive"
        || config.missing_value_policy != "drop_row"
        || config.retained_row_policy != "preserve_input_row_order_and_duplicates"
    {
        return Err(format!(
            "{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} componentConfig is outside the generic exact categorical row-filter contract"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} refuses duplicate column names"
        ));
    }
    let source_row = required_header(
        &headers,
        "source_row_id",
        EXACT_CATEGORICAL_ROW_FILTER_ADAPTER,
    )?;
    let required = required_header(
        &headers,
        &config.required_field,
        EXACT_CATEGORICAL_ROW_FILTER_ADAPTER,
    )?;
    let excluded = required_header(
        &headers,
        &config.excluded_field,
        EXACT_CATEGORICAL_ROW_FILTER_ADAPTER,
    )?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(&headers)
        .map_err(|error| format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} write header: {error}"))?;
    let mut source_row_count = 0usize;
    let mut emitted_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} row {row_number}: {error}")
        })?;
        source_row_count += 1;
        let source_row_id = record.get(source_row).unwrap_or("");
        if source_row_id.is_empty() {
            return Err(format!(
                "{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} row {row_number} requires a nonempty source_row_id"
            ));
        }
        let required_value = record.get(required).unwrap_or("");
        let excluded_value = record.get(excluded).unwrap_or("");
        let retained = required_value == config.required_value
            && !excluded_value.is_empty()
            && !excluded_values
                .iter()
                .any(|candidate| candidate.as_str() == excluded_value);
        if retained {
            writer.write_record(record.iter()).map_err(|error| {
                format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} write row {row_number}: {error}")
            })?;
            emitted_row_count += 1;
        }
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{EXACT_CATEGORICAL_ROW_FILTER_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        EXACT_CATEGORICAL_ROW_FILTER_ADAPTER,
        "literature-exact-categorical-row-filter-csv",
        original_input_digest,
        bindings,
        source_row_count,
        emitted_row_count,
        csv_bytes,
    )
}

// Insert in literature_input_adapters.rs beside existing standalone components.
// Reuses the existing 79-pattern constant; leaves its older normalized-row route unchanged.
const NOTIFICATION_PAYLOAD_CLEANING_ADAPTER: &str = "chronicle.notification-payload-cleaning";

fn released_notification_source_exclusion_patterns() -> Result<&'static RegexSet, String> {
    static PATTERNS: OnceLock<Result<RegexSet, String>> = OnceLock::new();
    PATTERNS.get_or_init(|| {
        // The retained base-R oracle checks TRE's default dot/newline semantics.
        regex::RegexSetBuilder::new(NOTIFICATION_SOURCE_EXCLUSION_PATTERNS)
            .dot_matches_new_line(true)
            .build()
            .map_err(|error| format!("invalid released notification exclusion regex: {error}"))
    }).as_ref().map_err(Clone::clone)
}

fn notification_payload_sender(data: &str) -> String {
    // Released R: sub('text.*', '', Data), then substr(data, 2, nchar(data)-6).
    // This is not a JSON parser; malformed/short strings retain the source slicing.
    let prefix = data.split_once("text").map_or(data, |(before, _)| before);
    prefix.chars().skip(1).take(prefix.chars().count().saturating_sub(7)).collect()
}

fn notification_payload_date_and_time(value: &str, row_number: usize) -> Result<(String, String), String> {
    // A bounded character-Time contract, not vroom class/locale inference.
    // Validate the literal ISO date only; never shift the source's clock.
    let date: String = value.chars().take(10).collect();
    let bytes = date.as_bytes();
    let iso_date = bytes.len() == 10
        && bytes.iter().enumerate().all(|(index, byte)| {
            if index == 4 || index == 7 { *byte == b'-' } else { byte.is_ascii_digit() }
        });
    if !iso_date || parse_chronicle_timestamp_ns(&format!("{date} 00:00:00")).is_none() {
        return Err(format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} row {row_number} Time requires a valid canonical YYYY-MM-DD prefix"));
    }
    Ok((date, value.chars().skip(11).take(8).collect()))
}

fn adapt_notification_payload_cleaning(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| {
        format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} header: {error}")
    })?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} refuses duplicate column names"));
    }
    let source_row = required_header(&headers, "source_row_id", NOTIFICATION_PAYLOAD_CLEANING_ADAPTER)?;
    let code_column = required_header(&headers, "Code", NOTIFICATION_PAYLOAD_CLEANING_ADAPTER)?;
    let time_column = required_header(&headers, "Time", NOTIFICATION_PAYLOAD_CLEANING_ADAPTER)?;
    let data_column = required_header(&headers, "Data", NOTIFICATION_PAYLOAD_CLEANING_ADAPTER)?;
    let study_week = header_index(&headers, "study_week");
    let intervention_group = header_index(&headers, "intervention_group");
    let patterns = released_notification_source_exclusion_patterns()?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record([
        "source_row_id", "ID", "date", "time", "app", "Time",
        "participant_id", "event_timestamp", "interaction_type", "application_label",
        "study_local_date", "tracking_date_observed", "notification_observed",
        "study_week", "intervention_group",
    ]).map_err(|error| format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} write header: {error}"))?;
    let mut source_row_count = 0usize;
    let mut emitted_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} row {row_number}: {error}")
        })?;
        source_row_count += 1;
        let source_row_id = record.get(source_row).unwrap_or("");
        let code = record.get(code_column).unwrap_or("");
        if source_row_id.is_empty() || code.is_empty() {
            return Err(format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} row {row_number} requires nonempty source_row_id and Code"));
        }
        // The released filter removes the test identity BEFORE sender/date mutation.
        if code == "hmK3i4czcpB7qOiAg0" { continue; }
        let raw_time = record.get(time_column).unwrap_or("");
        let (date, time) = notification_payload_date_and_time(raw_time, row_number)?;
        let app = notification_payload_sender(record.get(data_column).unwrap_or(""));
        if patterns.is_match(&app) { continue; }
        writer.write_record([
            source_row_id, code, date.as_str(), time.as_str(), app.as_str(), raw_time,
            code, raw_time, "Notification", app.as_str(), date.as_str(), "false", "true",
            study_week.and_then(|index| record.get(index)).unwrap_or(""),
            intervention_group.and_then(|index| record.get(index)).unwrap_or(""),
        ]).map_err(|error| {
            format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} write row {row_number}: {error}")
        })?;
        emitted_row_count += 1;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{NOTIFICATION_PAYLOAD_CLEANING_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        NOTIFICATION_PAYLOAD_CLEANING_ADAPTER,
        "literature-notification-payload-cleaning-csv",
        original_input_digest, bindings, source_row_count, emitted_row_count, csv_bytes,
    )
}

const ETHICA_FOREGROUND_PREPARATION_ADAPTER: &str =
    "chronicle.ethica-foreground-interval-preparation";

#[derive(Debug, Clone, Copy)]
enum EthicaPreparationMode {
    LegacyKernel,
    ReleasedSource { last_used_offset_ns: i64 },
}

impl EthicaPreparationMode {
    fn is_released_source(self) -> bool {
        matches!(self, Self::ReleasedSource { .. })
    }

    fn last_used_offset_ns(self) -> i64 {
        match self {
            Self::LegacyKernel => 2 * 60 * 60 * 1_000_000_000,
            Self::ReleasedSource { last_used_offset_ns } => last_used_offset_ns,
        }
    }
}

struct EthicaIntervalPreparation {
    intervals: Vec<(EthicaAppUsageRow, i64, i64)>,
    source_row_count: u32,
    duplicate_rows_removed: u32,
    corrected_timestamp_rows: u32,
}

fn parse_ethica_coordinate(value: &str, mode: EthicaPreparationMode) -> Option<i64> {
    if mode.is_released_source() {
        chronicle_chrono_kernel_wasm::parse_chronicle_timestamp_ns_checked(value)
    } else {
        parse_chronicle_timestamp_ns(value)
    }
}

fn prepare_ethica_app_usage_intervals(
    raw_csv: &[u8],
    mode: EthicaPreparationMode,
) -> Result<EthicaIntervalPreparation, String> {
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(raw_csv);
    let headers = reader.headers()
        .map_err(|error| format!("chronicle.ethica-app-usage-stream raw header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err("chronicle.ethica-app-usage-stream refuses duplicate raw column names".into());
    }
    let user_id = required_header(&headers, "user_id", "chronicle.ethica-app-usage-stream")?;
    let app_name = required_header(&headers, "app_name", "chronicle.ethica-app-usage-stream")?;
    let start_time = required_header(&headers, "start_time", "chronicle.ethica-app-usage-stream")?;
    let foreground_time = required_header(&headers, "fg_time_ms", "chronicle.ethica-app-usage-stream")?;
    let last_used = required_header(&headers, "last_used", "chronicle.ethica-app-usage-stream")?;
    let mut source_row_count = 0u32;
    let mut corrected_timestamp_rows = 0u32;
    let mut admitted_rows = Vec::new();
    for (index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| format!("chronicle.ethica-app-usage-stream raw row: {error}"))?;
        source_row_count = source_row_count.checked_add(1)
            .ok_or("chronicle.ethica-app-usage-stream row count overflow")?;
        // Typed CSV boundary: empty/NA cells represent declared missing values.
        // Any supplied column participates in source na.omit(), including extras.
        // Arbitrary vroom parsing/missing-token conventions are not reconstructed.
        if mode.is_released_source()
            && (record.iter().any(|value| matches!(value, "" | "NA"))
                || record.get(foreground_time) == Some("NaN"))
        {
            continue;
        }
        let user_id_value = if mode.is_released_source() { record.get(user_id).unwrap_or("") } else { record_value(&record, Some(user_id)) };
        let app_name_value = if mode.is_released_source() { record.get(app_name).unwrap_or("") } else { record_value(&record, Some(app_name)) };
        let start_time_ns = parse_ethica_coordinate(record_value(&record, Some(start_time)), mode)
            .ok_or_else(|| format!("chronicle.ethica-app-usage-stream row {} has invalid start_time", index + 1))?;
        let foreground_time_text = record_value(&record, Some(foreground_time));
        let foreground_time_ms = foreground_time_text.parse::<f64>()
            .map_err(|_| format!("chronicle.ethica-app-usage-stream row {} has invalid fg_time_ms", index + 1))?;
        if !foreground_time_ms.is_finite() {
            return Err(format!("chronicle.ethica-app-usage-stream row {} has non-finite fg_time_ms", index + 1));
        }
        let last_used_ns = parse_ethica_coordinate(record_value(&record, Some(last_used)), mode)
            .ok_or_else(|| format!("chronicle.ethica-app-usage-stream row {} has invalid last_used", index + 1))?;
        if user_id_value.is_empty() || app_name_value.is_empty() {
            return Err(format!("chronicle.ethica-app-usage-stream row {} requires user_id and app_name", index + 1));
        }
        // Preserve the legacy raw-positive gate. The released preparation stage
        // instead retains zero/reset counters until AFTER differencing.
        if !mode.is_released_source() && foreground_time_ms <= 0.0 {
            continue;
        }
        let foreground_time_ns_float = foreground_time_ms * 1_000_000.0;
        let out_of_range = if mode.is_released_source() {
            !foreground_time_ns_float.is_finite()
                || !(-9_223_372_036_854_775_808.0..9_223_372_036_854_775_808.0).contains(&foreground_time_ns_float)
        } else {
            foreground_time_ns_float > i64::MAX as f64
        };
        if out_of_range {
            return Err(format!("chronicle.ethica-app-usage-stream row {} fg_time_ms is outside the supported range", index + 1));
        }
        // Existing typed owner uses nanosecond coordinates. Refuse finer source
        // counters rather than silently merging distinct counters or losing a
        // positive sub-nanosecond duration. Legacy rounding stays unchanged.
        if mode.is_released_source() && foreground_time_ns_float.fract() != 0.0 {
            return Err(format!("chronicle.ethica-app-usage-stream row {} fg_time_ms exceeds nanosecond precision", index + 1));
        }
        let foreground_time_ns = foreground_time_ns_float.round() as i64;
        if !mode.is_released_source() && foreground_time_ns <= 0 {
            return Err(format!("chronicle.ethica-app-usage-stream row {} fg_time_ms exceeds nanosecond precision", index + 1));
        }
        let corrected_last_used_ns = last_used_ns.checked_add(mode.last_used_offset_ns())
            .ok_or_else(|| format!("chronicle.ethica-app-usage-stream row {} corrected last_used is outside the supported range", index + 1))?;
        corrected_timestamp_rows = corrected_timestamp_rows.checked_add(1)
            .ok_or("chronicle.ethica-app-usage-stream corrected row count overflow")?;
        let source_counter_identity = if mode.is_released_source() {
            // R double equality treats positive/negative zero as the same value.
            if foreground_time_ms == 0.0 { 0 } else { foreground_time_ms.to_bits() }
        } else {
            // Original adapter used the admitted nanosecond value as identity.
            foreground_time_ns as u64
        };
        admitted_rows.push(EthicaAppUsageRow {
            source_row: u32::try_from(index + 1)
                .map_err(|_| "chronicle.ethica-app-usage-stream source row index overflow")?,
            user_id: user_id_value.to_owned(),
            app_name: app_name_value.to_owned(),
            start_time_ns,
            foreground_time_ns,
            last_used_ns: corrected_last_used_ns,
            foreground_time_ms: foreground_time_text.to_owned(),
            source_counter_identity,
        });
    }
    let mut duplicate_rows_removed = 0u32;
    let mut seen = BTreeSet::new();
    // FIRST original input row wins; last_used is deliberately NOT in the key.
    admitted_rows.retain(|row| {
        let keep = seen.insert((row.user_id.clone(), row.app_name.clone(),
            row.start_time_ns, row.source_counter_identity));
        if !keep { duplicate_rows_removed += 1; }
        keep
    });
    let mut groups = BTreeMap::<(String, String, i64), Vec<EthicaAppUsageRow>>::new();
    for row in admitted_rows {
        groups.entry((row.user_id.clone(), row.app_name.clone(), row.start_time_ns))
            .or_default().push(row);
    }
    let mut intervals = Vec::new();
    for (_, mut group) in groups {
        group.sort_by_key(|row| (row.last_used_ns, row.source_row));
        let mut previous_foreground_time_ns = None;
        for row in group {
            let duration_ns = match previous_foreground_time_ns {
                Some(previous) => row.foreground_time_ns.checked_sub(previous)
                    .ok_or("chronicle.ethica-app-usage-stream counter difference overflow")?,
                None => row.foreground_time_ns,
            };
            previous_foreground_time_ns = Some(row.foreground_time_ns);
            if duration_ns <= 0 { continue; }
            let segment_start_ns = row.last_used_ns.checked_sub(duration_ns)
                .ok_or("chronicle.ethica-app-usage-stream segment start is outside the supported range")?;
            intervals.push((row, segment_start_ns, duration_ns));
        }
    }
    if mode.is_released_source() {
        // Reproduce arrange(last_used) before grouped mutate, followed by stable
        // arrange(user_id,start). Across-group equal starts retain end/input order.
        intervals.sort_by(|(left, left_start, _), (right, right_start, _)| {
            (&left.user_id, left_start, left.last_used_ns, left.source_row)
                .cmp(&(&right.user_id, right_start, right.last_used_ns, right.source_row))
        });
    } else {
        intervals.sort_by(|(left, left_start, _), (right, right_start, _)| {
            (&left.user_id, left_start, left.source_row)
                .cmp(&(&right.user_id, right_start, right.source_row))
        });
    }
    Ok(EthicaIntervalPreparation { intervals, source_row_count,
        duplicate_rows_removed, corrected_timestamp_rows })
}

struct EthicaDateWindowParameters {
    configuration_id: String,
    study_start_date: String,
    study_end_date: String,
    last_used_offset_seconds: i64,
    last_used_offset_ns: i64,
    start_midnight_ns: i64,
    end_next_midnight_ns: i64,
    end_clip_ns: i64,
}

fn ethica_date_midnight_ns(date: &str) -> Result<i64, String> {
    if date.len() != 10 || date.as_bytes()[4] != b'-' || date.as_bytes()[7] != b'-'
        || date.bytes().enumerate().any(|(index, byte)| index != 4 && index != 7 && !byte.is_ascii_digit())
    {
        return Err("Ethica study dates require exact YYYY-MM-DD dates".into());
    }
    chronicle_chrono_kernel_wasm::parse_chronicle_timestamp_ns_checked(&format!("{date} 00:00:00"))
        .ok_or_else(|| format!("Ethica study date is invalid or outside supported range: {date}"))
}

fn parse_ethica_date_window_parameters(bytes: &[u8]) -> Result<EthicaDateWindowParameters, String> {
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(bytes);
    let headers = reader.headers().map_err(|error| format!("Ethica parameter header: {error}"))?.clone();
    let expected = ["configuration_id", "study_start_date", "study_end_date", "last_used_offset_seconds"];
    if headers.len() != expected.len() || expected.iter().any(|field| headers.iter().filter(|header| *header == *field).count() != 1) {
        return Err("Ethica parameters require exactly the four declared columns".into());
    }
    let index = |field| headers.iter().position(|header| header == field).expect("validated parameter header");
    let records = reader.records().collect::<Result<Vec<_>, _>>()
        .map_err(|error| format!("Ethica parameter row: {error}"))?;
    if records.len() != 1 { return Err("Ethica parameters require exactly one invocation-level row".into()); }
    let record = &records[0];
    let configuration_id = record[index("configuration_id")].to_owned();
    let study_start_date = record[index("study_start_date")].to_owned();
    let study_end_date = record[index("study_end_date")].to_owned();
    let last_used_offset_seconds = record[index("last_used_offset_seconds")].parse::<i64>()
        .map_err(|_| "Ethica last_used_offset_seconds requires an integer")?;
    match configuration_id.as_str() {
        "source_june_2020_plus_2h" if study_start_date == "2020-06-01"
            && study_end_date == "2020-06-23" && last_used_offset_seconds == 7200 => {}
        "supplied_date_window" => {}
        _ => return Err("Ethica configuration must be the exact named source preset or supplied_date_window".into()),
    }
    let start_midnight_ns = ethica_date_midnight_ns(&study_start_date)?;
    let end_midnight_ns = ethica_date_midnight_ns(&study_end_date)?;
    if start_midnight_ns > end_midnight_ns { return Err("Ethica study start date exceeds end date".into()); }
    let end_next_midnight_ns = end_midnight_ns.checked_add(86_400 * 1_000_000_000)
        .ok_or("Ethica end date exceeds supported range")?;
    let end_clip_ns = end_next_midnight_ns.checked_sub(1_000_000_000)
        .ok_or("Ethica end clipping instant exceeds supported range")?;
    let last_used_offset_ns = last_used_offset_seconds.checked_mul(1_000_000_000)
        .ok_or("Ethica timestamp offset exceeds supported range")?;
    Ok(EthicaDateWindowParameters { configuration_id, study_start_date, study_end_date,
        last_used_offset_seconds, last_used_offset_ns, start_midnight_ns,
        end_next_midnight_ns, end_clip_ns })
}

type EthicaClippedInterval = (EthicaAppUsageRow, i64, i64, i64, i64);

fn retain_and_clip_ethica_intervals(
    intervals: Vec<(EthicaAppUsageRow, i64, i64)>,
    parameters: &EthicaDateWindowParameters,
) -> Vec<EthicaClippedInterval> {
    let mut retained = intervals.into_iter().filter_map(|(row, start, duration)| {
        // as_date(end)>=first date AND as_date(start)<=last date, in the explicit
        // parsed-UTC/+offset coordinate basis. This is not a continuous clamp.
        if row.last_used_ns < parameters.start_midnight_ns || start >= parameters.end_next_midnight_ns { return None; }
        let clipped_start = if start < parameters.start_midnight_ns { parameters.start_midnight_ns } else { start };
        let clipped_end = if row.last_used_ns >= parameters.end_next_midnight_ns { parameters.end_clip_ns } else { row.last_used_ns };
        Some((row, start, duration, clipped_start, clipped_end))
    }).collect::<Vec<_>>();
    // Stable final arrange(user_id,start): earlier pre-clipping order breaks ties.
    retained.sort_by(|left, right| (&left.0.user_id, left.3).cmp(&(&right.0.user_id, right.3)));
    retained
}

fn adapt_ethica_foreground_interval_preparation(
    raw_csv: &[u8],
    parameters_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings.iter().find(|binding| binding.adapter_id == ETHICA_FOREGROUND_PREPARATION_ADAPTER)
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or("Ethica preparation has no registered component")?;
    let expected_config = serde_json::json!({
        "parameterSourceRole": "study_dates_file",
        "windowSemantics": "inclusive_source_dates_conditional_endpoint_clipping",
        "counterStage": "processed_chunks_before_diff",
        "retainedDuration": "original_positive_difference_seconds",
        "sourcePreset": {"configurationId":"source_june_2020_plus_2h",
            "studyStartDate":"2020-06-01", "studyEndDate":"2020-06-23", "lastUsedOffsetSeconds":7200}
    });
    if group.component_config.as_ref() != Some(&expected_config) {
        return Err("Ethica preparation componentConfig drifts from released stage".into());
    }
    let parameters = parse_ethica_date_window_parameters(parameters_csv)?;
    let prepared = prepare_ethica_app_usage_intervals(raw_csv,
        EthicaPreparationMode::ReleasedSource { last_used_offset_ns: parameters.last_used_offset_ns })?;
    let retained = retain_and_clip_ethica_intervals(prepared.intervals, &parameters);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(["user_id", "apk", "start", "duration", "end", "source_data_row",
        "unclipped_start", "unclipped_end", "source_start_time", "source_fg_time_ms",
        "configuration_id", "study_start_date", "study_end_date", "last_used_offset_seconds"])
        .map_err(|error| format!("Ethica preparation output header: {error}"))?;
    let timestamp = |value| format_chronicle_timestamp_ns(value).ok_or("Ethica output timestamp outside supported range");
    for (row, original_start, duration, start, end) in &retained {
        writer.write_record([row.user_id.clone(), row.app_name.clone(), timestamp(*start)?,
            format_duration_seconds_from_ns(*duration), timestamp(*end)?, row.source_row.to_string(),
            timestamp(*original_start)?, timestamp(row.last_used_ns)?, timestamp(row.start_time_ns)?,
            row.foreground_time_ms.clone(), parameters.configuration_id.clone(),
            parameters.study_start_date.clone(), parameters.study_end_date.clone(),
            parameters.last_used_offset_seconds.to_string()])
            .map_err(|error| format!("Ethica preparation output row: {error}"))?;
    }
    let bytes = writer.into_inner().map_err(|error| format!("Ethica preparation output: {error}"))?;
    let mut adapted = complete_standalone_component_adaptation(
        ETHICA_FOREGROUND_PREPARATION_ADAPTER, "literature-ethica-foreground-interval-preparation-csv",
        original_input_digest, bindings, prepared.source_row_count as usize, retained.len(), bytes)?;
    adapted.receipt.duplicate_source_ids_removed = prepared.duplicate_rows_removed;
    adapted.receipt.corrected_timestamp_provenance_rows = prepared.corrected_timestamp_rows;
    adapted.receipt.materialized_interval_count = u32::try_from(retained.len()).map_err(|_| "Ethica output row count overflow")?;
    Ok(adapted)
}

