// Touchstroke, DOI 10.1007/978-3-319-23222-5_4, printed p.30/PDF p.4:
// Eq.1 and Fig.1. These normalized tables are computation inputs, not a
// reconstruction of the undisclosed Android export or ARFF serialization.
const TOUCHSTROKE_TIMING_COLUMNS: [&str; 14] = [
    "D1", "D2", "D3", "D4", "F1Type1", "F2Type1", "F3Type1",
    "F1Type2", "F2Type2", "F3Type2", "F1Type3", "F2Type3", "F3Type3", "FType4",
];

// Shared by the two source-disclosed norm calculations. This is mathematical
// formula parity, not parity with an unrecovered author's FP evaluation order.
fn finite_three_axis_magnitude(axes: [f64; 3]) -> Option<f64> {
    if axes.iter().any(|axis| !axis.is_finite()) {
        return None;
    }
    let norm = axes[0].hypot(axes[1]).hypot(axes[2]);
    norm.is_finite().then_some(norm)
}

// Carat DOI10.2196/26540 primary p4 Eq1–2/text100:218–265;
// App1 pp1–2. Only supplied frequencies/rescaled hours/resolved day pairs.
// No raw grouping, rescaling, missing-hour policy or log-base recovery.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CaratStateProbability { state_id: String, probability: f64 }
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CaratPairedHour { hour_id: String, day_a_value: f64, day_b_value: f64 }
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CaratDayPair {
    pair_id: String, day_a_id: String, day_b_id: String, regularity_index: f64,
}

// Hammer352.txt:82–198/426–432; HMOG112.txt:330–335; MoMM author.pdf
// pp2–3§3.3,p3Figure1/footnote,p5§5. These stages consume supplied
// source-qualified memberships, endpoints, order and classifications only.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct SuppliedFinitePoint { sample_id: String, value: f64 }
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct SuppliedCategoryPoint { sample_id: String, state: String }
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct HammerPreparedGroup {
    numeric: Vec<SuppliedFinitePoint>,
    categorical: Vec<SuppliedCategoryPoint>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct HammerEndpoint {
    owner_id: String, event_id: String, event_kind: String,
    clock_id: String, timestamp_ns: i64, precision_ns: i64,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct HammerEligibleApp { occurrence_id: String, app_id: String }
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct MommTraceEvent {
    event_id: String, event_key: String,
    locked_length_equals_authentication_time: Option<bool>,
}

fn supplied_finite_points(text: &str) -> Result<Vec<SuppliedFinitePoint>, String> {
    let points: Vec<SuppliedFinitePoint> = serde_json::from_str(text)
        .map_err(|error| format!("invalid supplied points: {error}"))?;
    validate_supplied_finite_points(&points)?;
    Ok(points)
}
fn validate_supplied_finite_points(points: &[SuppliedFinitePoint]) -> Result<(), String> {
    let mut ids = BTreeSet::new();
    for point in points {
        if point.sample_id.trim().is_empty() || !ids.insert(&point.sample_id) {
            return Err("requires unique nonblank literal sample identities".into());
        }
        if !point.value.is_finite() { return Err("requires finite supplied values; missingness is not imputed".into()); }
    }
    Ok(())
}
fn supplied_point_mean(points: &[SuppliedFinitePoint]) -> Result<f64, String> {
    if points.is_empty() { return Err("empty_complete_membership".into()); }
    carat_complete_mean(&points.iter().map(|point| point.value).collect::<Vec<_>>())
}

// No generic keyguard/PIN state aliases: all13 edge groups and their actions
// are transcribed from the rendered MoMM Figure1. Equality is supplied, not
// numerically reconstructed; this output is an action trace, not raw sessions.
fn momm_supported_trace(initial: &str, text: &str) -> Result<String, String> {
    const STATES: [&str; 6] = ["locked, display off","locked, ringing",
        "locked, display on","locked, active call","unlocked","unlocked, call"];
    let events: Vec<MommTraceEvent> = serde_json::from_str(text)
        .map_err(|error| format!("invalid ordered source events: {error}"))?;
    let mut seen = BTreeSet::new();
    for event in &events {
        if event.event_id.trim().is_empty() || !seen.insert(&event.event_id) {
            return Err("requires unique nonblank literal event identities".into());
        }
    }
    if !STATES.contains(&initial) { return Err("unknown_explicit_initial_state".into()); }
    let mut state = initial;
    let mut output = Vec::new();
    for event in &events {
        let keyguard = state == "locked, display on" && event.event_key == "phone|keyguardremoved";
        let (next, actions): (&str, Vec<&str>) = match (state, event.event_key.as_str()) {
            ("locked, display off","screen|power (on)") =>
                ("locked, display on",vec!["start locked session","start authentication timer"]),
            ("locked, display off","phone|ringing") => ("locked, ringing",vec![]),
            ("locked, ringing","phone|idle") => ("locked, display off",vec![]),
            ("locked, ringing","screen|power (on)" | "screen|power (off)") => ("locked, ringing",vec![]),
            ("locked, ringing","phone|offhook") => ("locked, active call",vec!["start locked session"]),
            ("locked, active call","screen|power (on)" | "screen|power (off)") => ("locked, active call",vec![]),
            ("locked, active call","phone|idle") => ("locked, display on",vec!["start authentication timer"]),
            ("locked, display on","screen|power (off)" | "shutdown") =>
                ("locked, display off",vec!["end locked session","discard authentication timer"]),
            ("locked, display on","phone|keyguardremoved") => {
                let equal = event.locked_length_equals_authentication_time
                    .ok_or("missing_source_qualified_locked_length_authentication_equality")?;
                ("unlocked",vec!["end authentication timer","start unlocked session",
                    if equal { "discard locked session" } else { "end locked session" }])
            },
            ("unlocked","screen|power (off)" | "shutdown") =>
                ("locked, display off",vec!["end unlocked session"]),
            ("unlocked","phone|calling" | "phone|ringing") => ("unlocked, call",vec![]),
            ("unlocked, call","screen|power (on)" | "screen|power (off)") => ("unlocked, call",vec![]),
            ("unlocked, call","phone|idle") => ("unlocked",vec![]),
            _ => return Err(format!("unsupported_source_transition:{state}:{}",event.event_key)),
        };
        if !keyguard && event.locked_length_equals_authentication_time.is_some() {
            return Err("equality qualification belongs only to the supported keyguard-removal edge".into());
        }
        output.push(serde_json::json!({"event_id":event.event_id,"event_key":event.event_key,
            "from":state,"to":next,"actions":actions}));
        state = next;
    }
    serde_json::to_string(&output).map_err(|error| error.to_string())
}

fn adapt_supplied_hammer_hmog_momm(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt], adapter: &str,
) -> Result<AdaptedLiteratureInput, String> {
    let (kind, outputs, identity_fields): (&'static str,&[&str],&[&str]) = match adapter {
        "chronicle.hammer-supplied-application-response-proxy" => ("literature-hammer-supplied-application-response-proxy-csv",
            &["notification_response_proxy","computation_status","computation_reason"],
            &["participant_id","device_id","source_stream_id","notification_id"]),
        "chronicle.hammer-supplied-elapsed" => ("literature-hammer-supplied-elapsed-csv",
            &["elapsed_ns"], &["participant_id","device_id","source_stream_id","pair_id","quantity"]),
        "chronicle.hammer-prepared-group-summary" => ("literature-hammer-prepared-group-summary-csv",
            &["numeric_minimum","numeric_maximum","numeric_average","numeric_mean_status","numeric_mean_reason",
              "categorical_mode","categorical_mode_status","categorical_mode_reason"],
            &["participant_id","group_kind","group_id","feature_id"]),
        "chronicle.hammer-first-eligible-app" => ("literature-hammer-first-eligible-app-csv",
            &["first_eligible_app_id","first_eligible_occurrence_id","computation_status","computation_reason"],
            &["participant_id","session_id"]),
        "chronicle.hmog-contact-size-summary" => ("literature-hmog-contact-size-summary-csv",
            &["contact_size_mean","contact_size_minimum","contact_size_maximum","first_contact_size",
              "mean_status","mean_reason"], &["participant_id","task_id","tap_id","contact_size_stream_id"]),
        "chronicle.momm-supplied-diagonal-form-factor" => ("literature-momm-supplied-diagonal-form-factor-csv",
            &["form_factor"], &["device_id","observation_id"]),
        "chronicle.momm-prepared-means" => ("literature-momm-prepared-means-csv",
            &["arithmetic_mean","computation_status","computation_reason"],
            &["analysis_id","owner_id","stage","feature_id","usage_stratum","context_id","form_factor"]),
        "chronicle.momm-supported-action-trace" => ("literature-momm-supported-action-trace-csv",
            &["supported_state_action_trace_json","computation_status","computation_reason"],
            &["participant_id","device_id","source_stream_id","trace_id"]),
        _ => return Err("unknown supplied Hammer/HMOG/MoMM stage".into()),
    };
    let group = bindings.iter().find(|binding| binding.adapter_id == adapter)
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter} has no registered component"))?;
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{adapter} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || outputs.iter().any(|name| headers.iter().any(|field| field == *name))
    { return Err(format!("{adapter} refuses duplicate/reserved output columns")); }
    let required = group.required_fields.iter().map(|field| required_header(&headers,field,adapter))
        .collect::<Result<Vec<_>,_>>()?;
    let mut writer = csv::Writer::from_writer(Vec::new());
    let mut out_headers = headers.clone(); out_headers.extend(outputs.iter().copied());
    writer.write_record(&out_headers).map_err(|error| error.to_string())?;
    let mut owners = BTreeSet::new();
    let mut count = 0usize;
    for record in reader.records() {
        let mut row = record.map_err(|error| format!("{adapter} row: {error}"))?;
        let value = |name| row.get(header_index(&headers,name).unwrap()).unwrap_or_default();
        if required.iter().any(|column| {
            let field = headers.get(*column).unwrap();
            row[*column].trim().is_empty() && (adapter != "chronicle.hammer-supplied-application-response-proxy"
                || identity_fields.contains(&field) || field == "comparison_id")
        }) {
            return Err(format!("{adapter} requires all declared fields; no imputation"));
        }
        let identity = identity_fields.iter().map(|name| value(name).to_owned()).collect::<Vec<_>>();
        if !owners.insert(identity) { return Err(format!("{adapter} refuses duplicate scoped output ownership")); }
        let mean_fields = |result: Result<f64,String>| -> Vec<String> {
            match result {
                Ok(mean) => vec![mean.to_string(),"computed".into(),String::new()],
                Err(reason) => vec![String::new(),"arithmetic_unavailable".into(),reason],
            }
        };
        let extra = match adapter {
            "chronicle.hammer-supplied-application-response-proxy" => {
                // App-owner IDs, not person/contact senders. Selection stays upstream.
                let unavailable = if value("input_qualification") != "source_qualified_dismissal_and_selected_next_foreground_application_ownership" {
                    Some("unknown_source_application_ownership_qualification")
                } else if value("notification_owner_app_namespace").trim().is_empty()
                    || value("next_foreground_owner_app_namespace").trim().is_empty() {
                    Some("unresolved_application_identity_namespace")
                } else if value("notification_owner_app_namespace") != value("next_foreground_owner_app_namespace") {
                    Some("application_identity_namespace_mismatch")
                } else if value("notification_owner_app_id").trim().is_empty()
                    || value("next_foreground_owner_app_id").trim().is_empty() {
                    Some("unresolved_application_owner_identity")
                } else { None };
                match unavailable {
                    Some(reason) => vec![String::new(),"arithmetic_unavailable".into(),reason.into()],
                    None => vec![if value("notification_owner_app_id") == value("next_foreground_owner_app_id") {
                        "inferred_click"
                    } else { "inferred_dismissal_or_swipe" }.into(),"computed".into(),String::new()],
                }
            },
            "chronicle.hammer-supplied-elapsed" => {
                if value("input_qualification") != "source_qualified_resolved_elapsed_pair" {
                    return Err("Hammer requires a supplied resolved source elapsed pair".into());
                }
                let start: HammerEndpoint = serde_json::from_str(value("start_endpoint_json"))
                    .map_err(|error| format!("invalid start endpoint: {error}"))?;
                let end: HammerEndpoint = serde_json::from_str(value("end_endpoint_json"))
                    .map_err(|error| format!("invalid end endpoint: {error}"))?;
                for point in [&start,&end] {
                    if [&point.owner_id,&point.event_id,&point.event_kind,&point.clock_id]
                        .iter().any(|field| field.trim().is_empty()) || point.precision_ns <= 0 {
                        return Err("elapsed endpoints require nonblank identities/clock and positive declared ns precision".into());
                    }
                }
                if start.clock_id != end.clock_id || start.event_id == end.event_id {
                    return Err("elapsed endpoints require one known common clock and distinct event identities".into());
                }
                let (start_kind,end_kind,same_owner) = match value("quantity") {
                    "session_duration" => ("session_start","session_end",true),
                    "inter_session_time" => ("session_end","next_session_start",false),
                    "notification_response_time" => ("notification_arrival","notification_departure",true),
                    "notification_interarrival" => ("notification_arrival","notification_arrival",false),
                    "notification_interdeparture" => ("notification_departure","notification_departure",false),
                    _ => return Err("unknown Hammer elapsed quantity; departure-to-click is not an alias".into()),
                };
                if start.event_kind != start_kind || end.event_kind != end_kind
                    || (same_owner && start.owner_id != end.owner_id)
                    || (value("quantity") == "inter_session_time" && start.owner_id == end.owner_id) {
                    return Err("supplied elapsed endpoints contradict the source quantity/owner relationship".into());
                }
                let elapsed = supplied_anchor_elapsed_nanoseconds(start.timestamp_ns,end.timestamp_ns);
                if elapsed < 0 { return Err("supplied elapsed pair is reversed; endpoints are not sorted".into()); }
                vec![elapsed.to_string()]
            },
            "chronicle.hammer-prepared-group-summary" => {
                if value("input_qualification") != "source_qualified_complete_group_membership"
                    || !matches!(value("group_kind"),"session"|"frame_30_seconds") {
                    return Err("Hammer requires caller-qualified session or30-second frame membership; no frame constructor/default".into());
                }
                let members: HammerPreparedGroup = serde_json::from_str(value("members_json"))
                    .map_err(|error| format!("invalid group members: {error}"))?;
                validate_supplied_finite_points(&members.numeric)?;
                let extrema = finite_scalar_extrema_by_group(members.numeric.iter().map(|point| ((),point.value)))
                    .map_err(|error| format!("finite extrema: {error:?}"))?;
                let mut values = extrema.first().map(|row| vec![row.minimum.to_string(),row.maximum.to_string()])
                    .unwrap_or_else(|| vec![String::new(),String::new()]);
                values.extend(mean_fields(supplied_point_mean(&members.numeric)));
                let mut ids = BTreeSet::new();
                for point in &members.categorical {
                    if point.sample_id.trim().is_empty() || point.state.trim().is_empty() || !ids.insert(&point.sample_id) {
                        return Err("categorical memberships require unique nonblank sample IDs and supplied literal states".into());
                    }
                }
                let mode = unique_mode_by_group(members.categorical.iter().map(|point| ((),point.state.clone())));
                values.extend(match mode {
                    Ok(modes) if !modes.is_empty() => vec![modes[0].category.clone(),"computed".into(),String::new()],
                    Ok(_) => vec![String::new(),"arithmetic_unavailable".into(),"empty_complete_categorical_membership".into()],
                    Err(_) => vec![String::new(),"arithmetic_unavailable".into(),"tied_mode_source_convention_unknown".into()],
                });
                values
            },
            "chronicle.hammer-first-eligible-app" => {
                if value("input_qualification") != "source_qualified_complete_eligible_session_app_order" {
                    return Err("Hammer requires caller-qualified eligible session application order".into());
                }
                let apps: Vec<HammerEligibleApp> = serde_json::from_str(value("eligible_apps_json"))
                    .map_err(|error| format!("invalid eligible apps: {error}"))?;
                let mut ids = BTreeSet::new();
                for app in &apps {
                    if app.occurrence_id.trim().is_empty() || app.app_id.trim().is_empty() || !ids.insert(&app.occurrence_id) {
                        return Err("eligible applications require distinct nonblank occurrence IDs and literal app IDs".into());
                    }
                }
                apps.first().map(|app| vec![app.app_id.clone(),app.occurrence_id.clone(),"computed".into(),String::new()])
                    .unwrap_or_else(|| vec![String::new(),String::new(),"arithmetic_unavailable".into(),"no_supplied_eligible_application".into()])
            },
            "chronicle.hmog-contact-size-summary" => {
                if value("input_qualification") != "source_qualified_complete_ordered_tap_contact_sizes" {
                    return Err("HMOG requires caller-qualified complete tap/contact-size membership and order".into());
                }
                let points = supplied_finite_points(value("contact_size_points_json"))?;
                let mean = mean_fields(supplied_point_mean(&points));
                let extrema = finite_scalar_extrema_by_group(points.iter().map(|point| ((),point.value)))
                    .map_err(|error| format!("finite contact extrema: {error:?}"))?;
                vec![mean[0].clone(),
                    extrema.first().map(|row| row.minimum.to_string()).unwrap_or_default(),
                    extrema.first().map(|row| row.maximum.to_string()).unwrap_or_default(),
                    points.first().map(|point| point.value.to_string()).unwrap_or_default(),
                    mean[1].clone(),mean[2].clone()]
            },
            "chronicle.momm-supplied-diagonal-form-factor" => {
                if value("input_qualification") != "source_qualified_supplied_screen_diagonal"
                    || value("diagonal_unit") != "inch" { return Err("MoMM classification requires explicitly supplied source-qualified diagonal inches".into()); }
                let diagonal = value("screen_diagonal").parse::<f64>()
                    .map_err(|_| "screen_diagonal requires a finite scalar")?;
                let classifier = FiniteScalarPivotClassifier::new(7.0,"smartphone","tablet","tablet")
                    .map_err(|error| error.to_string())?;
                vec![classifier.category_for(diagonal).map_err(|error| error.to_string())?.to_string()]
            },
            "chronicle.momm-prepared-means" => {
                if !matches!(value("usage_stratum"),"locked"|"unlocked"|"overall")
                    || !matches!(value("form_factor"),"smartphone"|"tablet"|"combined") {
                    return Err("MoMM means require declared source usage/form-factor strata; no classification or pooling is inferred".into());
                }
                let qualification = match value("stage") {
                    "daily_mean" if matches!(value("feature_id"),"daily_interaction_count"|"daily_usage_time") =>
                        "source_qualified_complete_all_observed_days_for_device_stratum",
                    "session_mean" if value("feature_id") == "session_duration" =>
                        "source_qualified_complete_entire_period_sessions_for_device_stratum",
                    "device_grand_mean" if matches!(value("feature_id"),"daily_interaction_count"|"daily_usage_time"|"session_duration") =>
                        "source_qualified_complete_one_mean_per_device_for_feature_stratum",
                    _ => return Err("unknown MoMM mean-only stage/feature".into()),
                };
                if value("input_qualification") != qualification {
                    return Err("MoMM means require complete supplied source membership at the declared stage".into());
                }
                let points = supplied_finite_points(value("observations_json"))?;
                mean_fields(supplied_point_mean(&points))
            },
            "chronicle.momm-supported-action-trace" => {
                if value("input_qualification") != "source_qualified_ordered_supported_events_and_equality" {
                    return Err("MoMM trace requires supplied source event/order/equality qualification".into());
                }
                match momm_supported_trace(value("initial_state"),value("ordered_events_json")) {
                    Ok(trace) => vec![trace,"computed".into(),String::new()],
                    Err(reason) if reason.starts_with("unsupported_source_transition:")
                        || reason == "missing_source_qualified_locked_length_authentication_equality"
                        || reason == "unknown_explicit_initial_state" =>
                        vec![String::new(),"arithmetic_unavailable".into(),reason],
                    Err(error) => return Err(error),
                }
            },
            _ => unreachable!(),
        };
        row.extend(extra.iter().map(String::as_str));
        writer.write_record(&row).map_err(|error| error.to_string())?;
        count += 1;
    }
    let bytes = writer.into_inner().map_err(|error| error.to_string())?;
    complete_standalone_component_adaptation(adapter,kind,original_input_digest,bindings,count,count,bytes)
}

fn carat_complete_mean(values: &[f64]) -> Result<f64, String> {
    let rows = values.iter().map(|value| GroupedNumericRow {
        group: Some("supplied".into()), values: vec![Some(*value)],
    }).collect::<Vec<_>>();
    let means = mean_columns_by_factor_group(&rows, &[Some("supplied".into())], 1)
        .map_err(|error| format!("complete supplied mean: {error:?}"))?;
    means.first().and_then(|row| row.values[0]).filter(|value| value.is_finite())
        .ok_or_else(|| "nonfinite_mean_arithmetic".into())
}

fn carat_paired_hour_regularity(hours: &[CaratPairedHour]) -> Result<f64, String> {
    carat_complete_mean(&hours.iter().map(|hour| hour.day_a_value * hour.day_b_value).collect::<Vec<_>>())
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CaratWeekHour { hour_id: String, value: f64 }
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CaratWeekDay { day_id: String, hours: Vec<CaratWeekHour> }

// Primary p4 Eq2/text100:243–265: each target compares to every other
// day in its week. The caller supplies the COMPLETE week membership;
// calendar, week start, incomplete-week policy and rescaling stay upstream.
fn adapt_carat_complete_week_regularity(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    const ADAPTER: &str = "chronicle.carat-complete-week-regularity";
    const OUTPUTS: [&str; 4] = [
        "all_other_day_regularity_json", "weekly_mean_regularity_index",
        "computation_status", "computation_reason",
    ];
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{ADAPTER} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || OUTPUTS.iter().any(|output| headers.iter().any(|field| field == *output))
    { return Err(format!("{ADAPTER} refuses duplicate/reserved output columns")); }
    let required = [
        "participant_id", "week_id", "target_day_id", "behavioral_stream",
        "rescaled_value_unit", "input_qualification", "week_days_json",
    ].iter().map(|field| required_header(&headers, field, ADAPTER)).collect::<Result<Vec<_>, _>>()?;
    let mut output_headers = headers.clone();
    for field in OUTPUTS { output_headers.push_field(field); }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&output_headers).map_err(|error| format!("{ADAPTER} output header: {error}"))?;
    let mut owners = BTreeSet::new();
    let mut count = 0usize;
    for (index, record) in reader.records().enumerate() {
        let mut record = record.map_err(|error| format!("{ADAPTER} row {}: {error}", index + 1))?;
        let value = |name| record.get(header_index(&headers, name).unwrap()).unwrap_or_default();
        if required.iter().any(|column| record[*column].trim().is_empty()) {
            return Err(format!("{ADAPTER} requires all declared fields; missingness is not imputed"));
        }
        if value("input_qualification") != "source_qualified_complete_week_day_roster_and_rescaled_hours" {
            return Err("complete-week regularity requires explicit source-qualified COMPLETE roster/rescaled-hour membership; unknown or partial weeks are not completed".into());
        }
        if !matches!(value("behavioral_stream"), "screen_status" | "internet_connectivity" | "foreground_app_usage") {
            return Err("complete-week regularity requires a source-qualified behavioral_stream".into());
        }
        if !owners.insert((value("participant_id").to_owned(), value("week_id").to_owned(),
            value("target_day_id").to_owned(), value("behavioral_stream").to_owned()))
        { return Err("complete-week regularity refuses repeated participant/week/target/stream ownership".into()); }
        let days: Vec<CaratWeekDay> = serde_json::from_str(value("week_days_json"))
            .map_err(|error| format!("invalid week_days_json: {error}"))?;
        let target = days.iter().position(|day| day.day_id == value("target_day_id"))
            .ok_or("target_day_id must explicitly resolve within the supplied complete week roster")?;
        let mut day_ids = BTreeSet::new();
        let mut hour_maps = Vec::with_capacity(days.len());
        for day in &days {
            if day.day_id.trim().is_empty() || !day_ids.insert(&day.day_id) {
                return Err("complete week requires unique nonblank lexical day ownership".into());
            }
            if day.hours.len() != 24 {
                return Err("each supplied day requires exactly24 hours; missing/extra-hour policy is not inferred".into());
            }
            let mut hours = BTreeMap::new();
            for hour in &day.hours {
                if hour.hour_id.trim().is_empty() || hours.insert(hour.hour_id.as_str(), hour.value).is_some()
                    || !hour.value.is_finite() || !(-0.5..=0.5).contains(&hour.value)
                { return Err("week hours require unique nonblank lexical hour IDs and finite already-rescaled values in[-.5,.5]".into()); }
            }
            hour_maps.push(hours);
        }
        // Compare memberships only; BTreeMap order never pairs sample values.
        // Each product follows target's supplied hour order, matched by raw ID.
        if hour_maps.iter().any(|hours| !hours.keys().eq(hour_maps[target].keys())) {
            return Err("all supplied days must have the same24 literal hour memberships; no order pairing or hour aliasing".into());
        }
        let mut pair_values = Vec::new();
        let mut pair_output = Vec::new();
        for (other, day) in days.iter().enumerate() {
            if other == target { continue; }
            let paired = days[target].hours.iter().map(|hour| CaratPairedHour {
                hour_id: hour.hour_id.clone(), day_a_value: hour.value,
                day_b_value: hour_maps[other][hour.hour_id.as_str()],
            }).collect::<Vec<_>>();
            let regularity = carat_paired_hour_regularity(&paired)?;
            pair_values.push(regularity);
            pair_output.push(serde_json::json!({
                "target_day_id": days[target].day_id,
                "other_day_id": day.day_id, "regularity_index": regularity,
            }));
        }
        let pair_json = serde_json::to_string(&pair_output)
            .map_err(|error| format!("complete-week pair output: {error}"))?;
        let mean = if pair_values.is_empty() {
            Err("no_other_day_in_supplied_complete_week".into())
        } else { carat_complete_mean(&pair_values) };
        record.push_field(&pair_json);
        match mean {
            Ok(number) => { record.push_field(&number.to_string()); record.push_field("computed"); record.push_field(""); }
            Err(reason) => { record.push_field(""); record.push_field("arithmetic_unavailable"); record.push_field(&reason); }
        }
        writer.write_record(&record).map_err(|error| format!("{ADAPTER} output row: {error}"))?;
        count += 1;
    }
    let bytes = writer.into_inner().map_err(|error| format!("{ADAPTER} output: {error}"))?;
    complete_standalone_component_adaptation(ADAPTER, "literature-carat-complete-week-regularity-csv",
        original_input_digest, bindings, count, count, bytes)
}

fn carat_normalized_entropy(probabilities: &[f64]) -> Result<f64, String> {
    if probabilities.len() < 2 { return Err("undefined_normalization_N_le_1".into()); }
    let entropy = probabilities.iter().filter(|value| **value > 0.0)
        .map(|value| -value * value.ln()).sum::<f64>();
    // Same log base in numerator/denominator cancels. No raw H is emitted.
    let normalized = entropy / (probabilities.len() as f64).ln();
    if !normalized.is_finite() { return Err("nonfinite_entropy_arithmetic".into()); }
    Ok(if normalized == 0.0 { 0.0 } else { normalized })
}

fn adapt_carat_computation(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt], adapter: &str,
) -> Result<AdaptedLiteratureInput, String> {
    let (fields, output, result_kind, qualification): (&[&str], _, _, _) = match adapter {
        "chronicle.carat-normalized-entropy" => (
            &["participant_id", "day_id", "behavioral_stream", "probability_encoding",
              "input_qualification", "state_count", "state_probabilities_json"],
            "normalized_entropy", "literature-carat-normalized-entropy-csv",
            "source_qualified_complete_state_probabilities"),
        "chronicle.carat-pair-regularity" => (
            &["participant_id", "pair_id", "day_a_id", "day_b_id", "behavioral_stream",
              "rescaled_value_unit", "input_qualification", "paired_hours_json"],
            "regularity_index", "literature-carat-pair-regularity-csv",
            "source_qualified_24_paired_rescaled_hours"),
        "chronicle.carat-day-regularity-mean" => (
            &["participant_id", "day_pair_domain_id", "target_day_id", "behavioral_stream",
              "regularity_index_unit", "input_qualification", "day_pairs_json"],
            "mean_regularity_index", "literature-carat-day-regularity-mean-csv",
            "source_qualified_resolved_day_pair_membership"),
        _ => return Err("unknown Carat component".into()),
    };
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{adapter} header: {error}"))?.clone();
    let outputs = [output, "computation_status", "computation_reason"];
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || outputs.iter().any(|output| headers.iter().any(|field| field == *output))
    { return Err(format!("{adapter} refuses duplicate/reserved output columns")); }
    let required = fields.iter().map(|field| required_header(&headers, field, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut output_headers = headers.clone();
    for field in outputs { output_headers.push_field(field); }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&output_headers).map_err(|error| format!("{adapter} output header: {error}"))?;
    let mut owners = BTreeSet::new();
    let mut count = 0usize;
    for (index, record) in reader.records().enumerate() {
        let mut record = record.map_err(|error| format!("{adapter} row {}: {error}", index + 1))?;
        let value = |name| record.get(header_index(&headers, name).unwrap()).unwrap_or_default();
        if required.iter().any(|column| record[*column].trim().is_empty()) {
            return Err(format!("{adapter} row {} requires all declared fields; missingness is not imputed", index + 1));
        }
        if value("input_qualification") != qualification {
            return Err(format!("{adapter} requires {qualification}; upstream construction is not inferred"));
        }
        if !matches!(value("behavioral_stream"), "screen_status" | "internet_connectivity" | "foreground_app_usage") {
            return Err(format!("{adapter} requires a source-qualified behavioral_stream"));
        }
        let owner = match adapter {
            "chronicle.carat-normalized-entropy" => vec![value("participant_id"), value("day_id"), value("behavioral_stream")],
            "chronicle.carat-pair-regularity" => vec![value("participant_id"), value("pair_id"), value("behavioral_stream")],
            _ => vec![value("participant_id"), value("day_pair_domain_id"), value("target_day_id"), value("behavioral_stream")],
        }.into_iter().map(str::to_owned).collect::<Vec<_>>();
        if !owners.insert(owner) { return Err(format!("{adapter} refuses repeated scoped computation identity")); }
        let computed = match adapter {
            "chronicle.carat-normalized-entropy" => {
                let states: Vec<CaratStateProbability> = serde_json::from_str(value("state_probabilities_json"))
                    .map_err(|error| format!("invalid state_probabilities_json: {error}"))?;
                let n = value("state_count").parse::<usize>()
                    .map_err(|_| "state_count requires a supplied positive integer")?;
                if n == 0 || states.len() != n {
                    return Err("state_count must match complete supplied state memberships; N is not inferred".into());
                }
                if value("behavioral_stream") != "foreground_app_usage" && n != 2 {
                    return Err("source screen/internet state count must be 2".into());
                }
                let scale = match value("probability_encoding") {
                    "proportion" => 1.0, "percent" => 100.0,
                    _ => return Err("probability_encoding must explicitly declare proportion or percent; no scale is inferred".into()),
                };
                let mut ids = BTreeSet::new();
                let mut probabilities = Vec::with_capacity(n);
                for state in &states {
                    if state.state_id.trim().is_empty() || !ids.insert(&state.state_id)
                        || !state.probability.is_finite() || !(0.0..=scale).contains(&state.probability)
                    { return Err("state probabilities require unique raw IDs and finite values within declared encoding range".into()); }
                    let probability = state.probability / scale;
                    if state.probability > 0.0 && probability == 0.0 {
                        return Err("declared probability conversion underflow; state is not silently removed".into());
                    }
                    probabilities.push(probability);
                }
                let total = probabilities.iter().sum::<f64>();
                if total == 0.0 {
                    Err("zero_probability_total".into())
                } else {
                    // Transport validation tolerance, not an author convention.
                    // Never repair, clamp or renormalize the supplied distribution.
                    if (total - 1.0).abs() > 1e-12 {
                        return Err("complete normalized state distribution must sum to1 within absolute1e-12; no renormalization".into());
                    }
                    if value("behavioral_stream") == "foreground_app_usage"
                        && probabilities.contains(&0.0)
                    { return Err("foreground state_count is distinct visited apps; unvisited zero states are not added".into()); }
                    carat_normalized_entropy(&probabilities)
                }
            }
            "chronicle.carat-pair-regularity" => {
                if value("day_a_id") == value("day_b_id") { return Err("regularity requires distinct supplied days".into()); }
                let hours: Vec<CaratPairedHour> = serde_json::from_str(value("paired_hours_json"))
                    .map_err(|error| format!("invalid paired_hours_json: {error}"))?;
                if hours.len() != 24 { return Err("regularity requires exactly24 explicitly paired hours; no missing-hour handling is inferred".into()); }
                let mut ids = BTreeSet::new();
                for hour in &hours {
                    if hour.hour_id.trim().is_empty() || !ids.insert(&hour.hour_id)
                        || ![hour.day_a_value, hour.day_b_value].iter()
                            .all(|value| value.is_finite() && (-0.5..=0.5).contains(value))
                    { return Err("paired hours require distinct raw IDs and finite already-rescaled values in[-.5,.5]".into()); }
                }
                // Existing complete-value mean gives sum of24 products /24;
                // its rounding order is not claimed to be the author's code.
                carat_paired_hour_regularity(&hours)
            }
            _ => {
                let pairs: Vec<CaratDayPair> = serde_json::from_str(value("day_pairs_json"))
                    .map_err(|error| format!("invalid day_pairs_json: {error}"))?;
                if pairs.is_empty() { return Err("supplied pair mean requires a nonempty resolved membership; no missing-pair handling is inferred".into()); }
                let mut pair_ids = BTreeSet::new();
                let mut others = BTreeSet::new();
                for pair in &pairs {
                    let other = if pair.day_a_id == value("target_day_id") { &pair.day_b_id }
                        else if pair.day_b_id == value("target_day_id") { &pair.day_a_id }
                        else { return Err("each day pair must explicitly contain the target".into()); };
                    if pair.pair_id.trim().is_empty() || !pair_ids.insert(&pair.pair_id)
                        || other.trim().is_empty() || other == value("target_day_id") || !others.insert(other)
                        || !pair.regularity_index.is_finite() || !(-0.25..=0.25).contains(&pair.regularity_index)
                    { return Err("day pairs require unique raw target/other membership and finite supplied RI in[-.25,.25]".into()); }
                }
                carat_complete_mean(&pairs.iter().map(|pair| pair.regularity_index).collect::<Vec<_>>())
            }
        };
        match computed {
            Ok(number) => { record.push_field(&number.to_string()); record.push_field("computed"); record.push_field(""); }
            Err(reason) => { record.push_field(""); record.push_field("arithmetic_unavailable"); record.push_field(&reason); }
        }
        writer.write_record(&record).map_err(|error| format!("{adapter} output row: {error}"))?;
        count += 1;
    }
    let bytes = writer.into_inner().map_err(|error| format!("{adapter} output: {error}"))?;
    complete_standalone_component_adaptation(adapter, result_kind, original_input_digest, bindings, count, count, bytes)
}
// The poster (DOI 10.1145/3490100.3532456, p.1, text361:31-38)
// specifies centers and Euclidean distance, not how boxes/events are constructed.
fn adapt_touch_box_displacement(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    const ADAPTER: &str = "chronicle.touch-box-displacement";
    const OUTPUTS: [&str; 7] = [
        "box_a_center_x", "box_a_center_y", "box_b_center_x", "box_b_center_y",
        "displacement_magnitude", "computation_status", "computation_reason",
    ];
    let mut reader = csv::ReaderBuilder::new().flexible(false).from_reader(raw_csv);
    let headers = reader.headers()
        .map_err(|error| format!("{ADAPTER} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || OUTPUTS.iter().any(|name| headers.iter().any(|header| header == *name))
    {
        return Err(format!("{ADAPTER} refuses duplicate or reserved output columns"));
    }
    let required = |field| required_header(&headers, field, ADAPTER);
    let identities = [
        "participant_id", "interaction_id", "pair_id", "touch_event_a_id",
        "touch_event_b_id", "coordinate_frame_id", "coordinate_unit",
        "interaction_qualification",
    ].iter().map(|field| required(field)).collect::<Result<Vec<_>, _>>()?;
    let coordinates = [
        "box_a_x_min", "box_a_y_min", "box_a_x_max", "box_a_y_max",
        "box_b_x_min", "box_b_y_min", "box_b_x_max", "box_b_y_max",
    ].iter().map(|field| required(field)).collect::<Result<Vec<_>, _>>()?;
    let mut output_headers = headers.clone();
    for output in OUTPUTS { output_headers.push_field(output); }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&output_headers)
        .map_err(|error| format!("{ADAPTER} output header: {error}"))?;
    let mut seen_pairs = BTreeSet::new();
    let mut rows = 0usize;
    for (index, row) in reader.records().enumerate() {
        let mut row = row.map_err(|error| format!("{ADAPTER} row {}: {error}", index + 1))?;
        for identity in &identities {
            if row[*identity].trim().is_empty() {
                return Err(format!("{ADAPTER} requires nonblank {}", &headers[*identity]));
            }
        }
        if &row[identities[7]] != "source_qualified_long_touch_interaction" {
            return Err(format!("{ADAPTER} requires caller-qualified long-touch membership; no gesture threshold is inferred"));
        }
        if row[identities[3]] == row[identities[4]] {
            return Err(format!("{ADAPTER} requires two distinct supplied touch-event identities"));
        }
        if !seen_pairs.insert((
            row[identities[0]].to_owned(), row[identities[1]].to_owned(),
            row[identities[2]].to_owned(),
        )) {
            return Err(format!("{ADAPTER} refuses duplicate pair identity within participant/interaction"));
        }
        let values = coordinates.iter().map(|column| {
            row[*column].parse::<f64>().ok().filter(|value| value.is_finite())
                .ok_or_else(|| format!("{ADAPTER} requires finite {}; missingness is not imputed", &headers[*column]))
        }).collect::<Result<Vec<_>, _>>()?;
        for offset in [0, 4] {
            if values[offset] > values[offset + 2] || values[offset + 1] > values[offset + 3] {
                return Err(format!("{ADAPTER} requires supplied ordered rectangle bounds; endpoints are not sorted or repaired"));
            }
        }
        // Standard midpoint avoids overflow of (min+max) and does not infer
        // origin, orientation, pixel units, integer rounding or raw box format.
        let centers = [
            values[0].midpoint(values[2]), values[1].midpoint(values[3]),
            values[4].midpoint(values[6]), values[5].midpoint(values[7]),
        ];
        for center in centers { row.push_field(&center.to_string()); }
        // The existing finite norm implements the exact 2D formula with z=0.
        // Its f64 order is not claimed to reproduce unavailable author code.
        let distance = finite_three_axis_magnitude([
            centers[2] - centers[0], centers[3] - centers[1], 0.0,
        ]);
        match distance {
            Some(distance) => {
                row.push_field(&distance.to_string());
                row.push_field("computed");
                row.push_field("");
            }
            None => {
                row.push_field("");
                row.push_field("arithmetic_unavailable");
                row.push_field("nonfinite_distance_arithmetic");
            }
        }
        writer.write_record(&row)
            .map_err(|error| format!("{ADAPTER} output row: {error}"))?;
        rows += 1;
    }
    let bytes = writer.into_inner()
        .map_err(|error| format!("{ADAPTER} output: {error}"))?;
    complete_standalone_component_adaptation(
        ADAPTER, "literature-touch-box-displacement-csv",
        original_input_digest, bindings, rows, rows, bytes,
    )
}

fn adapt_touchstroke_computation(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
    magnitude: bool,
) -> Result<AdaptedLiteratureInput, String> {
    let (adapter, result_kind, output_columns) = if magnitude {
        (TOUCHSTROKE_SENSOR_MAGNITUDE_ADAPTER, "literature-touchstroke-sensor-magnitude-csv", & ["magnitude"][..])
    } else {
        (TOUCHSTROKE_TIMING_ADAPTER, "literature-touchstroke-four-stroke-timing-csv", &TOUCHSTROKE_TIMING_COLUMNS[..])
    };
    let group = bindings.first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter} has no registered component"))?;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{adapter} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || output_columns.iter().any(|name| headers.iter().any(|header| header == *name))
    {
        return Err(format!("{adapter} requires unique input columns without computed output columns"));
    }
    let required = group.required_fields.iter().map(|name| {
        required_header(&headers, name, adapter)
    }).collect::<Result<Vec<_>, _>>()?;
    let mut output_headers = headers.clone();
    output_headers.extend(output_columns.iter().copied());
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&output_headers).map_err(|error| format!("{adapter} write header: {error}"))?;
    let mut identities = BTreeSet::new();
    let mut rows = 0;
    for (row_index, record) in reader.records().enumerate() {
        let mut record = record.map_err(|error| format!("{adapter} row {}: {error}", row_index + 1))?;
        let value = |name: &str| record.get(header_index(&headers, name).unwrap()).unwrap_or_default();
        if required.iter().any(|index| record.get(*index).unwrap_or_default().trim().is_empty()) {
            return Err(format!("{adapter} row {} has an empty required value", row_index + 1));
        }
        let identity = if magnitude {
            vec![value("participant_id"), value("attempt_id"), value("sensor_stream_id"), value("sample_id")]
        } else {
            vec![value("participant_id"), value("attempt_id")]
        }.into_iter().map(str::to_owned).collect::<Vec<_>>();
        if !identities.insert(identity) {
            return Err(format!("{adapter} row {} duplicates a computation owner", row_index + 1));
        }
        let computed = if magnitude {
            if !matches!(value("sensor_stream_id"),
                "sensor.stream.raw_accelerometer" | "sensor.stream.low_pass_accelerometer"
                | "sensor.stream.high_pass_accelerometer" | "sensor.stream.gravity"
                | "sensor.stream.gyroscope" | "sensor.stream.magnetometer" | "sensor.stream.orientation")
            {
                return Err(format!("{adapter} row {} has an unknown sensor_stream_id", row_index + 1));
            }
            let mut axes = [0.0_f64; 3];
            for (axis, name) in axes.iter_mut().zip(["x", "y", "z"]) {
                *axis = parse_python_float(value(name), name, row_index + 1)?;
                if !axis.is_finite() {
                    return Err(format!("{adapter} row {} requires finite {name}", row_index + 1));
                }
            }
            let norm = finite_three_axis_magnitude(axes).ok_or_else(||
                format!("{adapter} row {} magnitude exceeds the finite output range", row_index + 1))?;
            vec![norm.to_string()]
        } else {
            if !matches!(value("time_unit"), "ns" | "us" | "ms" | "s") {
                return Err(format!("{adapter} row {} requires a declared time_unit (ns/us/ms/s)", row_index + 1));
            }
            let integer = |name: &str| value(name).parse::<i64>()
                .map_err(|_| format!("{adapter} row {} requires signed integer {name}", row_index + 1));
            let precision = integer("time_precision")?;
            if precision <= 0 {
                return Err(format!("{adapter} row {} requires positive time_precision in time_unit", row_index + 1));
            }
            let mut presses = [0_i128; 4];
            let mut releases = [0_i128; 4];
            for i in 0..4 {
                let press = integer(&format!("P{}", i + 1))?;
                let release = integer(&format!("R{}", i + 1))?;
                if release < press {
                    return Err(format!("{adapter} row {} has release before its paired press", row_index + 1));
                }
                presses[i] = i128::from(press);
                releases[i] = i128::from(release);
            }
            let mut timings = Vec::with_capacity(14);
            timings.extend((0..4).map(|i| releases[i] - presses[i]));
            timings.extend((0..3).map(|i| presses[i + 1] - releases[i]));
            timings.extend((0..3).map(|i| releases[i + 1] - releases[i]));
            timings.extend((0..3).map(|i| presses[i + 1] - presses[i]));
            timings.push(releases[3] - presses[0]);
            timings.into_iter().map(|value| value.to_string()).collect()
        };
        record.extend(computed.iter().map(String::as_str));
        writer.write_record(&record).map_err(|error| format!("{adapter} write row: {error}"))?;
        rows += 1;
    }
    let bytes = writer.into_inner().map_err(|error| format!("{adapter} finish output: {error}"))?;
    complete_standalone_component_adaptation(adapter, result_kind, original_input_digest, bindings, rows, rows, bytes)
}

// HMOG retained primary arXiv:1501.01199v3 (25 Jan 2016), printed p.3:
// Table I, resistance/stability formulas and Algorithm 1; p.5: key latencies.
// The caller supplies normalized memberships and endpoint relationships. These
// operations never reconstruct raw windows, sort samples, or infer key pairing.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct HmogScalarSample {
    sample_id: String,
    value: f64,
    #[serde(default)]
    timestamp: Option<i64>,
}

fn hmog_samples(value: &str, field: &str) -> Result<Vec<HmogScalarSample>, String> {
    let samples: Vec<HmogScalarSample> = serde_json::from_str(value)
        .map_err(|error| format!("invalid {field}: {error}"))?;
    let mut ids = BTreeSet::new();
    for sample in &samples {
        if sample.sample_id.is_empty() || !ids.insert(&sample.sample_id) {
            return Err(format!("{field} requires distinct nonempty sample_id values"));
        }
        if !sample.value.is_finite() {
            return Err(format!("{field} requires finite sample values"));
        }
    }
    Ok(samples)
}

fn hmog_mean(samples: &[HmogScalarSample]) -> Option<f64> {
    if samples.is_empty() {
        return None;
    }
    let rows = samples.iter().map(|sample| GroupedNumericRow {
        group: Some("supplied".into()), values: vec![Some(sample.value)],
    }).collect::<Vec<_>>();
    let means = mean_columns_by_factor_group(&rows, &[Some("supplied".into())], 1).ok()?;
    means.first()?.values[0].filter(|value| value.is_finite())
}

fn hmog_integer(value: &str, name: &str) -> Result<i128, String> {
    value.parse::<i64>().map(i128::from)
        .map_err(|_| format!("requires signed integer {name}"))
}

fn hmog_clock(value: impl Fn(&str) -> String) -> Result<(), String> {
    if value("clock_id").is_empty() {
        return Err("requires explicitly supplied clock_id".into());
    }
    if !matches!(value("time_unit").as_str(), "ns" | "us" | "ms" | "s") {
        return Err("requires declared time_unit (ns/us/ms/s)".into());
    }
    if hmog_integer(&value("time_precision"), "time_precision")? <= 0 {
        return Err("requires positive time_precision in time_unit".into());
    }
    // Metadata is not a zero-aligned epoch: never modulo, round or normalize.
    Ok(())
}

fn hmog_numeric_output(result: Result<f64, String>) -> [String; 2] {
    match result {
        Ok(value) if value.is_finite() => [value.to_string(), "computed".into()],
        Ok(_) => [String::new(), "refused:nonfinite_result".into()],
        Err(reason) => [String::new(), format!("refused:{reason}")],
    }
}

fn hmog_normalized_duration(numerator: Result<i128, String>, denominator: Option<f64>) -> Result<f64, String> {
    let numerator = numerator?;
    let denominator = denominator.ok_or("missing_or_nonfinite_window_reduction")?;
    if !denominator.is_finite() {
        return Err("nonfinite_denominator".into());
    }
    if denominator == 0.0 {
        return Err("zero_denominator_source_behavior_unknown".into());
    }
    let numeric = numerator as f64;
    if numeric as i128 != numerator {
        return Err("integer_time_difference_not_exactly_representable_as_f64".into());
    }
    Ok(numeric / denominator)
}

// HMOG residual stages preserve supplied memberships/endpoints. They do not
// choose an estimator, distance metric, raw pairing, or original key serializer.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct HmogDomainKey { key_id: String, vocabulary_class: String }

fn hmog_contact_unique_statistics(points: &[SuppliedFinitePoint]) -> Vec<String> {
    let mut values = points.iter().map(|point| point.value).collect::<Vec<_>>();
    let median = if values.is_empty() {
        Err("empty_complete_membership".into())
    } else if values.len() % 2 == 1 {
        // Only the unambiguous odd branch of the existing helper is used.
        Ok(phonestudy_median(values))
    } else {
        values.sort_by(f64::total_cmp);
        let middle = values.len() / 2;
        if values[middle - 1] == values[middle] {
            // Returning the coincident value avoids an overflowing (x+x)/2.
            Ok(values[middle])
        } else { Err("even_distinct_median_source_convention_unknown".into()) }
    };
    let extrema = finite_scalar_extrema_by_group(points.iter().map(|point| ((),point.value)))
        .expect("supplied_finite_points already validated finiteness");
    let sd = if points.len() >= 2 && extrema.first().is_some_and(|row| row.minimum == row.maximum) {
        Ok(0.0)
    } else { Err("standard_deviation_estimator_or_definedness_unknown".into()) };
    let mut output = Vec::new();
    output.extend(hmog_numeric_output(median));
    output.extend(hmog_numeric_output(sd));
    // No retained quartile rule establishes rank/interpolation or minimum
    // membership, including for constants. Do not alias Q2 to known median.
    for _ in 0..3 {
        output.extend(hmog_numeric_output(Err("quartile_estimator_and_definedness_unknown".into())));
    }
    output
}

fn hmog_supplied_tap_elapsed(value: impl Fn(&str) -> String) -> Result<Result<i128,String>,String> {
    // Validate both typed coordinates and precision before semantic unavailable.
    let coordinate = |name| -> Result<Option<i64>,String> {
        let token = value(name);
        if token.is_empty() { Ok(None) }
        else { token.parse::<i64>().map(Some).map_err(|_| format!("{name} requires a supplied i64 coordinate")) }
    };
    let start = coordinate("start")?;
    let end = coordinate("end")?;
    let precision = coordinate("time_precision")?;
    if value("start_event_id").trim().is_empty() || value("end_event_id").trim().is_empty()
        || value("start_event_id") == value("end_event_id") {
        return Err("requires distinct nonblank literal endpoint identities".into());
    }
    let qualifier = value("input_qualification");
    if !matches!(qualifier.as_str(),"source_qualified_paired_tap_start_end"|"source_qualified_consecutive_tap_presses_and_resolved_pixel_distance") {
        return Ok(Err("unknown_source_endpoint_qualification".into()));
    }
    if value("start_clock_id").trim().is_empty() || value("end_clock_id").trim().is_empty() {
        return Ok(Err("missing_explicit_endpoint_clock".into()));
    }
    if value("start_clock_id") != value("end_clock_id") {
        return Ok(Err("incompatible_endpoint_clocks".into()));
    }
    if precision.is_none() { return Ok(Err("missing_positive_time_precision".into())); }
    let clock = hmog_clock(|name| if name == "clock_id" { value("start_clock_id") } else { value(name) });
    if let Err(reason) = clock { return Ok(Err(reason)); }
    let (Some(start),Some(end)) = (start,end) else {
        return Ok(Err("missing_supplied_endpoint_coordinate".into()));
    };
    let elapsed = supplied_anchor_elapsed_nanoseconds(start,end);
    Ok(if elapsed < 0 { Err("supplied_endpoint_order_reversed".into()) } else { Ok(elapsed) })
}

fn hmog_supplied_pixel_rate(distance: Option<f64>, elapsed: Result<i128,String>, unit: &str) -> Result<f64,String> {
    let elapsed = elapsed?;
    if elapsed == 0 { return Err("zero_elapsed_source_velocity_behavior_unknown".into()); }
    let distance = distance.ok_or("missing_supplied_resolved_pixel_distance")?;
    let numeric = elapsed as f64;
    if numeric as i128 != elapsed {
        return Err("integer_time_difference_not_exactly_representable_as_f64".into());
    }
    let seconds = numeric / match unit { "ns" => 1e9, "us" => 1e6, "ms" => 1e3, "s" => 1.0,
        _ => return Err("unknown_time_unit".into()) };
    let rate = distance / seconds;
    if !rate.is_finite() { return Err("nonfinite_velocity_result".into()); }
    if distance > 0.0 && rate == 0.0 { return Err("positive_velocity_underflow".into()); }
    Ok(rate)
}

fn adapt_hmog_computation(
    raw_csv: &[u8], original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt], adapter: &str,
) -> Result<AdaptedLiteratureInput, String> {
    let output_columns: &[&str] = match adapter {
        HMOG_MAGNITUDE_ADAPTER => &["magnitude"],
        HMOG_REDUCTIONS_ADAPTER => &[
            "before_mean", "before_mean_status", "during_mean", "during_mean_status",
            "after_mean", "after_mean_status", "during_maximum", "during_maximum_status",
            "before_after_difference", "before_after_difference_status",
            "net_tap_change", "net_tap_change_status", "maximum_tap_change", "maximum_tap_change_status",
            "normalized_before_after_duration", "normalized_before_after_duration_status",
            "normalized_max_after_duration", "normalized_max_after_duration_status", "normalized_duration_unit",
        ],
        HMOG_STABILITY_ADAPTER => &["suffix_average_absolute_deviations_json", "t_min", "time_to_stability", "stability_status"],
        HMOG_KEY_HOLD_ADAPTER => &["key_hold"],
        HMOG_DIGRAPH_ADAPTER => &["digraph"],
        HMOG_TAP_DURATION_ADAPTER => &["tap_duration","tap_duration_status","tap_duration_unit"],
        HMOG_CONTACT_STATISTICS_ADAPTER => &["contact_size_median","contact_size_median_status",
            "contact_size_sd","contact_size_sd_status","contact_size_q1","contact_size_q1_status",
            "contact_size_q2","contact_size_q2_status","contact_size_q3","contact_size_q3_status"],
        HMOG_PIXEL_VELOCITY_ADAPTER => &["tap_velocity","tap_velocity_status","tap_velocity_unit"],
        HMOG_KEY_DOMAINS_ADAPTER => &["key_hold_domain_json","ordered_digraph_domain_json","domain_status"],
        _ => return Err("unknown HMOG computation".into()),
    };
    let group = bindings.first().and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter} has no registered component"))?;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader.headers().map_err(|error| format!("{adapter} header: {error}"))?.clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len()
        || output_columns.iter().any(|name| headers.iter().any(|header| header == *name)) {
        return Err(format!("{adapter} requires unique input columns without computed output columns"));
    }
    let required = group.required_fields.iter().map(|name| required_header(&headers, name, adapter))
        .collect::<Result<Vec<_>, _>>()?;
    let mut output_headers = headers.clone();
    output_headers.extend(output_columns.iter().copied());
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&output_headers).map_err(|error| format!("{adapter} write header: {error}"))?;
    let mut owners = BTreeSet::new();
    let mut rows = 0;
    for (row_index, record) in reader.records().enumerate() {
        let mut record = record.map_err(|error| format!("{adapter} row {}: {error}", row_index + 1))?;
        let value = |name: &str| header_index(&headers, name)
            .and_then(|index| record.get(index)).unwrap_or_default();
        let residual = matches!(adapter, HMOG_TAP_DURATION_ADAPTER | HMOG_CONTACT_STATISTICS_ADAPTER
            | HMOG_PIXEL_VELOCITY_ADAPTER | HMOG_KEY_DOMAINS_ADAPTER);
        if required.iter().any(|index| record.get(*index).unwrap_or_default().is_empty()) && !residual {
            return Err(format!("{adapter} row {} has an empty required value", row_index + 1));
        }
        let mut owner = vec![value("participant_id"), value("task_occurrence_id")];
        if adapter == HMOG_MAGNITUDE_ADAPTER {
            owner.extend([value("sensor_stream_id"), value("sample_id")]);
        } else if matches!(adapter, HMOG_REDUCTIONS_ADAPTER | HMOG_STABILITY_ADAPTER) {
            owner.extend([value("tap_id"), value("sensor_stream_id"), value("sensor_axis")]);
        } else if adapter == HMOG_CONTACT_STATISTICS_ADAPTER {
            owner.extend([value("tap_id"),value("contact_size_stream_id")]);
        } else if adapter == HMOG_TAP_DURATION_ADAPTER {
            owner.push(value("tap_id"));
        } else if adapter == HMOG_KEY_DOMAINS_ADAPTER {
            owner.extend([value("roster_id"),value("key_namespace")]);
        } else {
            owner.push(value("pair_id"));
        }
        if residual && owner.iter().any(|token| token.trim().is_empty()) {
            return Err(format!("{adapter} requires nonblank literal scoped identities"));
        }
        if !owners.insert(owner.into_iter().map(str::to_owned).collect::<Vec<_>>()) {
            return Err(format!("{adapter} row {} duplicates a computation owner", row_index + 1));
        }
        let computed = (|| -> Result<Vec<String>, String> {
            if matches!(adapter, HMOG_MAGNITUDE_ADAPTER | HMOG_REDUCTIONS_ADAPTER | HMOG_STABILITY_ADAPTER) {
                if !matches!(value("sensor_stream_id"), "accelerometer" | "gyroscope" | "magnetometer") {
                    return Err("requires HMOG sensor_stream_id (accelerometer/gyroscope/magnetometer)".into());
                }
                if adapter != HMOG_MAGNITUDE_ADAPTER && !matches!(value("sensor_axis"), "x" | "y" | "z" | "magnitude") {
                    return Err("requires supplied sensor_axis (x/y/z/magnitude)".into());
                }
            }
            if adapter == HMOG_MAGNITUDE_ADAPTER {
                let mut axes = [0.0; 3];
                for (axis, name) in axes.iter_mut().zip(["x", "y", "z"]) {
                    *axis = parse_python_float(value(name), name, row_index + 1)?;
                }
                return finite_three_axis_magnitude(axes).map(|norm| vec![norm.to_string()])
                    .ok_or_else(|| "requires finite axes and magnitude".into());
            }
            if adapter == HMOG_REDUCTIONS_ADAPTER {
                let before = hmog_samples(value("before_samples_json"), "before_samples_json")?;
                let during = hmog_samples(value("during_samples_json"), "during_samples_json")?;
                let after = hmog_samples(value("after_samples_json"), "after_samples_json")?;
                let mut known_samples = BTreeMap::<&String, (f64, Option<i64>)>::new();
                for sample in before.iter().chain(&during).chain(&after) {
                    if let Some((known_value, known_timestamp)) = known_samples.get_mut(&sample.sample_id) {
                        if *known_value != sample.value
                            || known_timestamp.zip(sample.timestamp).is_some_and(|(known, supplied)| known != supplied) {
                            return Err("contradictory repeated sample_id across supplied windows".into());
                        }
                        if known_timestamp.is_none() { *known_timestamp = sample.timestamp; }
                    } else {
                        known_samples.insert(&sample.sample_id, (sample.value, sample.timestamp));
                    }
                }
                let before_mean = hmog_mean(&before);
                let during_mean = hmog_mean(&during);
                let after_mean = hmog_mean(&after);
                let maximum = finite_scalar_extrema_by_group(during.iter().map(|sample| ((), sample.value)))
                    .map_err(|_| "nonfinite_during_value")?.first().map(|extrema| extrema.maximum);
                let before_after = after_mean.zip(before_mean).map(|(after, before)| after - before);
                let net = during_mean.zip(before_mean).map(|(during, before)| during - before);
                let max_change = maximum.zip(before_mean).map(|(maximum, before)| maximum - before);
                let mut output = Vec::new();
                for result in [before_mean, during_mean, after_mean, maximum, before_after, net, max_change] {
                    output.extend(hmog_numeric_output(result.ok_or_else(|| "empty_or_nonfinite_window".into())));
                }
                let clock = hmog_clock(|name| value(name).to_owned());
                let difference = |end: &str, start: &str| -> Result<i128, String> {
                    clock.clone()?;
                    Ok(hmog_integer(value(end), end)? - hmog_integer(value(start), start)?)
                };
                output.extend(hmog_numeric_output(hmog_normalized_duration(
                    difference("after_center", "before_center"), before_after)));
                // A timestamp is explicitly supplied, not selected from tied maxima.
                output.extend(hmog_numeric_output(hmog_normalized_duration(
                    difference("after_center", "tap_max_timestamp"), after_mean.zip(maximum).map(|(after, maximum)| after - maximum))));
                output.push(if clock.is_ok() { format!("{}/({})", value("time_unit"), value("sensor_unit")) } else { String::new() });
                return Ok(output);
            }
            if adapter == HMOG_CONTACT_STATISTICS_ADAPTER {
                let points = supplied_finite_points(value("contact_size_points_json"))?;
                if value("contact_size_unit").trim().is_empty()
                    || value("input_qualification") != "source_qualified_complete_ordered_tap_contact_sizes" {
                    return Ok((0..5).flat_map(|_| hmog_numeric_output(Err("unknown_complete_contact_membership_or_unit".into()))).collect());
                }
                return Ok(hmog_contact_unique_statistics(&points));
            }
            if matches!(adapter,HMOG_TAP_DURATION_ADAPTER|HMOG_PIXEL_VELOCITY_ADAPTER) {
                let distance = if adapter == HMOG_PIXEL_VELOCITY_ADAPTER && !value("resolved_pixel_distance").is_empty() {
                    let number = parse_python_float(value("resolved_pixel_distance"),"resolved_pixel_distance",row_index+1)?;
                    // A nonzero decimal must not become a known zero distance.
                    // Exponent digits do not make a zero significand nonzero.
                    if number == 0.0 && value("resolved_pixel_distance").split(['e','E']).next()
                        .is_some_and(|significand| significand.bytes().any(|digit| matches!(digit,b'1'..=b'9'))) {
                        return Err("resolved_pixel_distance lexical nonzero parse underflow".into());
                    }
                    if !number.is_finite() || number < 0.0 { return Err("requires finite nonnegative supplied pixel distance".into()); }
                    Some(number)
                } else { None };
                let elapsed = hmog_supplied_tap_elapsed(|name| value(name).to_owned())?;
                let expected = if adapter == HMOG_TAP_DURATION_ADAPTER { "source_qualified_paired_tap_start_end" }
                    else { "source_qualified_consecutive_tap_presses_and_resolved_pixel_distance" };
                let elapsed = if value("input_qualification") == expected { elapsed }
                    else { Err("unknown_source_endpoint_qualification".into()) };
                if adapter == HMOG_TAP_DURATION_ADAPTER {
                    return Ok(match elapsed {
                        Ok(elapsed) => vec![elapsed.to_string(),"computed".into(),value("time_unit").into()],
                        Err(reason) => vec![String::new(),format!("refused:{reason}"),String::new()],
                    });
                }
                if value("first_tap_id").trim().is_empty() || value("second_tap_id").trim().is_empty()
                    || value("first_tap_id") == value("second_tap_id") {
                    return Err("velocity requires two distinct supplied tap identities".into());
                }
                let result = if value("distance_unit") == "pixel" {
                    hmog_supplied_pixel_rate(distance,elapsed,value("time_unit"))
                } else { Err("unknown_supplied_distance_unit".into()) };
                let mut output = hmog_numeric_output(result).to_vec();
                output.push(if output[1] == "computed" { "pixel/s".into() } else { String::new() });
                return Ok(output);
            }
            if adapter == HMOG_KEY_DOMAINS_ADAPTER {
                let keys: Vec<String> = serde_json::from_str(value("key_hold_roster_json"))
                    .map_err(|error| format!("invalid key-hold roster: {error}"))?;
                let digraph: Vec<HmogDomainKey> = serde_json::from_str(value("digraph_roster_json"))
                    .map_err(|error| format!("invalid digraph roster: {error}"))?;
                let mut hold_ids = BTreeSet::new();
                for key in &keys {
                    if key.trim().is_empty() || !hold_ids.insert(key) {
                        return Err("key-hold roster requires unique nonblank literal key identities".into());
                    }
                }
                let mut digraph_ids = BTreeSet::new();
                let mut classes = BTreeMap::<&str,usize>::new();
                for key in &digraph {
                    if key.key_id.trim().is_empty() || !digraph_ids.insert(&key.key_id) {
                        return Err("digraph roster requires unique nonblank literal key identities".into());
                    }
                    if !matches!(key.vocabulary_class.as_str(),"alphabetic"|"keyboard_switches"|"special") {
                        return Err("unknown supplied source vocabulary class".into());
                    }
                    *classes.entry(&key.vocabulary_class).or_default() += 1;
                }
                if value("input_qualification") != "source_qualified_complete_key_hold_and_digraph_rosters" {
                    return Ok(vec![String::new(),String::new(),"refused:unknown_complete_roster_qualification".into()]);
                }
                if keys.len() != 89 || digraph.len() != 35
                    || classes.get("alphabetic") != Some(&26) || classes.get("keyboard_switches") != Some(&5)
                    || classes.get("special") != Some(&4) || digraph.iter().any(|key| !hold_ids.contains(&key.key_id)) {
                    return Ok(vec![String::new(),String::new(),"refused:incomplete_or_incompatible_source_key_domains".into()]);
                }
                let pairs = digraph.iter().flat_map(|first| digraph.iter().map(move |second|
                    serde_json::json!({"first_key":first.key_id,"second_key":second.key_id}))).collect::<Vec<_>>();
                return Ok(vec![serde_json::to_string(&keys).map_err(|error| error.to_string())?,
                    serde_json::to_string(&pairs).map_err(|error| error.to_string())?,
                    "enumerated_schema_only".into()]);
            }
            hmog_clock(|name| value(name).to_owned())?;
            if adapter == HMOG_STABILITY_ADAPTER {
                let baseline = parse_python_float(value("before_mean"), "before_mean", row_index + 1)?;
                if !baseline.is_finite() { return Err("requires finite before_mean".into()); }
                let samples = hmog_samples(value("stability_samples_json"), "stability_samples_json")?;
                let tap_end = hmog_integer(value("tap_end"), "tap_end")?;
                if samples.iter().any(|sample| sample.timestamp.is_none()) {
                    return Err("stability samples require explicitly supplied integer timestamps".into());
                }
                // Source Algorithm 1 uses supplied suffix order and independent
                // sums, not an instantaneous minimum or a reverse-sum rewrite.
                let averages = (0..samples.len()).map(|i| samples[i..].iter()
                    .map(|sample| (sample.value - baseline).abs()).sum::<f64>() / (samples.len() - i) as f64)
                    .collect::<Vec<_>>();
                if averages.is_empty() || averages.iter().any(|average| !average.is_finite()) {
                    return Ok(vec![String::new(), String::new(), String::new(), "refused:empty_or_nonfinite_stability_suffix".into()]);
                }
                let minimum = averages.iter().copied().reduce(f64::min).unwrap();
                let minimizers = averages.iter().enumerate().filter(|(_, average)| **average == minimum)
                    .map(|(i, _)| i).collect::<Vec<_>>();
                let serialized = serde_json::to_string(&averages).map_err(|error| error.to_string())?;
                if minimizers.len() != 1 {
                    return Ok(vec![serialized, String::new(), String::new(), "refused:argmin_tie_source_rule_unknown".into()]);
                }
                let selected = i128::from(samples[minimizers[0]].timestamp.unwrap());
                return Ok(vec![serialized, selected.to_string(), (selected - tap_end).to_string(), "computed".into()]);
            }
            let (first, second, first_id, second_id) = if adapter == HMOG_KEY_HOLD_ADAPTER {
                ("press", "release", "press_event_id", "release_event_id")
            } else { ("first_press", "second_press", "first_press_event_id", "second_press_event_id") };
            if value(first_id) == value(second_id) { return Err("requires distinct supplied endpoint identities".into()); }
            let first = hmog_integer(value(first), first)?;
            let second = hmog_integer(value(second), second)?;
            if second < first { return Err("supplied endpoint order contradicts the named pair".into()); }
            Ok(vec![(second - first).to_string()])
        })().map_err(|error| format!("{adapter} row {}: {error}", row_index + 1))?;
        record.extend(computed.iter().map(String::as_str));
        writer.write_record(&record).map_err(|error| format!("{adapter} write row: {error}"))?;
        rows += 1;
    }
    let bytes = writer.into_inner().map_err(|error| format!("{adapter} finish output: {error}"))?;
    let kind = match adapter {
        HMOG_MAGNITUDE_ADAPTER => "literature-hmog-sensor-magnitude-csv",
        HMOG_REDUCTIONS_ADAPTER => "literature-hmog-supplied-window-reductions-csv",
        HMOG_STABILITY_ADAPTER => "literature-hmog-supplied-stability-search-csv",
        HMOG_KEY_HOLD_ADAPTER => "literature-hmog-paired-key-hold-csv",
        HMOG_DIGRAPH_ADAPTER => "literature-hmog-consecutive-press-digraph-csv",
        HMOG_TAP_DURATION_ADAPTER => "literature-hmog-paired-tap-duration-csv",
        HMOG_CONTACT_STATISTICS_ADAPTER => "literature-hmog-contact-size-unique-statistics-csv",
        HMOG_PIXEL_VELOCITY_ADAPTER => "literature-hmog-supplied-pixel-velocity-csv",
        HMOG_KEY_DOMAINS_ADAPTER => "literature-hmog-supplied-key-feature-domains-csv",
        _ => unreachable!("adapter validated before parsing"),
    };
    complete_standalone_component_adaptation(adapter, kind, original_input_digest, bindings, rows, rows, bytes)
}

fn adapt_timestamp_correction(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{TIMESTAMP_CORRECTION_ADAPTER} has no registered component"))?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{TIMESTAMP_CORRECTION_ADAPTER} requires registered componentConfig")
    })?;
    let configuration: TimestampCorrectionConfiguration =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {TIMESTAMP_CORRECTION_ADAPTER} componentConfig: {error}")
        })?;
    let output = execute_timestamp_correction_csv(raw_csv, &configuration)
        .map_err(|error| format!("{TIMESTAMP_CORRECTION_ADAPTER}: {error}"))?;
    let source_row_count = output.input_row_count;
    let output_row_count = output.output_row_count;
    let duplicate_id_row_count = u32::try_from(output.duplicate_id_row_count)
        .map_err(|_| format!("{TIMESTAMP_CORRECTION_ADAPTER} duplicate count overflow"))?;
    let corrected_timestamp_rows = u32::try_from(output.output_row_count).map_err(|_| {
        format!("{TIMESTAMP_CORRECTION_ADAPTER} corrected timestamp count overflow")
    })?;
    let mut adapted = complete_standalone_component_adaptation(
        TIMESTAMP_CORRECTION_ADAPTER,
        "literature-timestamp-correction-csv",
        original_input_digest,
        bindings,
        source_row_count,
        output_row_count,
        output.derived_csv,
    )?;
    adapted.receipt.duplicate_source_ids_removed = duplicate_id_row_count;
    adapted.receipt.corrected_timestamp_provenance_rows = corrected_timestamp_rows;
    Ok(adapted)
}

fn adapt_esm_timezone_window_correction(
    sensing_csv: &[u8],
    esm_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{ESM_TIMEZONE_WINDOW_CORRECTION_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{ESM_TIMEZONE_WINDOW_CORRECTION_ADAPTER} requires registered componentConfig")
    })?;
    let configuration: EsmTimezoneWindowCorrectionConfiguration =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {ESM_TIMEZONE_WINDOW_CORRECTION_ADAPTER} componentConfig: {error}")
        })?;
    let output = execute_esm_timezone_window_correction_csv(sensing_csv, esm_csv, &configuration)
        .map_err(|error| format!("{ESM_TIMEZONE_WINDOW_CORRECTION_ADAPTER}: {error}"))?;
    let mut adapted = complete_standalone_component_adaptation(
        ESM_TIMEZONE_WINDOW_CORRECTION_ADAPTER,
        "literature-esm-timezone-window-correction-csv",
        original_input_digest,
        bindings,
        output.sensing_input_row_count,
        output.esm_input_row_count,
        output.derived_csv,
    )?;
    adapted.receipt.corrected_timestamp_provenance_rows =
        u32::try_from(output.corrected_esm_row_count).map_err(|_| {
            format!("{ESM_TIMEZONE_WINDOW_CORRECTION_ADAPTER} corrected row count overflow")
        })?;
    Ok(adapted)
}

fn adapt_aggregated_app_observation(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{AGGREGATED_APP_OBSERVATION_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{AGGREGATED_APP_OBSERVATION_ADAPTER} requires registered componentConfig")
    })?;
    let configuration: AggregatedAppObservationComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {AGGREGATED_APP_OBSERVATION_ADAPTER} componentConfig: {error}")
        })?;
    if configuration.measure_representation != "lexical"
        || configuration.input_stage != "already_aggregated_application_observations"
    {
        return Err(format!(
            "{AGGREGATED_APP_OBSERVATION_ADAPTER} refuses undisclosed units or aggregation"
        ));
    }
    let records = parse_aggregated_app_observations(raw_csv)
        .map_err(|error| format!("{AGGREGATED_APP_OBSERVATION_ADAPTER}: {error}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "user_id",
            "date",
            "application_name",
            "screen_time",
            "launch_count",
        ])
        .map_err(|error| format!("{AGGREGATED_APP_OBSERVATION_ADAPTER} write header: {error}"))?;
    for record in &records {
        writer
            .write_record([
                record.user_id.as_str(),
                record.date.as_str(),
                record.application_name.as_str(),
                record.screen_time.as_str(),
                record.launch_count.as_str(),
            ])
            .map_err(|error| {
                format!("{AGGREGATED_APP_OBSERVATION_ADAPTER} write output row: {error}")
            })?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{AGGREGATED_APP_OBSERVATION_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        AGGREGATED_APP_OBSERVATION_ADAPTER,
        "literature-aggregated-app-observation-csv",
        original_input_digest,
        bindings,
        records.len(),
        records.len(),
        csv_bytes,
    )
}

fn adapt_communication_detail_record(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{COMMUNICATION_DETAIL_RECORD_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{COMMUNICATION_DETAIL_RECORD_ADAPTER} requires registered componentConfig")
    })?;
    let configuration: CommunicationDetailRecordComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {COMMUNICATION_DETAIL_RECORD_ADAPTER} componentConfig: {error}")
        })?;
    if configuration.supported_modalities != ["voice_call", "sms"]
        || configuration.observed_modality_cardinality != "zero_or_more_each"
    {
        return Err(format!(
            "{COMMUNICATION_DETAIL_RECORD_ADAPTER} requires the source-supported modality vocabulary without observed-row cardinality constraints"
        ));
    }
    let records = parse_joint_voice_sms_communication_details(raw_csv)
        .map_err(|error| format!("{COMMUNICATION_DETAIL_RECORD_ADAPTER}: {error}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_record_index",
            "endpoint_1_id",
            "endpoint_2_id",
            "communication_modality",
        ])
        .map_err(|error| format!("{COMMUNICATION_DETAIL_RECORD_ADAPTER} write header: {error}"))?;
    for record in &records {
        let source_record_index = record.source_record_index.to_string();
        let modality = match record.modality {
            CommunicationModality::VoiceCall => "voice_call",
            CommunicationModality::Sms => "sms",
        };
        writer
            .write_record([
                source_record_index.as_str(),
                record.endpoint_1_id.as_str(),
                record.endpoint_2_id.as_str(),
                modality,
            ])
            .map_err(|error| {
                format!("{COMMUNICATION_DETAIL_RECORD_ADAPTER} write output row: {error}")
            })?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{COMMUNICATION_DETAIL_RECORD_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        COMMUNICATION_DETAIL_RECORD_ADAPTER,
        "literature-communication-detail-record-csv",
        original_input_digest,
        bindings,
        records.len(),
        records.len(),
        csv_bytes,
    )
}

fn adapt_participant_day_duration_exclusion(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} requires registered componentConfig")
    })?;
    let config: ParticipantDayDurationExclusionComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} componentConfig: {error}")
        })?;
    if config.maximum_inclusive_duration_ns != 36_000_000_000_000
        || config.comparator != "strict_greater_than"
        || config.scope != "participant_day"
        || config.disposition != "exclude_day"
    {
        return Err(format!(
            "{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} refuses unsupported threshold semantics"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} header: {error}"))?
        .clone();
    let participant = required_header(
        &headers,
        "participant_id",
        PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER,
    )?;
    let source_day = required_header(
        &headers,
        "source_day_id",
        PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER,
    )?;
    let total_duration = required_header(
        &headers,
        "total_duration_ns",
        PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER,
    )?;
    let mut observed_days = Vec::new();
    let mut daily_durations = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let participant_id = record_value(&record, Some(participant)).to_owned();
        let source_day_id = record_value(&record, Some(source_day)).to_owned();
        let duration_ns = record_value(&record, Some(total_duration))
            .parse::<u64>()
            .map_err(|_| {
                format!(
                    "{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} row {} requires unsigned integer total_duration_ns",
                    row_index + 1
                )
            })?;
        observed_days.push(ObservedScreenDay {
            participant_id: participant_id.clone(),
            source_day_id: source_day_id.clone(),
        });
        daily_durations.push(ScreenBoutDailyDuration {
            participant_id,
            source_day_id,
            duration_ns,
        });
    }
    let decisions = exclude_participant_days_over_duration(
        &observed_days,
        &daily_durations,
        config.maximum_inclusive_duration_ns,
    )
    .map_err(|error| format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER}: {error}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "source_day_id",
            "total_duration_ns",
            "exclude_day",
        ])
        .map_err(|error| {
            format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} write header: {error}")
        })?;
    for decision in &decisions {
        writer
            .serialize((
                decision.participant_id.as_str(),
                decision.source_day_id.as_str(),
                decision.total_duration_ns,
                decision.exclude_day,
            ))
            .map_err(|error| {
                format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        PARTICIPANT_DAY_DURATION_EXCLUSION_ADAPTER,
        "literature-participant-day-duration-exclusion-csv",
        original_input_digest,
        bindings,
        daily_durations.len(),
        decisions.len(),
        csv_bytes,
    )
}

fn adapt_date_count_conjunction_exclusion(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} requires registered componentConfig")
    })?;
    let config: DateCountConjunctionExclusionComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} componentConfig: {error}")
        })?;
    if config.primary_comparator != "strict_less_than_mean_minus_one_sd"
        || config.secondary_comparator != "strict_greater_than_mean"
        || config.standard_deviation != "sample"
        || config.missing_comparison_disposition != "not_selected_r_which_na"
    {
        return Err(format!(
            "{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} refuses unsupported count-conjunction semantics"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} header: {error}"))?
        .clone();
    let record_type = required_header(
        &headers,
        "record_type",
        DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER,
    )?;
    let date = required_header(&headers, "date", DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER)?;
    let primary_count = required_header(
        &headers,
        "primary_count",
        DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER,
    )?;
    let secondary_count = required_header(
        &headers,
        "secondary_count",
        DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER,
    )?;
    let ema_scope_id = required_header(
        &headers,
        "ema_scope_id",
        DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER,
    )?;
    let mut daily_counts = Vec::new();
    let mut scopes = Vec::new();
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let date_value = record_value(&record, Some(date)).to_owned();
        let primary = record_value(&record, Some(primary_count));
        let secondary = record_value(&record, Some(secondary_count));
        let scope = record_value(&record, Some(ema_scope_id));
        match record_value(&record, Some(record_type)) {
            "daily_count" if scope.is_empty() && !primary.is_empty() => {
                daily_counts.push(DailyPairedEventCounts {
                    date: date_value,
                    primary_count: primary.parse::<u64>().map_err(|_| {
                        format!(
                            "{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} row {} requires unsigned integer primary_count",
                            row_index + 1
                        )
                    })?,
                    secondary_count: if secondary.is_empty() {
                        None
                    } else {
                        Some(secondary.parse::<u64>().map_err(|_| {
                            format!(
                                "{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} row {} requires unsigned integer secondary_count or an empty R NA cell",
                                row_index + 1
                            )
                        })?)
                    },
                });
            }
            "ema_scope" if primary.is_empty() && secondary.is_empty() && !scope.is_empty() => {
                scopes.push(DateEmaScope {
                    date: date_value,
                    ema_scope_id: scope.to_owned(),
                });
            }
            _ => {
                return Err(format!(
                    "{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} row {} must be a daily_count row with counts or ema_scope row without counts",
                    row_index + 1
                ));
            }
        }
    }
    let evaluation = evaluate_date_scoped_count_conjunction(&daily_counts, &scopes)
        .map_err(|error| format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER}: {error}"))?;
    let excluded_scope_ids = evaluation
        .excluded_scopes
        .iter()
        .map(|scope| scope.ema_scope_id.as_str())
        .collect::<BTreeSet<_>>();
    let optional_float =
        |value: Option<f64>| value.map(|value| value.to_string()).unwrap_or_default();
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "record_type",
            "date",
            "ema_scope_id",
            "primary_count",
            "secondary_count",
            "primary_below_cutoff",
            "secondary_above_mean",
            "excluded",
            "primary_mean",
            "primary_sample_sd",
            "primary_cutoff",
            "secondary_mean",
        ])
        .map_err(|error| {
            format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} write header: {error}")
        })?;
    for evidence in &evaluation.daily_evidence {
        writer
            .write_record([
                "daily_count",
                evidence.date.as_str(),
                "",
                evidence.primary_count.to_string().as_str(),
                evidence
                    .secondary_count
                    .map(|value| value.to_string())
                    .unwrap_or_default()
                    .as_str(),
                evidence.primary_below_cutoff.to_string().as_str(),
                evidence.secondary_above_mean.to_string().as_str(),
                "",
                optional_float(evaluation.primary_mean).as_str(),
                optional_float(evaluation.primary_sample_sd).as_str(),
                optional_float(evaluation.primary_cutoff).as_str(),
                optional_float(evaluation.secondary_mean).as_str(),
            ])
            .map_err(|error| {
                format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} write daily row: {error}")
            })?;
    }
    for scope in &scopes {
        writer
            .write_record([
                "ema_scope",
                scope.date.as_str(),
                scope.ema_scope_id.as_str(),
                "",
                "",
                "",
                "",
                if excluded_scope_ids.contains(scope.ema_scope_id.as_str()) {
                    "true"
                } else {
                    "false"
                },
                "",
                "",
                "",
                "",
            ])
            .map_err(|error| {
                format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} write EMA row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        DATE_COUNT_CONJUNCTION_EXCLUSION_ADAPTER,
        "literature-date-count-conjunction-exclusion-csv",
        original_input_digest,
        bindings,
        source_row_count,
        evaluation.daily_evidence.len() + scopes.len(),
        csv_bytes,
    )
}

fn adapt_participation_day_warmup(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{PARTICIPATION_DAY_WARMUP_ADAPTER} has no registered component"))?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{PARTICIPATION_DAY_WARMUP_ADAPTER} requires registered componentConfig")
    })?;
    let config: ParticipationDayWarmupComponentConfig = serde_json::from_value(raw_config.clone())
        .map_err(|error| {
            format!("invalid {PARTICIPATION_DAY_WARMUP_ADAPTER} componentConfig: {error}")
        })?;
    if config.warmup_duration_ns != SOURCE_WARMUP_DURATION_NS
        || config.excluded_elapsed_interval != "[0,3600s)"
        || config.boundary_source != "explicit_participant_day_input"
    {
        return Err(format!(
            "{PARTICIPATION_DAY_WARMUP_ADAPTER} refuses inferred participation-day boundaries"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{PARTICIPATION_DAY_WARMUP_ADAPTER} header: {error}"))?
        .clone();
    let record_type = required_header(&headers, "record_type", PARTICIPATION_DAY_WARMUP_ADAPTER)?;
    let participant =
        required_header(&headers, "participant_id", PARTICIPATION_DAY_WARMUP_ADAPTER)?;
    let source_day = required_header(&headers, "source_day_id", PARTICIPATION_DAY_WARMUP_ADAPTER)?;
    let timestamp = required_header(&headers, "timestamp_ns", PARTICIPATION_DAY_WARMUP_ADAPTER)?;
    let payload = required_header(&headers, "payload", PARTICIPATION_DAY_WARMUP_ADAPTER)?;
    let mut boundaries = Vec::new();
    let mut records = Vec::new();
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{PARTICIPATION_DAY_WARMUP_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let participant_id = record_value(&record, Some(participant)).to_owned();
        let source_day_id = record_value(&record, Some(source_day)).to_owned();
        let timestamp_ns = record_value(&record, Some(timestamp))
            .parse::<i64>()
            .map_err(|_| {
                format!(
                    "{PARTICIPATION_DAY_WARMUP_ADAPTER} row {} requires integer timestamp_ns",
                    row_index + 1
                )
            })?;
        let payload_value = record_value(&record, Some(payload));
        match record_value(&record, Some(record_type)) {
            "boundary" if payload_value.is_empty() => boundaries.push(ParticipationDayBoundary {
                participant_id,
                source_day_id,
                start_timestamp_ns: timestamp_ns,
            }),
            "event" if !payload_value.is_empty() => records.push(ParticipationDayRecord {
                participant_id,
                source_day_id,
                event_timestamp_ns: timestamp_ns,
                payload: payload_value.to_owned(),
            }),
            _ => {
                return Err(format!(
                    "{PARTICIPATION_DAY_WARMUP_ADAPTER} row {} must be an empty-payload boundary or non-empty-payload event",
                    row_index + 1
                ));
            }
        }
    }
    let retained = exclude_first_participation_day_hour(records, boundaries)
        .map_err(|error| format!("{PARTICIPATION_DAY_WARMUP_ADAPTER}: {error}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "participant_id",
            "source_day_id",
            "event_timestamp_ns",
            "payload",
        ])
        .map_err(|error| format!("{PARTICIPATION_DAY_WARMUP_ADAPTER} write header: {error}"))?;
    for record in &retained {
        writer
            .serialize((
                record.participant_id.as_str(),
                record.source_day_id.as_str(),
                record.event_timestamp_ns,
                record.payload.as_str(),
            ))
            .map_err(|error| format!("{PARTICIPATION_DAY_WARMUP_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{PARTICIPATION_DAY_WARMUP_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        PARTICIPATION_DAY_WARMUP_ADAPTER,
        "literature-participation-day-warmup-csv",
        original_input_digest,
        bindings,
        source_row_count,
        retained.len(),
        csv_bytes,
    )
}

fn adapt_fixed_weekly_self_report_cap(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} requires registered componentConfig")
    })?;
    let config: FixedWeeklySelfReportCapComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} componentConfig: {error}")
        })?;
    if config.threshold_hours != SOURCE_WEEKLY_CAP_HOURS
        || config.comparator != "greater_than_or_equal"
        || config.outlier_disposition != "retain_row_and_cap_value"
        || !config.preserve_original_value
    {
        return Err(format!(
            "{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} refuses unsupported cap semantics"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} header: {error}"))?
        .clone();
    let participant = required_header(
        &headers,
        "participant_id",
        FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER,
    )?;
    let measure = required_header(&headers, "measure_id", FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER)?;
    let weekly_hours = required_header(
        &headers,
        "weekly_hours",
        FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER,
    )?;
    let mut records = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let value = record_value(&record, Some(weekly_hours))
            .parse::<f64>()
            .map_err(|_| {
                format!(
                    "{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} row {} requires numeric weekly_hours",
                    row_index + 1
                )
            })?;
        records.push(WeeklySelfReportRecord {
            participant_id: record_value(&record, Some(participant)).to_owned(),
            measure_id: record_value(&record, Some(measure)).to_owned(),
            weekly_hours: value,
            payload: row_index + 1,
        });
    }
    let source_row_count = records.len();
    let capped = cap_weekly_self_reports_at_84_hours(records)
        .map_err(|error| format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER}: {error}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_record_index",
            "participant_id",
            "measure_id",
            "original_weekly_hours",
            "analysis_weekly_hours",
            "source_outlier",
        ])
        .map_err(|error| format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} write header: {error}"))?;
    for record in &capped {
        writer
            .serialize((
                record.payload,
                record.participant_id.as_str(),
                record.measure_id.as_str(),
                record.original_weekly_hours,
                record.analysis_weekly_hours,
                record.source_outlier,
            ))
            .map_err(|error| {
                format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        FIXED_WEEKLY_SELF_REPORT_CAP_ADAPTER,
        "literature-fixed-weekly-self-report-cap-csv",
        original_input_digest,
        bindings,
        source_row_count,
        capped.len(),
        csv_bytes,
    )
}

fn adapt_esm_app_sampling_gate(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{ESM_APP_SAMPLING_GATE_ADAPTER} has no registered component"))?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{ESM_APP_SAMPLING_GATE_ADAPTER} requires registered componentConfig")
    })?;
    let config: EsmAppSamplingGateComponentConfig = serde_json::from_value(raw_config.clone())
        .map_err(|error| {
            format!("invalid {ESM_APP_SAMPLING_GATE_ADAPTER} componentConfig: {error}")
        })?;
    if config.during_delay_draw_outcome_count != 106
        || config.inclusive_delay_seconds != [15, 120]
        || config.end_minimum_use_ms != 15_000
        || config.same_app_history_length != 3
        || config.cooldown_variants.len() != 2
    {
        return Err(format!(
            "{ESM_APP_SAMPLING_GATE_ADAPTER} componentConfig drifts from the bounded sources"
        ));
    }
    let expected_variants = BTreeMap::from([
        (
            "paper_at_least_30_minutes",
            (
                "62ca882c4385d020b1462331736224aa48d9a6c9dcf10e384c978af9eb12e62c",
                "greater_than_or_equal",
                "1d04a62c6113e874206248ba6e69baa07b5676c30746ce5d48dd419a494cdac6",
                "4eb4444cf90a23a490f6c3b6cf21a88cbd145da0b07e705d9448a97bf389e000",
            ),
        ),
        (
            "released_code_strictly_after_30_minutes",
            (
                "e2007dd9eaadc581b900195409ebf78222ce6ace3660ae18177187e62d1caae3",
                "strictly_greater_than",
                "77e09da8bd03d68575884751e085fb11c3e24a9228381c8c85aa60999d7fbafa",
                "15034b5e82778971caa842c54b407b8b6c95f1fd9d5f1c4c232616a0f9274cdd",
            ),
        ),
    ]);
    let mut registered_variants = BTreeMap::new();
    for variant in config.cooldown_variants {
        let expected = expected_variants
            .get(variant.variant_id.as_str())
            .ok_or_else(|| {
                format!(
                    "{ESM_APP_SAMPLING_GATE_ADAPTER} has unknown cooldown variant {}",
                    variant.variant_id
                )
            })?;
        if variant.source_artifact_sha256 != expected.0
            || variant.comparator != expected.1
            || variant.threshold_ms != GLOBAL_PROMPT_COOLDOWN_MS
            || variant.configuration_sha256 != expected.2
            || variant.equality_outcome_sha256 != expected.3
            || registered_variants
                .insert(variant.variant_id.clone(), variant)
                .is_some()
        {
            return Err(format!(
                "{ESM_APP_SAMPLING_GATE_ADAPTER} cooldown variant registration drift"
            ));
        }
    }
    if registered_variants.len() != expected_variants.len() {
        return Err(format!(
            "{ESM_APP_SAMPLING_GATE_ADAPTER} requires both named cooldown variants"
        ));
    }

    const CONFIGURATION_DIRECTIVE_PREFIX: &str =
        "# chronicle-literature-component-configuration/v1:";
    let input = std::str::from_utf8(raw_csv)
        .map_err(|error| format!("{ESM_APP_SAMPLING_GATE_ADAPTER} input UTF-8: {error}"))?;
    let (directive, data_csv) = input.split_once('\n').ok_or_else(|| {
        format!(
            "{ESM_APP_SAMPLING_GATE_ADAPTER} requires one invocation-level configuration directive before the CSV header"
        )
    })?;
    let selected_id = directive
        .trim_end_matches('\r')
        .strip_prefix(CONFIGURATION_DIRECTIVE_PREFIX)
        .ok_or_else(|| {
            format!(
                "{ESM_APP_SAMPLING_GATE_ADAPTER} requires one invocation-level configuration directive before the CSV header"
            )
        })?;
    let selected = registered_variants.get(selected_id).ok_or_else(|| {
        format!(
            "{ESM_APP_SAMPLING_GATE_ADAPTER} invocation must select exactly one registered cooldown configuration"
        )
    })?;
    let source_variant = match selected_id {
        "paper_at_least_30_minutes" => CooldownSourceVariant::PaperAtLeastThirtyMinutes,
        "released_code_strictly_after_30_minutes" => {
            CooldownSourceVariant::ReleasedCodeStrictlyAfterThirtyMinutes
        }
        _ => unreachable!("registered variant IDs were closed above"),
    };

    let mut reader = csv::ReaderBuilder::new().from_reader(data_csv.as_bytes());
    let headers = reader
        .headers()
        .map_err(|error| format!("{ESM_APP_SAMPLING_GATE_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", ESM_APP_SAMPLING_GATE_ADAPTER)?;
    let package = required_header(&headers, "package_id", ESM_APP_SAMPLING_GATE_ADAPTER)?;
    let draw = required_header(
        &headers,
        "during_delay_draw_index",
        ESM_APP_SAMPLING_GATE_ADAPTER,
    )?;
    let duration = required_header(
        &headers,
        "contiguous_use_duration_ms",
        ESM_APP_SAMPLING_GATE_ADAPTER,
    )?;
    let history = required_header(
        &headers,
        "recent_successful_package_ids",
        ESM_APP_SAMPLING_GATE_ADAPTER,
    )?;
    let elapsed = required_header(
        &headers,
        "elapsed_since_last_prompt_ms",
        ESM_APP_SAMPLING_GATE_ADAPTER,
    )?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_row_id",
            "package_id",
            "during_delay_ms",
            "end_prompt_eligible",
            "same_app_eligible",
            "updated_recent_package_ids",
            "cooldown_variant_id",
            "cooldown_configuration_sha256",
            "cooldown_equality_outcome_sha256",
            "cooldown_eligible",
        ])
        .map_err(|error| format!("{ESM_APP_SAMPLING_GATE_ADAPTER} write header: {error}"))?;
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{ESM_APP_SAMPLING_GATE_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let source_row_id = record_value(&record, Some(source_row));
        let package_id = record_value(&record, Some(package));
        if source_row_id.is_empty() {
            return Err(format!(
                "{ESM_APP_SAMPLING_GATE_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let draw_index = record_value(&record, Some(draw))
            .parse::<u16>()
            .map_err(|_| {
                format!(
                    "{ESM_APP_SAMPLING_GATE_ADAPTER} row {} requires integer during_delay_draw_index",
                    row_index + 1
                )
            })?;
        let contiguous_use_duration_ms = record_value(&record, Some(duration))
            .parse::<u64>()
            .map_err(|_| {
                format!(
                    "{ESM_APP_SAMPLING_GATE_ADAPTER} row {} requires unsigned contiguous_use_duration_ms",
                    row_index + 1
                )
            })?;
        let recent = record_value(&record, Some(history));
        let recent = if recent.is_empty() {
            Vec::new()
        } else {
            recent.split('|').map(str::to_owned).collect::<Vec<_>>()
        };
        let elapsed_text = record_value(&record, Some(elapsed));
        let elapsed_ms = if elapsed_text.is_empty() {
            None
        } else {
            Some(elapsed_text.parse::<u64>().map_err(|_| {
                format!(
                    "{ESM_APP_SAMPLING_GATE_ADAPTER} row {} requires unsigned elapsed_since_last_prompt_ms or an empty no-prior-prompt cell",
                    row_index + 1
                )
            })?)
        };
        let same_app_eligible = same_app_is_eligible(package_id, &recent).map_err(|error| {
            format!(
                "{ESM_APP_SAMPLING_GATE_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let updated = if same_app_eligible {
            record_successful_app_sample(package_id, &recent)
                .map_err(|error| {
                    format!(
                        "{ESM_APP_SAMPLING_GATE_ADAPTER} row {}: {error}",
                        row_index + 1
                    )
                })?
                .join("|")
        } else {
            String::new()
        };
        writer
            .serialize((
                source_row_id,
                package_id,
                during_use_delay_ms(draw_index).map_err(|error| {
                    format!(
                        "{ESM_APP_SAMPLING_GATE_ADAPTER} row {}: {error}",
                        row_index + 1
                    )
                })?,
                end_prompt_is_eligible(contiguous_use_duration_ms),
                same_app_eligible,
                updated,
                selected_id,
                selected.configuration_sha256.as_str(),
                selected.equality_outcome_sha256.as_str(),
                cooldown_is_eligible(elapsed_ms, source_variant),
            ))
            .map_err(|error| format!("{ESM_APP_SAMPLING_GATE_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{ESM_APP_SAMPLING_GATE_ADAPTER} finish output: {error}"))?;
    let mut adapted = complete_standalone_component_adaptation(
        ESM_APP_SAMPLING_GATE_ADAPTER,
        "literature-esm-app-sampling-gate-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )?;
    adapted.receipt.component_configuration =
        Some(LiteratureComponentConfigurationSelectionReceipt {
            configuration_id: selected_id.to_owned(),
            source_artifact_sha256: selected.source_artifact_sha256.clone(),
            configuration_sha256: selected.configuration_sha256.clone(),
            equality_outcome_sha256: selected.equality_outcome_sha256.clone(),
        });
    Ok(adapted)
}

fn parse_r_numeric_cell(value: &str, field: &str, row_index: usize) -> Result<Option<f64>, String> {
    match value {
        "NA" | "" => Ok(None),
        "NaN" => Ok(Some(f64::NAN)),
        "Inf" => Ok(Some(f64::INFINITY)),
        "-Inf" => Ok(Some(f64::NEG_INFINITY)),
        value => {
            let parsed = value.parse::<f64>().map_err(|_| {
                format!("row {row_index} requires R numeric {field} or NA/NaN/Inf/-Inf")
            })?;
            parsed
                .is_finite()
                .then_some(Some(parsed))
                .ok_or_else(|| format!("row {row_index} has unsupported {field} spelling"))
        }
    }
}

fn format_r_numeric(value: Option<f64>) -> String {
    match value {
        None => "NA".to_owned(),
        Some(value) if value.is_nan() => "NaN".to_owned(),
        Some(value) if value == f64::INFINITY => "Inf".to_owned(),
        Some(value) if value == f64::NEG_INFINITY => "-Inf".to_owned(),
        Some(value) => value.to_string(),
    }
}

fn adapt_screen_academic_row_derivation(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} requires registered componentConfig")
    })?;
    let config: ScreenAcademicRowDerivationComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} componentConfig: {error}")
        })?;
    if config.r_version != "4.1.2"
        || config.input_stage != "post_as_integer_grade_source_rows"
        || config.scale_centered
        || config.sample_sd_na_rm
        || !config.apply_background_complete_case_filter
        || config.special_value_encoding != "R_NA_NaN_Inf_-Inf"
    {
        return Err(format!(
            "{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} componentConfig drifts from the deposited R boundary"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let integer_grade = required_header(
        &headers,
        "integer_grade",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let screen_time = required_header(
        &headers,
        "screen_time",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let attendance = required_header(
        &headers,
        "attendance_percent",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let parent_income = required_header(
        &headers,
        "parent_income_mean",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let smoke = required_header(
        &headers,
        "smoke_frequency",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let course = required_header(
        &headers,
        "course_semester_id",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let high_school_gpa = required_header(
        &headers,
        "high_school_gpa",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;
    let parent_education = required_header(
        &headers,
        "parent_education_max",
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
    )?;

    let mut derivation_rows = Vec::new();
    let mut background_rows = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let source_row_id = record_value(&record, Some(source_row)).to_owned();
        if source_row_id.is_empty() {
            return Err(format!(
                "{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let grade_text = record_value(&record, Some(integer_grade));
        let grade = if matches!(grade_text, "" | "NA") {
            None
        } else {
            Some(grade_text.parse::<i32>().map_err(|_| {
                format!(
                    "{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} row {} requires integer_grade after upstream as.integer",
                    row_index + 1
                )
            })?)
        };
        let screen_time_value = parse_r_numeric_cell(
            record_value(&record, Some(screen_time)),
            "screen_time",
            row_index + 1,
        )?;
        let attendance_value = parse_r_numeric_cell(
            record_value(&record, Some(attendance)),
            "attendance_percent",
            row_index + 1,
        )?;
        let parent_income_value = parse_r_numeric_cell(
            record_value(&record, Some(parent_income)),
            "parent_income_mean",
            row_index + 1,
        )?;
        let smoke_value = parse_r_numeric_cell(
            record_value(&record, Some(smoke)),
            "smoke_frequency",
            row_index + 1,
        )?;
        let course_text = record_value(&record, Some(course));
        derivation_rows.push(ScreenAcademicInputRow {
            integer_grade: grade,
            screen_time: screen_time_value,
            attendance_percent: attendance_value,
            parent_income_mean: parent_income_value,
            smoke_frequency: smoke_value,
            course_semester_id: (course_text != "NA").then(|| course_text.to_owned()),
            payload: source_row_id.clone(),
        });
        background_rows.push(ScreenAcademicBackgroundRow {
            high_school_gpa: parse_r_numeric_cell(
                record_value(&record, Some(high_school_gpa)),
                "high_school_gpa",
                row_index + 1,
            )?,
            parent_education_max: parse_r_numeric_cell(
                record_value(&record, Some(parent_education)),
                "parent_education_max",
                row_index + 1,
            )?,
            parent_income_mean: parent_income_value,
            payload: source_row_id,
        });
    }
    let source_row_count = derivation_rows.len();
    let retained_ids = retain_complete_screen_academic_background(background_rows)
        .into_iter()
        .map(|row| row.payload)
        .collect::<BTreeSet<_>>();
    let derivation = derive_screen_academic_rows(derivation_rows);
    let retained = derivation
        .rows
        .into_iter()
        .filter(|row| retained_ids.contains(&row.payload))
        .collect::<Vec<_>>();
    let grade_sd = format_r_numeric(derivation.grade_sample_sd);
    let screen_sd = format_r_numeric(derivation.screen_time_sample_sd);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_row_id",
            "skipping_percent",
            "parent_income_ten_thousands",
            "screen_time_scale_only",
            "grade_scale_only",
            "smoker_indicator",
            "course_id",
            "grade_sample_sd",
            "screen_time_sample_sd",
        ])
        .map_err(|error| {
            format!("{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} write header: {error}")
        })?;
    for row in &retained {
        writer
            .write_record([
                row.payload.as_str(),
                format_r_numeric(row.skipping_percent).as_str(),
                format_r_numeric(row.parent_income_ten_thousands).as_str(),
                format_r_numeric(row.screen_time_scale_only).as_str(),
                format_r_numeric(row.grade_scale_only).as_str(),
                row.smoker_indicator
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "NA".to_owned())
                    .as_str(),
                row.course_id.as_deref().unwrap_or("NA"),
                grade_sd.as_str(),
                screen_sd.as_str(),
            ])
            .map_err(|error| {
                format!("{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        SCREEN_ACADEMIC_ROW_DERIVATION_ADAPTER,
        "literature-screen-academic-row-derivation-csv",
        original_input_digest,
        bindings,
        source_row_count,
        retained.len(),
        csv_bytes,
    )
}

fn adapt_screen_academic_preparation(
    input: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let table = crate::binary_exports::read_single_table_arrow(input)?;
    let (course, participant) =
        crate::screen_academic_row_derivation::prepare_screen_academic_tables(&table)?;
    let mut adapted = complete_standalone_component_adaptation(
        SCREEN_ACADEMIC_PREPARATION_ADAPTER,
        "literature-screen-academic-participant-arrow",
        original_input_digest,
        bindings,
        table.num_rows(),
        participant.num_rows(),
        crate::binary_exports::single_table_arrow(&participant)?,
    )?;
    adapted.csv_bytes = crate::binary_exports::single_table_arrow(&course)?;
    adapted.receipt.adapted_input_digest = sha256(&adapted.csv_bytes);
    adapted.receipt.emitted_row_count =
        u32::try_from(course.num_rows()).map_err(|_| "course row count overflow")?;
    adapted.receipt.adapter_ids = bindings
        .iter()
        .map(|binding| format!("{}/{}", binding.adapter_id, binding.adapter_version))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    Ok(adapted)
}

fn adapt_iterative_sparse_group_filter(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} has no registered component")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} requires registered componentConfig")
    })?;
    let config: IterativeSparseGroupFilterComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("invalid {ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} componentConfig: {error}")
        })?;
    if config.threshold != BJERRE_SPARSE_PANEL_SUPPORT_THRESHOLD
        || config.iteration_order != "course_then_participant_until_stable"
        || config.support_measure != "row_count_including_duplicates_and_na_keys"
    {
        return Err(format!(
            "{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} componentConfig drifts from released R"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER,
    )?;
    let user = required_header(&headers, "user_idx", ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER)?;
    let course = required_header(
        &headers,
        "course_num_sem",
        ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER,
    )?;
    let payload = required_header(&headers, "payload", ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER)?;
    let mut rows = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let source_row_id = record_value(&record, Some(source_row)).to_owned();
        if source_row_id.is_empty() {
            return Err(format!(
                "{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let optional_key = |value: &str| (value != "NA").then(|| value.to_owned());
        rows.push(BjerreSparsePanelRow {
            user_idx: optional_key(record_value(&record, Some(user))),
            course_num_sem: optional_key(record_value(&record, Some(course))),
            row: (
                source_row_id,
                record_value(&record, Some(payload)).to_owned(),
            ),
        });
    }
    let source_row_count = rows.len();
    let retained = filter_bjerre_sparse_panel_support(rows);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", "user_idx", "course_num_sem", "payload"])
        .map_err(|error| {
            format!("{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} write header: {error}")
        })?;
    for row in &retained {
        writer
            .write_record([
                row.row.0.as_str(),
                row.user_idx.as_deref().unwrap_or("NA"),
                row.course_num_sem.as_deref().unwrap_or("NA"),
                row.row.1.as_str(),
            ])
            .map_err(|error| {
                format!("{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        ITERATIVE_SPARSE_GROUP_FILTER_ADAPTER,
        "literature-iterative-sparse-group-filter-csv",
        original_input_digest,
        bindings,
        source_row_count,
        retained.len(),
        csv_bytes,
    )
}

#[derive(Debug, Clone)]
struct AdjacentDuplicateRecord {
    source_row_id: String,
    timestamp_seconds: f64,
    battery_level: f64,
    battery_state: String,
    time_zone: String,
    battery_capacity: f64,
    battery_technology: String,
    battery_charger: String,
    battery_health: String,
    process_importances: Vec<String>,
}

fn adapt_adjacent_record_duplicate(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} has no registered component")
        })?;
    let config: AdjacentRecordDuplicateComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {ADJACENT_RECORD_DUPLICATE_ADAPTER} componentConfig: {error}")
        })?;
    let expected_fields = [
        "battery_level",
        "battery_state",
        "time_zone",
        "battery_capacity",
        "battery_technology",
        "battery_charger",
        "battery_health",
    ];
    let expected_exceptions = ["installed", "disabled", "replaced", "uninstalled"];
    if config.exclusive_interval_seconds != 300.0
        || config
            .compared_fields
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>()
            != expected_fields
        || config.exception_field != "process_importances"
        || config
            .retain_current_exception_values
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>()
            != expected_exceptions
        || config.previous_advancement != "after_every_comparison_including_suppressed"
        || config.source_variant_id != "recovered_carat_android_f4242acf_adjacent_upload"
        || config.recovered_commit != "f4242acf3fe8f7db9d2a47ac9af4940ac3eacd39"
    {
        return Err(format!(
            "{ADJACENT_RECORD_DUPLICATE_ADAPTER} componentConfig drifts from its recovered source variant"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{ADJACENT_RECORD_DUPLICATE_ADAPTER} refuses duplicate column names"
        ));
    }
    let column = |name| required_header(&headers, name, ADJACENT_RECORD_DUPLICATE_ADAPTER);
    let source_row = column("source_row_id")?;
    let timestamp = column("timestamp_seconds")?;
    let battery_level = column("battery_level")?;
    let battery_state = column("battery_state")?;
    let time_zone = column("time_zone")?;
    let battery_capacity = column("battery_capacity")?;
    let battery_technology = column("battery_technology")?;
    let battery_charger = column("battery_charger")?;
    let battery_health = column("battery_health")?;
    let process_importances = column("process_importances")?;
    let parse_finite = |value: &str, field: &str, row: usize| -> Result<f64, String> {
        let value = value.parse::<f64>().map_err(|_| {
            format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} row {row} requires numeric {field}")
        })?;
        value.is_finite().then_some(value).ok_or_else(|| {
            format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} row {row} requires finite {field}")
        })
    };
    let mut records = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} row {row_number}: {error}")
        })?;
        let required_text =
            |index: usize, field: &str| -> Result<String, String> {
                let value = record_value(&record, Some(index));
                (!value.is_empty()).then(|| value.to_owned()).ok_or_else(|| {
                format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} row {row_number} has empty {field}")
            })
            };
        let process_text = record_value(&record, Some(process_importances));
        let importances = if process_text.is_empty() {
            Vec::new()
        } else {
            let values = process_text
                .split('|')
                .map(str::to_owned)
                .collect::<Vec<_>>();
            if values.iter().any(String::is_empty) {
                return Err(format!(
                    "{ADJACENT_RECORD_DUPLICATE_ADAPTER} row {row_number} has an empty process importance"
                ));
            }
            values
        };
        records.push(AdjacentDuplicateRecord {
            source_row_id: required_text(source_row, "source_row_id")?,
            timestamp_seconds: parse_finite(
                record_value(&record, Some(timestamp)),
                "timestamp_seconds",
                row_number,
            )?,
            battery_level: parse_finite(
                record_value(&record, Some(battery_level)),
                "battery_level",
                row_number,
            )?,
            battery_state: required_text(battery_state, "battery_state")?,
            time_zone: required_text(time_zone, "time_zone")?,
            battery_capacity: parse_finite(
                record_value(&record, Some(battery_capacity)),
                "battery_capacity",
                row_number,
            )?,
            battery_technology: required_text(battery_technology, "battery_technology")?,
            battery_charger: required_text(battery_charger, "battery_charger")?,
            battery_health: required_text(battery_health, "battery_health")?,
            process_importances: importances,
        });
    }

    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "source_row_id",
            "timestamp_seconds",
            "battery_level",
            "battery_state",
            "time_zone",
            "battery_capacity",
            "battery_technology",
            "battery_charger",
            "battery_health",
            "process_importances",
        ])
        .map_err(|error| format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} write header: {error}"))?;
    let mut previous: Option<&AdjacentDuplicateRecord> = None;
    let mut retained = 0usize;
    let mut suppressed = 0usize;
    for current in &records {
        let compared_fields_equal = previous.is_some_and(|previous| {
            current.battery_level == previous.battery_level
                && current.battery_state == previous.battery_state
                && current.time_zone == previous.time_zone
                && current.battery_capacity == previous.battery_capacity
                && current.battery_technology == previous.battery_technology
                && current.battery_charger == previous.battery_charger
                && current.battery_health == previous.battery_health
        });
        let retain_current_exception = current.process_importances.iter().any(|importance| {
            config
                .retain_current_exception_values
                .iter()
                .any(|expected| expected == importance)
        });
        let suppress = should_suppress_adjacent_record(
            current.timestamp_seconds,
            previous.map(|record| record.timestamp_seconds),
            config.exclusive_interval_seconds,
            compared_fields_equal,
            retain_current_exception,
        )
        .map_err(|error| format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER}: {error}"))?;
        previous = Some(current);
        if suppress {
            suppressed += 1;
            continue;
        }
        retained += 1;
        writer
            .serialize((
                current.source_row_id.as_str(),
                current.timestamp_seconds,
                current.battery_level,
                current.battery_state.as_str(),
                current.time_zone.as_str(),
                current.battery_capacity,
                current.battery_technology.as_str(),
                current.battery_charger.as_str(),
                current.battery_health.as_str(),
                current.process_importances.join("|"),
            ))
            .map_err(|error| format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} finish output: {error}"))?;
    let mut adapted = complete_standalone_component_adaptation(
        ADJACENT_RECORD_DUPLICATE_ADAPTER,
        "literature-adjacent-record-duplicate-csv",
        original_input_digest,
        bindings,
        records.len(),
        retained,
        csv_bytes,
    )?;
    adapted.receipt.duplicate_source_ids_removed = u32::try_from(suppressed)
        .map_err(|_| format!("{ADJACENT_RECORD_DUPLICATE_ADAPTER} suppression count overflow"))?;
    Ok(adapted)
}

fn adapt_integer_daypart_bucketizer(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER} has no registered component")
        })?;
    let config: IntegerDaypartBucketizerComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {INTEGER_DAYPART_BUCKETIZER_ADAPTER} componentConfig: {error}")
        })?;
    if config.thresholds != [6.0, 12.0, 18.0]
        || config.categories != ["night", "morning", "afternoon", "evening"]
        || config.inclusive_hour_domain != [0, 23]
    {
        return Err(format!(
            "{INTEGER_DAYPART_BUCKETIZER_ADAPTER} componentConfig drifts from the disclosed dayparts"
        ));
    }
    let bucketizer = OrderedThresholdBucketizer::new(config.thresholds, config.categories)
        .map_err(|error| format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER}: {error}"))?;
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        INTEGER_DAYPART_BUCKETIZER_ADAPTER,
    )?;
    let hour = required_header(&headers, "hour_of_day", INTEGER_DAYPART_BUCKETIZER_ADAPTER)?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", "hour_of_day", "daypart"])
        .map_err(|error| format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER} write header: {error}"))?;
    let mut source_row_count = 0usize;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{INTEGER_DAYPART_BUCKETIZER_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        let source_row_id = record_value(&record, Some(source_row));
        if source_row_id.is_empty() {
            return Err(format!(
                "{INTEGER_DAYPART_BUCKETIZER_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        let hour = record_value(&record, Some(hour))
            .parse::<u8>()
            .map_err(|_| {
                format!(
                    "{INTEGER_DAYPART_BUCKETIZER_ADAPTER} row {} requires integer hour_of_day",
                    row_index + 1
                )
            })?;
        if !(config.inclusive_hour_domain[0]..=config.inclusive_hour_domain[1]).contains(&hour) {
            return Err(format!(
                "{INTEGER_DAYPART_BUCKETIZER_ADAPTER} row {} hour_of_day is outside 0..=23",
                row_index + 1
            ));
        }
        let category = bucketizer
            .category_for(f64::from(hour))
            .map_err(|error| format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER}: {error}"))?;
        writer
            .serialize((source_row_id, hour, category))
            .map_err(|error| format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{INTEGER_DAYPART_BUCKETIZER_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        INTEGER_DAYPART_BUCKETIZER_ADAPTER,
        "literature-integer-daypart-bucketizer-csv",
        original_input_digest,
        bindings,
        source_row_count,
        source_row_count,
        csv_bytes,
    )
}

fn adapt_grouped_distinct_member_count(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
    adapter_id: &'static str,
    hourly: bool,
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter_id} has no registered component"))?;
    let config: GroupedDistinctMemberCountComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{adapter_id} requires componentConfig"))?,
    )
    .map_err(|error| format!("invalid {adapter_id} componentConfig: {error}"))?;
    let expected_scope = if hourly {
        "participant_source_day_integer_hour"
    } else {
        "participant_source_day"
    };
    if config.group_scope != expected_scope
        || config.member_identity != "opaque_caller_supplied"
        || config.absent_group_policy != "do_not_synthesize_or_zero_fill"
    {
        return Err(format!(
            "{adapter_id} componentConfig drifts from its source boundary"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{adapter_id} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", adapter_id)?;
    let participant = required_header(&headers, "participant_id", adapter_id)?;
    let source_day = required_header(&headers, "source_day_id", adapter_id)?;
    let hour = hourly
        .then(|| required_header(&headers, "hour_of_day", adapter_id))
        .transpose()?;
    let member = required_header(&headers, "member_identity", adapter_id)?;
    let mut source_row_count = 0usize;
    let mut observations = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record =
            record.map_err(|error| format!("{adapter_id} row {}: {error}", row_index + 1))?;
        source_row_count += 1;
        for (index, field) in [
            (source_row, "source_row_id"),
            (participant, "participant_id"),
            (source_day, "source_day_id"),
            (member, "member_identity"),
        ] {
            if record_value(&record, Some(index)).is_empty() {
                return Err(format!(
                    "{adapter_id} row {} has empty {field}",
                    row_index + 1
                ));
            }
        }
        let hour = hour
            .map(|index| {
                let value = record_value(&record, Some(index))
                    .parse::<u8>()
                    .map_err(|_| {
                        format!(
                            "{adapter_id} row {} requires integer hour_of_day",
                            row_index + 1
                        )
                    })?;
                (value <= 23).then_some(value).ok_or_else(|| {
                    format!(
                        "{adapter_id} row {} hour_of_day is outside 0..=23",
                        row_index + 1
                    )
                })
            })
            .transpose()?;
        observations.push((
            (
                record_value(&record, Some(participant)).to_owned(),
                record_value(&record, Some(source_day)).to_owned(),
                hour,
            ),
            record_value(&record, Some(member)).to_owned(),
        ));
    }
    let counts = count_distinct_members_by_group(observations);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    if hourly {
        writer
            .write_record([
                "participant_id",
                "source_day_id",
                "hour_of_day",
                "distinct_member_count",
            ])
            .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    } else {
        writer
            .write_record(["participant_id", "source_day_id", "distinct_member_count"])
            .map_err(|error| format!("{adapter_id} write header: {error}"))?;
    }
    for count in &counts {
        if let Some(hour) = count.group.2 {
            writer
                .serialize((
                    count.group.0.as_str(),
                    count.group.1.as_str(),
                    hour,
                    count.distinct_member_count,
                ))
                .map_err(|error| format!("{adapter_id} write row: {error}"))?;
        } else {
            writer
                .serialize((
                    count.group.0.as_str(),
                    count.group.1.as_str(),
                    count.distinct_member_count,
                ))
                .map_err(|error| format!("{adapter_id} write row: {error}"))?;
        }
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{adapter_id} finish output: {error}"))?;
    let derived_kind = if hourly {
        "literature-hourly-distinct-member-count-csv"
    } else {
        "literature-daily-distinct-member-count-csv"
    };
    complete_standalone_component_adaptation(
        adapter_id,
        derived_kind,
        original_input_digest,
        bindings,
        source_row_count,
        counts.len(),
        csv_bytes,
    )
}

fn adapt_hourly_categorical_mode(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{HOURLY_CATEGORICAL_MODE_ADAPTER} has no registered component"))?;
    let config: HourlyCategoricalModeComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{HOURLY_CATEGORICAL_MODE_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {HOURLY_CATEGORICAL_MODE_ADAPTER} componentConfig: {error}")
        })?;
    if config.allowed_streams != ["hourly_screen_state", "hourly_internet_state"]
        || config.group_scope != "stream_participant_source_day_integer_hour"
        || config.weighting != "observation_frequency"
        || config.tie_policy != "fail_closed"
        || config.absent_group_policy != "do_not_synthesize_or_zero_fill"
    {
        return Err(format!(
            "{HOURLY_CATEGORICAL_MODE_ADAPTER} componentConfig drifts from the disclosed modes"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{HOURLY_CATEGORICAL_MODE_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(&headers, "source_row_id", HOURLY_CATEGORICAL_MODE_ADAPTER)?;
    let stream = required_header(&headers, "stream_id", HOURLY_CATEGORICAL_MODE_ADAPTER)?;
    let participant = required_header(&headers, "participant_id", HOURLY_CATEGORICAL_MODE_ADAPTER)?;
    let source_day = required_header(&headers, "source_day_id", HOURLY_CATEGORICAL_MODE_ADAPTER)?;
    let hour = required_header(&headers, "hour_of_day", HOURLY_CATEGORICAL_MODE_ADAPTER)?;
    let category = required_header(&headers, "category", HOURLY_CATEGORICAL_MODE_ADAPTER)?;
    let mut source_row_count = 0usize;
    let mut observations = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{HOURLY_CATEGORICAL_MODE_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count += 1;
        for (index, field) in [
            (source_row, "source_row_id"),
            (stream, "stream_id"),
            (participant, "participant_id"),
            (source_day, "source_day_id"),
            (category, "category"),
        ] {
            if record_value(&record, Some(index)).is_empty() {
                return Err(format!(
                    "{HOURLY_CATEGORICAL_MODE_ADAPTER} row {} has empty {field}",
                    row_index + 1
                ));
            }
        }
        let stream_id = record_value(&record, Some(stream));
        if !config
            .allowed_streams
            .iter()
            .any(|value| value == stream_id)
        {
            return Err(format!(
                "{HOURLY_CATEGORICAL_MODE_ADAPTER} row {} has unsupported stream_id",
                row_index + 1
            ));
        }
        let hour = record_value(&record, Some(hour))
            .parse::<u8>()
            .map_err(|_| {
                format!(
                    "{HOURLY_CATEGORICAL_MODE_ADAPTER} row {} requires integer hour_of_day",
                    row_index + 1
                )
            })?;
        if hour > 23 {
            return Err(format!(
                "{HOURLY_CATEGORICAL_MODE_ADAPTER} row {} hour_of_day is outside 0..=23",
                row_index + 1
            ));
        }
        observations.push((
            (
                stream_id.to_owned(),
                record_value(&record, Some(participant)).to_owned(),
                record_value(&record, Some(source_day)).to_owned(),
                hour,
            ),
            record_value(&record, Some(category)).to_owned(),
        ));
    }
    let modes = unique_mode_by_group(observations).map_err(|error| {
        format!(
            "{HOURLY_CATEGORICAL_MODE_ADAPTER} refuses a tied maximum in group {:?}",
            error
        )
    })?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "stream_id",
            "participant_id",
            "source_day_id",
            "hour_of_day",
            "category",
            "frequency",
        ])
        .map_err(|error| format!("{HOURLY_CATEGORICAL_MODE_ADAPTER} write header: {error}"))?;
    for mode in &modes {
        writer
            .serialize((
                mode.group.0.as_str(),
                mode.group.1.as_str(),
                mode.group.2.as_str(),
                mode.group.3,
                mode.category.as_str(),
                mode.frequency,
            ))
            .map_err(|error| format!("{HOURLY_CATEGORICAL_MODE_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{HOURLY_CATEGORICAL_MODE_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        HOURLY_CATEGORICAL_MODE_ADAPTER,
        "literature-hourly-categorical-mode-csv",
        original_input_digest,
        bindings,
        source_row_count,
        modes.len(),
        csv_bytes,
    )
}

fn adapt_categorical_response_rate(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{CATEGORICAL_RESPONSE_RATE_ADAPTER} has no registered component")
        })?;
    let config: CategoricalResponseRateComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{CATEGORICAL_RESPONSE_RATE_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {CATEGORICAL_RESPONSE_RATE_ADAPTER} componentConfig: {error}")
        })?;
    if config.responded_label != "responded"
        || config.no_response_label != "no-response"
        || config.missing_values != "exclude_from_numerator_and_denominator"
        || config.zero_denominator != "NaN"
        || config.missing_column_policy != "empty_table_NaN_nonempty_fail_closed"
        || config.fields.is_empty()
    {
        return Err(format!(
            "{CATEGORICAL_RESPONSE_RATE_ADAPTER} componentConfig drifts from released source"
        ));
    }
    let mut configured_setting_ids = BTreeSet::new();
    let mut configured_input_fields = BTreeSet::new();
    let mut configured_output_fields = BTreeSet::new();
    for field in &config.fields {
        if field.setting_id.trim().is_empty()
            || field.input_field.trim().is_empty()
            || field.output_field.trim().is_empty()
            || !configured_setting_ids.insert(field.setting_id.as_str())
            || !configured_input_fields.insert(field.input_field.as_str())
            || !configured_output_fields.insert(field.output_field.as_str())
        {
            return Err(format!(
                "{CATEGORICAL_RESPONSE_RATE_ADAPTER} componentConfig has malformed or duplicate field bindings"
            ));
        }
    }
    let requested_setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.as_str())
        .collect::<BTreeSet<_>>();
    let selected_fields = config
        .fields
        .iter()
        .filter(|field| requested_setting_ids.contains(field.setting_id.as_str()))
        .collect::<Vec<_>>();
    if selected_fields.len() != requested_setting_ids.len() {
        return Err(format!(
            "{CATEGORICAL_RESPONSE_RATE_ADAPTER} has no configured field binding for every requested setting"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{CATEGORICAL_RESPONSE_RATE_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{CATEGORICAL_RESPONSE_RATE_ADAPTER} refuses duplicate column names"
        ));
    }
    let source_row = required_header(&headers, "source_row_id", CATEGORICAL_RESPONSE_RATE_ADAPTER)?;
    let selected_input_columns = selected_fields
        .iter()
        .map(|field| header_index(&headers, &field.input_field))
        .collect::<Vec<_>>();
    let mut labels_by_field = vec![Vec::<Option<String>>::new(); selected_fields.len()];
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{CATEGORICAL_RESPONSE_RATE_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        if record_value(&record, Some(source_row)).is_empty() {
            return Err(format!(
                "{CATEGORICAL_RESPONSE_RATE_ADAPTER} row {} has empty source_row_id",
                row_index + 1
            ));
        }
        for (labels, label_column) in labels_by_field.iter_mut().zip(&selected_input_columns) {
            labels.push(label_column.and_then(|index| {
                let value = record_value(&record, Some(index));
                (!value.is_empty() && value != "NA").then(|| value.to_owned())
            }));
        }
    }
    let mut rates = Vec::with_capacity(selected_fields.len());
    for ((field, label_column), labels) in selected_fields
        .iter()
        .zip(&selected_input_columns)
        .zip(&labels_by_field)
    {
        let borrowed = labels.iter().map(Option::as_deref).collect::<Vec<_>>();
        let rate = match label_column {
            Some(_) => categorical_response_rate(CategoricalResponseRateInput::Present(&borrowed)),
            None => categorical_response_rate(CategoricalResponseRateInput::MissingColumn {
                row_count: labels.len(),
            }),
        }
        .map_err(|_| {
            format!(
                "{CATEGORICAL_RESPONSE_RATE_ADAPTER} nonempty input is missing the label column {}",
                field.input_field
            )
        })?;
        rates.push(rate);
    }
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(
            selected_fields
                .iter()
                .map(|field| field.output_field.as_str()),
        )
        .map_err(|error| format!("{CATEGORICAL_RESPONSE_RATE_ADAPTER} write header: {error}"))?;
    writer
        .write_record(rates.into_iter().map(|rate| format_r_numeric(Some(rate))))
        .map_err(|error| format!("{CATEGORICAL_RESPONSE_RATE_ADAPTER} write row: {error}"))?;
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{CATEGORICAL_RESPONSE_RATE_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        CATEGORICAL_RESPONSE_RATE_ADAPTER,
        "literature-categorical-response-rate-csv",
        original_input_digest,
        bindings,
        labels_by_field.first().map_or(0, Vec::len),
        1,
        csv_bytes,
    )
}

fn adapt_duration_span_window_projection(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} has no registered component")
        })?;
    let config: DurationSpanWindowProjectionComponentConfig =
        serde_json::from_value(group.component_config.clone().ok_or_else(|| {
            format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} requires componentConfig")
        })?)
        .map_err(|error| {
            format!("invalid {DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} componentConfig: {error}")
        })?;
    if config.numeric_semantics != "released_python3.7_numpy1.16.2_pandas1.0.5"
        || config.window_scope != "one_exact_window_per_invocation"
        || config.retention_predicate != "positive_overlap_or_start_inside_inclusive_window"
        || config.malformed_value_policy != "preserve_released_span_behavior"
    {
        return Err(format!(
            "{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} componentConfig drifts from released source"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} header: {error}"))?
        .clone();
    let source_row = required_header(
        &headers,
        "source_row_id",
        DURATION_SPAN_WINDOW_PROJECTION_ADAPTER,
    )?;
    let start = required_header(&headers, "start", DURATION_SPAN_WINDOW_PROJECTION_ADAPTER)?;
    let duration = required_header(
        &headers,
        "duration",
        DURATION_SPAN_WINDOW_PROJECTION_ADAPTER,
    )?;
    let window_start = required_header(
        &headers,
        "window_start",
        DURATION_SPAN_WINDOW_PROJECTION_ADAPTER,
    )?;
    let window_end = required_header(
        &headers,
        "window_end",
        DURATION_SPAN_WINDOW_PROJECTION_ADAPTER,
    )?;
    let required_number = |value: &str, field: &str, row: usize| -> Result<f64, String> {
        parse_r_numeric_cell(value, field, row)?.ok_or_else(|| {
            format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} row {row} requires present {field}")
        })
    };
    let mut rows = Vec::new();
    let mut invocation_window: Option<(f64, f64)> = None;
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} row {row_number}: {error}")
        })?;
        let source_row_id = record_value(&record, Some(source_row)).to_owned();
        if source_row_id.is_empty() {
            return Err(format!(
                "{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} row {row_number} has empty source_row_id"
            ));
        }
        let candidate_window = (
            required_number(
                record_value(&record, Some(window_start)),
                "window_start",
                row_number,
            )?,
            required_number(
                record_value(&record, Some(window_end)),
                "window_end",
                row_number,
            )?,
        );
        if !candidate_window.0.is_finite() || !candidate_window.1.is_finite() {
            return Err(format!(
                "{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} requires finite invocation window boundaries"
            ));
        }
        if invocation_window.is_some_and(|expected| {
            expected.0 != candidate_window.0 || expected.1 != candidate_window.1
        }) {
            return Err(format!(
                "{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} requires one exact window per invocation"
            ));
        }
        invocation_window = Some(candidate_window);
        rows.push(DurationSpan {
            start: required_number(record_value(&record, Some(start)), "start", row_number)?,
            duration: required_number(
                record_value(&record, Some(duration)),
                "duration",
                row_number,
            )?,
            payload: source_row_id,
        });
    }
    let source_row_count = rows.len();
    let (window_start, window_end) = invocation_window.ok_or_else(|| {
        format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} requires at least one source row")
    })?;
    let projected = project_duration_spans_to_window(rows, window_start, window_end);
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record(["source_row_id", "start", "duration", "overlap"])
        .map_err(|error| {
            format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} write header: {error}")
        })?;
    for row in &projected {
        writer
            .write_record([
                row.payload.as_str(),
                format_r_numeric(Some(row.start)).as_str(),
                format_r_numeric(Some(row.duration)).as_str(),
                format_r_numeric(Some(row.overlap)).as_str(),
            ])
            .map_err(|error| {
                format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{DURATION_SPAN_WINDOW_PROJECTION_ADAPTER} finish output: {error}")
    })?;
    complete_standalone_component_adaptation(
        DURATION_SPAN_WINDOW_PROJECTION_ADAPTER,
        "literature-duration-span-window-projection-csv",
        original_input_digest,
        bindings,
        source_row_count,
        projected.len(),
        csv_bytes,
    )
}

fn adapt_grouped_column_summary(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} has no registered component"))?;
    let config: GroupedColumnSummaryComponentConfig = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} requires componentConfig"))?,
    )
    .map_err(|error| {
        format!("invalid {GROUPED_COLUMN_SUMMARY_ADAPTER} componentConfig: {error}")
    })?;
    if config.group_order != "first_seen"
        || config.missing_group_semantics != "retain_as_all_missing_summary_group"
        || config.missing_value_semantics != "columnwise_remove_NA_and_NaN"
        || config.statistics != ["mean", "sample_standard_deviation"]
        || config.oracle_runtime != "R_4.6.1_compatibility_not_study_attribution"
    {
        return Err(format!(
            "{GROUPED_COLUMN_SUMMARY_ADAPTER} componentConfig drifts from released source"
        ));
    }
    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{GROUPED_COLUMN_SUMMARY_ADAPTER} refuses duplicate column names"
        ));
    }
    let source_row = required_header(&headers, "source_row_id", GROUPED_COLUMN_SUMMARY_ADAPTER)?;
    let group_index = required_header(&headers, "group", GROUPED_COLUMN_SUMMARY_ADAPTER)?;
    let value_columns = headers
        .iter()
        .enumerate()
        .filter(|(index, _)| *index != source_row && *index != group_index)
        .map(|(index, name)| (index, name.to_owned()))
        .collect::<Vec<_>>();
    if value_columns.is_empty() {
        return Err(format!(
            "{GROUPED_COLUMN_SUMMARY_ADAPTER} requires at least one numeric value column"
        ));
    }
    let mut rows = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let row_number = row_index + 1;
        let record = record.map_err(|error| {
            format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} row {row_number}: {error}")
        })?;
        if record_value(&record, Some(source_row)).is_empty() {
            return Err(format!(
                "{GROUPED_COLUMN_SUMMARY_ADAPTER} row {row_number} has empty source_row_id"
            ));
        }
        let group = record_value(&record, Some(group_index));
        rows.push(GroupedNumericRow {
            group: (!group.is_empty() && group != "NA").then(|| group.to_owned()),
            values: value_columns
                .iter()
                .map(|(index, name)| {
                    parse_r_numeric_cell(record_value(&record, Some(*index)), name, row_number)
                })
                .collect::<Result<Vec<_>, _>>()?,
        });
    }
    let source_row_count = rows.len();
    let summaries = summarize_columns_by_first_seen_group(&rows).map_err(|error| {
        format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} source boundary error: {error:?}")
    })?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    let mut output_headers = vec!["group".to_owned()];
    for (_, name) in &value_columns {
        output_headers.push(format!("{name}_mean"));
        output_headers.push(format!("{name}_sample_sd"));
    }
    writer
        .write_record(output_headers)
        .map_err(|error| format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} write header: {error}"))?;
    for summary in &summaries {
        let mut output = vec![summary.group.clone().unwrap_or_else(|| "NA".to_owned())];
        for (mean, sample_sd) in summary
            .means
            .iter()
            .zip(&summary.sample_standard_deviations)
        {
            output.push(format_r_numeric(Some(*mean)));
            output.push(format_r_numeric(*sample_sd));
        }
        writer
            .write_record(output)
            .map_err(|error| format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} write row: {error}"))?;
    }
    let csv_bytes = writer
        .into_inner()
        .map_err(|error| format!("{GROUPED_COLUMN_SUMMARY_ADAPTER} finish output: {error}"))?;
    complete_standalone_component_adaptation(
        GROUPED_COLUMN_SUMMARY_ADAPTER,
        "literature-grouped-column-summary-csv",
        original_input_digest,
        bindings,
        source_row_count,
        summaries.len(),
        csv_bytes,
    )
}

fn adapt_questionnaire_screen_session_summary(
    adapter_id: &str,
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| format!("{adapter_id} has no registered component configuration"))?;
    let raw_config = group
        .component_config
        .as_ref()
        .ok_or_else(|| format!("{adapter_id} has no registered bounded session configuration"))?;
    let configuration: QuestionnaireScreenSessionComponentConfiguration =
        serde_json::from_value(raw_config.clone())
            .map_err(|error| format!("{adapter_id} has malformed configuration: {error}"))?;
    let registration = group
        .component_execution
        .as_ref()
        .ok_or_else(|| format!("{adapter_id} has no component execution registration"))?;
    if registration.limitations.is_empty() {
        return Err(format!(
            "{adapter_id} requires receipt-visible source limitations"
        ));
    }

    let output = execute_questionnaire_screen_session_component_csv(raw_csv, &configuration)
        .map_err(|error| format!("{adapter_id}: {error}"))?;
    let source_row_count = u32::try_from(output.input_row_count)
        .map_err(|_| format!("{adapter_id} source row count overflow"))?;
    let output_row_count = u32::try_from(output.output_row_count)
        .map_err(|_| format!("{adapter_id} output row count overflow"))?;
    let materialized_session_count = u32::try_from(output.materialized_session_count)
        .map_err(|_| format!("{adapter_id} materialized session count overflow"))?;
    let mut setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.clone())
        .collect::<Vec<_>>();
    setting_ids.sort();
    let csv_bytes = output.derived_csv;
    let receipt = LiteratureInputAdaptationReceipt {
        protocol_version: "chronicle-literature-input-adaptation-receipt/v1",
        setting_ids,
        adapter_ids: vec![registration.component_id.clone()],
        original_input_digest: original_input_digest.to_owned(),
        adapted_input_digest: sha256(&csv_bytes),
        source_row_count,
        emitted_row_count: output_row_count,
        mapped_event_row_count: 0,
        materialized_interval_count: materialized_session_count,
        duplicate_source_ids_removed: 0,
        corrected_timestamp_provenance_rows: 0,
        participants_removed: 0,
        derived_result: Some(LiteratureDerivedResultReceipt {
            kind: "literature-questionnaire-screen-session-summary-csv",
            digest: sha256(&csv_bytes),
            row_count: output_row_count,
        }),
        source_oracle_id: Some(registration.source_oracle_id.clone()),
        component_configuration: None,
        keyguard_fsm: None,
        schoedel_screen_preprocessing: None,
    };
    Ok(AdaptedLiteratureInput {
        csv_bytes: csv_bytes.clone(),
        receipt,
        derived_result_bytes: Some(csv_bytes),
    })
}

fn adapt_daily_screen_session_participant_summary(
    sensing_csv: &[u8],
    questionnaire_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!(
                "{DAILY_SCREEN_SESSION_PARTICIPANT_SUMMARY_ADAPTER} has no registered component"
            )
        })?;
    let configuration: DailyScreenSessionParticipantSummaryConfiguration = serde_json::from_value(
        group
            .component_config
            .clone()
            .ok_or_else(|| {
                format!(
                    "{DAILY_SCREEN_SESSION_PARTICIPANT_SUMMARY_ADAPTER} requires registered componentConfig"
                )
            })?,
    )
    .map_err(|error| {
        format!(
            "invalid {DAILY_SCREEN_SESSION_PARTICIPANT_SUMMARY_ADAPTER} componentConfig: {error}"
        )
    })?;
    let output = execute_daily_screen_session_participant_summary_csv(
        sensing_csv,
        questionnaire_csv,
        &configuration,
    )
    .map_err(|error| format!("{DAILY_SCREEN_SESSION_PARTICIPANT_SUMMARY_ADAPTER}: {error}"))?;
    let interval_count = output
        .usage_session_count
        .checked_add(output.nonusage_session_count)
        .and_then(|count| u32::try_from(count).ok())
        .ok_or_else(|| {
            format!("{DAILY_SCREEN_SESSION_PARTICIPANT_SUMMARY_ADAPTER} interval count overflow")
        })?;
    let mut adapted = complete_standalone_component_adaptation(
        DAILY_SCREEN_SESSION_PARTICIPANT_SUMMARY_ADAPTER,
        "literature-daily-screen-session-participant-summary-csv",
        original_input_digest,
        bindings,
        output.sensing_row_count,
        output.output_row_count,
        output.derived_csv,
    )?;
    adapted.receipt.materialized_interval_count = interval_count;
    Ok(adapted)
}

fn fixed_grid_cadence(configured_seconds: f64) -> Result<(Duration, i64), String> {
    if !configured_seconds.is_finite() || configured_seconds <= 0.0 {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires a finite positive sampling cadence"
        ));
    }
    let nanoseconds = configured_seconds * 1_000_000_000.0;
    if !nanoseconds.is_finite() || nanoseconds.fract() != 0.0 || nanoseconds > i64::MAX as f64 {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} cadence must resolve to whole nanoseconds"
        ));
    }
    let nanoseconds = nanoseconds as i64;
    Ok((Duration::from_nanos(nanoseconds as u64), nanoseconds))
}

fn adapt_fixed_minute_packet_aggregation(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!(
                "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} has no registered component configuration"
            )
        })?;
    let config = group.component_config.as_ref().ok_or_else(|| {
        format!(
            "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} requires an explicit bounded-fixture bin anchor"
        )
    })?;
    let config: FixedMinutePacketAggregationComponentConfig =
        serde_json::from_value(config.clone()).map_err(|error| {
            format!(
                "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} has malformed component configuration: {error}"
            )
        })?;
    if config.bin_anchor.kind != "bounded_fixture_explicit_timestamp_ns" {
        return Err(format!(
            "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} refuses a bin anchor not explicitly limited to the bounded fixture"
        ));
    }
    let registration = group.component_execution.as_ref().ok_or_else(|| {
        format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} has no component execution registration")
    })?;
    if registration.limitations.is_empty() {
        return Err(format!(
            "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} requires a receipt-visible source limitation"
        ));
    }

    let mut reader = csv::ReaderBuilder::new()
        .flexible(false)
        .from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} refuses duplicate column names"
        ));
    }
    let phone_key = required_header(
        &headers,
        "phone_key",
        FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER,
    )?;
    let phone_address = required_header(
        &headers,
        "phone_address",
        FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER,
    )?;
    let timestamp_ns = required_header(
        &headers,
        "timestamp_ns",
        FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER,
    )?;
    let source_address = required_header(
        &headers,
        "source_address",
        FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER,
    )?;
    let destination_address = required_header(
        &headers,
        "destination_address",
        FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER,
    )?;
    let payload_bytes = required_header(
        &headers,
        "payload_bytes",
        FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER,
    )?;

    let mut packets = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let phone_key_value = record_value(&record, Some(phone_key));
        let phone_address_value = record_value(&record, Some(phone_address));
        let source_address_value = record_value(&record, Some(source_address));
        let destination_address_value = record_value(&record, Some(destination_address));
        if [
            phone_key_value,
            phone_address_value,
            source_address_value,
            destination_address_value,
        ]
        .iter()
        .any(|value| value.trim().is_empty())
        {
            return Err(format!(
                "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} requires non-empty phone/address fields at row {}",
                row_index + 1
            ));
        }
        let timestamp_ns_value = record_value(&record, Some(timestamp_ns))
            .parse::<i64>()
            .map_err(|_| {
                format!(
                    "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} requires integer timestamp_ns at row {}",
                    row_index + 1
                )
            })?;
        let payload_bytes_value = record_value(&record, Some(payload_bytes))
            .parse::<u64>()
            .map_err(|_| {
                format!(
                    "{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} requires unsigned integer payload_bytes at row {}",
                    row_index + 1
                )
            })?;
        packets.push(BidirectionalPacketObservation {
            phone_key: phone_key_value.to_owned(),
            phone_address: phone_address_value.to_owned(),
            timestamp_ns: timestamp_ns_value,
            source_address: source_address_value.to_owned(),
            destination_address: destination_address_value.to_owned(),
            payload_bytes: payload_bytes_value,
        });
    }

    let aggregates = aggregate_bidirectional_packets_by_fixed_minute(
        &packets,
        FixedMinuteBinAnchor::ExplicitTimestampNs(config.bin_anchor.timestamp_ns),
    )
    .map_err(|error| format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER}: {error}"))?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "phone_key",
            "external_address",
            "bin_start_timestamp_ns",
            "payload_bytes",
        ])
        .map_err(|error| {
            format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} write header: {error}")
        })?;
    for aggregate in &aggregates {
        writer
            .write_record([
                aggregate.phone_key.as_str(),
                aggregate.external_address.as_str(),
                &aggregate.bin_start_timestamp_ns.to_string(),
                &aggregate.payload_bytes.to_string(),
            ])
            .map_err(|error| {
                format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} write row: {error}")
            })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} finish output CSV: {error}")
    })?;
    let source_row_count = u32::try_from(packets.len()).map_err(|_| {
        format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} source row count overflow")
    })?;
    let output_row_count = u32::try_from(aggregates.len()).map_err(|_| {
        format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER} output row count overflow")
    })?;
    let mut setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.clone())
        .collect::<Vec<_>>();
    setting_ids.sort();
    let receipt = LiteratureInputAdaptationReceipt {
        protocol_version: "chronicle-literature-input-adaptation-receipt/v1",
        setting_ids,
        adapter_ids: vec![format!("{FIXED_MINUTE_PACKET_AGGREGATION_ADAPTER}/v1")],
        original_input_digest: original_input_digest.to_owned(),
        adapted_input_digest: sha256(&csv_bytes),
        source_row_count,
        emitted_row_count: output_row_count,
        mapped_event_row_count: 0,
        materialized_interval_count: 0,
        duplicate_source_ids_removed: 0,
        corrected_timestamp_provenance_rows: 0,
        participants_removed: 0,
        derived_result: Some(LiteratureDerivedResultReceipt {
            kind: "literature-fixed-minute-packet-aggregation-csv",
            digest: sha256(&csv_bytes),
            row_count: output_row_count,
        }),
        source_oracle_id: Some(registration.source_oracle_id.clone()),
        component_configuration: None,
        keyguard_fsm: None,
        schoedel_screen_preprocessing: None,
    };
    Ok(AdaptedLiteratureInput {
        csv_bytes: csv_bytes.clone(),
        receipt,
        derived_result_bytes: Some(csv_bytes),
    })
}

fn adapt_fixed_grid_categorical_dwell(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} has no registered component configuration"
            )
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} has no registered fixed-grid configuration")
    })?;
    let config: FixedGridCategoricalDwellComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} has malformed configuration: {error}")
        })?;
    let registration = group.component_execution.as_ref().ok_or_else(|| {
        format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} has no component execution registration")
    })?;
    if registration.limitations.is_empty() {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires receipt-visible source limitations"
        ));
    }
    if config.progression != "non_overlapping"
        || config.grid_anchoring != "explicit_input_only"
        || config.incomplete_window_policy != "reject"
    {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} only executes explicit-anchor complete non-overlapping grids"
        ));
    }
    let (sampling_cadence, cadence_ns) = fixed_grid_cadence(config.sampling_cadence_seconds)?;
    let configured_windows = config
        .window_durations_minutes
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    if configured_windows.is_empty()
        || configured_windows.len() != config.window_durations_minutes.len()
        || configured_windows.contains(&0)
    {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires unique positive window durations"
        ));
    }
    let mut features = BTreeMap::new();
    for feature in config.threshold_features {
        if feature.feature_id.trim().is_empty()
            || feature.scalar_input_stage != "precomputed_scalar"
            || feature.source_scalar_unit.trim().is_empty()
            || features.contains_key(&feature.feature_id)
        {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires unique precomputed scalar feature registrations"
            ));
        }
        let bucketizer =
            OrderedThresholdBucketizer::new(feature.thresholds.clone(), feature.categories.clone())
                .map_err(|error| {
                    format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} invalid threshold feature {}: {error}",
                feature.feature_id
            )
                })?;
        if feature
            .categories
            .iter()
            .any(|category| category.trim().is_empty())
            || feature.categories.iter().collect::<BTreeSet<_>>().len() != feature.categories.len()
        {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires unique non-empty categories for {}",
                feature.feature_id
            ));
        }
        features.insert(feature.feature_id.clone(), (feature, bucketizer));
    }
    if features.is_empty() {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires at least one threshold feature"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} refuses duplicate column names"
        ));
    }
    let feature_id = required_header(&headers, "feature_id", FIXED_GRID_CATEGORICAL_DWELL_ADAPTER)?;
    let window_minutes = required_header(
        &headers,
        "window_minutes",
        FIXED_GRID_CATEGORICAL_DWELL_ADAPTER,
    )?;
    let anchor = required_header(
        &headers,
        "grid_anchor_timestamp_ns",
        FIXED_GRID_CATEGORICAL_DWELL_ADAPTER,
    )?;
    let run_start = required_header(
        &headers,
        "run_start_sample_index",
        FIXED_GRID_CATEGORICAL_DWELL_ADAPTER,
    )?;
    let run_length = required_header(
        &headers,
        "run_length_samples",
        FIXED_GRID_CATEGORICAL_DWELL_ADAPTER,
    )?;
    let scalar_value = required_header(
        &headers,
        "scalar_value",
        FIXED_GRID_CATEGORICAL_DWELL_ADAPTER,
    )?;

    let mut source_row_count = 0u32;
    let mut groups: BTreeMap<(String, u32), (i64, Vec<FixedGridCompressedRun>)> = BTreeMap::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count = source_row_count.checked_add(1).ok_or_else(|| {
            format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} source row count overflow")
        })?;
        let parsed_feature_id = record_value(&record, Some(feature_id)).to_owned();
        if !features.contains_key(&parsed_feature_id) {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} row {} has unregistered feature {}",
                row_index + 1,
                parsed_feature_id
            ));
        }
        let invalid = |field: &str| {
            format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} row {} requires valid {field}",
                row_index + 1
            )
        };
        let parsed_window = record_value(&record, Some(window_minutes))
            .parse::<u32>()
            .map_err(|_| invalid("window_minutes"))?;
        if !configured_windows.contains(&parsed_window) {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} row {} has unregistered window duration {}",
                row_index + 1,
                parsed_window
            ));
        }
        let parsed_anchor = record_value(&record, Some(anchor))
            .parse::<i64>()
            .map_err(|_| invalid("grid_anchor_timestamp_ns"))?;
        let parsed_start = record_value(&record, Some(run_start))
            .parse::<usize>()
            .map_err(|_| invalid("run_start_sample_index"))?;
        let parsed_length = record_value(&record, Some(run_length))
            .parse::<usize>()
            .map_err(|_| invalid("run_length_samples"))?;
        if parsed_length == 0 {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} row {} has a zero-length run",
                row_index + 1
            ));
        }
        let parsed_value = record_value(&record, Some(scalar_value))
            .parse::<f64>()
            .map_err(|_| invalid("scalar_value"))?;
        let entry = groups
            .entry((parsed_feature_id, parsed_window))
            .or_insert_with(|| (parsed_anchor, Vec::new()));
        if entry.0 != parsed_anchor {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} refuses multiple anchors for one feature/window fixture"
            ));
        }
        entry.1.push(FixedGridCompressedRun {
            start_sample_index: parsed_start,
            run_length_samples: parsed_length,
            scalar_value: parsed_value,
        });
    }
    let expected_group_count = features
        .len()
        .checked_mul(configured_windows.len())
        .ok_or_else(|| format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} group count overflow"))?;
    if groups.len() != expected_group_count {
        return Err(format!(
            "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} requires one complete fixture for every configured feature/window pair; expected {expected_group_count}, got {}",
            groups.len()
        ));
    }

    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "feature_id",
            "source_scalar_unit",
            "window_minutes",
            "window_index",
            "window_start_timestamp_ns",
            "window_end_timestamp_ns",
            "category",
            "category_dwell_nanoseconds",
        ])
        .map_err(|error| format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} write header: {error}"))?;
    let mut output_row_count = 0u32;
    let mut materialized_window_count = 0u32;
    for ((feature_id, window_minutes), (anchor_ns, mut runs)) in groups {
        let (feature, bucketizer) = features
            .get(&feature_id)
            .expect("fixture feature was validated against configuration");
        let window_seconds = u64::from(window_minutes).checked_mul(60).ok_or_else(|| {
            format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} window duration overflow")
        })?;
        let window_duration = Duration::from_secs(window_seconds);
        let window_ns = i64::try_from(window_duration.as_nanos()).map_err(|_| {
            format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} window exceeds timestamp range")
        })?;
        if window_ns % cadence_ns != 0 {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} window is not a whole number of sampling cadences"
            ));
        }
        let samples_per_window = usize::try_from(window_ns / cadence_ns).map_err(|_| {
            format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} sample count exceeds platform range")
        })?;
        runs.sort_by_key(|run| run.start_sample_index);
        let mut next_sample_index = 0usize;
        let mut observations = Vec::with_capacity(samples_per_window);
        for run in runs {
            if run.start_sample_index != next_sample_index {
                return Err(format!(
                    "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} refuses a gap or overlap before sample {} for {feature_id}/{window_minutes}",
                    run.start_sample_index
                ));
            }
            let run_end = run
                .start_sample_index
                .checked_add(run.run_length_samples)
                .ok_or_else(|| {
                    format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} run length overflow")
                })?;
            if run_end > samples_per_window {
                return Err(format!(
                    "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} refuses a run beyond the complete fixture window"
                ));
            }
            for sample_index in run.start_sample_index..run_end {
                let offset_ns = i64::try_from(sample_index)
                    .ok()
                    .and_then(|index| index.checked_mul(cadence_ns))
                    .ok_or_else(|| {
                        format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} timestamp offset overflow")
                    })?;
                observations.push(FixedGridScalarObservation {
                    timestamp_ns: anchor_ns.checked_add(offset_ns).ok_or_else(|| {
                        format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} timestamp overflow")
                    })?,
                    value: run.scalar_value,
                });
            }
            next_sample_index = run_end;
        }
        if next_sample_index != samples_per_window {
            return Err(format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} refuses incomplete {feature_id}/{window_minutes} fixture: expected {samples_per_window} samples, got {next_sample_index}"
            ));
        }
        let windows = materialize_complete_fixed_grid_category_dwell(
            &observations,
            bucketizer,
            FixedGridDwellConfiguration {
                sampling_cadence,
                window_duration,
                progression: FixedGridWindowProgression::NonOverlapping,
                anchor: FixedGridAnchor::ExplicitTimestampNs(anchor_ns),
                incomplete_window_policy: IncompleteWindowPolicy::Reject,
            },
        )
        .map_err(|error| {
            format!(
                "{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} cannot materialize {feature_id}/{window_minutes}: {error}"
            )
        })?;
        for window in windows {
            materialized_window_count =
                materialized_window_count.checked_add(1).ok_or_else(|| {
                    format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} window count overflow")
                })?;
            for category in &feature.categories {
                let row = [
                    feature_id.clone(),
                    feature.source_scalar_unit.clone(),
                    window_minutes.to_string(),
                    window.window_index.to_string(),
                    window.start_timestamp_ns.to_string(),
                    window.end_timestamp_ns.to_string(),
                    category.clone(),
                    window
                        .category_dwell_ns
                        .get(category)
                        .copied()
                        .unwrap_or_default()
                        .to_string(),
                ];
                writer.write_record(&row).map_err(|error| {
                    format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} write output row: {error}")
                })?;
                output_row_count = output_row_count.checked_add(1).ok_or_else(|| {
                    format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} output row count overflow")
                })?;
            }
        }
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER} finish output CSV: {error}")
    })?;
    let mut setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.clone())
        .collect::<Vec<_>>();
    setting_ids.sort();
    let receipt = LiteratureInputAdaptationReceipt {
        protocol_version: "chronicle-literature-input-adaptation-receipt/v1",
        setting_ids,
        adapter_ids: vec![format!("{FIXED_GRID_CATEGORICAL_DWELL_ADAPTER}/v1")],
        original_input_digest: original_input_digest.to_owned(),
        adapted_input_digest: sha256(&csv_bytes),
        source_row_count,
        emitted_row_count: output_row_count,
        mapped_event_row_count: 0,
        materialized_interval_count: materialized_window_count,
        duplicate_source_ids_removed: 0,
        corrected_timestamp_provenance_rows: 0,
        participants_removed: 0,
        derived_result: Some(LiteratureDerivedResultReceipt {
            kind: "literature-fixed-grid-categorical-dwell-csv",
            digest: sha256(&csv_bytes),
            row_count: output_row_count,
        }),
        source_oracle_id: Some(registration.source_oracle_id.clone()),
        component_configuration: None,
        keyguard_fsm: None,
        schoedel_screen_preprocessing: None,
    };
    Ok(AdaptedLiteratureInput {
        csv_bytes: csv_bytes.clone(),
        receipt,
        derived_result_bytes: Some(csv_bytes),
    })
}

fn adapt_screen_bout_daily_summary(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} has no registered component configuration")
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!(
            "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} has no registered bounded summary configuration"
        )
    })?;
    let config: ScreenBoutDailySummaryComponentConfig = serde_json::from_value(raw_config.clone())
        .map_err(|error| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} has malformed configuration: {error}")
        })?;
    let registration = group.component_execution.as_ref().ok_or_else(|| {
        format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} has no component execution registration")
    })?;
    if registration.limitations.is_empty() {
        return Err(format!(
            "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} requires receipt-visible source limitations"
        ));
    }
    if config.input_stage != "paired_screen_bouts_with_explicit_observed_day_inventory"
        || config.day_assignment != "explicit_source_day_id_only"
        || config.maximum_bout_comparator != "strict_greater_than"
        || config.maximum_bout_disposition != "exclude_participant"
        || config.minimum_day_comparator != "strict_less_than"
        || config.participant_mean_denominator != "explicit_observed_day_inventory"
    {
        return Err(format!(
            "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} only executes paired bouts with an explicit observed-day denominator and the registered strict participant exclusions"
        ));
    }
    let maximum_inclusive_bout_duration_ns = config
        .maximum_bout_duration_hours
        .checked_mul(3_600_000_000_000)
        .ok_or_else(|| {
            format!(
                "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} maximum bout duration overflows nanoseconds"
            )
        })?;

    let mut reader = csv::ReaderBuilder::new()
        .flexible(false)
        .from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} refuses duplicate column names"
        ));
    }
    let record_type = required_header(&headers, "record_type", SCREEN_BOUT_DAILY_SUMMARY_ADAPTER)?;
    let participant_id = required_header(
        &headers,
        "participant_id",
        SCREEN_BOUT_DAILY_SUMMARY_ADAPTER,
    )?;
    let source_day_id =
        required_header(&headers, "source_day_id", SCREEN_BOUT_DAILY_SUMMARY_ADAPTER)?;
    let bout_id = required_header(&headers, "bout_id", SCREEN_BOUT_DAILY_SUMMARY_ADAPTER)?;
    let screen_on_timestamp_ns = required_header(
        &headers,
        "screen_on_timestamp_ns",
        SCREEN_BOUT_DAILY_SUMMARY_ADAPTER,
    )?;
    let screen_off_timestamp_ns = required_header(
        &headers,
        "screen_off_timestamp_ns",
        SCREEN_BOUT_DAILY_SUMMARY_ADAPTER,
    )?;

    let mut observed_days = Vec::new();
    let mut bouts = Vec::new();
    let mut source_row_count = 0u32;
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count = source_row_count.checked_add(1).ok_or_else(|| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} source row count overflow")
        })?;
        let participant = record_value(&record, Some(participant_id));
        let day = record_value(&record, Some(source_day_id));
        if participant.trim().is_empty() || day.trim().is_empty() {
            return Err(format!(
                "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {} requires non-empty participant_id and source_day_id",
                row_index + 1
            ));
        }
        let bout = record_value(&record, Some(bout_id));
        let screen_on = record_value(&record, Some(screen_on_timestamp_ns));
        let screen_off = record_value(&record, Some(screen_off_timestamp_ns));
        match record_value(&record, Some(record_type)) {
            "observed_day" => {
                if !bout.is_empty() || !screen_on.is_empty() || !screen_off.is_empty() {
                    return Err(format!(
                        "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {} observed_day must not carry bout fields",
                        row_index + 1
                    ));
                }
                observed_days.push(ObservedScreenDay {
                    participant_id: participant.to_owned(),
                    source_day_id: day.to_owned(),
                });
            }
            "screen_bout" => {
                if bout.trim().is_empty() {
                    return Err(format!(
                        "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {} screen_bout requires a bout_id",
                        row_index + 1
                    ));
                }
                let screen_on_timestamp_ns = screen_on.parse::<i64>().map_err(|_| {
                    format!(
                        "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {} requires an integer screen_on_timestamp_ns",
                        row_index + 1
                    )
                })?;
                let screen_off_timestamp_ns = screen_off.parse::<i64>().map_err(|_| {
                    format!(
                        "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {} requires an integer screen_off_timestamp_ns",
                        row_index + 1
                    )
                })?;
                bouts.push(PairedScreenBout {
                    bout_id: bout.to_owned(),
                    participant_id: participant.to_owned(),
                    source_day_id: day.to_owned(),
                    screen_on_timestamp_ns,
                    screen_off_timestamp_ns,
                });
            }
            other => {
                return Err(format!(
                    "{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} row {} has unsupported record_type {other}",
                    row_index + 1
                ));
            }
        }
    }
    let materialized_interval_count = u32::try_from(bouts.len()).map_err(|_| {
        format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} bout count exceeds receipt range")
    })?;
    let summary = summarize_screen_bouts_by_explicit_day(
        &observed_days,
        &bouts,
        ScreenBoutDailySummaryConfiguration {
            maximum_inclusive_bout_duration_ns,
            minimum_inclusive_observed_day_count: config.minimum_observed_days,
        },
    )
    .map_err(|error| format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} cannot summarize: {error}"))?;
    let participants_removed = u32::try_from(summary.excluded_participants.len()).map_err(|_| {
        format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} excluded participant count exceeds receipt range")
    })?;

    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "record_kind",
            "participant_id",
            "source_day_id",
            "duration_ns",
            "observed_day_count",
            "total_duration_ns",
            "mean_daily_duration_ns",
            "exclusion_reasons",
            "maximum_bout_duration_ns",
        ])
        .map_err(|error| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} write output header: {error}")
        })?;
    let mut output_row_count = 0u32;
    for day in summary.retained_daily_durations {
        writer
            .write_record([
                "daily".to_owned(),
                day.participant_id,
                day.source_day_id,
                day.duration_ns.to_string(),
                String::new(),
                String::new(),
                String::new(),
                String::new(),
                String::new(),
            ])
            .map_err(|error| {
                format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} write daily row: {error}")
            })?;
        output_row_count = output_row_count.checked_add(1).ok_or_else(|| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} output row count overflow")
        })?;
    }
    for participant in summary.retained_participant_means {
        writer
            .write_record([
                "participant_mean".to_owned(),
                participant.participant_id,
                String::new(),
                String::new(),
                participant.observed_day_count.to_string(),
                participant.total_duration_ns.to_string(),
                participant.mean_daily_duration_ns.to_string(),
                String::new(),
                String::new(),
            ])
            .map_err(|error| {
                format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} write participant mean: {error}")
            })?;
        output_row_count = output_row_count.checked_add(1).ok_or_else(|| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} output row count overflow")
        })?;
    }
    for participant in summary.excluded_participants {
        let reasons = participant
            .reasons
            .iter()
            .map(|reason| match reason {
                ScreenBoutParticipantExclusionReason::BoutExceedsMaximum => "bout_exceeds_maximum",
                ScreenBoutParticipantExclusionReason::FewerThanMinimumObservedDays => {
                    "fewer_than_minimum_observed_days"
                }
            })
            .collect::<Vec<_>>()
            .join("|");
        writer
            .write_record([
                "excluded_participant".to_owned(),
                participant.participant_id,
                String::new(),
                String::new(),
                participant.observed_day_count.to_string(),
                String::new(),
                String::new(),
                reasons,
                participant
                    .maximum_bout_duration_ns
                    .map(|duration| duration.to_string())
                    .unwrap_or_default(),
            ])
            .map_err(|error| {
                format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} write exclusion row: {error}")
            })?;
        output_row_count = output_row_count.checked_add(1).ok_or_else(|| {
            format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} output row count overflow")
        })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER} finish output CSV: {error}")
    })?;
    let mut setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.clone())
        .collect::<Vec<_>>();
    setting_ids.sort();
    let receipt = LiteratureInputAdaptationReceipt {
        protocol_version: "chronicle-literature-input-adaptation-receipt/v1",
        setting_ids,
        adapter_ids: vec![format!("{SCREEN_BOUT_DAILY_SUMMARY_ADAPTER}/v1")],
        original_input_digest: original_input_digest.to_owned(),
        adapted_input_digest: sha256(&csv_bytes),
        source_row_count,
        emitted_row_count: output_row_count,
        mapped_event_row_count: 0,
        materialized_interval_count,
        duplicate_source_ids_removed: 0,
        corrected_timestamp_provenance_rows: 0,
        participants_removed,
        derived_result: Some(LiteratureDerivedResultReceipt {
            kind: "literature-screen-bout-daily-summary-csv",
            digest: sha256(&csv_bytes),
            row_count: output_row_count,
        }),
        source_oracle_id: Some(registration.source_oracle_id.clone()),
        component_configuration: None,
        keyguard_fsm: None,
        schoedel_screen_preprocessing: None,
    };
    Ok(AdaptedLiteratureInput {
        csv_bytes: csv_bytes.clone(),
        receipt,
        derived_result_bytes: Some(csv_bytes),
    })
}

fn adapt_anchor_relative_category_window(
    raw_csv: &[u8],
    anchor_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} has no registered component configuration"
            )
        })?;
    let raw_config = group.component_config.as_ref().ok_or_else(|| {
        format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} has no registered window configuration")
    })?;
    let config: AnchorRelativeCategoryWindowComponentConfig =
        serde_json::from_value(raw_config.clone()).map_err(|error| {
            format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} has malformed configuration: {error}"
            )
        })?;
    let registration = group.component_execution.as_ref().ok_or_else(|| {
        format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} has no component execution registration")
    })?;
    if registration.limitations.is_empty() {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} requires receipt-visible source limitations"
        ));
    }
    if config.duration_coercion != "truncate_toward_zero_integer_seconds"
        || config.occupied_hour_gap_thresholds_hours != [18, 12, 24]
        || config.interval_expansion != "one_second_half_open"
        || config.boundary_inclusion != "strict_open"
        || !config.skip_final_anchor
        || !config.retain_all_anchors
        || config.category_aggregation != "count_seconds_divide_60"
        || config.all_category_aggregation != "row_sum"
    {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} requires integer-second half-open expansion, strict-open windows, final-anchor skip with retained anchors, category-minute counts, and an all-category row sum"
        ));
    }
    let configured_directions = config.directions.iter().collect::<BTreeSet<_>>();
    if config.directions.len() != 2
        || configured_directions.len() != 2
        || !config.directions.iter().any(|value| value == "before")
        || !config.directions.iter().any(|value| value == "after")
    {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} requires one before and one after direction"
        ));
    }
    let configured_windows = config
        .window_durations_minutes
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    if configured_windows.len() != config.window_durations_minutes.len()
        || configured_windows.iter().any(|minutes| *minutes == 0)
    {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} requires unique positive window durations"
        ));
    }

    let mut raw_reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let raw_headers = raw_reader
        .headers()
        .map_err(|error| format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} header: {error}"))?
        .clone();
    if raw_headers.iter().collect::<BTreeSet<_>>().len() != raw_headers.len() {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} refuses duplicate raw column names"
        ));
    }
    let raw_participant = required_header(
        &raw_headers,
        "participant_id",
        ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER,
    )?;
    let recorded_naive = required_header(
        &raw_headers,
        "recorded_naive",
        ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER,
    )?;
    let duration = required_header(
        &raw_headers,
        "duration",
        ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER,
    )?;
    let category = required_header(
        &raw_headers,
        "category",
        ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER,
    )?;
    let mut intervals_by_participant = BTreeMap::<String, Vec<CategorizedDurationInterval>>::new();
    let mut source_row_count = 0u32;
    for (row_index, record) in raw_reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} raw row {}: {error}",
                row_index + 1
            )
        })?;
        source_row_count = source_row_count.checked_add(1).ok_or_else(|| {
            format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} source row count overflow")
        })?;
        let participant_id = record_value(&record, Some(raw_participant));
        let category = record_value(&record, Some(category));
        if participant_id.trim().is_empty() || category.trim().is_empty() {
            return Err(format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} raw row {} requires non-empty participant_id and post-taxonomy category",
                row_index + 1
            ));
        }
        let start_ns = parse_chronicle_timestamp_ns(record_value(
            &record,
            Some(recorded_naive),
        ))
        .ok_or_else(|| {
            format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} raw row {} requires a valid recorded_naive timestamp",
                row_index + 1
            )
        })?;
        let duration_seconds = record_value(&record, Some(duration))
            .parse::<f64>()
            .map_err(|_| {
                format!(
                    "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} raw row {} requires a numeric duration",
                    row_index + 1
                )
            })?;
        intervals_by_participant
            .entry(participant_id.to_owned())
            .or_default()
            .push(CategorizedDurationInterval {
                start_ns,
                duration_seconds,
                category: category.to_owned(),
            });
    }
    if intervals_by_participant.is_empty() {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} requires at least one post-clean interval"
        ));
    }

    let mut anchor_reader = csv::ReaderBuilder::new().from_reader(anchor_csv);
    let anchor_headers = anchor_reader
        .headers()
        .map_err(|error| {
            format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} anchor header: {error}")
        })?
        .clone();
    if anchor_headers.iter().collect::<BTreeSet<_>>().len() != anchor_headers.len() {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} refuses duplicate anchor column names"
        ));
    }
    let anchor_participant = required_header(
        &anchor_headers,
        "participant_id",
        ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER,
    )?;
    let anchor_timestamp = required_header(
        &anchor_headers,
        "anchor_timestamp",
        ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER,
    )?;
    let mut anchors_by_participant = BTreeMap::<String, Vec<i64>>::new();
    for (row_index, record) in anchor_reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} anchor row {}: {error}",
                row_index + 1
            )
        })?;
        let participant_id = record_value(&record, Some(anchor_participant));
        if participant_id.trim().is_empty() {
            return Err(format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} anchor row {} requires a non-empty participant_id",
                row_index + 1
            ));
        }
        let timestamp_ns = parse_chronicle_timestamp_ns(record_value(
            &record,
            Some(anchor_timestamp),
        ))
        .ok_or_else(|| {
            format!(
                "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} anchor row {} requires a valid anchor_timestamp",
                row_index + 1
            )
        })?;
        anchors_by_participant
            .entry(participant_id.to_owned())
            .or_default()
            .push(timestamp_ns);
    }
    if anchors_by_participant.keys().collect::<BTreeSet<_>>()
        != intervals_by_participant.keys().collect::<BTreeSet<_>>()
    {
        return Err(format!(
            "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} requires identical participant scopes in raw and anchor inputs"
        ));
    }

    let mut materialized = Vec::new();
    for (participant_id, intervals) in &intervals_by_participant {
        let anchors = anchors_by_participant
            .get(participant_id)
            .expect("participant scopes were checked above");
        for &threshold in &config.occupied_hour_gap_thresholds_hours {
            for configured_direction in &config.directions {
                let direction = match configured_direction.as_str() {
                    "before" => AnchorWindowDirection::Before,
                    "after" => AnchorWindowDirection::After,
                    _ => unreachable!("direction set was checked above"),
                };
                let rows = materialize_strict_open_anchor_category_minutes(
                    intervals,
                    anchors,
                    &config.window_durations_minutes,
                    direction,
                    config.skip_final_anchor,
                    Some(threshold),
                )
                .map_err(|error| {
                    format!(
                        "{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} cannot materialize participant {participant_id}: {error:?}"
                    )
                })?;
                materialized.extend(
                    rows.into_iter()
                        .map(|row| (participant_id.clone(), threshold, row)),
                );
            }
        }
    }

    let category_columns = materialized
        .iter()
        .flat_map(|(_, _, row)| row.category_minutes.keys().cloned())
        .collect::<BTreeSet<_>>();
    let mut header = vec![
        "participant_id".to_owned(),
        "anchor_index".to_owned(),
        "anchor_timestamp".to_owned(),
        "direction".to_owned(),
        "window_minutes".to_owned(),
        "missing_hour_threshold".to_owned(),
    ];
    header.extend(category_columns.iter().cloned());
    header.push("app_usage_min".to_owned());
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer.write_record(&header).map_err(|error| {
        format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} write header: {error}")
    })?;
    let mut output_row_count = 0u32;
    for (participant_id, threshold, output) in materialized {
        let mut row = vec![
            participant_id,
            output.anchor_index.to_string(),
            format_chronicle_timestamp_ns(output.anchor_time_ns).ok_or_else(|| {
                format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} output timestamp overflow")
            })?,
            match output.direction {
                AnchorWindowDirection::Before => "before".to_owned(),
                AnchorWindowDirection::After => "after".to_owned(),
            },
            output.window_minutes.to_string(),
            threshold.to_string(),
        ];
        row.extend(category_columns.iter().map(|category| {
            output
                .category_minutes
                .get(category)
                .map(f64::to_string)
                .unwrap_or_default()
        }));
        row.push(output.app_usage_min.to_string());
        writer.write_record(&row).map_err(|error| {
            format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} write output row: {error}")
        })?;
        output_row_count = output_row_count.checked_add(1).ok_or_else(|| {
            format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} output row count overflow")
        })?;
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER} finish output CSV: {error}")
    })?;
    let mut setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.clone())
        .collect::<Vec<_>>();
    setting_ids.sort();
    let receipt = LiteratureInputAdaptationReceipt {
        protocol_version: "chronicle-literature-input-adaptation-receipt/v1",
        setting_ids,
        adapter_ids: vec![format!("{ANCHOR_RELATIVE_CATEGORY_WINDOW_ADAPTER}/v1")],
        original_input_digest: original_input_digest.to_owned(),
        adapted_input_digest: sha256(&csv_bytes),
        source_row_count,
        emitted_row_count: output_row_count,
        mapped_event_row_count: 0,
        materialized_interval_count: output_row_count,
        duplicate_source_ids_removed: 0,
        corrected_timestamp_provenance_rows: 0,
        participants_removed: 0,
        derived_result: Some(LiteratureDerivedResultReceipt {
            kind: "literature-anchor-relative-category-window-csv",
            digest: sha256(&csv_bytes),
            row_count: output_row_count,
        }),
        source_oracle_id: Some(registration.source_oracle_id.clone()),
        component_configuration: None,
        keyguard_fsm: None,
        schoedel_screen_preprocessing: None,
    };
    Ok(AdaptedLiteratureInput {
        csv_bytes: csv_bytes.clone(),
        receipt,
        derived_result_bytes: Some(csv_bytes),
    })
}

fn adapt_participant_scoped_interval_union(
    raw_csv: &[u8],
    original_input_digest: &str,
    bindings: &[MethodProfileInputBindingReceipt],
) -> Result<AdaptedLiteratureInput, String> {
    let group = bindings
        .first()
        .and_then(|binding| contract_by_setting().ok()?.get(&binding.setting_id))
        .ok_or_else(|| {
            format!(
                "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} has no registered component configuration"
            )
        })?;
    let config = group.component_config.as_ref().ok_or_else(|| {
        format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} has no registered scope configuration")
    })?;
    let config: ParticipantScopedIntervalUnionComponentConfig =
        serde_json::from_value(config.clone()).map_err(|error| {
            format!(
                "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} has malformed scope configuration: {error}"
            )
        })?;
    let registration = group.component_execution.as_ref().ok_or_else(|| {
        format!(
            "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} has no component execution registration"
        )
    })?;
    let mut scope_ids = BTreeSet::new();
    let mut scopes = Vec::with_capacity(config.scopes.len());
    for scope in &config.scopes {
        if scope.scope_id.trim().is_empty() || !scope_ids.insert(scope.scope_id.as_str()) {
            return Err(format!(
                "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} requires unique non-empty scope IDs"
            ));
        }
        let selector = match scope.selector.as_str() {
            "all" if scope.values.is_empty() && scope.value.is_none() => ScopeSelector::All,
            "application_name_in" if !scope.values.is_empty() && scope.value.is_none() => {
                if scope.values.iter().any(|value| value.trim().is_empty()) {
                    return Err(format!(
                        "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} refuses empty application-name selectors"
                    ));
                }
                ScopeSelector::ApplicationNameIn(scope.values.clone())
            }
            "application_category_equals" if scope.values.is_empty() => {
                let value = scope
                    .value
                    .as_ref()
                    .filter(|value| !value.trim().is_empty())
                    .ok_or_else(|| {
                        format!(
                            "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} requires an application-category selector value"
                        )
                    })?;
                ScopeSelector::ApplicationCategoryEquals(value.clone())
            }
            _ => {
                return Err(format!(
                    "invalid interval-union scope selector: {}",
                    scope.selector
                ))
            }
        };
        scopes.push(IntervalUnionScope {
            scope_id: scope.scope_id.clone(),
            selector,
        });
    }
    if scopes.is_empty() {
        return Err(format!(
            "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} requires at least one registered scope"
        ));
    }

    let mut reader = csv::ReaderBuilder::new().from_reader(raw_csv);
    let headers = reader
        .headers()
        .map_err(|error| format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} header: {error}"))?
        .clone();
    if headers.iter().collect::<BTreeSet<_>>().len() != headers.len() {
        return Err(format!(
            "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} refuses duplicate column names"
        ));
    }
    let participant = required_header(
        &headers,
        "participant_id",
        PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER,
    )?;
    let application_name = required_header(
        &headers,
        "application_name",
        PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER,
    )?;
    let application_category = required_header(
        &headers,
        "application_category",
        PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER,
    )?;
    let start = required_header(
        &headers,
        "start_unix_seconds",
        PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER,
    )?;
    let end = required_header(
        &headers,
        "end_unix_seconds",
        PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER,
    )?;
    let duration = required_header(
        &headers,
        "derived_duration_seconds",
        PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER,
    )?;

    let mut rows = Vec::new();
    for (row_index, record) in reader.records().enumerate() {
        let record = record.map_err(|error| {
            format!(
                "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} row {}: {error}",
                row_index + 1
            )
        })?;
        let number = |index, field| {
            record_value(&record, Some(index))
                .parse::<f64>()
                .map_err(|_| {
                    format!(
                        "{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} requires numeric {field} at row {}",
                        row_index + 1
                    )
                })
        };
        let optional = |index| {
            let value = record_value(&record, Some(index));
            (!value.is_empty()).then(|| value.to_owned())
        };
        rows.push(ParticipantInterval {
            participant_id: record_value(&record, Some(participant)).to_owned(),
            application_name: optional(application_name),
            application_category: optional(application_category),
            start_unix_seconds: number(start, "start_unix_seconds")?,
            end_unix_seconds: number(end, "end_unix_seconds")?,
            derived_duration_seconds: number(duration, "derived_duration_seconds")?,
        });
    }

    let outputs = participant_scoped_interval_unions(&rows, &scopes)?;
    let mut writer = csv::WriterBuilder::new().from_writer(Vec::new());
    writer
        .write_record([
            "scope_id",
            "participant_id",
            "start_unix_seconds",
            "end_unix_seconds",
            "duration",
            "duration_unit",
        ])
        .map_err(|error| {
            format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} write header: {error}")
        })?;
    let mut output_row_count = 0u32;
    for output in outputs {
        for interval in output.intervals {
            writer
                .write_record([
                    output.scope_id.as_str(),
                    interval.participant_id.as_str(),
                    &interval.start_unix_seconds.to_string(),
                    &interval.end_unix_seconds.to_string(),
                    &interval.duration.to_string(),
                    output.duration_unit.source_label(),
                ])
                .map_err(|error| {
                    format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} write output row: {error}")
                })?;
            output_row_count = output_row_count.checked_add(1).ok_or_else(|| {
                format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} row count overflow")
            })?;
        }
    }
    let csv_bytes = writer.into_inner().map_err(|error| {
        format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} finish output CSV: {error}")
    })?;
    let source_row_count = u32::try_from(rows.len()).map_err(|_| {
        format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER} source row count overflow")
    })?;
    let mut setting_ids = bindings
        .iter()
        .map(|binding| binding.setting_id.clone())
        .collect::<Vec<_>>();
    setting_ids.sort();
    let receipt = LiteratureInputAdaptationReceipt {
        protocol_version: "chronicle-literature-input-adaptation-receipt/v1",
        setting_ids,
        adapter_ids: vec![format!("{PARTICIPANT_SCOPED_INTERVAL_UNION_ADAPTER}/v1")],
        original_input_digest: original_input_digest.to_owned(),
        adapted_input_digest: sha256(&csv_bytes),
        source_row_count,
        emitted_row_count: output_row_count,
        mapped_event_row_count: 0,
        materialized_interval_count: output_row_count,
        duplicate_source_ids_removed: 0,
        corrected_timestamp_provenance_rows: 0,
        participants_removed: 0,
        derived_result: Some(LiteratureDerivedResultReceipt {
            kind: "literature-participant-scoped-interval-union-csv",
            digest: sha256(&csv_bytes),
            row_count: output_row_count,
        }),
        source_oracle_id: Some(registration.source_oracle_id.clone()),
        component_configuration: None,
        keyguard_fsm: None,
        schoedel_screen_preprocessing: None,
    };
    Ok(AdaptedLiteratureInput {
        csv_bytes: csv_bytes.clone(),
        receipt,
        derived_result_bytes: Some(csv_bytes),
    })
}

