        let out = supplied_three_family_output(MEAN,MEAN_RAW);
        assert_eq!(out.iter().map(|row| &row[11]).collect::<Vec<_>>(),["4","4","4","15","9.5",""]);
        // Two devices have2 versus3 sessions: grand(4,15)=9.5,
        // NOT pooled (2+6+9+15+21)/5=10.6.
