    fn carat_test_run(adapter: &str, raw: &str) -> Result<AdaptedLiteratureInput, String> {
        let (registration, bindings) = literature_component_execution_unit(&format!("{adapter}/v1"))?;
        assert_eq!(registration.full_profile_execution_status, "blocked");
        assert_eq!(registration.source_work_id, "doi:10.2196/26540");
        assert_eq!(registration.source_method_variant_id, "source-audit-configuration-space-f69f04c44ab471393feb37a9");
        assert_eq!(registration.method_profile_version, "literature-sublation-v3-atomic+source-complete-v1");
        assert_eq!(bindings.len(), if adapter == "chronicle.carat-pair-regularity" { 2 } else { 1 });
        let adapted = adapt_literature_inputs(raw.as_bytes(), &sha256(raw.as_bytes()), &bindings, |_| &[])?.unwrap();
        assert_eq!(adapted.receipt.original_input_digest, sha256(raw.as_bytes()));
        assert_eq!(adapted.receipt.adapted_input_digest, sha256(&adapted.csv_bytes));
        assert_eq!(adapted.derived_result_bytes.as_ref(), Some(&adapted.csv_bytes));
        assert!(!receipt_is_kernel_input_eligible(&adapted.receipt));
        // Compare each original field byte-for-byte after CSV decoding.
        let original = csv::Reader::from_reader(raw.as_bytes()).records().collect::<Result<Vec<_>, _>>().unwrap();
        let output = csv::Reader::from_reader(adapted.csv_bytes.as_slice()).records().collect::<Result<Vec<_>, _>>().unwrap();
        assert_eq!(adapted.receipt.source_row_count, u32::try_from(original.len()).unwrap());
        assert_eq!(adapted.receipt.emitted_row_count, u32::try_from(original.len()).unwrap());
        for (a, b) in original.iter().zip(&output) {
            assert_eq!(a.iter().collect::<Vec<_>>(), b.iter().take(a.len()).collect::<Vec<_>>());
        }
        Ok(adapted)
    }

    fn carat_test_replace(raw: &str, row: usize, column: usize, value: &str) -> String {
        let mut reader = csv::Reader::from_reader(raw.as_bytes());
        let header = reader.headers().unwrap().clone();
        let records = reader.records().collect::<Result<Vec<_>, _>>().unwrap();
        let mut writer = csv::Writer::from_writer(Vec::new());
        writer.write_record(&header).unwrap();
        for (index, record) in records.iter().enumerate() {
            let mut fields = record.iter().map(str::to_owned).collect::<Vec<_>>();
            if index == row { fields[column] = value.into(); }
            writer.write_record(fields).unwrap();
        }
        String::from_utf8(writer.into_inner().unwrap()).unwrap()
    }

    #[test]
    fn carat_normalized_entropy_matches_hand_math_and_explicit_probability_boundary() {
        const ADAPTER: &str = "chronicle.carat-normalized-entropy";
        const RAW: &str = r###"participant_id,day_id,behavioral_stream,probability_encoding,input_qualification,state_count,state_probabilities_json
 P , d1 ,screen_status,proportion,source_qualified_complete_state_probabilities,2,"[{""state_id"":"" on "",""probability"":0.5},{""state_id"":""off"",""probability"":0.5}]"
P,d2,internet_connectivity,percent,source_qualified_complete_state_probabilities,2,"[{""state_id"":""connected"",""probability"":100},{""state_id"":""disconnected"",""probability"":0}]"
P,d3,foreground_app_usage,proportion,source_qualified_complete_state_probabilities,4,"[{""state_id"":""a"",""probability"":0.25},{""state_id"":""b"",""probability"":0.25},{""state_id"":""c"",""probability"":0.25},{""state_id"":""d"",""probability"":0.25}]"
P,d4,foreground_app_usage,proportion,source_qualified_complete_state_probabilities,1,"[{""state_id"":""a"",""probability"":1}]"
P,d5,screen_status,percent,source_qualified_complete_state_probabilities,2,"[{""state_id"":""on"",""probability"":0},{""state_id"":""off"",""probability"":0}]"
"###;
        let adapted = carat_test_run(ADAPTER, RAW).unwrap();
        let records = csv::Reader::from_reader(adapted.csv_bytes.as_slice()).records().collect::<Result<Vec<_>, _>>().unwrap();
        // Fair binary H/log2=1; all mass in one of two states=0;
        // four equiprobable visited apps H/log4=1. No raw-H oracle/base claim.
        assert_eq!(&records[0][7], "1");
        assert_eq!(&records[1][7], "0");
        assert_eq!(&records[2][7], "1");
        assert_eq!(&records[3][7], "");
        assert_eq!(&records[3][9], "undefined_normalization_N_le_1");
        assert_eq!(&records[4][9], "zero_probability_total");
        let skewed = carat_test_replace(RAW, 0, 6, r#"[{"state_id":"on","probability":0.75},{"state_id":"off","probability":0.25}]"#);
        let output = carat_test_run(ADAPTER, &skewed).unwrap();
        let record = csv::Reader::from_reader(output.csv_bytes.as_slice()).records().next().unwrap().unwrap();
        // Hand Shannon calculation for3/4 and1/4:0.8112781244591328.
        assert!((record[7].parse::<f64>().unwrap() - 0.8112781244591328).abs() < 1e-15);
        for (column, value) in [
            (3, "unknown"), (5, "3"), (4, "unqualified"),
            (6, r#"[{"state_id":"a","probability":0.25},{"state_id":"b","probability":0.25}]"#),
            (6, r#"[{"state_id":"a","probability":0.500000000002},{"state_id":"b","probability":0.5}]"#),
            (6, r#"[{"state_id":"a","probability":-0.1},{"state_id":"b","probability":1.1}]"#),
            (6, r#"[{"state_id":"a","probability":1e308},{"state_id":"b","probability":0}]"#),
            (6, r#"[{"state_id":"a","probability":0.5},{"state_id":"a","probability":0.5}]"#),
            (6, r#"[{"state_id":"a","probability":null},{"state_id":"b","probability":1}]"#),
            (6, "[]"),
        ] { assert!(carat_test_run(ADAPTER, &carat_test_replace(RAW, 0, column, value)).is_err(), "{column}/{value}"); }
        let tolerated = carat_test_replace(RAW, 0, 6, r#"[{"state_id":"a","probability":0.5000000000005},{"state_id":"b","probability":0.5}]"#);
        assert!(carat_test_run(ADAPTER, &tolerated).is_ok());
        let zero_app = carat_test_replace(RAW, 2, 6, r#"[{"state_id":"a","probability":0.5},{"state_id":"b","probability":0.25},{"state_id":"c","probability":0.25},{"state_id":"unvisited","probability":0}]"#);
        assert!(carat_test_run(ADAPTER, &zero_app).is_err());
        let conversion_underflow = carat_test_replace(RAW, 1, 6, r#"[{"state_id":"a","probability":100},{"state_id":"b","probability":5e-324}]"#);
        assert!(carat_test_run(ADAPTER, &conversion_underflow).is_err());
        let padded_ids = carat_test_replace(RAW, 0, 6, r#"[{"state_id":"same","probability":0.5},{"state_id":" same ","probability":0.5}]"#);
        assert!(carat_test_run(ADAPTER, &padded_ids).is_ok());
        let duplicate = format!("{}\n{}", RAW.trim_end(), RAW.lines().nth(1).unwrap());
        assert!(carat_test_run(ADAPTER, &duplicate).is_err());
        let collision = RAW.replacen("participant_id,", "normalized_entropy,", 1);
        assert!(carat_test_run(ADAPTER, &collision).is_err());
    }

