    fn assert_schoedel_released_r_cells(
        case_id: &str,
        actual_csv: &[u8],
        released_r_csv: &str,
        participant_id: &str,
    ) -> (usize, usize) {
        let mut actual_reader = csv::Reader::from_reader(actual_csv);
        let actual_headers = actual_reader.headers().unwrap().clone();
        let actual_rows = actual_reader
            .records()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        let mut expected_reader = csv::Reader::from_reader(released_r_csv.as_bytes());
        let expected_headers = expected_reader.headers().unwrap().clone();
        let expected_rows = expected_reader
            .records()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(
            actual_rows.len(),
            expected_rows.len(),
            "{case_id} row count"
        );
        assert_eq!(
            expected_headers.iter().collect::<Vec<_>>(),
            vec![
                "row_id",
                "activityName",
                "event",
                "client_db_id",
                "communication_id",
                "timestamp.corrected",
                "call_length",
                "usage",
                "nonusage",
            ],
            "{case_id} released-R projection"
        );
        let actual_user = header_index(&actual_headers, "user_id").unwrap();
        let mut compared_cells = 0;
        let mut representation_only_differences = 0;
        for (row_index, (actual, expected)) in
            actual_rows.iter().zip(expected_rows.iter()).enumerate()
        {
            assert_eq!(
                actual.get(actual_user),
                Some(participant_id),
                "{case_id} row {} participant partition",
                row_index + 1
            );
            compared_cells += 1;
            for (expected_column, header) in expected_headers.iter().enumerate() {
                let actual_column = header_index(&actual_headers, header).unwrap();
                let actual_value = actual.get(actual_column).unwrap();
                let expected_value = expected.get(expected_column).unwrap();
                compared_cells += 1;
                if actual_value == expected_value {
                    continue;
                }
                let both_missing =
                    matches!(actual_value, "" | "NA") && matches!(expected_value, "" | "NA");
                if both_missing {
                    representation_only_differences += 1;
                    continue;
                }
                let row_id = expected.get(0).unwrap();
                if case_id == "filters"
                    && row_id == "call1_after_end"
                    && header == "timestamp.corrected"
                {
                    // The locked R object retains the exact same POSIXct double bits as
                    // the input (0x1.7da1e77466666p+30). format(..., %OS3) truncates
                    // those bits to .099, whereas Chronicle losslessly retains .100.
                    assert_eq!(expected_value, "2020-09-21 10:01:01.099");
                    assert_eq!(actual_value, "2020-09-21 10:01:01.100");
                    representation_only_differences += 1;
                    continue;
                }
                panic!(
                    "{case_id} row {} ({row_id}) field {header}: released R {expected_value:?}, Chronicle {actual_value:?}",
                    row_index + 1
                );
            }
        }
        (compared_cells, representation_only_differences)
    }

    #[test]
    fn schoedel_screen_preprocessing_matches_released_r_stage_boundaries() {
        let patterns = concat!(
            "row_id,user_id,activityName,event,client_db_id,communication_id,timestamp.corrected\n",
            "lead_nonusage,PATTERNS,APPLICATION,APP_EVENT,a0,,2020-09-21 10:00:00.000\n",
            "duplicate_keep,PATTERNS,SCREEN,OFF_LOCKED,s_dup_keep,,2020-09-21 10:00:01.000\n",
            "duplicate_drop,PATTERNS,SCREEN,OFF_LOCKED,s_dup_drop,,2020-09-21 10:00:02.000\n",
            "huawei_start,PATTERNS,SCREEN,ON_UNLOCKED,s_huawei_on,,2020-09-21 10:00:10.000\n",
            "huawei_mid,PATTERNS,APPLICATION,APP_EVENT,a_huawei_mid,,2020-09-21 10:00:11.000\n",
            "huawei_end,PATTERNS,SCREEN,OFF_LOCKED,s_huawei_off,,2020-09-21 10:00:12.000\n",
            "merge_gap,PATTERNS,APPLICATION,APP_EVENT,a_merge_gap,,2020-09-21 10:00:14.000\n",
            "samsung_start,PATTERNS,SCREEN,ON_UNLOCKED,s_samsung_on,,2020-09-21 10:00:16.500\n",
            "samsung_mid,PATTERNS,APPLICATION,APP_EVENT,a_samsung_mid,,2020-09-21 10:00:17.000\n",
            "samsung_end,PATTERNS,SCREEN,OFF_UNLOCKED,s_samsung_off,,2020-09-21 10:00:18.000\n",
            "exact_five_gap,PATTERNS,APPLICATION,APP_EVENT,a_exact_gap,,2020-09-21 10:00:20.000\n",
            "check_start,PATTERNS,SCREEN,ON_LOCKED,s_check_on,,2020-09-21 10:00:23.000\n",
            "check_mid,PATTERNS,APPLICATION,APP_EVENT,a_check_mid,,2020-09-21 10:00:24.000\n",
            "check_end,PATTERNS,SCREEN,OFF_LOCKED,s_check_off,,2020-09-21 10:00:25.000\n",
            "tail_nonusage,PATTERNS,APPLICATION,APP_EVENT,a_tail,,2020-09-21 10:00:26.000\n",
        );
        let patterns = schoedel_screen_adapt(patterns, "id,type,length\nunused,SMS,1\n");
        let patterns_csv = String::from_utf8(patterns.csv_bytes).unwrap();
        assert!(patterns_csv.contains(
            "huawei_mid,PATTERNS,APPLICATION,APP_EVENT,a_huawei_mid,,2020-09-21 10:00:11.000,NA,2,NA"
        ));
        assert!(patterns_csv.contains(
            "samsung_mid,PATTERNS,APPLICATION,APP_EVENT,a_samsung_mid,,2020-09-21 10:00:17.000,NA,2,NA"
        ));
        assert!(patterns_csv.contains(
            "exact_five_gap,PATTERNS,APPLICATION,APP_EVENT,a_exact_gap,,2020-09-21 10:00:20.000,NA,NA,2"
        ));
        assert!(!patterns_csv.contains("duplicate_drop"));
        assert_eq!(patterns.receipt.source_row_count, 15);
        assert_eq!(patterns.receipt.emitted_row_count, 14);
        assert_eq!(patterns.receipt.materialized_interval_count, 5);
        let evidence = patterns.receipt.schoedel_screen_preprocessing.unwrap();
        assert_eq!(evidence.adjacent_screen_duplicates_removed, 1);
        assert_eq!(evidence.huawei_pattern_count, 1);
        assert_eq!(evidence.samsung_pattern_count, 1);
        assert_eq!(evidence.checking_pattern_count, 1);
        assert_eq!(evidence.usage_session_count, 2);
        assert_eq!(evidence.nonusage_session_count, 3);

        let filters = concat!(
            "row_id,user_id,activityName,event,client_db_id,communication_id,timestamp.corrected\n",
            "before_onhold,FILTERS,SCREEN,OFF_UNLOCKED,s_before_onhold,,2020-09-21 10:00:00.000\n",
            "onhold,FILTERS,PHONE,ONHOLD,p_onhold,,2020-09-21 10:00:01.000\n",
            "before_lt10_separator,FILTERS,SCREEN,ON_LOCKED,s_before_lt10_separator,,2020-09-21 10:00:05.000\n",
            "lt10_off,FILTERS,SCREEN,OFF_UNLOCKED,s_lt10_off,,2020-09-21 10:00:10.000\n",
            "lt10_on,FILTERS,SCREEN,ON_UNLOCKED,s_lt10_on,,2020-09-21 10:00:19.999\n",
            "eq10_off,FILTERS,SCREEN,OFF_UNLOCKED,s_eq10_off,,2020-09-21 10:00:30.000\n",
            "eq10_on,FILTERS,SCREEN,ON_UNLOCKED,s_eq10_on,,2020-09-21 10:00:40.000\n",
            "call1_origin,FILTERS,PHONE,OUTGOING,p_call1,call1,2020-09-21 10:00:50.000\n",
            "call1_at_start,FILTERS,SCREEN,ON_LOCKED,s_call1_at_start,,2020-09-21 10:00:50.000\n",
            "call1_inside,FILTERS,SCREEN,OFF_LOCKED,s_call1_inside,,2020-09-21 10:00:50.100\n",
            "call1_at_end,FILTERS,SCREEN,ON_UNLOCKED,s_call1_at_end,,2020-09-21 10:01:01.000\n",
            "call1_after_end,FILTERS,SCREEN,OFF_LOCKED,s_call1_after_end,,2020-09-21 10:01:01.100\n",
            "double_on_first,FILTERS,SCREEN,ON_UNLOCKED,s_double_first,,2020-09-21 10:01:10.000\n",
            "call2_origin,FILTERS,PHONE,OUTGOING,p_call2,call2,2020-09-21 10:01:11.000\n",
            "double_on_separator,FILTERS,SCREEN,OFF_LOCKED,s_double_separator,,2020-09-21 10:01:12.000\n",
            "double_on_second,FILTERS,SCREEN,ON_UNLOCKED,s_double_second,,2020-09-21 10:01:14.100\n",
            "sms_origin,FILTERS,PHONE,OUTGOING,p_sms,sms1,2020-09-21 10:01:20.000\n",
            "sms_screen_start,FILTERS,SCREEN,ON_LOCKED,s_sms_on,,2020-09-21 10:01:21.000\n",
            "sms_screen_end,FILTERS,SCREEN,OFF_LOCKED,s_sms_off,,2020-09-21 10:01:22.000\n",
        );
        let support = "id,type,length\ncall1,PHONE,10\ncall2,PHONE,2\nsms1,SMS,100\n";
        let filters = schoedel_screen_adapt(filters, support);
        let filters_csv = String::from_utf8(filters.csv_bytes).unwrap();
        for removed in [
            "before_onhold",
            "lt10_off",
            "call1_inside",
            "call1_at_end",
            "double_on_separator",
            "double_on_second",
        ] {
            assert!(!filters_csv.contains(removed), "retained {removed}");
        }
        for retained in [
            "eq10_off",
            "call1_at_start",
            "call1_after_end",
            "sms_origin",
        ] {
            assert!(filters_csv.contains(retained), "removed {retained}");
        }
        assert!(filters_csv.contains(
            "call1_origin,FILTERS,PHONE,OUTGOING,p_call1,call1,2020-09-21 10:00:50.000,10,NA,2"
        ));
        assert!(filters_csv.contains(
            "sms_origin,FILTERS,PHONE,OUTGOING,p_sms,sms1,2020-09-21 10:01:20.000,NA,NA,3"
        ));
        assert_eq!(filters.receipt.source_row_count, 19);
        assert_eq!(filters.receipt.emitted_row_count, 13);
        assert_eq!(filters.receipt.materialized_interval_count, 6);
        let evidence = filters.receipt.schoedel_screen_preprocessing.unwrap();
        assert_eq!(evidence.in_call_screen_rows_removed, 3);
        assert_eq!(evidence.off_unlocked_before_onhold_rows_removed, 1);
        assert_eq!(evidence.short_off_unlocked_rows_removed, 1);
        assert_eq!(evidence.double_on_unlocked_rows_removed, 1);
        assert_eq!(evidence.usage_session_count, 3);
        assert_eq!(evidence.nonusage_session_count, 3);
    }

