    #[test]
    fn schoedel_screen_preprocessing_uses_participant_first_occurrence_order() {
        let interleaved = concat!(
            "row_id,user_id,activityName,event,client_db_id,communication_id,timestamp.corrected\n",
            "z_lead,Z,APPLICATION,APP_EVENT,z0,,2020-09-21 10:00:00.000\n",
            "a_lead,A,APPLICATION,APP_EVENT,a0,,2020-09-21 10:00:00.500\n",
            "z_on1,Z,SCREEN,ON_UNLOCKED,z1,,2020-09-21 10:00:01.000\n",
            "a_on1,A,SCREEN,ON_UNLOCKED,a1,,2020-09-21 10:00:01.500\n",
            "z_off1,Z,SCREEN,OFF_LOCKED,z2,,2020-09-21 10:00:02.000\n",
            "a_off1,A,SCREEN,OFF_LOCKED,a2,,2020-09-21 10:00:02.500\n",
            "z_gap,Z,APPLICATION,APP_EVENT,z3,,2020-09-21 10:00:04.000\n",
            "a_gap,A,APPLICATION,APP_EVENT,a3,,2020-09-21 10:00:04.500\n",
            "z_on2,Z,SCREEN,ON_UNLOCKED,z4,,2020-09-21 10:00:07.000\n",
            "a_on2,A,SCREEN,ON_UNLOCKED,a4,,2020-09-21 10:00:07.500\n",
            "z_off2,Z,SCREEN,OFF_LOCKED,z5,,2020-09-21 10:00:08.000\n",
            "a_off2,A,SCREEN,OFF_LOCKED,a5,,2020-09-21 10:00:08.500\n",
            "z_tail,Z,APPLICATION,APP_EVENT,z6,,2020-09-21 10:00:09.000\n",
            "a_tail,A,APPLICATION,APP_EVENT,a6,,2020-09-21 10:00:09.500\n",
        );
        let adapted = schoedel_screen_adapt(interleaved, "id,type,length\nunused,SMS,1\n");
        let output = String::from_utf8(adapted.csv_bytes).unwrap();
        let row_ids = output
            .lines()
            .skip(1)
            .map(|line| line.split(',').next().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            row_ids,
            [
                "z_lead", "a_lead", "z_on1", "a_on1", "z_off1", "a_off1", "z_gap", "a_gap",
                "z_on2", "a_on2", "z_off2", "a_off2", "z_tail", "a_tail",
            ]
        );
        assert!(output.contains("z_on1,Z,SCREEN,ON_UNLOCKED,z1,,2020-09-21 10:00:01.000,NA,1,NA"));
        assert!(output.contains("a_on1,A,SCREEN,ON_UNLOCKED,a1,,2020-09-21 10:00:01.500,NA,1,NA"));
        assert!(output.contains("z_on2,Z,SCREEN,ON_UNLOCKED,z4,,2020-09-21 10:00:07.000,NA,2,NA"));
        assert!(output.contains("a_on2,A,SCREEN,ON_UNLOCKED,a4,,2020-09-21 10:00:07.500,NA,2,NA"));

        let two_errors = concat!(
            "user_id,activityName,event,client_db_id,communication_id,timestamp.corrected\n",
            "Z,SCREEN,ON_UNLOCKED,z_on,,2020-09-21 10:00:00.000\n",
            "A,SCREEN,ON_LOCKED,a_on,,2020-09-21 10:00:00.500\n",
            "Z,SCREEN,OFF_LOCKED,z_off,,2020-09-21 10:00:02.000\n",
            "A,SCREEN,OFF_UNLOCKED,a_off,,2020-09-21 10:00:02.500\n",
        );
        let error = adapt_schoedel_screen_preprocessing(
            two_errors.as_bytes(),
            b"id,type,length\nunused,SMS,1\n",
            &sha256(two_errors.as_bytes()),
            &[],
        )
        .err()
        .unwrap();
        assert!(
            error.contains("participant Z"),
            "wrong error precedence: {error}"
        );
        assert!(
            error.contains("one-session failure"),
            "wrong failure: {error}"
        );
    }

