    #[test]
    fn prepared_sensor_formula_components_preserve_grouping_status_and_blocked_parents() {
        let raw = b"participant_id,window_id,sample_id,dimension,value,input_unit,window_duration_seconds\nP,w,a,accelerometer_x,-2,opaque unit,5\nP,w,b,accelerometer_x,0,opaque unit,5\nP,w,c,accelerometer_x,2,opaque unit,5\nP,w,d,accelerometer_x,4,opaque unit,5\nP,w,a,gyroscope_y,7,other unit,5\nP,w,b,gyroscope_y,7,other unit,5\n";
        let (s3, s3_bindings) = literature_component_execution_unit(
            "chronicle.s3-prepared-sensor-window/v1",
        ).unwrap();
        assert_eq!(s3.full_profile_execution_status, "blocked");
        assert_eq!(s3_bindings.len(), 4);
        let s3_result = adapt_literature_inputs(raw, &sha256(raw), &s3_bindings, |_| &[])
            .unwrap().unwrap();
        assert_eq!(s3_result.receipt.source_row_count, 6);
        assert_eq!(s3_result.receipt.emitted_row_count, 8);
        assert_eq!(s3_result.receipt.setting_ids.len(), 4);
        let text = String::from_utf8(s3_result.csv_bytes).unwrap();
        assert!(text.contains("P,w,accelerometer_x,opaque unit,5,4,,average,1.0,computed,,input_unit"));
        assert!(text.contains("P,w,accelerometer_x,opaque unit,5,4,,peak_to_peak,6.0,computed,,input_unit"));
        assert!(text.contains("P,w,gyroscope_y,other unit,5,2,,peak_to_peak,0.0,computed,,input_unit"));
        let (autosen, auto_bindings) = literature_component_execution_unit(
            "chronicle.autosen-prepared-normalization/v1",
        ).unwrap();
        assert_eq!(autosen.full_profile_execution_status, "blocked");
        assert_eq!(auto_bindings.len(), 1);
        let normalized = adapt_literature_inputs(raw, &sha256(raw), &auto_bindings, |_| &[])
            .unwrap().unwrap();
        assert_eq!(normalized.receipt.source_row_count, 6);
        assert_eq!(normalized.receipt.emitted_row_count, 6);
        let text = String::from_utf8(normalized.csv_bytes).unwrap();
        assert!(text.contains("P,w,accelerometer_x,opaque unit,5,4,b,min_max_normalization,0.3333333333333333,computed,,dimensionless"));
        assert!(text.contains("P,w,gyroscope_y,other unit,5,2,a,min_max_normalization,,source_undefined,zero_range_behavior_undisclosed,dimensionless"));
        let mut combined = s3_bindings;
        combined.extend(auto_bindings);
        assert!(adapt_literature_inputs(raw, &sha256(raw), &combined, |_| &[])
            .err().unwrap().contains("refuses composition"));
    }

