    #[test]
    fn study_date_exclusion_bindings_require_each_exact_source_label() {
        let bindings = [
            binding("method-setting-e5a87fa0f1a10d4184bfe018"),
            binding("method-setting-acbce6b9d05461111a8792b1"),
            binding("method-setting-0c549383fd539ac9ee4fa5f1"),
        ];
        let raw = b"participant_id,event_timestamp,interaction_type\nP1,2026-01-01 00:00:00,Activity Resumed\n";
        let raw_digest = sha256(raw);
        let complete = b"participant_id,start_date,end_date,exclusion_label,exclusion_start_date,exclusion_end_date\n\
P1,2026-01-01,2026-05-31,Remove holiday week 6,2026-02-02,2026-02-08\n\
P1,2026-01-01,2026-05-31,exam weeks 8,2026-02-16,2026-02-22\n\
P1,2026-01-01,2026-05-31,16,2026-04-13,2026-04-19\n";
        adapt_literature_inputs(raw, &raw_digest, &bindings, |role| {
            if role == "study_dates_file" {
                complete.as_slice()
            } else {
                &[]
            }
        })
        .expect("all three exact source labels are present");

        let aliased_raw = b"participant_id,event_timestamp,interaction_type\nTECH-1042-D2,2026-01-01 00:00:00,Activity Resumed\n";
        let aliased_support = std::str::from_utf8(complete)
            .expect("support fixture is UTF-8")
            .replace("P1,", "1042,");
        adapt_literature_inputs(aliased_raw, &sha256(aliased_raw), &bindings, |role| {
            if role == "study_dates_file" {
                aliased_support.as_bytes()
            } else {
                &[]
            }
        })
        .expect("preprocessing preserves the StudyWindow numerical participant alias");

        let missing_numeric = b"participant_id,start_date,end_date,exclusion_label,exclusion_start_date,exclusion_end_date\n\
P1,2026-01-01,2026-05-31,Remove holiday week 6,2026-02-02,2026-02-08\n\
P1,2026-01-01,2026-05-31,exam weeks 8,2026-02-16,2026-02-22\n";
        let error = adapt_literature_inputs(raw, &raw_digest, &bindings, |role| {
            if role == "study_dates_file" {
                missing_numeric.as_slice()
            } else {
                &[]
            }
        })
        .err()
        .expect("numeric sourceValue must match plain-text label 16");
        assert!(
            error.contains("method-setting-0c549383fd539ac9ee4fa5f1"),
            "{error}"
        );

        let unrelated = std::str::from_utf8(complete)
            .expect("support fixture is UTF-8")
            .replace("P1,", "P2,");
        let error = adapt_literature_inputs(raw, &raw_digest, &bindings, |role| {
            if role == "study_dates_file" {
                unrelated.as_bytes()
            } else {
                &[]
            }
        })
        .err()
        .expect("labels for another participant cannot authorize P1");
        assert!(error.contains("every raw participant"), "{error}");
    }

    #[test]
    fn analysis_feature_missingness_honors_source_boundaries_and_feature_sets() {
        let mut input =
            String::from("participant_id,feature_id,value,missing_state,feature_set_id\n");
        for participant in 1..=32 {
            for feature in [
                "week_01", "week_02", "g1", "g2", "g3", "g4", "g5", "g6", "g7", "g8", "g9",
            ] {
                let missing = (feature == "week_01" && participant <= 30)
                    || (feature == "week_02" && participant <= 31)
                    || (feature == "g1" && participant == 1);
                let value = if missing {
                    ""
                } else if feature == "g9" && participant == 32 {
                    "-1"
                } else {
                    "1"
                };
                input.push_str(&format!(
                    "p{participant:02},{feature},{},{},setA\n",
                    value,
                    if missing { "missing" } else { "observed" },
                ));
            }
        }
        input.push_str("p01,week_01,7,observed,setB\n");

        let (output, row_count) = analysis_feature_matrix_result(input.as_bytes()).unwrap();
        let output = String::from_utf8(output).unwrap();
        assert_eq!(row_count, 353);
        assert!(output
            .contains("p01,setA,week_01,,missing,30,true,2,10,20.000000,false,,drop_participant"));
        assert!(output
            .contains("p02,setA,week_01,,missing,30,true,1,10,10.000000,true,-1,impute_minus_one"));
        assert!(output.contains("p01,setA,week_02,,missing,31,false"));
        assert!(output
            .contains("p01,setB,week_01,7,observed,0,true,0,1,0.000000,true,7,retain_observed"));
        assert!(
            output.contains("p32,setA,g9,-1,observed,0,true,0,10,0.000000,true,-1,retain_observed")
        );
    }

