    #[test]
    fn borrowed_support_lookup_preserves_owned_results_and_early_refusals() {
        let raw = b"participant_id,event_timestamp,interaction_type,communication_modality\nEQ,2026-01-01 00:00:00,Communication,call\nZERO,2026-01-01 00:00:01,Activity Resumed,\n";
        let bindings = [binding("method-setting-adda9b69e35b45ac28a7d314")];
        let adapted = {
            // The caller's support storage and lookup both expire before the
            // returned owned CSV and receipt are inspected below.
            let volume = b"participant_id,modality_scope,availability_state,year_equivalent_exposure_numerator,year_equivalent_exposure_denominator\nEQ,call_text_combined,available,1,300\nZERO,call_text_combined,available,1,1\n".to_vec();
            let requested = std::cell::RefCell::new(Vec::<String>::new());
            let adapted = adapt_literature_inputs(raw, &sha256(raw), &bindings, |role| {
                requested.borrow_mut().push(role.to_owned());
                if role == "call_sms_eligibility_file" {
                    volume.as_slice()
                } else {
                    &[]
                }
            })
            .unwrap()
            .unwrap();
            assert_eq!(
                requested.borrow().iter().filter(|role| role.as_str() == "call_sms_eligibility_file").count(),
                1
            );
            adapted
        };
        assert_eq!(adapted.receipt.source_row_count, 2);
        assert_eq!(adapted.receipt.participants_removed, 1);
        assert_eq!(sha256(&adapted.csv_bytes), adapted.receipt.adapted_input_digest);
        let derived = adapted.derived_result_bytes.unwrap();
        assert_eq!(sha256(&derived), adapted.receipt.derived_result.unwrap().digest);
        assert!(String::from_utf8(derived).unwrap().contains("EQ,call_text_combined,available,1,300,1,300,strict_less_than,true"));

        assert!(adapt_literature_inputs(raw, &sha256(raw), &bindings, |_| &[])
            .err().unwrap().contains("requires call_sms_eligibility_file"));
        let mut invalid = bindings.clone();
        invalid[0].adapter_version = "unregistered-version".into();
        assert!(adapt_literature_inputs(raw, &sha256(raw), &invalid, |_| {
            panic!("invalid registration must be refused before support lookup")
        }).is_err());
        assert!(adapt_literature_inputs(raw, &sha256(raw), &[], |_| {
            panic!("empty bindings must not request support")
        }).unwrap().is_none());
        assert!(adapt_literature_inputs(&[], &sha256(&[]), &bindings, |_| {
            panic!("raw-less input must be refused before support lookup")
        }).err().unwrap().contains("require the verified raw CSV"));
    }

